INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94819, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "激励", "is_correct": true, "explanation": "激励：用好话或行动让人更想努力，正确答案。"}, {"text": "极力", "is_correct": false, "explanation": "jí（第二声）与 jī（第一声）声调不同，意思是竭尽全力。"}, {"text": "接力", "is_correct": false, "explanation": "jiē 与 jī 的韵母不同，意思是轮流传递。"}, {"text": "吉利", "is_correct": false, "explanation": "jí（第二声）与 jī（第一声）声调不同，意思是吉祥顺利。"}], "explanations": {"激励": "激励：用好话或行动让人更想努力，正确答案。", "极力": "jí（第二声）与 jī（第一声）声调不同，意思是竭尽全力。", "接力": "jiē 与 jī 的韵母不同，意思是轮流传递。", "吉利": "jí（第二声）与 jī（第一声）声调不同，意思是吉祥顺利。"}, "sentence_index": null, "correct_answer": "激励"}, "level_3": {"options": [{"text": "激励", "is_correct": true, "explanation": "激励：用言语使人振作，与“老板开会时”和“说公司会越来越好”的语境相合，正确。"}, {"text": "埋葬", "is_correct": false, "explanation": "语义：“埋葬”表示掩埋，与“说公司会越来越好”的积极语境相反。"}, {"text": "驱赶", "is_correct": false, "explanation": "语义：“驱赶”是赶走，与“说公司会越来越好”的语境矛盾。"}, {"text": "收养", "is_correct": false, "explanation": "搭配：“收养”指领养孩子，不能用于“开会时”的“大家”，句意不通。"}], "explanations": {"激励": "激励：用言语使人振作，与“老板开会时”和“说公司会越来越好”的语境相合，正确。", "埋葬": "语义：“埋葬”表示掩埋，与“说公司会越来越好”的积极语境相反。", "驱赶": "语义：“驱赶”是赶走，与“说公司会越来越好”的语境矛盾。", "收养": "搭配：“收养”指领养孩子，不能用于“开会时”的“大家”，句意不通。"}, "sentence_index": 6, "correct_answer": "激励"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次活动激励了学生的注意，大家都看着台上。", "explanation": "这里应该用〈引起〉。要说“引起注意”；“激励”的对象必须是人，不能用来搭配“注意”。"}, {"text": "她激励了那扇门，门却没有动。", "explanation": "激励的对象是人，门不能被激励，这里的用法不对。"}, {"text": "这种药物激励了神经，病人感到很疼。", "explanation": "这里应该用〈刺激〉。对神经产生作用要说“刺激”；“激励”指使人振作，对象必须是人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16f75cd7-34c5-4e6d-8efa-ea9e49b7dc17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94819, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这句话激励我过很多次。", "corrected_sentence": "这句话激励过我很多次。", "error_description": "错误：“激励我过很多次”；正确：“激励过我很多次”。表示经历的“过”应紧跟动词“激励”，放在动词后、宾语前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16f75cd7-34c5-4e6d-8efa-ea9e49b7dc17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94819, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份工作一直激励我着继续学习。", "corrected_sentence": "这份工作一直激励着我继续学习。", "error_description": "错误：“激励我着”；正确：“激励着我”。表示持续的“着”应紧跟动词，放在动词后、宾语前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16f75cd7-34c5-4e6d-8efa-ea9e49b7dc17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
