INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94820, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "激发鼓励，使人振作起来去做事。", "primary_collocate": null, "pronunciation": "jī lì", "ipa": "tɕi˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "失败后，朋友的话激励他重新开始。", "target_word": "激励", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人的经历激励着很多人。", "target_word": "激励", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想用新办法激励工人多做事。", "target_word": "激励", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奥运冠军的故事激励了一代年轻人。", "target_word": "激励", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试没考好，爸爸没有骂我，而是激励我再试一次。", "target_word": "激励", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好老师会激励学生自己去学习。", "target_word": "激励", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想用自己的成功激励家乡的孩子。", "target_word": "激励", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小故事激励我每天早起跑步。", "target_word": "激励", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "队长大声说了几句话，激励了全队。", "target_word": "激励", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的努力激励我不要放弃。", "target_word": "激励", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "激励了", "label": "体标"}, {"form": "激励着", "label": "体标"}, {"form": "激励机制", "label": "复合"}], "register": "中性", "sense_fingerprint": "激发并鼓励人振作起来行动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3101b179-ea35-4787-b575-d3c8af1182ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94820, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "激励", "is_correct": true, "explanation": "激励：激发鼓励，使人振作去做事，正确答案。"}, {"text": "吉利", "is_correct": false, "explanation": "jí（第二声）与 jī（第一声）声调不同，意思是吉祥顺利。"}, {"text": "接力", "is_correct": false, "explanation": "jiē 与 jī 的韵母不同，意思是轮流传递。"}, {"text": "极力", "is_correct": false, "explanation": "jí（第二声）与 jī（第一声）声调不同，意思是竭尽全力。"}], "explanations": {"激励": "激励：激发鼓励，使人振作去做事，正确答案。", "吉利": "jí（第二声）与 jī（第一声）声调不同，意思是吉祥顺利。", "接力": "jiē 与 jī 的韵母不同，意思是轮流传递。", "极力": "jí（第二声）与 jī（第一声）声调不同，意思是竭尽全力。"}, "sentence_index": null, "correct_answer": "激励"}, "level_3": {"options": [{"text": "激励", "is_correct": true, "explanation": "激励：激发鼓励，与“朋友的话”和“重新开始”相合，正确。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”带讽刺意味，与“失败后”需要鼓励的语境相反。"}, {"text": "辱骂", "is_correct": false, "explanation": "语义：“辱骂”与帮助人重新开始的语境相反。"}, {"text": "冷落", "is_correct": false, "explanation": "搭配：“朋友的话冷落他”不成立，且与“重新开始”矛盾。"}], "explanations": {"激励": "激励：激发鼓励，与“朋友的话”和“重新开始”相合，正确。", "嘲笑": "语义：“嘲笑”带讽刺意味，与“失败后”需要鼓励的语境相反。", "辱骂": "语义：“辱骂”与帮助人重新开始的语境相反。", "冷落": "搭配：“朋友的话冷落他”不成立，且与“重新开始”矛盾。"}, "sentence_index": 0, "correct_answer": "激励"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "听到这个消息，他激励得说不出话来。", "explanation": "这里应该用〈激动〉。因情绪强烈而说不出话，要说“激动”；“激励”是使人振作去做事，不能描述情绪激烈的样子。"}, {"text": "我激励了一本书，让书变得更厚。", "explanation": "激励的对象是人，书不能被激励，这里的用法不对。"}, {"text": "他激励了那块石头，石头却一动不动。", "explanation": "激励的对象应是能被鼓舞的人，石头不能被激励，这里的用法不对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16f75cd7-34c5-4e6d-8efa-ea9e49b7dc17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94820, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "激励", "is_correct": true, "explanation": "激励：激发鼓励，使人振作去做事，正确答案。"}, {"text": "精力", "is_correct": false, "explanation": "jīng 比 jī 多了 ng 韵尾，意思是体力和精神。"}, {"text": "积累", "is_correct": false, "explanation": "lěi（第三声）与 lì（第四声）的韵母和声调都不同，意思是逐渐增加。"}, {"text": "机理", "is_correct": false, "explanation": "lǐ（第三声）与 lì（第四声）声调不同，意思是事物的内在道理。"}], "explanations": {"激励": "激励：激发鼓励，使人振作去做事，正确答案。", "精力": "jīng 比 jī 多了 ng 韵尾，意思是体力和精神。", "积累": "lěi（第三声）与 lì（第四声）的韵母和声调都不同，意思是逐渐增加。", "机理": "lǐ（第三声）与 lì（第四声）声调不同，意思是事物的内在道理。"}, "sentence_index": null, "correct_answer": "激励"}, "level_3": {"options": [{"text": "激励", "is_correct": true, "explanation": "激励：激发鼓励，与“用自己的成功”和“家乡的孩子”相合，正确。"}, {"text": "埋葬", "is_correct": false, "explanation": "语义：“埋葬”表示掩埋，与“用自己的成功”的积极语境相反。"}, {"text": "驱赶", "is_correct": false, "explanation": "语义：“驱赶”是赶走，与“用成功”的语境矛盾。"}, {"text": "收养", "is_correct": false, "explanation": "搭配：“用成功收养孩子”不通，“收养”不能与“用……成功”搭配。"}], "explanations": {"激励": "激励：激发鼓励，与“用自己的成功”和“家乡的孩子”相合，正确。", "埋葬": "语义：“埋葬”表示掩埋，与“用自己的成功”的积极语境相反。", "驱赶": "语义：“驱赶”是赶走，与“用成功”的语境矛盾。", "收养": "搭配：“用成功收养孩子”不通，“收养”不能与“用……成功”搭配。"}, "sentence_index": 6, "correct_answer": "激励"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道菜激励了我的食欲，我一口气吃了三碗。", "explanation": "这里应该用〈刺激〉。对食欲产生作用要说“刺激”；“激励”指使人振作，对象必须是人。"}, {"text": "这个标题激励了读者的注意，很多人都点开看了。", "explanation": "这里应该用〈引起〉。要说“引起注意”；“激励”的对象必须是人，不能用来搭配“注意”。"}, {"text": "老师的一个问题激励了我的思路。", "explanation": "这里应该用〈启发〉。对思路产生作用要说“启发”；“激励”指使人振作，对象必须是人，不说“激励思路”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16f75cd7-34c5-4e6d-8efa-ea9e49b7dc17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94820, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本书激励得很多年轻人。", "corrected_sentence": "这本书激励了很多年轻人。", "error_description": "错误：“激励得很多年轻人”；正确：“激励了很多年轻人”。动词后直接带宾语表示完成，应用“了”，不用“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16f75cd7-34c5-4e6d-8efa-ea9e49b7dc17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94820, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小故事激励了了我，让我每天早起跑步。", "corrected_sentence": "这个小故事激励了我，让我每天早起跑步。", "error_description": "错误：“激励了了我”；正确：“激励了我”。动态助词“了”只用一次，紧跟动词“激励”之后，不能重复。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16f75cd7-34c5-4e6d-8efa-ea9e49b7dc17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
