INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94821, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "无论如何是不管怎么样，都要做。", "primary_collocate": null, "pronunciation": "wú lùn rú hé", "ipa": "u˧˥ lwən˥˩ ɻu˧˥ xɤ˧˥", "syllable_count": 4, "sentences": [{"text": "无论如何，你今天都要打电话给妈妈。", "target_word": "无论如何", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我无论如何都要学好汉语。", "target_word": "无论如何", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事无论如何要做完。", "target_word": "无论如何", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "明天有考试，你无论如何要早点睡。", "target_word": "无论如何", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他无论如何要见你一面。", "target_word": "无论如何", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "无论如何，我们都要准时到。", "target_word": "无论如何", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "车票太贵了，可我无论如何要回家。", "target_word": "无论如何", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你无论如何要把门关好。", "target_word": "无论如何", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我无论如何也要找到那只猫。", "target_word": "无论如何", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友有困难，我们无论如何要帮他。", "target_word": "无论如何", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "不管怎么样，都一定要做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c775263-ec78-4df2-815b-c2b3a153698a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94821, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "无论如何", "is_correct": true, "explanation": "正确：无论如何表示不管怎样都要做某事，与“都要打电话”的语气一致。"}, {"text": "也许", "is_correct": false, "explanation": "语义：“也许”表示推测，不表示必须要做，与“都要”冲突。"}, {"text": "难道", "is_correct": false, "explanation": "语义：“难道”用于反问，与“你今天都要打电话”这样的陈述不合。"}, {"text": "只好", "is_correct": false, "explanation": "搭配：“只好”表示无奈地接受，不能与“都要”这样表示必须的命令语气搭配。"}], "explanations": {"无论如何": "正确：无论如何表示不管怎样都要做某事，与“都要打电话”的语气一致。", "也许": "语义：“也许”表示推测，不表示必须要做，与“都要”冲突。", "难道": "语义：“难道”用于反问，与“你今天都要打电话”这样的陈述不合。", "只好": "搭配：“只好”表示无奈地接受，不能与“都要”这样表示必须的命令语气搭配。"}, "sentence_index": 0, "correct_answer": "无论如何"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天无论如何会下雨。", "explanation": "这里应该用〈也许〉。无论如何表示必须要做的决心，不用于推测天气。"}, {"text": "这件事无论如何重要。", "explanation": "这里应该用〈非常〉。无论如何表示必须要做的决心，不能像〈非常〉那样直接修饰形容词表示程度。"}, {"text": "他今天无论如何迟到了。", "explanation": "这里应该用〈已经〉。无论如何表示必须要做的决心，指向将来，不能用于已经发生的迟到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf47c05-ff6e-4ac9-8a71-e8a1aae506d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94821, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "无论如何", "is_correct": true, "explanation": "正确：无论如何表示不管车票多贵都要回家，与前句的让步语境相合。"}, {"text": "竟然", "is_correct": false, "explanation": "语义：“竟然”表示出乎意料，与“可我”的转折语气不合。"}, {"text": "恰好", "is_correct": false, "explanation": "语义：“恰好”表示巧合，与“车票太贵了”的让步关系不合。"}, {"text": "不妨", "is_correct": false, "explanation": "搭配：“不妨”后接动词表示可以试试，不能与“要回家”的必须语气并列。"}], "explanations": {"无论如何": "正确：无论如何表示不管车票多贵都要回家，与前句的让步语境相合。", "竟然": "语义：“竟然”表示出乎意料，与“可我”的转折语气不合。", "恰好": "语义：“恰好”表示巧合，与“车票太贵了”的让步关系不合。", "不妨": "搭配：“不妨”后接动词表示可以试试，不能与“要回家”的必须语气并列。"}, "sentence_index": 6, "correct_answer": "无论如何"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她无论如何漂亮。", "explanation": "这里应该用〈非常〉。无论如何表示必须要做的决心，不能直接修饰形容词表示程度。"}, {"text": "周末无论如何会下雨。", "explanation": "这里应该用〈大概〉。无论如何表示必须要做的决心，不用于推测天气。"}, {"text": "他的性格无论如何好。", "explanation": "这里应该用〈特别〉。无论如何表示必须要做的决心，不能直接修饰形容词来描述性格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf47c05-ff6e-4ac9-8a71-e8a1aae506d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94821, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你无论如何地要按时吃药。", "corrected_sentence": "你无论如何要按时吃药。", "error_description": "错误：“无论如何”后多加了“地”。“无论如何”本身是副词，后面不能再加“地”，应说“你无论如何要按时吃药”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf47c05-ff6e-4ac9-8a71-e8a1aae506d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94821, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他无论如何帮了朋友。", "corrected_sentence": "他无论如何要帮朋友。", "error_description": "错误在“了”：“无论如何”表示必须要做的决心，指向将来，不能与已完成的“了”搭配，应改为“要”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf47c05-ff6e-4ac9-8a71-e8a1aae506d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94823, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "冷门", "is_correct": true, "explanation": "正确：「冷门」与「热门」反义，指少有人喜欢、不受关注的。"}, {"text": "陡峭", "is_correct": false, "explanation": "「陡峭」形容山坡或坡度很大，与「热门」的意思没有反义关系。"}, {"text": "柔软", "is_correct": false, "explanation": "「柔软」形容质地松软、不硬，与「热门」的意思没有反义关系。"}, {"text": "清晰", "is_correct": false, "explanation": "「清晰」形容看得或听得明白，与「热门」的意思没有反义关系。"}], "correct_answer": "冷门", "explanations": {"冷门": "正确：「冷门」与「热门」反义，指少有人喜欢、不受关注的。", "陡峭": "「陡峭」形容山坡或坡度很大，与「热门」的意思没有反义关系。", "柔软": "「柔软」形容质地松软、不硬，与「热门」的意思没有反义关系。", "清晰": "「清晰」形容看得或听得明白，与「热门」的意思没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef72aa20-fe36-47c5-8a6c-d1cb07ec2aab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94823, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "冷门", "is_correct": true, "explanation": "正确：「冷门」与「热门」反义，指少有人关注、不受欢迎的。"}, {"text": "粗糙", "is_correct": false, "explanation": "「粗糙」形容表面不光滑，与「热门」的意思没有反义关系。"}, {"text": "严肃", "is_correct": false, "explanation": "「严肃」形容态度认真、不轻松，与「热门」的意思没有反义关系。"}, {"text": "温暖", "is_correct": false, "explanation": "「温暖」形容温度适宜、令人亲切，与「热门」的意思没有反义关系。"}], "correct_answer": "冷门", "explanations": {"冷门": "正确：「冷门」与「热门」反义，指少有人关注、不受欢迎的。", "粗糙": "「粗糙」形容表面不光滑，与「热门」的意思没有反义关系。", "严肃": "「严肃」形容态度认真、不轻松，与「热门」的意思没有反义关系。", "温暖": "「温暖」形容温度适宜、令人亲切，与「热门」的意思没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef72aa20-fe36-47c5-8a6c-d1cb07ec2aab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94823, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "热门是很多人喜欢、爱看的。", "primary_collocate": null, "pronunciation": "rè mén", "ipa": "ʐɤ˥˩ mən˧˥", "syllable_count": 2, "sentences": [{"text": "这部电影很热门。", "target_word": "热门", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这是最热门的歌。", "target_word": "热门", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "热门电视剧我都爱看。", "target_word": "热门", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她喜欢看热门的小说。", "target_word": "热门", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "周末，热门电影的票很难买。", "target_word": "热门", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书太热门了，书店里已经卖完了。", "target_word": "热门", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想听几首最近热门的歌。", "target_word": "热门", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店的热门菜卖得很快。", "target_word": "热门", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个游戏现在特别热门，同学们都在玩。", "target_word": "热门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看热门节目时，他们常常一边吃一边聊。", "target_word": "热门", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "熱門", "label": "繁体"}], "register": "中性", "sense_fingerprint": "很多人喜欢爱看的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60b8685b-8c93-4781-a5d8-5d5358d689c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94823, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "热门", "is_correct": true, "explanation": "正确：「热门」指很多人喜欢、爱看，用来形容这部电影很受欢迎。"}, {"text": "咸", "is_correct": false, "explanation": "语义：「咸」指味道，不能用来形容电影。"}, {"text": "饿", "is_correct": false, "explanation": "搭配：「饿」只用于人或动物需要进食，不能用来形容电影。"}, {"text": "矮", "is_correct": false, "explanation": "体貌：「矮」形容人或物的高度，不能用来形容电影。"}], "explanations": {"热门": "正确：「热门」指很多人喜欢、爱看，用来形容这部电影很受欢迎。", "咸": "语义：「咸」指味道，不能用来形容电影。", "饿": "搭配：「饿」只用于人或动物需要进食，不能用来形容电影。", "矮": "体貌：「矮」形容人或物的高度，不能用来形容电影。"}, "sentence_index": 0, "correct_answer": "热门"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "教室里很热门，同学们都在说话。", "explanation": "这里应该用〈热闹〉。「热门」指很多人喜欢、爱看，不用来形容场面的吵闹。"}, {"text": "他的脾气很热门，一生气就大喊大叫。", "explanation": "这里应该用〈火爆〉。「热门」形容受欢迎，不能用来形容脾气。"}, {"text": "夏天的天气很热门，我们都不想出门。", "explanation": "这里应该用〈炎热〉。「热门」指受欢迎，不能用来形容天气的温度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef72aa20-fe36-47c5-8a6c-d1cb07ec2aab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94823, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "热门", "is_correct": true, "explanation": "正确：「热门」指很多人喜欢、爱看，用来形容最近大家都爱听的歌。"}, {"text": "陈旧", "is_correct": false, "explanation": "语义：「陈旧」指过时、旧，与前面的「最近」矛盾。"}, {"text": "圆", "is_correct": false, "explanation": "语义：「圆」形容形状，不能用来形容歌。"}, {"text": "湿", "is_correct": false, "explanation": "搭配：「湿」形容物体含水，不能用来修饰「歌」。"}], "explanations": {"热门": "正确：「热门」指很多人喜欢、爱看，用来形容最近大家都爱听的歌。", "陈旧": "语义：「陈旧」指过时、旧，与前面的「最近」矛盾。", "圆": "语义：「圆」形容形状，不能用来形容歌。", "湿": "搭配：「湿」形容物体含水，不能用来修饰「歌」。"}, "sentence_index": 6, "correct_answer": "热门"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这壶水很热门，你先别喝。", "explanation": "「热门」指很多人喜欢、爱看，形容受欢迎的程度，不能用来形容水的温度，这句把它当成了「热」的意思。"}, {"text": "这杯茶很热门，等一会儿再喝。", "explanation": "「热门」指受欢迎、受关注，不能用来形容茶的温度，这句误用了它的意思。"}, {"text": "这碗汤很热门，小心烫嘴。", "explanation": "「热门」形容事物受欢迎，不能用来说汤的热度，这句误用了它的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef72aa20-fe36-47c5-8a6c-d1cb07ec2aab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94823, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我最近在看一部热门地电影。", "corrected_sentence": "我最近在看一部热门的电影。", "error_description": "错误：「热门」修饰名词「电影」时应用「的」，这里误用了「地」。「地」用于修饰动词或形容词，正确的是「一部热门的电影」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef72aa20-fe36-47c5-8a6c-d1cb07ec2aab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94823, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这首歌现在是很最热门的。", "corrected_sentence": "这首歌现在是最热门的。", "error_description": "错误：「很最热门」。正确：「最热门」。「最」已表示最高程度，不能与程度副词「很」叠用，应删去「很」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef72aa20-fe36-47c5-8a6c-d1cb07ec2aab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94824, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "冷门", "is_correct": true, "explanation": "正确：「冷门」与「热门」反义，指不受欢迎、少有人关注的。"}, {"text": "幼稚", "is_correct": false, "explanation": "「幼稚」形容想法不成熟，与「热门」的意思没有反义关系。"}, {"text": "潮湿", "is_correct": false, "explanation": "「潮湿」形容含水多、不干燥，与「热门」的意思没有反义关系。"}, {"text": "粗壮", "is_correct": false, "explanation": "「粗壮」形容身体或物体又粗又结实，与「热门」的意思没有反义关系。"}], "correct_answer": "冷门", "explanations": {"冷门": "正确：「冷门」与「热门」反义，指不受欢迎、少有人关注的。", "幼稚": "「幼稚」形容想法不成熟，与「热门」的意思没有反义关系。", "潮湿": "「潮湿」形容含水多、不干燥，与「热门」的意思没有反义关系。", "粗壮": "「粗壮」形容身体或物体又粗又结实，与「热门」的意思没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef72aa20-fe36-47c5-8a6c-d1cb07ec2aab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94824, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "冷门", "is_correct": true, "explanation": "正确：「冷门」与「热门」反义，指少有人关注、不受欢迎的。"}, {"text": "辛苦", "is_correct": false, "explanation": "「辛苦」形容付出很多力气，与「热门」的意思没有反义关系。"}, {"text": "干燥", "is_correct": false, "explanation": "「干燥」形容缺少水分，与「热门」的意思没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "「明亮」形容光线足、亮堂，与「热门」的意思没有反义关系。"}], "correct_answer": "冷门", "explanations": {"冷门": "正确：「冷门」与「热门」反义，指少有人关注、不受欢迎的。", "辛苦": "「辛苦」形容付出很多力气，与「热门」的意思没有反义关系。", "干燥": "「干燥」形容缺少水分，与「热门」的意思没有反义关系。", "明亮": "「明亮」形容光线足、亮堂，与「热门」的意思没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef72aa20-fe36-47c5-8a6c-d1cb07ec2aab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94824, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "受到很多人欢迎和关注的。", "primary_collocate": null, "pronunciation": "rè mén", "ipa": "ʐɤ˥˩ mən˧˥", "syllable_count": 2, "sentences": [{"text": "这个话题很热门。", "target_word": "热门", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "热门景点人特别多。", "target_word": "热门", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个词最近变得很热门。", "target_word": "热门", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "现在最热门的专业是什么？", "target_word": "热门", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "暑假里，热门的旅游城市到处是人。", "target_word": "热门", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他选了一个不太热门的工作。", "target_word": "热门", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "热门的比赛，网上有很多人讨论。", "target_word": "热门", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "因为很热门，这家饭馆要排队。", "target_word": "热门", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她写的文章成了网上最热门的话题。", "target_word": "热门", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个热门问题，记者已经问过很多次了。", "target_word": "热门", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "熱門", "label": "繁体"}], "register": "中性", "sense_fingerprint": "受很多人欢迎和关注的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60b8685b-8c93-4781-a5d8-5d5358d689c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94824, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "热门", "is_correct": true, "explanation": "正确：「热门」指受很多人欢迎和关注，用来形容这个话题很受关注。"}, {"text": "咸", "is_correct": false, "explanation": "语义：「咸」指味道，不能用来形容话题。"}, {"text": "饱", "is_correct": false, "explanation": "语义：「饱」指吃得满足，不能用来形容话题。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：「瘦」形容人或动物的身材，不能用来形容话题。"}], "explanations": {"热门": "正确：「热门」指受很多人欢迎和关注，用来形容这个话题很受关注。", "咸": "语义：「咸」指味道，不能用来形容话题。", "饱": "语义：「饱」指吃得满足，不能用来形容话题。", "瘦": "体貌：「瘦」形容人或动物的身材，不能用来形容话题。"}, "sentence_index": 0, "correct_answer": "热门"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这碗面太热门了，等凉一点再吃。", "explanation": "「热门」指受很多人欢迎和关注，不能用来形容食物的温度，这句把它当成了「热」的意思。"}, {"text": "这杯奶茶很热门，你先放凉再喝。", "explanation": "「热门」形容受欢迎的程度，不能用来说奶茶的温度，这句误用了它的意思。"}, {"text": "这间屋子很热门，我们开窗吧。", "explanation": "「热门」指受欢迎、受关注，不能用来形容屋子的温度，这句误用了它的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef72aa20-fe36-47c5-8a6c-d1cb07ec2aab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94824, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "热门", "is_correct": true, "explanation": "正确：「热门」指受很多人欢迎和关注，用来形容这场比赛受到大家讨论。"}, {"text": "饿", "is_correct": false, "explanation": "搭配：「饿」只用于人或动物想吃东西，不能用来修饰「比赛」。"}, {"text": "寂静", "is_correct": false, "explanation": "语义：「寂静」指没有声音，与后面「网上有很多人讨论」矛盾。"}, {"text": "辣", "is_correct": false, "explanation": "语义：「辣」指味道，不能用来修饰比赛。"}], "explanations": {"热门": "正确：「热门」指受很多人欢迎和关注，用来形容这场比赛受到大家讨论。", "饿": "搭配：「饿」只用于人或动物想吃东西，不能用来修饰「比赛」。", "寂静": "语义：「寂静」指没有声音，与后面「网上有很多人讨论」矛盾。", "辣": "语义：「辣」指味道，不能用来修饰比赛。"}, "sentence_index": 6, "correct_answer": "热门"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "服务员的态度很热门，客人都很满意。", "explanation": "这里应该用〈热情〉。「热门」指受欢迎，不能用来形容态度。"}, {"text": "正午的太阳很热门，大家都躲在树下。", "explanation": "这里应该用〈炎热〉。「热门」指受欢迎，不能用来形容太阳的热度。"}, {"text": "大家为他的演讲鼓起了热门的掌声。", "explanation": "这里应该用〈热烈〉。「热门」指受欢迎，不能用来形容掌声的热烈程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef72aa20-fe36-47c5-8a6c-d1cb07ec2aab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94824, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一个热门地话题。", "corrected_sentence": "这是一个热门的话题。", "error_description": "错误：「热门」修饰名词「话题」时应用「的」，这里误用了「地」。「地」用于修饰动词或形容词，正确的是「一个热门的话题」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef72aa20-fe36-47c5-8a6c-d1cb07ec2aab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
