INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94825, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "独自是自己一个人，没有别人。", "primary_collocate": null, "pronunciation": "dú zì", "ipa": "tu³⁵ tsɹ̩⁵¹", "syllable_count": 2, "sentences": [{"text": "他独自坐在窗边看书。", "target_word": "独自", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她独自一人走在回家的路上。", "target_word": "独自", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "晚上，爷爷独自在院子里坐着。", "target_word": "独自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我常常独自去公园走走。", "target_word": "独自", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他独自吃完了一大碗面。", "target_word": "独自", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈出差了，小明独自在家过了一晚。", "target_word": "独自", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他喜欢独自一个人安静地想事情。", "target_word": "独自", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨天，她独自撑着伞站在车站。", "target_word": "独自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小女孩独自留在教室里等妈妈。", "target_word": "独自", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人独自住在山里，已经十年了。", "target_word": "独自", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "獨自", "label": "繁体"}], "register": "中性", "sense_fingerprint": "自己一个人，身边没有别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59c51a76-670c-44fa-8b2f-c5c9944b2429') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94825, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "独自", "is_correct": true, "explanation": "正确：独自（dú zì），指自己一个人，没有别人。"}, {"text": "独子", "is_correct": false, "explanation": "zǐ（第三声）与 zì（第四声）声调不同，独子指家里唯一的儿子。"}, {"text": "独资", "is_correct": false, "explanation": "zī（第一声）与 zì（第四声）声调不同，独资指由一方全部出资。"}, {"text": "肚子", "is_correct": false, "explanation": "dùzi 与 dú zì 声调不同（dù 为第四声，zi 为轻声），肚子指腹部。"}, {"text": "赌资", "is_correct": false, "explanation": "dǔ（第三声）与 dú（第二声）声调不同，zī 与 zì 声调也不同，赌资指赌博用的钱。"}], "explanations": {"独自": "正确：独自（dú zì），指自己一个人，没有别人。", "独子": "zǐ（第三声）与 zì（第四声）声调不同，独子指家里唯一的儿子。", "独资": "zī（第一声）与 zì（第四声）声调不同，独资指由一方全部出资。", "肚子": "dùzi 与 dú zì 声调不同（dù 为第四声，zi 为轻声），肚子指腹部。", "赌资": "dǔ（第三声）与 dú（第二声）声调不同，zī 与 zì 声调也不同，赌资指赌博用的钱。"}, "sentence_index": null, "correct_answer": "独自"}, "level_3": {"options": [{"text": "独自", "is_correct": true, "explanation": "独自：副词，表示自己一个人，与“他坐在窗边看书”的情况相符。"}, {"text": "一起", "is_correct": false, "explanation": "配价：“一起”需要多人共同参与，句中只有“他”一人，无法说一起坐。"}, {"text": "大声", "is_correct": false, "explanation": "搭配：“大声”修饰说话、喊叫，不能修饰“坐”，“大声坐着看书”不通。"}, {"text": "陆续", "is_correct": false, "explanation": "语义：“陆续”表示接连不断、一个接一个，与“他坐在窗边看书”这一次性的动作不符。"}], "explanations": {"独自": "独自：副词，表示自己一个人，与“他坐在窗边看书”的情况相符。", "一起": "配价：“一起”需要多人共同参与，句中只有“他”一人，无法说一起坐。", "大声": "搭配：“大声”修饰说话、喊叫，不能修饰“坐”，“大声坐着看书”不通。", "陆续": "语义：“陆续”表示接连不断、一个接一个，与“他坐在窗边看书”这一次性的动作不符。"}, "sentence_index": 0, "correct_answer": "独自"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我常常和朋友独自去公园走走。", "explanation": "这里应该用〈一起〉。独自表示只有自己一个人，句中“和朋友”说明有同行的人，二者矛盾。"}, {"text": "我们独自去公园散步吧。", "explanation": "这里应该用〈一起〉。独自只能指一个人，“我们”指多人，应说“一起”。"}, {"text": "周末我常常独自合影留念。", "explanation": "这里应该用〈一起〉。“合影”需要多人一起拍照，不能与“独自”搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34687fa6-00cd-48ee-851a-715f6055399c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94825, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "独自", "is_correct": true, "explanation": "正确：独自（dú zì），指自己一个人，没有别人。"}, {"text": "毒刺", "is_correct": false, "explanation": "cì 与 zì 声母不同（c 与 z），声调相同，毒刺指动植物身上带毒的刺。"}, {"text": "犊子", "is_correct": false, "explanation": "犊子读 dú zi，zi 为轻声，与 zì（第四声）不同；犊子指小牛。"}, {"text": "秃子", "is_correct": false, "explanation": "秃子读 tū zi，声母 t 与 d 不同，tū（第一声）与 dú（第二声）声调不同，zi 为轻声；秃子指没有头发的人。"}], "explanations": {"独自": "正确：独自（dú zì），指自己一个人，没有别人。", "毒刺": "cì 与 zì 声母不同（c 与 z），声调相同，毒刺指动植物身上带毒的刺。", "犊子": "犊子读 dú zi，zi 为轻声，与 zì（第四声）不同；犊子指小牛。", "秃子": "秃子读 tū zi，声母 t 与 d 不同，tū（第一声）与 dú（第二声）声调不同，zi 为轻声；秃子指没有头发的人。"}, "sentence_index": null, "correct_answer": "独自"}, "level_3": {"options": [{"text": "独自", "is_correct": true, "explanation": "独自：副词，表示只有自己一人，与“一个人”的说法一致。"}, {"text": "齐声", "is_correct": false, "explanation": "语义：“齐声”指多人同时发出声音，与“一个人”矛盾。"}, {"text": "大肆", "is_correct": false, "explanation": "搭配：“大肆”多修饰宣传、破坏一类行为，不能修饰“想事情”。"}, {"text": "一齐", "is_correct": false, "explanation": "配价：“一齐”要求多个主体同时行动，句中只有“他”一人。"}], "explanations": {"独自": "独自：副词，表示只有自己一人，与“一个人”的说法一致。", "齐声": "语义：“齐声”指多人同时发出声音，与“一个人”矛盾。", "大肆": "搭配：“大肆”多修饰宣传、破坏一类行为，不能修饰“想事情”。", "一齐": "配价：“一齐”要求多个主体同时行动，句中只有“他”一人。"}, "sentence_index": 6, "correct_answer": "独自"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老人和儿子独自住在山里，已经十年了。", "explanation": "这里应该用〈一起〉。“和儿子”说明有同住的人，独自表示只有老人一人，二者矛盾。"}, {"text": "老两口独自住在山里，已经十年了。", "explanation": "这里应该用〈一起〉。“老两口”指两个人，独自只能用于一个人。"}, {"text": "老人每年都独自聚会，已经十年了。", "explanation": "这里应该用〈一起〉。“聚会”指多人相聚，不能与“独自”搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34687fa6-00cd-48ee-851a-715f6055399c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94825, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她在房间里独自了整理照片。", "corrected_sentence": "她在房间里独自整理照片。", "error_description": "错误：“了”放在了副词“独自”和动词“整理”之间。“独自”后应直接接动词，应说“独自整理照片”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34687fa6-00cd-48ee-851a-715f6055399c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94825, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她很独自在山边的小屋里写信。", "corrected_sentence": "她独自在山边的小屋里写信。", "error_description": "错误：在“独自”前加了程度副词“很”。正确：“独自”本身是副词，不能再受“很”修饰，应说“她独自在山边的小屋里写信”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34687fa6-00cd-48ee-851a-715f6055399c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
