INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94828, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用泥土烧制成的、覆盖屋顶用的建筑材料。", "primary_collocate": null, "pronunciation": "wǎ", "ipa": "wa˨˩˦", "syllable_count": 1, "sentences": [{"text": "瓦是用泥土烧成的。", "target_word": "瓦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种瓦很结实，下雨不漏水。", "target_word": "瓦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里有一家工厂专门烧瓦。", "target_word": "瓦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要买一千片瓦盖新房子。", "target_word": "瓦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把新瓦一片一片放到屋顶上。", "target_word": "瓦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老房子的瓦旧了，得换新瓦。", "target_word": "瓦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红瓦白墙的小房子很好看。", "target_word": "瓦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在很多人用钢板，不用瓦盖房子了。", "target_word": "瓦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在山边的小厂里学烧瓦。", "target_word": "瓦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅用泥做瓦，再放进火里烧。", "target_word": "瓦", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "片", "label": "量词"}, {"form": "块", "label": "量词"}, {"form": "瓦片", "label": "复合词"}], "register": "通用", "sense_fingerprint": "瓦：用泥土烧成、盖屋顶用的建筑材料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecab3b97-f3d7-4c95-a0b9-3d6f706e958c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94828, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "瓦", "is_correct": true, "explanation": "正确：瓦（wǎ），用泥土烧成、盖屋顶的建筑材料。"}, {"text": "蛙", "is_correct": false, "explanation": "wā（第一声）与 wǎ（第三声）声调不同，意思是青蛙。"}, {"text": "娃", "is_correct": false, "explanation": "wá（第二声）与 wǎ（第三声）声调不同，意思是娃娃。"}, {"text": "晚", "is_correct": false, "explanation": "wǎn（第三声）比 wǎ 多一个韵尾 n，意思是晚上。"}, {"text": "我", "is_correct": false, "explanation": "wǒ（第三声）与 wǎ（第三声）韵母不同（o 与 a），意思是我。"}], "explanations": {"瓦": "正确：瓦（wǎ），用泥土烧成、盖屋顶的建筑材料。", "蛙": "wā（第一声）与 wǎ（第三声）声调不同，意思是青蛙。", "娃": "wá（第二声）与 wǎ（第三声）声调不同，意思是娃娃。", "晚": "wǎn（第三声）比 wǎ 多一个韵尾 n，意思是晚上。", "我": "wǒ（第三声）与 wǎ（第三声）韵母不同（o 与 a），意思是我。"}, "sentence_index": null, "correct_answer": "瓦"}, "level_3": {"options": [{"text": "瓦", "is_correct": true, "explanation": "瓦：用泥土烧成的建筑材料，符合句意。"}, {"text": "木头", "is_correct": false, "explanation": "语义：“木头”是树木砍成的材料，不是用泥土烧成的。"}, {"text": "布", "is_correct": false, "explanation": "搭配：“烧成”用于陶瓷、砖瓦一类，不说烧布。"}, {"text": "面包", "is_correct": false, "explanation": "搭配：面包用“烤”制作，不说“烧成”。"}], "explanations": {"瓦": "瓦：用泥土烧成的建筑材料，符合句意。", "木头": "语义：“木头”是树木砍成的材料，不是用泥土烧成的。", "布": "搭配：“烧成”用于陶瓷、砖瓦一类，不说烧布。", "面包": "搭配：面包用“烤”制作，不说“烧成”。"}, "sentence_index": 0, "correct_answer": "瓦"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人在山上采了一千片瓦。", "explanation": "这里应该用〈石头〉。瓦是烧制成的，不能从山上采，采的是石头。"}, {"text": "他用一片瓦擦汗。", "explanation": "这里应该用〈毛巾〉。瓦是烧制的建材，擦汗要用毛巾。"}, {"text": "这扇窗是用瓦做的。", "explanation": "这里应该用〈玻璃〉。瓦是烧成的屋顶材料，窗子要用玻璃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac21c432-ba06-4bde-be5a-b3bcdaf2db26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94828, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "瓦", "is_correct": true, "explanation": "正确：瓦（wǎ），用泥土烧成、盖屋顶的建筑材料。"}, {"text": "挖", "is_correct": false, "explanation": "wā（第一声）与 wǎ（第三声）声调不同，意思是挖。"}, {"text": "袜", "is_correct": false, "explanation": "wà（第四声）与 wǎ（第三声）声调不同，意思是袜子。"}, {"text": "往", "is_correct": false, "explanation": "wǎng（第三声）比 wǎ 多一个韵尾 ng，意思是朝、向。"}, {"text": "五", "is_correct": false, "explanation": "wǔ（第三声）与 wǎ（第三声）韵母不同（u 与 a），意思是数字五。"}], "explanations": {"瓦": "正确：瓦（wǎ），用泥土烧成、盖屋顶的建筑材料。", "挖": "wā（第一声）与 wǎ（第三声）声调不同，意思是挖。", "袜": "wà（第四声）与 wǎ（第三声）声调不同，意思是袜子。", "往": "wǎng（第三声）比 wǎ 多一个韵尾 ng，意思是朝、向。", "五": "wǔ（第三声）与 wǎ（第三声）韵母不同（u 与 a），意思是数字五。"}, "sentence_index": null, "correct_answer": "瓦"}, "level_3": {"options": [{"text": "瓦", "is_correct": true, "explanation": "瓦：红色的屋顶瓦片，与“白墙”搭配，符合句意。"}, {"text": "酒", "is_correct": false, "explanation": "语义：“酒”是饮品，“红酒白墙的小房子”说不通。"}, {"text": "鞋", "is_correct": false, "explanation": "语义：“鞋”是穿在脚上的，不是房子的材料。"}, {"text": "笔", "is_correct": false, "explanation": "语义：“笔”是写字用的，与屋顶和白墙无关。"}], "explanations": {"瓦": "瓦：红色的屋顶瓦片，与“白墙”搭配，符合句意。", "酒": "语义：“酒”是饮品，“红酒白墙的小房子”说不通。", "鞋": "语义：“鞋”是穿在脚上的，不是房子的材料。", "笔": "语义：“笔”是写字用的，与屋顶和白墙无关。"}, "sentence_index": 6, "correct_answer": "瓦"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座桥是用瓦建成的。", "explanation": "这里应该用〈钢〉。瓦是烧制的建材，建桥要用钢。"}, {"text": "这本书是用瓦印的。", "explanation": "这里应该用〈纸〉。瓦不能用来印书，印书要用纸。"}, {"text": "这把椅子是用瓦做的。", "explanation": "这里应该用〈木头〉。瓦是烧制的屋顶材料，做椅子要用木头。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac21c432-ba06-4bde-be5a-b3bcdaf2db26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.