INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94833, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "发育是小孩身体一点一点长大。", "primary_collocate": null, "pronunciation": "fā yù", "ipa": "fa˥ y˥˩", "syllable_count": 2, "sentences": [{"text": "这个孩子发育得很好。", "target_word": "发育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "男孩十三岁左右开始发育。", "target_word": "发育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多吃鸡蛋和牛奶，有助于孩子发育。", "target_word": "发育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的身体发育比同学快。", "target_word": "发育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子睡得好，发育才会好。", "target_word": "发育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说他发育得有点慢。", "target_word": "发育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女孩子十一岁就开始发育了。", "target_word": "发育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他个子小，是因为还没有发育。", "target_word": "发育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子正在发育，每天要吃好。", "target_word": "发育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈很担心女儿发育不好。", "target_word": "发育", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "发育期", "label": "复合词"}, {"form": "发育不良", "label": "否定"}], "register": "中性", "sense_fingerprint": "孩子的身体慢慢长大成熟", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c88eb55d-87b9-4467-ab1d-de538215c096') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94833, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "发育", "is_correct": true, "explanation": "发育（fā yù）指孩子身体一点一点长大，是正确答案。"}, {"text": "法语", "is_correct": false, "explanation": "fǎ（第三声）与 fā（第一声）声调不同，yǔ 与 yù 声调也不同，意思是“法语”。"}, {"text": "富裕", "is_correct": false, "explanation": "fù 与 fā 韵母不同（u 与 a），yù 相同，意思是“富裕”。"}, {"text": "抚育", "is_correct": false, "explanation": "fǔ 与 fā 韵母不同（u 与 a），yù 相同，意思是“抚养培育”。"}], "explanations": {"发育": "发育（fā yù）指孩子身体一点一点长大，是正确答案。", "法语": "fǎ（第三声）与 fā（第一声）声调不同，yǔ 与 yù 声调也不同，意思是“法语”。", "富裕": "fù 与 fā 韵母不同（u 与 a），yù 相同，意思是“富裕”。", "抚育": "fǔ 与 fā 韵母不同（u 与 a），yù 相同，意思是“抚养培育”。"}, "sentence_index": null, "correct_answer": "发育"}, "level_3": {"options": [{"text": "发育", "is_correct": true, "explanation": "“发育”指孩子身体逐渐长成熟，与“得很好”搭配。"}, {"text": "融化", "is_correct": false, "explanation": "语义：孩子不会融化，“融化”只用于冰雪等物质。"}, {"text": "腐烂", "is_correct": false, "explanation": "语义：“腐烂”指食物或物体变质，不说孩子腐烂。"}, {"text": "凝固", "is_correct": false, "explanation": "配价：“凝固”的主语是液体等物质，不能用于“这个孩子”。"}], "explanations": {"发育": "“发育”指孩子身体逐渐长成熟，与“得很好”搭配。", "融化": "语义：孩子不会融化，“融化”只用于冰雪等物质。", "腐烂": "语义：“腐烂”指食物或物体变质，不说孩子腐烂。", "凝固": "配价：“凝固”的主语是液体等物质，不能用于“这个孩子”。"}, "sentence_index": 0, "correct_answer": "发育"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他这一年发育了十厘米。", "explanation": "这里应该用〈长高〉。发育指身体逐渐成熟，不能说“发育了十厘米”。"}, {"text": "她这个月发育了三公斤。", "explanation": "这里应该用〈变胖〉。发育指身体逐渐成熟，不表示体重增加；体重增加要说“变胖”。"}, {"text": "他的头发最近发育得很快。", "explanation": "这里应该用〈长〉。发育指身体器官逐渐成熟，头发变长要用“长”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b5e7af-0dbd-4dff-b509-1d0c08d0bf16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94833, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发育", "is_correct": true, "explanation": "“发育”指身体逐渐成熟，“开始发育”指青春期身体的变化。"}, {"text": "退休", "is_correct": false, "explanation": "语义：十一岁的孩子不会退休，“退休”指年老后停止工作。"}, {"text": "离职", "is_correct": false, "explanation": "语义：“离职”指离开工作岗位，与十一岁的孩子不合。"}, {"text": "辞职", "is_correct": false, "explanation": "搭配：“辞职”要求有工作的人，不说“十一岁就辞职”。"}], "explanations": {"发育": "“发育”指身体逐渐成熟，“开始发育”指青春期身体的变化。", "退休": "语义：十一岁的孩子不会退休，“退休”指年老后停止工作。", "离职": "语义：“离职”指离开工作岗位，与十一岁的孩子不合。", "辞职": "搭配：“辞职”要求有工作的人，不说“十一岁就辞职”。"}, "sentence_index": 6, "correct_answer": "发育"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的伤口发育得很快。", "explanation": "这里应该用〈愈合〉。发育指身体成长成熟，伤口复原要用愈合。"}, {"text": "他生病后，体温发育得很快。", "explanation": "这里应该用〈升高〉。发育指身体器官的成长，体温上升要用“升高”。"}, {"text": "老人的身体发育得很快。", "explanation": "这里应该用〈退化〉。发育指成长变成熟，老人身体衰退要用退化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b5e7af-0dbd-4dff-b509-1d0c08d0bf16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94833, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个男孩发育的很快。", "corrected_sentence": "这个男孩发育得很快。", "error_description": "补语标记错误：“发育”后引出补语应用“得”，应说“发育得很快”，不说“发育的很快”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b5e7af-0dbd-4dff-b509-1d0c08d0bf16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94833, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她发育了不好，所以个子很矮。", "corrected_sentence": "她发育不好，所以个子很矮。", "error_description": "了的位置错误：“发育不好”中“发育”后不能加“了”，应说“她发育不好”，不说“她发育了不好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b5e7af-0dbd-4dff-b509-1d0c08d0bf16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
