INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94834, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "生物体在生长过程中，器官、机能逐渐成熟。", "primary_collocate": null, "pronunciation": "fā yù", "ipa": "fa˥ y˥˩", "syllable_count": 2, "sentences": [{"text": "小鸡在蛋里慢慢发育。", "target_word": "发育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种花发育得很慢。", "target_word": "发育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天到了，树上的果子开始发育。", "target_word": "发育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鱼的眼睛先发育，然后是身体。", "target_word": "发育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大脑要到二十几岁才发育成熟。", "target_word": "发育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "种子在土里发育成小苗。", "target_word": "发育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小马出生后，骨头继续发育。", "target_word": "发育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只小狗发育不好，所以很瘦。", "target_word": "发育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小蝌蚪在水里发育成青蛙。", "target_word": "发育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气太冷，这些小鸟发育得很慢。", "target_word": "发育", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "发育期", "label": "复合词"}, {"form": "发育不良", "label": "否定"}], "register": "中性", "sense_fingerprint": "动植物的器官、机能逐渐成熟", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c88eb55d-87b9-4467-ab1d-de538215c096') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94834, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "发育", "is_correct": true, "explanation": "发育（fā yù）指生物的器官和机能逐渐成熟，是正确答案。"}, {"text": "法语", "is_correct": false, "explanation": "fǎ（第三声）与 fā（第一声）声调不同，yǔ 与 yù 声调也不同，意思是“法语”。"}, {"text": "富裕", "is_correct": false, "explanation": "fù 与 fā 韵母不同（u 与 a），yù 相同，意思是“富裕”。"}, {"text": "抚育", "is_correct": false, "explanation": "fǔ 与 fā 韵母不同（u 与 a），yù 相同，意思是“抚养培育”。"}], "explanations": {"发育": "发育（fā yù）指生物的器官和机能逐渐成熟，是正确答案。", "法语": "fǎ（第三声）与 fā（第一声）声调不同，yǔ 与 yù 声调也不同，意思是“法语”。", "富裕": "fù 与 fā 韵母不同（u 与 a），yù 相同，意思是“富裕”。", "抚育": "fǔ 与 fā 韵母不同（u 与 a），yù 相同，意思是“抚养培育”。"}, "sentence_index": null, "correct_answer": "发育"}, "level_3": {"options": [{"text": "发育", "is_correct": true, "explanation": "“发育”指小鸡体内器官逐渐成熟，与“小鸡在蛋里”相合。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：小鸡在蛋里不会唱歌，唱歌与生长的过程不合。"}, {"text": "跑步", "is_correct": false, "explanation": "搭配：蛋里的小鸡还不能跑步，“跑步”不搭配“在蛋里”。"}, {"text": "飞行", "is_correct": false, "explanation": "语义：蛋里的小鸡不能飞行，“飞行”指在空中移动，与“在蛋里”冲突。"}], "explanations": {"发育": "“发育”指小鸡体内器官逐渐成熟，与“小鸡在蛋里”相合。", "唱歌": "语义：小鸡在蛋里不会唱歌，唱歌与生长的过程不合。", "跑步": "搭配：蛋里的小鸡还不能跑步，“跑步”不搭配“在蛋里”。", "飞行": "语义：蛋里的小鸡不能飞行，“飞行”指在空中移动，与“在蛋里”冲突。"}, "sentence_index": 0, "correct_answer": "发育"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "冰块慢慢发育成水。", "explanation": "这里应该用〈融化〉。发育只用于生物的成长，冰受热变水要用融化。"}, {"text": "落叶慢慢发育成土。", "explanation": "这里应该用〈分解〉。发育用于生物的成长，落叶变成泥土要用分解。"}, {"text": "铁钉在潮湿的空气里发育了。", "explanation": "这里应该用〈生锈〉。发育用于生物的成长，铁器氧化要用生锈。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b5e7af-0dbd-4dff-b509-1d0c08d0bf16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94834, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发育", "is_correct": true, "explanation": "“发育”指骨骼等器官的成长，“继续发育”说的是骨头仍在成长。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：骨头不会跳舞，“跳舞”需要能做动作的人。"}, {"text": "写字", "is_correct": false, "explanation": "搭配：“写字”需要手和笔，不能用于“骨头继续”。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：骨头不会游泳，“游泳”指人或动物在水中活动。"}], "explanations": {"发育": "“发育”指骨骼等器官的成长，“继续发育”说的是骨头仍在成长。", "跳舞": "语义：骨头不会跳舞，“跳舞”需要能做动作的人。", "写字": "搭配：“写字”需要手和笔，不能用于“骨头继续”。", "游泳": "语义：骨头不会游泳，“游泳”指人或动物在水中活动。"}, "sentence_index": 6, "correct_answer": "发育"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "岩石在风里慢慢发育。", "explanation": "这里应该用〈风化〉。发育指生物的成长，岩石受风雨侵蚀要用风化。"}, {"text": "房子慢慢发育了。", "explanation": "这里应该用〈倒塌〉。发育只说生物的成长，房屋毁坏要用倒塌。"}, {"text": "木头在潮湿的地方慢慢发育。", "explanation": "这里应该用〈腐烂〉。发育是生物的成长，木头腐坏要用腐烂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b5e7af-0dbd-4dff-b509-1d0c08d0bf16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
