INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94834, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些树苗发育了不好，长得很细。", "corrected_sentence": "这些树苗发育不好，长得很细。", "error_description": "了的位置错误：“发育不好”中“发育”后不能加“了”，应说“这些树苗发育不好”，不说“这些树苗发育了不好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b5e7af-0dbd-4dff-b509-1d0c08d0bf16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
