INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94835, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "破产是钱全都没有了，店开不下去。", "primary_collocate": null, "pronunciation": "pò chǎn", "ipa": "pʰwo˥˩ ʈʂʰan˨˩˦", "syllable_count": 2, "sentences": [{"text": "我家的小店没有钱了，破产了。", "target_word": "破产", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的饭馆生意不好，上个月破产了。", "target_word": "破产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友的书店破产了，他很难过。", "target_word": "破产", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "钱都花完了，小公司只能破产。", "target_word": "破产", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家商店破产后，老板去别的城市工作了。", "target_word": "破产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我很怕自己的店有一天会破产。", "target_word": "破产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家小餐厅的钱全花光了，只能破产。", "target_word": "破产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没人来买东西，面包店很快就破产了。", "target_word": "破产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说那家老店破产了，大家都很吃惊。", "target_word": "破产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生意越来越差，老板怕店要破产。", "target_word": "破产", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "破产了", "label": "体标"}, {"form": "破产过", "label": "体标"}, {"form": "破产法", "label": "复合"}, {"form": "破產", "label": "繁体"}], "register": "中性", "sense_fingerprint": "钱全没了，店或生意再也开不下去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3101b179-ea35-4787-b575-d3c8af1182ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94835, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "破产", "is_correct": true, "explanation": "破产指店铺钱全没了、开不下去，与“没有钱了”的语境相符。"}, {"text": "发财", "is_correct": false, "explanation": "语义：没有钱就不可能发财，与前句矛盾。"}, {"text": "唱歌", "is_correct": false, "explanation": "配价：小店不能唱歌，“唱歌”要求人作主语。"}, {"text": "旅游", "is_correct": false, "explanation": "语义：没有钱与旅游无关，句意不通。"}], "explanations": {"破产": "破产指店铺钱全没了、开不下去，与“没有钱了”的语境相符。", "发财": "语义：没有钱就不可能发财，与前句矛盾。", "唱歌": "配价：小店不能唱歌，“唱歌”要求人作主语。", "旅游": "语义：没有钱与旅游无关，句意不通。"}, "sentence_index": 0, "correct_answer": "破产"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家店因为装修破产了三天。", "explanation": "这里应该用〈关门〉。破产指店铺永久失去财产、无法经营，不能表示暂时关门。"}, {"text": "我的手机没电了，破产了。", "explanation": "这里应该用〈关机〉。破产指店铺或个人失去全部财产，手机没电不能说“破产”。"}, {"text": "这台冰箱破产了，不能用了。", "explanation": "这里应该用〈坏〉。破产只用于店铺或个人的财产，不能用来说冰箱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16f75cd7-34c5-4e6d-8efa-ea9e49b7dc17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94835, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "破产", "is_correct": true, "explanation": "破产指店铺钱全花光、开不下去，与“钱全花光了，只能……”的语境相符。"}, {"text": "结婚", "is_correct": false, "explanation": "配价：餐厅不能结婚，“结婚”的主语只能是人。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：钱花光了却去跳舞，句意不通。"}, {"text": "扩张", "is_correct": false, "explanation": "语义：没有钱就谈不上扩张，与“钱全花光了”的语境矛盾。"}], "explanations": {"破产": "破产指店铺钱全花光、开不下去，与“钱全花光了，只能……”的语境相符。", "结婚": "配价：餐厅不能结婚，“结婚”的主语只能是人。", "跳舞": "语义：钱花光了却去跳舞，句意不通。", "扩张": "语义：没有钱就谈不上扩张，与“钱全花光了”的语境矛盾。"}, "sentence_index": 6, "correct_answer": "破产"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座桥破产了，车不能过。", "explanation": "这里应该用〈倒塌〉。破产只用于企业或个人的财产，桥不能破产，应说“倒塌”。"}, {"text": "老人的身体破产了，常常生病。", "explanation": "这里应该说〈不好〉。破产只指经济上失去全部财产，身体差应说“身体不好”。"}, {"text": "他的学习破产了，成绩很差。", "explanation": "这里应该用〈退步〉。破产只指经济上失去全部财产，学习变差应说“退步”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16f75cd7-34c5-4e6d-8efa-ea9e49b7dc17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94835, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的面包店没有生意了，最后被破产了。", "corrected_sentence": "他的面包店没有生意了，最后破产了。", "error_description": "被字句错误：“破产”是不及物动词，不能和“被”构成被动句。应改为“最后破产了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16f75cd7-34c5-4e6d-8efa-ea9e49b7dc17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94835, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家面包店以前破产了过，后来又开了。", "corrected_sentence": "这家面包店以前破产过，后来又开了。", "error_description": "错误：“破产了过”；正确：“破产过”。表示经历只用“过”，不能与“了”连用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16f75cd7-34c5-4e6d-8efa-ea9e49b7dc17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
