INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94836, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16f75cd7-34c5-4e6d-8efa-ea9e49b7dc17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94836, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "企业或个人因无力偿还债务而丧失全部财产。", "primary_collocate": null, "pronunciation": "pò chǎn", "ipa": "pʰwo˥˩ ʈʂʰan˨˩˦", "syllable_count": 2, "sentences": [{"text": "这家公司欠了很多钱，最后破产了。", "target_word": "破产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生意失败，欠了银行很多钱，已经破产。", "target_word": "破产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年有三家工厂破产。", "target_word": "破产", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板还不了债，只好让公司破产。", "target_word": "破产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的大银行一夜之间破产了。", "target_word": "破产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他曾经破产过，现在又开了新公司。", "target_word": "破产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济不好，很多小公司都破产了。", "target_word": "破产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司破产后，工人们都没有工作了。", "target_word": "破产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的店欠债太多，马上就要破产了。", "target_word": "破产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行说，这家公司已经申请破产。", "target_word": "破产", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "破产了", "label": "体标"}, {"form": "破产过", "label": "体标"}, {"form": "破产法", "label": "复合"}, {"form": "破產", "label": "繁体"}], "register": "中性", "sense_fingerprint": "企业或个人还不了债而失去全部财产", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3101b179-ea35-4787-b575-d3c8af1182ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94836, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "破产", "is_correct": true, "explanation": "破产指企业因还不起债而失去全部财产，与前句“欠了很多钱”的语境相符。"}, {"text": "结婚", "is_correct": false, "explanation": "配价：公司不能结婚，“结婚”的主语只能是人。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：欠债与唱歌无关，句意不通。"}, {"text": "散步", "is_correct": false, "explanation": "搭配：公司不能散步，“散步”一般只用于人。"}], "explanations": {"破产": "破产指企业因还不起债而失去全部财产，与前句“欠了很多钱”的语境相符。", "结婚": "配价：公司不能结婚，“结婚”的主语只能是人。", "唱歌": "语义：欠债与唱歌无关，句意不通。", "散步": "搭配：公司不能散步，“散步”一般只用于人。"}, "sentence_index": 0, "correct_answer": "破产"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家店每天都破产。", "explanation": "这里应该用〈营业〉。破产指企业或个人永久失去全部财产、无法继续经营，不能用来说每天都在发生的事，应说“每天都营业”。"}, {"text": "这家店因为疫情破产了一个月。", "explanation": "这里应该用〈停业〉。破产是永久失去全部财产，不能表示暂时关门，应说“停业了一个月”。"}, {"text": "他在路上破产了一百块钱。", "explanation": "这里应该用〈丢〉。破产指企业或个人因还不起债而失去全部财产，不能用来说丢了一点钱，应说“丢了一百块钱”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16f75cd7-34c5-4e6d-8efa-ea9e49b7dc17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94836, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "破产", "is_correct": true, "explanation": "破产指企业或个人失去全部财产，与“经济不好”的语境相符。"}, {"text": "旅游", "is_correct": false, "explanation": "语义：经济不好与旅游无关，句意矛盾。"}, {"text": "跳舞", "is_correct": false, "explanation": "配价：小公司不能跳舞，“跳舞”的主语须是人。"}, {"text": "生孩子", "is_correct": false, "explanation": "配价：公司不能生孩子，“生”的主语只能是人。"}], "explanations": {"破产": "破产指企业或个人失去全部财产，与“经济不好”的语境相符。", "旅游": "语义：经济不好与旅游无关，句意矛盾。", "跳舞": "配价：小公司不能跳舞，“跳舞”的主语须是人。", "生孩子": "配价：公司不能生孩子，“生”的主语只能是人。"}, "sentence_index": 6, "correct_answer": "破产"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台电脑破产了，不能用了。", "explanation": "这里应该用〈坏〉。破产只用于企业或个人的财产，不能用来说机器，应说“坏了”。"}, {"text": "这棵树因为干旱破产了。", "explanation": "这里应该用〈枯死〉。破产只用于企业或个人的财产，树因干旱应说“枯死”。"}, {"text": "这条裤子穿了很多年，已经破产了。", "explanation": "这里应该用〈破〉。破产只指企业或个人在经济上失去全部财产，不能用来说衣服旧了、坏了，应说“已经破了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16f75cd7-34c5-4e6d-8efa-ea9e49b7dc17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94836, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的工厂因为欠债太多，最后被破产了。", "corrected_sentence": "他的工厂因为欠债太多，最后破产了。", "error_description": "被字句错误：“破产”是不及物动词，不能和“被”构成被动句。应改为“最后破产了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16f75cd7-34c5-4e6d-8efa-ea9e49b7dc17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94836, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家老店曾经破产了过，后来又重新开业了。", "corrected_sentence": "这家老店曾经破产过，后来又重新开业了。", "error_description": "体标错误：“曾经……过”表示经历过某事，“了”与“过”不能同用。应改为“破产过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16f75cd7-34c5-4e6d-8efa-ea9e49b7dc17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
