INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94839, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "移是把东西从这里搬到那里。", "primary_collocate": null, "pronunciation": "yí", "ipa": "i˧˥", "syllable_count": 1, "sentences": [{"text": "请把这份文件移到另一个文件夹里。", "target_word": "移", "complexity_tier": "T3", "furigana": "qǐng bǎ zhè fèn wén jiàn yí dào lìng yí gè wén jiàn jiā lǐ", "sentence_source": "generated"}, {"text": "他把照片从电脑移到了手机里。", "target_word": "移", "complexity_tier": "T3", "furigana": "tā bǎ zhào piàn cóng diàn nǎo yí dào le shǒu jī lǐ", "sentence_source": "generated"}, {"text": "我把没用的草稿移走，电脑就快多了。", "target_word": "移", "complexity_tier": "T3", "furigana": "wǒ bǎ méi yòng de cǎo gǎo yí zǒu diàn nǎo jiù kuài duō le", "sentence_source": "generated"}, {"text": "他把下载的软件移到了另一块硬盘里。", "target_word": "移", "complexity_tier": "T3", "furigana": "tā bǎ xià zǎi de ruǎn jiàn yí dào le lìng yí kuài yìng pán lǐ", "sentence_source": "generated"}, {"text": "他把邮件移到了垃圾箱。", "target_word": "移", "complexity_tier": "T3", "furigana": "tā bǎ yóu jiàn yí dào le lā jī xiāng", "sentence_source": "generated"}, {"text": "老师让我们把表格移到共享文件夹里。", "target_word": "移", "complexity_tier": "T3", "furigana": "lǎo shī ràng wǒ men bǎ biǎo gé yí dào gòng xiǎng wén jiàn jiā lǐ", "sentence_source": "generated"}, {"text": "他想把这棵小树移到别的地方去。", "target_word": "移", "complexity_tier": "T3", "furigana": "tā xiǎng bǎ zhè kē xiǎo shù yí dào bié de dì fang qù", "sentence_source": "generated"}, {"text": "请你把这张图片移到桌面上。", "target_word": "移", "complexity_tier": "T3", "furigana": "qǐng nǐ bǎ zhè zhāng tú piàn yí dào zhuō miàn shàng", "sentence_source": "generated"}, {"text": "他们把旧数据都移到了新服务器。", "target_word": "移", "complexity_tier": "T3", "furigana": "tā men bǎ jiù shù jù dōu yí dào le xīn fú wù qì", "sentence_source": "generated"}, {"text": "她把备份从旧电脑移到了新硬盘里。", "target_word": "移", "complexity_tier": "T3", "furigana": "tā bǎ bèi fèn cóng jiù diàn nǎo yí dào le xīn yìng pán lǐ", "sentence_source": "generated"}], "morphological_forms": [{"form": "移了", "label": "体标"}, {"form": "移过", "label": "体标"}, {"form": "移走", "label": "复合"}, {"form": "移到", "label": "复合"}], "register": "中性", "sense_fingerprint": "把东西从一个地方搬到另一个地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f81bc4bc-44c8-4cf6-a5b7-596f28b237e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94839, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "移", "is_correct": true, "explanation": "正确：移，yí（第二声），意思是把东西挪到别处。"}, {"text": "衣", "is_correct": false, "explanation": "「yī（第一声）与 yí（第二声）声调不同，意思是衣服」，与搬运无关。"}, {"text": "椅", "is_correct": false, "explanation": "「yǐ（第三声）与 yí（第二声）声调不同，意思是椅子」。"}, {"text": "易", "is_correct": false, "explanation": "「yì（第四声）与 yí（第二声）声调不同，意思是容易」。"}, {"text": "医", "is_correct": false, "explanation": "「yī（第一声）与 yí（第二声）声调不同，意思是医生或治疗」。"}], "explanations": {"移": "正确：移，yí（第二声），意思是把东西挪到别处。", "衣": "「yī（第一声）与 yí（第二声）声调不同，意思是衣服」，与搬运无关。", "椅": "「yǐ（第三声）与 yí（第二声）声调不同，意思是椅子」。", "易": "「yì（第四声）与 yí（第二声）声调不同，意思是容易」。", "医": "「yī（第一声）与 yí（第二声）声调不同，意思是医生或治疗」。"}, "sentence_index": null, "correct_answer": "移"}, "level_3": {"options": [{"text": "移", "is_correct": true, "explanation": "正确：“把文件移到另一个文件夹里”表示把文件从一处搬到另一处。"}, {"text": "删除", "is_correct": false, "explanation": "语义：删除是去掉文件，与“放到另一个文件夹里”的挪动相矛盾。"}, {"text": "复印", "is_correct": false, "explanation": "搭配：“复印”产生副本，不能接“到文件夹里”表示挪动。"}, {"text": "打印", "is_correct": false, "explanation": "搭配：“打印”是输出纸质文件，不能说“打印到文件夹里”。"}], "explanations": {"移": "正确：“把文件移到另一个文件夹里”表示把文件从一处搬到另一处。", "删除": "语义：删除是去掉文件，与“放到另一个文件夹里”的挪动相矛盾。", "复印": "搭配：“复印”产生副本，不能接“到文件夹里”表示挪动。", "打印": "搭配：“打印”是输出纸质文件，不能说“打印到文件夹里”。"}, "sentence_index": 0, "correct_answer": "移"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把作业移给了老师。", "explanation": "这里应该用〈交〉。“移”指把东西挪到某处，不表示交付给别人，交作业要用“交”。"}, {"text": "妈妈每天把我移到学校门口。", "explanation": "这里应该用〈送〉。“移”用于挪动物品，接送人要用“送”。"}, {"text": "他把牛奶移进了杯子里。", "explanation": "这里应该用〈倒〉。“移”指挪动物体，把牛奶倒进杯子要用“倒”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00f0bd82-ed93-4eb3-873e-652b9b4bc670') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94839, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "移", "is_correct": true, "explanation": "正确：移，yí（第二声），意思是把东西挪到别处。"}, {"text": "已", "is_correct": false, "explanation": "「yǐ（第三声）与 yí（第二声）声调不同，意思是已经」。"}, {"text": "以", "is_correct": false, "explanation": "「yǐ（第三声）与 yí（第二声）声调不同，意思是用、以为」。"}, {"text": "意", "is_correct": false, "explanation": "「yì（第四声）与 yí（第二声）声调不同，意思是意思、心意」。"}, {"text": "艺", "is_correct": false, "explanation": "「yì（第四声）与 yí（第二声）声调不同，意思是艺术、技艺」。"}], "explanations": {"移": "正确：移，yí（第二声），意思是把东西挪到别处。", "已": "「yǐ（第三声）与 yí（第二声）声调不同，意思是已经」。", "以": "「yǐ（第三声）与 yí（第二声）声调不同，意思是用、以为」。", "意": "「yì（第四声）与 yí（第二声）声调不同，意思是意思、心意」。", "艺": "「yì（第四声）与 yí（第二声）声调不同，意思是艺术、技艺」。"}, "sentence_index": null, "correct_answer": "移"}, "level_3": {"options": [{"text": "移", "is_correct": true, "explanation": "正确：“把这棵小树移到别的地方去”表示挪动小树的位置。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”接桌面、玻璃等，不能用于小树的位置移动。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不接树作宾语，不能说“吃到别的地方去”。"}, {"text": "画", "is_correct": false, "explanation": "语义：“画”的结果是图画，不能把树“画到”别处。"}], "explanations": {"移": "正确：“把这棵小树移到别的地方去”表示挪动小树的位置。", "擦": "搭配：“擦”接桌面、玻璃等，不能用于小树的位置移动。", "吃": "搭配：“吃”不接树作宾语，不能说“吃到别的地方去”。", "画": "语义：“画”的结果是图画，不能把树“画到”别处。"}, "sentence_index": 6, "correct_answer": "移"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她在会上移了一个新方案。", "explanation": "这里应该用〈提出〉。“移”只用于具体物品的挪动，不能用于抽象的方案。"}, {"text": "她把屋子移得很干净。", "explanation": "这里应该用〈收拾〉。“移”只表示挪动位置，不表示整理或清洁。"}, {"text": "他向朋友移了一本书。", "explanation": "这里应该用〈借〉。“移”指位置的挪动，不能用于借入或借出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00f0bd82-ed93-4eb3-873e-652b9b4bc670') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94839, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把照片移了新的文件夹里。", "corrected_sentence": "他把照片移到了新的文件夹里。", "error_description": "补语错误：表示地点要用补语“到”，应说“移到了新的文件夹里”，不能省略“到”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00f0bd82-ed93-4eb3-873e-652b9b4bc670') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94839, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把书架移了到窗边。", "corrected_sentence": "她把书架移到了窗边。", "error_description": "体标位置错误：“了”应放在补语“到”之后，应说“移到了窗边”，不能说“移了到窗边”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00f0bd82-ed93-4eb3-873e-652b9b4bc670') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
