INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94840, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00f0bd82-ed93-4eb3-873e-652b9b4bc670') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94840, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "改变位置，挪动。", "primary_collocate": null, "pronunciation": "yí", "ipa": "i˧˥", "syllable_count": 1, "sentences": [{"text": "请把椅子往左移一点。", "target_word": "移", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张桌子太重，我一个人移不开。", "target_word": "移", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把杯子移开，给我让出位置。", "target_word": "移", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳慢慢移到了山后面。", "target_word": "移", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "影子往右移了一点。", "target_word": "移", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的包挡路了，请移一下。", "target_word": "移", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他轻轻把门口的石头移开了。", "target_word": "移", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把灯向前移一点，我看不清。", "target_word": "移", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书架往墙边移了一下。", "target_word": "移", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把手移开，我要看屏幕。", "target_word": "移", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "移了", "label": "体标"}, {"form": "移过", "label": "体标"}, {"form": "移开", "label": "复合"}, {"form": "移一下", "label": "复合"}], "register": "中性", "sense_fingerprint": "位置稍稍改变，挪一挪", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f81bc4bc-44c8-4cf6-a5b7-596f28b237e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94840, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "移", "is_correct": true, "explanation": "正确：移，yí（第二声），意思是改变位置、挪一挪。"}, {"text": "椅", "is_correct": false, "explanation": "「yǐ（第三声）与 yí（第二声）声调不同，意思是椅子」。"}, {"text": "以", "is_correct": false, "explanation": "「yǐ（第三声）与 yí（第二声）声调不同，意思是用、以为」。"}, {"text": "艺", "is_correct": false, "explanation": "「yì（第四声）与 yí（第二声）声调不同，意思是艺术、技艺」。"}], "explanations": {"移": "正确：移，yí（第二声），意思是改变位置、挪一挪。", "椅": "「yǐ（第三声）与 yí（第二声）声调不同，意思是椅子」。", "以": "「yǐ（第三声）与 yí（第二声）声调不同，意思是用、以为」。", "艺": "「yì（第四声）与 yí（第二声）声调不同，意思是艺术、技艺」。"}, "sentence_index": null, "correct_answer": "移"}, "level_3": {"options": [{"text": "移", "is_correct": true, "explanation": "正确：“往左移一点”表示椅子稍稍向左挪动。"}, {"text": "切", "is_correct": false, "explanation": "搭配：“切”表示割开，不能表示椅子的位置挪动。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”与“椅子往左”无关，不能表示位移。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”不能用来描述椅子的位置变化。"}], "explanations": {"移": "正确：“往左移一点”表示椅子稍稍向左挪动。", "切": "搭配：“切”表示割开，不能表示椅子的位置挪动。", "唱": "语义：“唱”与“椅子往左”无关，不能表示位移。", "写": "搭配：“写”不能用来描述椅子的位置变化。"}, "sentence_index": 0, "correct_answer": "移"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "听到这个消息，他的脸色移了。", "explanation": "这里应该用〈变〉。“移”表示位置的挪动，不能表示脸色的改变，脸色变化要用“变”。"}, {"text": "他在钢琴上移了一首曲子。", "explanation": "这里应该用〈弹〉。“移”表示挪动，不能表示演奏乐器。"}, {"text": "他狠狠地移了一拳。", "explanation": "这里应该用〈打〉。“移”表示位置的挪动，不能表示用拳头击打，打人要用“打”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00f0bd82-ed93-4eb3-873e-652b9b4bc670') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94840, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "移", "is_correct": true, "explanation": "正确：移，yí（第二声），意思是改变位置、挪一挪。"}, {"text": "衣", "is_correct": false, "explanation": "「yī（第一声）与 yí（第二声）声调不同，意思是衣服」。"}, {"text": "意", "is_correct": false, "explanation": "「yì（第四声）与 yí（第二声）声调不同，意思是意思、心意」。"}, {"text": "医", "is_correct": false, "explanation": "「yī（第一声）与 yí（第二声）声调不同，意思是医生或治疗」。"}], "explanations": {"移": "正确：移，yí（第二声），意思是改变位置、挪一挪。", "衣": "「yī（第一声）与 yí（第二声）声调不同，意思是衣服」。", "意": "「yì（第四声）与 yí（第二声）声调不同，意思是意思、心意」。", "医": "「yī（第一声）与 yí（第二声）声调不同，意思是医生或治疗」。"}, "sentence_index": null, "correct_answer": "移"}, "level_3": {"options": [{"text": "移", "is_correct": true, "explanation": "正确：“轻轻把门口的石头移开了”表示把石头挪开。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮开”指把液体烧到沸腾，不能用于石头。"}, {"text": "撕", "is_correct": false, "explanation": "搭配：“撕开”用于纸张、包装袋，不能用于石头。"}, {"text": "烤", "is_correct": false, "explanation": "语义：“烤”是加热食物的动作，与石头无关，不能表示把石头挪开。"}], "explanations": {"移": "正确：“轻轻把门口的石头移开了”表示把石头挪开。", "煮": "搭配：“煮开”指把液体烧到沸腾，不能用于石头。", "撕": "搭配：“撕开”用于纸张、包装袋，不能用于石头。", "烤": "语义：“烤”是加热食物的动作，与石头无关，不能表示把石头挪开。"}, "sentence_index": 6, "correct_answer": "移"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她给孩子移了一个故事。", "explanation": "这里应该用〈讲〉。“移”表示改变位置，不能表示讲述故事。"}, {"text": "他移了一下价钱。", "explanation": "这里应该用〈算〉。“移”表示挪动，不能表示计算价格。"}, {"text": "他大声移了一句。", "explanation": "这里应该用〈喊〉。“移”表示位置改变，不能表示发出声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00f0bd82-ed93-4eb3-873e-652b9b4bc670') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94840, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把书包移了开，我才坐下。", "corrected_sentence": "他把书包移开了，我才坐下。", "error_description": "体标位置错误：“了”应放在补语“开”之后，应说“移开了”，不能说“移了开”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00f0bd82-ed93-4eb3-873e-652b9b4bc670') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94840, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈把碗移桌子上。", "corrected_sentence": "妈妈把碗移到桌子上。", "error_description": "补语错误：表示移动到某处要用结果补语“到”，应说“移到桌子上”，不能漏掉“到”说“移桌子上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00f0bd82-ed93-4eb3-873e-652b9b4bc670') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
