INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94843, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "稍是只有一点点，不多。", "primary_collocate": null, "pronunciation": "shāo", "ipa": "ʂau˥", "syllable_count": 1, "sentences": [{"text": "把汤稍煮一下就可以喝了。", "target_word": "稍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水稍多了，再倒出来一点。", "target_word": "稍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他比弟弟稍胖。", "target_word": "稍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事稍有变化，我会告诉你。", "target_word": "稍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盐稍少，菜有点淡。", "target_word": "稍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路稍远，我们坐车去吧。", "target_word": "稍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书稍难，但是很有用。", "target_word": "稍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "语速稍慢，大家就听懂了。", "target_word": "稍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯稍暗，看书不太舒服。", "target_word": "稍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的病稍好了，可以吃饭了。", "target_word": "稍", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "稍微", "label": "复合"}, {"form": "稍稍", "label": "重叠"}], "register": "中性", "sense_fingerprint": "只有一点点，不多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59c51a76-670c-44fa-8b2f-c5c9944b2429') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94843, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "稍", "is_correct": true, "explanation": "稍（shāo）表示只有一点点，不多，是正确答案。"}, {"text": "少", "is_correct": false, "explanation": "shǎo（少）与 shāo（稍）声调不同（第三声与第一声），意思是数量不多。"}, {"text": "超", "is_correct": false, "explanation": "chāo（超）与 shāo（稍）声母不同（ch与sh），意思是超过。"}, {"text": "勺", "is_correct": false, "explanation": "sháo（勺）与 shāo（稍）声调不同（第二声与第一声），意思是勺子。"}], "explanations": {"稍": "稍（shāo）表示只有一点点，不多，是正确答案。", "少": "shǎo（少）与 shāo（稍）声调不同（第三声与第一声），意思是数量不多。", "超": "chāo（超）与 shāo（稍）声母不同（ch与sh），意思是超过。", "勺": "sháo（勺）与 shāo（稍）声调不同（第二声与第一声），意思是勺子。"}, "sentence_index": null, "correct_answer": "稍"}, "level_3": {"options": [{"text": "稍", "is_correct": true, "explanation": "稍表示略微，修饰“煮一下”，符合语境。"}, {"text": "足足", "is_correct": false, "explanation": "语义：足足表示充分或足量，与“煮一下”的短时间相矛盾。"}, {"text": "十分", "is_correct": false, "explanation": "搭配：十分修饰形容词或程度，不修饰“煮”这类动作。"}, {"text": "忒", "is_correct": false, "explanation": "语域：忒是方言口语，与烹饪的书面说明不合。"}], "explanations": {"稍": "稍表示略微，修饰“煮一下”，符合语境。", "足足": "语义：足足表示充分或足量，与“煮一下”的短时间相矛盾。", "十分": "搭配：十分修饰形容词或程度，不修饰“煮”这类动作。", "忒": "语域：忒是方言口语，与烹饪的书面说明不合。"}, "sentence_index": 0, "correct_answer": "稍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我稍在图书馆待了一整天。", "explanation": "这里的〈稍〉表示只有一点，与「一整天」的长时间矛盾；此处应改用〈一直〉，说「我一直在图书馆待了一整天」。"}, {"text": "她稍考了一百分，老师很惊讶。", "explanation": "这里的〈稍〉表示只有一点，与「考了一百分」的满分结果矛盾；应去掉〈稍〉，说「她考了一百分」。"}, {"text": "我稍看了整本书，眼睛都累了。", "explanation": "这里的〈稍〉表示只有一点，与「整本书」的全部矛盾；此处应改用〈通读〉，说「我通读了整本书」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34687fa6-00cd-48ee-851a-715f6055399c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94843, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "稍", "is_correct": true, "explanation": "稍表示略微，修饰“难”，符合语境。"}, {"text": "立即", "is_correct": false, "explanation": "语义：立即表示时间上马上，不表示程度，“立即难”说不通。"}, {"text": "常常", "is_correct": false, "explanation": "语义：常常表示经常发生，不能与“难”组成程度结构。"}, {"text": "赶紧", "is_correct": false, "explanation": "搭配：赶紧表示催促行动，不修饰“难”这类性质形容词。"}], "explanations": {"稍": "稍表示略微，修饰“难”，符合语境。", "立即": "语义：立即表示时间上马上，不表示程度，“立即难”说不通。", "常常": "语义：常常表示经常发生，不能与“难”组成程度结构。", "赶紧": "搭配：赶紧表示催促行动，不修饰“难”这类性质形容词。"}, "sentence_index": 6, "correct_answer": "稍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他稍花光了所有的钱，很后悔。", "explanation": "这里的〈稍〉表示只有一点，与「花光了所有的钱」的完全含义矛盾；此处应改用〈全〉，说「他把钱全花光了」。"}, {"text": "他稍买了大量的衣服，衣柜都装不下了。", "explanation": "这里的〈稍〉表示只有一点，与「大量」的数量矛盾；此处应改用〈一下子〉，说「他一下子买了大量的衣服」。"}, {"text": "他稍熬了整整一夜，第二天没有精神。", "explanation": "这里的〈稍〉表示只有一点，与「整整一夜」的长时间矛盾；此处应改用〈通宵〉，说「他通宵熬夜」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34687fa6-00cd-48ee-851a-715f6055399c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94843, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的腿疼稍，但是能走路。", "corrected_sentence": "他的腿稍疼，但是能走路。", "error_description": "错误形式“疼稍”，正确形式“稍疼”：稍是副词，要放在形容词前作状语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34687fa6-00cd-48ee-851a-715f6055399c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94843, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件衣服很稍贵，但很好看。", "corrected_sentence": "这件衣服稍贵，但很好看。", "error_description": "错误形式“很稍贵”，正确形式“稍贵”：稍已表示程度小，不能再与“很”同用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34687fa6-00cd-48ee-851a-715f6055399c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
