INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94845, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "为某事物起一个新的名字或叫法。", "primary_collocate": null, "pronunciation": "chēng zhī wéi", "ipa": "ʈʂʰɤŋ˥ ʈʂɨ˥ wei˧˥", "syllable_count": 3, "sentences": [{"text": "人们把这种花称之为“水仙”。", "target_word": "称之为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种又酸又甜的新饮料，我们称之为“彩虹水”。", "target_word": "称之为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家把他的办法称之为“笨办法”。", "target_word": "称之为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家把这个新发现称之为“暗物质”。", "target_word": "称之为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷把这条小河称之为“妈妈河”。", "target_word": "称之为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们把他称之为“小百科”，因为他什么都知道。", "target_word": "称之为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种新的做法，专家们称之为“创新模式”。", "target_word": "称之为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们把雪人称之为“冬天的朋友”。", "target_word": "称之为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们把她的小店称之为“快乐站”。", "target_word": "称之为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把这个新来的机器人称之为“小白”。", "target_word": "称之为", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "给事物起一个新的名字或叫法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '702d0700-d623-41b2-b926-c6455e91f03f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94845, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "称之为", "is_correct": true, "explanation": "正确：“称之为”表示给这种花起名叫“水仙”，与“把”字结构和引号中的名称相符。"}, {"text": "浇灌", "is_correct": false, "explanation": "搭配：“浇灌”的对象是植物或土地，不能接“水仙”这样的名称，句子读不通。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：“赞美”是称赞，不是给花起名，“人们把这种花赞美“水仙””读不通。"}, {"text": "修剪", "is_correct": false, "explanation": "配价：“修剪”需要带施事和受事，后面不能接名称作宾语，句子不成立。"}], "explanations": {"称之为": "正确：“称之为”表示给这种花起名叫“水仙”，与“把”字结构和引号中的名称相符。", "浇灌": "搭配：“浇灌”的对象是植物或土地，不能接“水仙”这样的名称，句子读不通。", "赞美": "语义：“赞美”是称赞，不是给花起名，“人们把这种花赞美“水仙””读不通。", "修剪": "配价：“修剪”需要带施事和受事，后面不能接名称作宾语，句子不成立。"}, "sentence_index": 0, "correct_answer": "称之为"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书我们称之为二十元。", "explanation": "此处〈称之为〉表示给事物起名，不能用来说价格。说价钱要用〈卖〉，这里应该说“这本书卖二十元”。"}, {"text": "妈妈把我称之为很快。", "explanation": "此处〈称之为〉后面接的是形容词短语“很快”，表示看法要用〈认为〉，而不是给人起名字。"}, {"text": "这箱书我们称之为三公斤。", "explanation": "此处〈称之为〉表示给事物起名，不表示用秤量。表示称重要说“称了三公斤”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '285ed9d0-33bc-43e9-8b33-d3745b24d339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94845, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "称之为", "is_correct": true, "explanation": "正确：“称之为”表示给这种新做法起名叫“创新模式”，主语是“专家们”。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：“感谢”针对的是人或事情，不能用来给做法起名，句子读不通。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：“驾驶”的对象是车辆等，不能接“创新模式”这样的名称。"}, {"text": "喂养", "is_correct": false, "explanation": "搭配：“喂养”的对象是动物，不能用于给做法命名，句子不通。"}], "explanations": {"称之为": "正确：“称之为”表示给这种新做法起名叫“创新模式”，主语是“专家们”。", "感谢": "语义：“感谢”针对的是人或事情，不能用来给做法起名，句子读不通。", "驾驶": "搭配：“驾驶”的对象是车辆等，不能接“创新模式”这样的名称。", "喂养": "搭配：“喂养”的对象是动物，不能用于给做法命名，句子不通。"}, "sentence_index": 6, "correct_answer": "称之为"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条河我们称之为三年前。", "explanation": "此处〈称之为〉后面接的是时间名词“三年前”，表示时间要用〈是〉，而不是给河起名字，这个词不这么用。"}, {"text": "我们把这首歌称之为很好听。", "explanation": "此处〈称之为〉后面接的是形容词短语，不是名称。这里应该用〈认为〉或〈觉得〉，表示看法。"}, {"text": "我们称之为这个机器人很聪明。", "explanation": "此处〈称之为〉后面接了整个句子，而“称之为”后面只能接一个名称。表示看法要说“我们觉得这个机器人很聪明”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '285ed9d0-33bc-43e9-8b33-d3745b24d339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94845, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "农民们把这种小麦把称之为“野麦”。", "corrected_sentence": "农民们把这种小麦称之为“野麦”。", "error_description": "“把”字用了两次。“把”字已在“这种小麦”前，“称之为”前不应再加“把”，正确说法是“把这种小麦称之为“野麦””。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '285ed9d0-33bc-43e9-8b33-d3745b24d339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94845, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把这种旧的做法称之为了“老办法”。", "corrected_sentence": "我们把这种旧的做法称之为“老办法”。", "error_description": "“称之为”后面多加了“了”。“称之为”表示给事物起名这个动作，不需要“了”，正确说法是“把这种旧的做法称之为“老办法””。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '285ed9d0-33bc-43e9-8b33-d3745b24d339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
