INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94846, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把某事物叫作某名称。", "primary_collocate": null, "pronunciation": "chēng zhī wéi", "ipa": "ʈʂʰɤŋ˥ ʈʂɨ˥ wei˧˥", "syllable_count": 3, "sentences": [{"text": "中国人把过年称之为“春节”。", "target_word": "称之为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们把天气很热的日子称之为“三伏天”。", "target_word": "称之为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把这种学习方法称之为“预习”。", "target_word": "称之为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把这个地方称之为“家”。", "target_word": "称之为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人把北京称之为“首都”。", "target_word": "称之为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座山很高，当地人称之为“天山”。", "target_word": "称之为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生把这种病称之为“感冒”。", "target_word": "称之为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们把一个人做的好事称之为“善行”。", "target_word": "称之为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上把这种动物称之为“大熊猫”。", "target_word": "称之为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把天上那条亮带称之为“银河”。", "target_word": "称之为", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "把某事物叫作某个通用的名称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '702d0700-d623-41b2-b926-c6455e91f03f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94846, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "称之为", "is_correct": true, "explanation": "正确：“称之为”表示把过年叫作“春节”，与“把”字结构和引号中的名称相符。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象是器物，不能用来给节日起名，句子读不通。"}, {"text": "饮用", "is_correct": false, "explanation": "搭配：“饮用”的对象是饮品，不能接“春节”这样的名称。"}, {"text": "驾驶", "is_correct": false, "explanation": "语义：“驾驶”指操纵车辆，与给节日起名无关，句子读不通。"}], "explanations": {"称之为": "正确：“称之为”表示把过年叫作“春节”，与“把”字结构和引号中的名称相符。", "修理": "搭配：“修理”的对象是器物，不能用来给节日起名，句子读不通。", "饮用": "搭配：“饮用”的对象是饮品，不能接“春节”这样的名称。", "驾驶": "语义：“驾驶”指操纵车辆，与给节日起名无关，句子读不通。"}, "sentence_index": 0, "correct_answer": "称之为"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座山我们称之为一百米。", "explanation": "此处〈称之为〉表示给事物起名，不能用来说高度。说高度要用〈有……高〉，这里应该说“这座山有一百米高”。"}, {"text": "这箱书我们称之为三斤。", "explanation": "此处〈称之为〉表示给事物起名，不表示用秤量。表示称重要说“称了三斤”。"}, {"text": "我们把那只狗称之为很可爱。", "explanation": "此处〈称之为〉后面接的是形容词短语，不是名称。这里应该用〈觉得〉，表示看法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '285ed9d0-33bc-43e9-8b33-d3745b24d339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94846, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "称之为", "is_correct": true, "explanation": "正确：“称之为”表示把这种病叫作“感冒”，与“把”字结构和引号中的名称相符。"}, {"text": "注射", "is_correct": false, "explanation": "搭配：“注射”的对象是药物，不能接“感冒”这样的病名作宾语，句子读不通。"}, {"text": "切除", "is_correct": false, "explanation": "语义：“切除”指通过手术去掉身体的部分，与给病起名无关，句子读不通。"}, {"text": "缝合", "is_correct": false, "explanation": "搭配：“缝合”的对象是伤口或组织，不能接“感冒”作宾语，句子不成立。"}], "explanations": {"称之为": "正确：“称之为”表示把这种病叫作“感冒”，与“把”字结构和引号中的名称相符。", "注射": "搭配：“注射”的对象是药物，不能接“感冒”这样的病名作宾语，句子读不通。", "切除": "语义：“切除”指通过手术去掉身体的部分，与给病起名无关，句子读不通。", "缝合": "搭配：“缝合”的对象是伤口或组织，不能接“感冒”作宾语，句子不成立。"}, "sentence_index": 6, "correct_answer": "称之为"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们把这座山称之为很高。", "explanation": "此处〈称之为〉后面接的是形容词短语，不是名称。这里应该用〈认为〉，表示看法。"}, {"text": "老师称之为我们明天考试。", "explanation": "此处〈称之为〉后面接了一件事，而“称之为”后面只能接一个名称。说通知要用〈告诉〉：“老师告诉我们明天考试”。"}, {"text": "这条路我们称之为三年前。", "explanation": "此处〈称之为〉后面接的是时间名词“三年前”，表示时间要用〈是〉，不是给路起的名字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '285ed9d0-33bc-43e9-8b33-d3745b24d339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94846, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村里人把这片树林把称之为“小森林”。", "corrected_sentence": "村里人把这片树林称之为“小森林”。", "error_description": "“把”字用了两次。“把”字句中只用一次，“把”字已在“这片树林”前，“称之为”前不应再加“把”，正确说法是“把这片树林称之为“小森林””。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '285ed9d0-33bc-43e9-8b33-d3745b24d339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94846, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们把这座楼称之为了“老楼”。", "corrected_sentence": "他们把这座楼称之为“老楼”。", "error_description": "“称之为”后面多加了“了”。“称之为”表示给事物起名这个动作，不需要“了”，正确说法是“把这座楼称之为“老楼””。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '285ed9d0-33bc-43e9-8b33-d3745b24d339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
