INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94848, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "某一天之后紧接着的那一天。", "primary_collocate": null, "pronunciation": "dì èr tiān", "ipa": "ti˥˩ aɚ˥˩ tʰjɛn˥", "syllable_count": 3, "sentences": [{"text": "我们周一到北京，第二天去长城。", "target_word": "第二天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们八点出发，第二天才到家。", "target_word": "第二天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下了大雪，第二天学校没开门。", "target_word": "第二天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我周五很累，第二天睡到中午。", "target_word": "第二天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她买了新书，第二天就看完了。", "target_word": "第二天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "婚礼后的第二天，我们去海边玩。", "target_word": "第二天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在山里住了一晚，第二天爬山。", "target_word": "第二天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喝了很多酒，第二天头很疼。", "target_word": "第二天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛结束后的第二天，大家都休息。", "target_word": "第二天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我到了上海，第二天就开始工作。", "target_word": "第二天", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "某一天之后紧接着的一天", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21944ec0-25a1-4e3d-9f77-8f4f59681f20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94848, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "第二天", "is_correct": true, "explanation": "正确答案：第二天，指某一天之后紧接着的那一天。"}, {"text": "第二班", "is_correct": false, "explanation": "bān（第一声）与 tiān（第一声）声母不同（b 与 t），意思是「第二班」。"}, {"text": "第二篇", "is_correct": false, "explanation": "piān（第一声）与 tiān（第一声）声母不同（p 与 t），意思是「第二篇」。"}, {"text": "第二间", "is_correct": false, "explanation": "jiān（第一声）与 tiān（第一声）只差声母（j 与 t），意思是「第二个房间」。"}], "explanations": {"第二天": "正确答案：第二天，指某一天之后紧接着的那一天。", "第二班": "bān（第一声）与 tiān（第一声）声母不同（b 与 t），意思是「第二班」。", "第二篇": "piān（第一声）与 tiān（第一声）声母不同（p 与 t），意思是「第二篇」。", "第二间": "jiān（第一声）与 tiān（第一声）只差声母（j 与 t），意思是「第二个房间」。"}, "sentence_index": null, "correct_answer": "第二天"}, "level_3": {"options": [{"text": "第二天", "is_correct": true, "explanation": "正确：第二天指「我们周一到北京」之后紧接的那一天，与「去长城」的时间顺序一致。"}, {"text": "前一天", "is_correct": false, "explanation": "语义：前一天是周一到北京之前的那一天，不可能排在到达北京之后去长城。"}, {"text": "半年前", "is_correct": false, "explanation": "时间：「半年前」与「周一到北京，第二天去长城」的紧接行程不符。"}, {"text": "去年", "is_correct": false, "explanation": "搭配：「周一到北京」的行程与一年前的「去年」无法衔接。"}], "explanations": {"第二天": "正确：第二天指「我们周一到北京」之后紧接的那一天，与「去长城」的时间顺序一致。", "前一天": "语义：前一天是周一到北京之前的那一天，不可能排在到达北京之后去长城。", "半年前": "时间：「半年前」与「周一到北京，第二天去长城」的紧接行程不符。", "去年": "搭配：「周一到北京」的行程与一年前的「去年」无法衔接。"}, "sentence_index": 0, "correct_answer": "第二天"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我周五到了北京，第二天是周四。", "explanation": "第二天是某一天之后紧接着的那一天，周五的第二天是周六，不是周四；指之前一天应该用〈前一天〉。"}, {"text": "我把行李放进了第二天里。", "explanation": "这里把时间词「第二天」误当成了能装东西的地方，应该用〈柜子〉这类表示容器的名词；时间词不能指容器。"}, {"text": "这种药第二天吃一次，却天天吃。", "explanation": "这里「第二天」指一个具体的日子，与「天天吃」矛盾；表示隔天重复应当用〈隔天〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d94915-20bc-43b4-a99f-f7a049f83d09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94848, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "第二天", "is_correct": true, "explanation": "正确答案：第二天，指某一天之后紧接着的那一天。"}, {"text": "第二边", "is_correct": false, "explanation": "biān（第一声）与 tiān（第一声）声母不同（b 与 t），意思是「第二边」。"}, {"text": "第二编", "is_correct": false, "explanation": "biān（第一声）与 tiān（第一声）声母不同（b 与 t），意思是「第二编」。"}, {"text": "第二篇", "is_correct": false, "explanation": "piān（第一声）与 tiān（第一声）声母不同（p 与 t），意思是「第二篇文章」。"}], "explanations": {"第二天": "正确答案：第二天，指某一天之后紧接着的那一天。", "第二边": "biān（第一声）与 tiān（第一声）声母不同（b 与 t），意思是「第二边」。", "第二编": "biān（第一声）与 tiān（第一声）声母不同（b 与 t），意思是「第二编」。", "第二篇": "piān（第一声）与 tiān（第一声）声母不同（p 与 t），意思是「第二篇文章」。"}, "sentence_index": null, "correct_answer": "第二天"}, "level_3": {"options": [{"text": "第二天", "is_correct": true, "explanation": "正确：第二天指「住了一晚」之后紧接的那一天，与「爬山」的时间顺序一致。"}, {"text": "前一天", "is_correct": false, "explanation": "语义：前一天在住宿之前，与「住了一晚」之后再爬山的顺序矛盾。"}, {"text": "上个星期", "is_correct": false, "explanation": "语义：上个星期已经过去，与「住了一晚」后紧接着爬山的语境不符。"}, {"text": "下个月", "is_correct": false, "explanation": "搭配：「住了一晚」之后紧接爬山，不能跨到下个月。"}], "explanations": {"第二天": "正确：第二天指「住了一晚」之后紧接的那一天，与「爬山」的时间顺序一致。", "前一天": "语义：前一天在住宿之前，与「住了一晚」之后再爬山的顺序矛盾。", "上个星期": "语义：上个星期已经过去，与「住了一晚」后紧接着爬山的语境不符。", "下个月": "搭配：「住了一晚」之后紧接爬山，不能跨到下个月。"}, "sentence_index": 6, "correct_answer": "第二天"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我到了上海，第二天却是一个月后才开始工作。", "explanation": "这里「第二天」指参照日之后的一天，却说成一个月后，与它的意思矛盾，应该用〈几周后〉之类表示较长的时段。"}, {"text": "这次培训共三天，第二天就是最后一天。", "explanation": "这里「第二天」与「最后一天」矛盾；共三天的最后一天是第三天，应用〈第三天〉。"}, {"text": "我昨天买了两个第二天。", "explanation": "这里把时间词「第二天」当成了可以用量词「个」计数的物品，应该用〈礼物〉等具体名词；时间词不能作可数物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d94915-20bc-43b4-a99f-f7a049f83d09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94848, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们一个第二天早上去爬山。", "corrected_sentence": "他们第二天早上去爬山。", "error_description": "错误：「第二天」是时间词，前面不能加量词「个」。应说「第二天早上」，不说「一个第二天早上」。正确形式：他们第二天早上去爬山。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d94915-20bc-43b4-a99f-f7a049f83d09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94848, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨天他们吃了火锅，第二天的拉肚子了。", "corrected_sentence": "昨天他们吃了火锅，第二天拉肚子了。", "error_description": "错误：「第二天」后面不能加「的」。作时间词时直接接动词「拉肚子」，应说「第二天拉肚子」，不说「第二天的拉肚子」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d94915-20bc-43b4-a99f-f7a049f83d09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
