INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94852, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "按高低、大小划分的等级。", "primary_collocate": null, "pronunciation": "jí bié", "ipa": "tɕi˧˥ pje˧˥", "syllable_count": 2, "sentences": [{"text": "这家酒店是最高级别。", "target_word": "级别", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这次地震的级别不高。", "target_word": "级别", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "比赛按年龄分成三个级别。", "target_word": "级别", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "台风的级别越高，风就越大。", "target_word": "级别", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我报了游泳班的第二个级别。", "target_word": "级别", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个级别的比赛，只有最好的队才能参加。", "target_word": "级别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院按大小分成不同的级别。", "target_word": "级别", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种车的级别很高，价钱当然也很贵。", "target_word": "级别", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我考过了汉语考试的第三个级别。", "target_word": "级别", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这套教材的难度分成几个级别，你可以选适合自己的。", "target_word": "级别", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "級別", "label": "繁体"}, {"form": "高级别", "label": "复合"}], "register": "中性", "sense_fingerprint": "按高低、大小划分出来的等级", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7870b6f4-2759-41c0-b1b7-31d9f7ccd8bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94852, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能用“最高”来比较等级。"}, {"text": "声音", "is_correct": false, "explanation": "语义：酒店不是声音，不能说“这家酒店是最高声音”。"}, {"text": "级别", "is_correct": true, "explanation": "正确：级别可以用“最高”修饰，表示最高的等级。"}, {"text": "精神", "is_correct": false, "explanation": "语义：“精神”不是能按等级评出最高的事物，“这家酒店是最高精神”说不通。"}], "explanations": {"颜色": "语义：颜色不能用“最高”来比较等级。", "声音": "语义：酒店不是声音，不能说“这家酒店是最高声音”。", "级别": "正确：级别可以用“最高”修饰，表示最高的等级。", "精神": "语义：“精神”不是能按等级评出最高的事物，“这家酒店是最高精神”说不通。"}, "sentence_index": 0, "correct_answer": "级别"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服的级别很红。", "explanation": "“级别”指等级，不能用颜色来形容。"}, {"text": "这个级别已经吃了晚饭。", "explanation": "这里把“级别”当成了有生命的人。应该用〈人〉：“级别”只指等级，不能吃晚饭。"}, {"text": "这次比赛的级别很远。", "explanation": "这里应该用〈距离〉。说远近要用“距离”，“级别”指等级高低，不能用来说远近。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb06fdd9-08b5-4670-be89-e1f673d9f1c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94852, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "味道", "is_correct": false, "explanation": "语义：味道不能用来按大小划分医院的类别。"}, {"text": "温度", "is_correct": false, "explanation": "语义：医院不会按温度划分成不同的类别。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：医院是按规模大小划分等级，不是按“年龄”划分，句意不通。"}, {"text": "级别", "is_correct": true, "explanation": "正确：医院按大小划分等级，可以说分成不同的级别。"}], "explanations": {"味道": "语义：味道不能用来按大小划分医院的类别。", "温度": "语义：医院不会按温度划分成不同的类别。", "年龄": "语义：医院是按规模大小划分等级，不是按“年龄”划分，句意不通。", "级别": "正确：医院按大小划分等级，可以说分成不同的级别。"}, "sentence_index": 6, "correct_answer": "级别"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈把这个级别切成了三块。", "explanation": "“级别”是抽象的等级，不是食物，不能切。"}, {"text": "这个级别很甜，我们都爱吃。", "explanation": "“级别”不能用味道来形容。"}, {"text": "我的新朋友叫级别。", "explanation": "“级别”是表示等级的词，不能用作人名。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb06fdd9-08b5-4670-be89-e1f673d9f1c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94852, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家酒店达到了一只最高级别。", "corrected_sentence": "这家酒店达到了最高级别。", "error_description": "错误形式：“一只最高级别”；正确形式：“最高级别”或“一个最高级别”。“只”是动物的量词，不能用于“级别”；可以去掉量词，也可以改用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb06fdd9-08b5-4670-be89-e1f673d9f1c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94852, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师的级别的很高，大家都很尊敬他。", "corrected_sentence": "老师的级别很高，大家都很尊敬他。", "error_description": "错误形式：“老师的级别的很高”；正确形式：“老师的级别很高”。“级别”后多了一个“的”，“的”后面接形容词谓语“很高”时不能用，应去掉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb06fdd9-08b5-4670-be89-e1f673d9f1c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
