INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94854, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "经常使用互联网的人。", "primary_collocate": null, "pronunciation": "wǎng mín", "ipa": "wɑŋ˨˩ min˧˥", "syllable_count": 2, "sentences": [{"text": "中国有很多网民。", "target_word": "网民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网民可以在网上买东西、付钱。", "target_word": "网民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的网民越来越多了。", "target_word": "网民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网民们都说这个软件很好用。", "target_word": "网民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是十年的老网民了，什么网站都用过。", "target_word": "网民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一位网民在网上写了一篇很长的文章。", "target_word": "网民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老年网民也学会了用手机付钱。", "target_word": "网民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网民应该保护自己的个人信息。", "target_word": "网民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个调查问了一千个网民。", "target_word": "网民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多网民每天都要上网查资料。", "target_word": "网民", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}], "register": "中性", "sense_fingerprint": "网民：经常使用互联网的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9338e44a-02f0-4ff6-8511-9734bc7b6a50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94854, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "太阳", "is_correct": false, "explanation": "语义：太阳是独一无二的天体，不能说“中国有很多太阳”。"}, {"text": "网民", "is_correct": true, "explanation": "网民指经常使用互联网的人，“中国有很多网民”成立。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮也是独一无二的，“中国有很多月亮”不成立。"}, {"text": "黎民", "is_correct": false, "explanation": "语域：「黎民」是古代书面语，与现代口语句子不协调。"}], "explanations": {"太阳": "语义：太阳是独一无二的天体，不能说“中国有很多太阳”。", "网民": "网民指经常使用互联网的人，“中国有很多网民”成立。", "月亮": "语义：月亮也是独一无二的，“中国有很多月亮”不成立。", "黎民": "语域：「黎民」是古代书面语，与现代口语句子不协调。"}, "sentence_index": 0, "correct_answer": "网民"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个网民很好用。", "explanation": "这里应该用〈网站〉。“好用”用于软件、网站等物品，不能用来形容人，网民是人。"}, {"text": "这个网民打开很慢。", "explanation": "这里应该用〈网页〉。“打开很慢”说的是网页，网民是人，不能被打开。"}, {"text": "这篇文章的网民是一位大学老师。", "explanation": "这里应该用〈作者〉。作者是写文章的人；网民泛指上网的人，不能指某篇文章的写作者。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babba5e0-0b28-42d0-8f55-614438535d6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94854, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "孩子", "is_correct": false, "explanation": "搭配：“老年”修饰人时可说“老年人”，不能说“老年孩子”。"}, {"text": "网民", "is_correct": true, "explanation": "网民指经常使用互联网的人，能够“学会了用手机付钱”。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会学会用手机付钱。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不会用手机付钱。"}], "explanations": {"孩子": "搭配：“老年”修饰人时可说“老年人”，不能说“老年孩子”。", "网民": "网民指经常使用互联网的人，能够“学会了用手机付钱”。", "石头": "语义：石头不会学会用手机付钱。", "窗户": "语义：窗户不会用手机付钱。"}, "sentence_index": 6, "correct_answer": "网民"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把网民打印了一遍。", "explanation": "这里应该用〈文章〉。“打印”的对象是文章、文件，网民是人，不能被打印。"}, {"text": "医院里住着很多网民，每天都有医生来查房。", "explanation": "这里应该用〈病人〉。病人指在医院接受治疗的人；网民指上网的人，不指住院的人。"}, {"text": "饭店的网民做出了一道好菜。", "explanation": "这里应该用〈厨师〉。厨师指做饭菜的人；网民指上网的人，不能指做菜的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babba5e0-0b28-42d0-8f55-614438535d6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94854, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一只年轻网民也喜欢在网上交朋友。", "corrected_sentence": "一位年轻网民也喜欢在网上交朋友。", "error_description": "量词错误：“网民”指人，应用“位”或“个”，不能用“只”。应说“一位年轻网民”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babba5e0-0b28-42d0-8f55-614438535d6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94854, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "很多年轻地网民都在网上玩游戏。", "corrected_sentence": "很多年轻网民都在网上玩游戏。", "error_description": "结构助词错误：“年轻”修饰名词“网民”时不用“地”，应直接说“年轻网民”（或用“的”）。“地”用于修饰动词、形容词。正确形式为“很多年轻网民都在网上玩游戏”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babba5e0-0b28-42d0-8f55-614438535d6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
