INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94855, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "总人口是一个地方所有的人加起来。", "primary_collocate": null, "pronunciation": "zǒng rén kǒu", "ipa": "tsʊŋ˨˩ ʐən˧˥ kʰoʊ˨˩˦", "syllable_count": 3, "sentences": [{"text": "这个小村子的总人口只有三百人。", "target_word": "总人口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个岛的总人口是三千多人，大多是渔民。", "target_word": "总人口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座小岛的总人口很少，大家都互相认识。", "target_word": "总人口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们算一算这个镇的总人口。", "target_word": "总人口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个渔村的总人口比去年多了一百人。", "target_word": "总人口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山里的小村子总人口不多，路上很安静。", "target_word": "总人口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要知道一个地方有多少人，就看它的总人口。", "target_word": "总人口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家那条街的总人口大概有五千人。", "target_word": "总人口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个社区的总人口在去年增加了两百人。", "target_word": "总人口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在本子上写下了小区的总人口。", "target_word": "总人口", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "一个村子、学校、社区等地方所有人的总数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73c1303b-ce7a-48fa-ac4b-097cecf36469') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94855, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "面积", "is_correct": false, "explanation": "语义：面积是土地的大小，不是人数，与“只有三百人”不合。"}, {"text": "户数", "is_correct": false, "explanation": "搭配：户数以户计，不能与“三百人”搭配。"}, {"text": "总人口", "is_correct": true, "explanation": "正确：总人口指一个地方所有人的总数，与“这个小村子”“只有三百人”相合。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指岁数，村子不能用“年龄”来说有多少人。"}], "explanations": {"面积": "语义：面积是土地的大小，不是人数，与“只有三百人”不合。", "户数": "搭配：户数以户计，不能与“三百人”搭配。", "总人口": "正确：总人口指一个地方所有人的总数，与“这个小村子”“只有三百人”相合。", "年龄": "语义：“年龄”指岁数，村子不能用“年龄”来说有多少人。"}, "sentence_index": 0, "correct_answer": "总人口"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师让我们数一数这次考试的总人口。", "explanation": "这里应该用〈人数〉。总人口指一个地方全部居民的总数，考试的参加者要说人数。"}, {"text": "这个社区的总人口是八十户。", "explanation": "这里应该用〈户数〉。总人口统计的是人，按家庭计算才用“户”，所以应说户数。"}, {"text": "这场演唱会的总人口很多，大家都很兴奋。", "explanation": "这里应该用〈观众〉。看演唱会的人要说观众，总人口指一个地方的全部居民。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f15f862-54ec-4f7c-b9bf-4afd8bb7ebdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94855, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "海拔", "is_correct": false, "explanation": "语义：海拔说的是高度，与“有多少人”不合。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“有多少人”不能这样问“温度”，两者不搭配。"}, {"text": "寿命", "is_correct": false, "explanation": "语义：寿命说的是存活的年数，不能用来说一个地方有多少人。"}, {"text": "总人口", "is_correct": true, "explanation": "正确：总人口指一个地方所有人的总数，与“有多少人”相合。"}], "explanations": {"海拔": "语义：海拔说的是高度，与“有多少人”不合。", "温度": "搭配：“有多少人”不能这样问“温度”，两者不搭配。", "寿命": "语义：寿命说的是存活的年数，不能用来说一个地方有多少人。", "总人口": "正确：总人口指一个地方所有人的总数，与“有多少人”相合。"}, "sentence_index": 6, "correct_answer": "总人口"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆公交车的总人口今天比昨天多了很多。", "explanation": "这里应该用〈乘客〉。总人口指一个地方的全部居民，车上的人要说乘客。"}, {"text": "这场比赛的总人口有八十人。", "explanation": "这里应该用〈选手〉。比赛的参加者要说选手，不能说总人口。"}, {"text": "这部电影的总人口很多，场场都满座。", "explanation": "这里应该用〈观众〉。看电影的人要说观众，总人口只用于一个地方的居民。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f15f862-54ec-4f7c-b9bf-4afd8bb7ebdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94855, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们学校的总人口的比去年少了二十人。", "corrected_sentence": "我们学校的总人口比去年少了二十人。", "error_description": "“的”多余：“总人口”后面不应再加“的”，“的”接“比”不通。应说“我们学校的总人口比去年少了二十人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f15f862-54ec-4f7c-b9bf-4afd8bb7ebdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94855, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个镇的总人口们在这十年里没怎么变。", "corrected_sentence": "这个镇的总人口在这十年里没怎么变。", "error_description": "错误形式：“总人口们”；正确形式：“总人口”。“总人口”是数量概念，不能再加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f15f862-54ec-4f7c-b9bf-4afd8bb7ebdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
