INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94856, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个国家或地区全部居民的总数。", "primary_collocate": null, "pronunciation": "zǒng rén kǒu", "ipa": "tsʊŋ˨˩ ʐən˧˥ kʰoʊ˨˩˦", "syllable_count": 3, "sentences": [{"text": "中国的总人口超过十四亿。", "target_word": "总人口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国家的总人口每年都在增加。", "target_word": "总人口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "日本的总人口正在慢慢减少。", "target_word": "总人口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "根据统计，这个地区的总人口约为八百万。", "target_word": "总人口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "非洲的总人口已经超过了十亿。", "target_word": "总人口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个省的总人口在全国排第三。", "target_word": "总人口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老年人在总人口中的比例越来越高。", "target_word": "总人口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国家总人口不多，但土地很大。", "target_word": "总人口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府每十年调查一次全国的总人口。", "target_word": "总人口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个地区的总人口比十年前多了很多。", "target_word": "总人口", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "国家、省份或地区统计意义上的全部居民数量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73c1303b-ce7a-48fa-ac4b-097cecf36469') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94856, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "面积", "is_correct": false, "explanation": "搭配：面积以平方公里计，不能说“超过十四亿”。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指岁数，不能用来说人数超过十四亿。"}, {"text": "总人口", "is_correct": true, "explanation": "正确：总人口指一个国家全部居民的总数，与“中国的”“超过十四亿”相合。"}, {"text": "寿命", "is_correct": false, "explanation": "语义：寿命说的是存活的年数，与人口数量不合。"}], "explanations": {"面积": "搭配：面积以平方公里计，不能说“超过十四亿”。", "年龄": "语义：“年龄”指岁数，不能用来说人数超过十四亿。", "总人口": "正确：总人口指一个国家全部居民的总数，与“中国的”“超过十四亿”相合。", "寿命": "语义：寿命说的是存活的年数，与人口数量不合。"}, "sentence_index": 0, "correct_answer": "总人口"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "根据统计，这个地区的总人口约为八百万户。", "explanation": "这里应该用〈户数〉。总人口统计的是人，按家庭计算才用“户”，所以应说户数。"}, {"text": "这场音乐节的总人口约为八万。", "explanation": "这里应该用〈观众〉。参加音乐节的人要说观众，总人口指一个国家或地区的全部居民。"}, {"text": "这家公司的总人口约为八百人。", "explanation": "这里应该用〈员工〉。公司里的人要说员工，总人口只用于地区的居民。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f15f862-54ec-4f7c-b9bf-4afd8bb7ebdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94856, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "词语", "is_correct": false, "explanation": "语义：“词语”不是人，句中要的是人群的范围。"}, {"text": "公里", "is_correct": false, "explanation": "搭配：“公里”是长度单位，不能作“中”的范围。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴不是人群的集合，与句意不合。"}, {"text": "总人口", "is_correct": true, "explanation": "正确：总人口指一个地区全部居民的总数，与“老年人在……中的比例”相合。"}], "explanations": {"词语": "语义：“词语”不是人，句中要的是人群的范围。", "公里": "搭配：“公里”是长度单位，不能作“中”的范围。", "钢琴": "语义：钢琴不是人群的集合，与句意不合。", "总人口": "正确：总人口指一个地区全部居民的总数，与“老年人在……中的比例”相合。"}, "sentence_index": 6, "correct_answer": "总人口"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这趟地铁的总人口比昨天多了很多。", "explanation": "这里应该用〈乘客〉。总人口指一个地区的全部居民，车上的人要说乘客。"}, {"text": "这场马拉松的总人口比去年多了很多。", "explanation": "这里应该用〈选手〉。比赛的参加者要说选手，不能说总人口。"}, {"text": "这部电影的总人口比首映那天多了很多。", "explanation": "这里应该用〈观众〉。看电影的人要说观众，总人口只用于地区的居民。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f15f862-54ec-4f7c-b9bf-4afd8bb7ebdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94856, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个国家的总人口们近几年一直在下降。", "corrected_sentence": "这个国家的总人口近几年一直在下降。", "error_description": "错误形式：“总人口们”；正确形式：“总人口”。“总人口”是数量概念，不能再加“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f15f862-54ec-4f7c-b9bf-4afd8bb7ebdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94856, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个州的总人口的比邻州多一倍。", "corrected_sentence": "这个州的总人口比邻州多一倍。", "error_description": "“的”多余：“总人口”后面不应再加“的”，“的”接“比”不通。应说“这个州的总人口比邻州多一倍”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f15f862-54ec-4f7c-b9bf-4afd8bb7ebdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
