INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94857, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "总书记是一个大团体里最主要的负责人。", "primary_collocate": null, "pronunciation": "zǒng shū jì", "ipa": "tsʊŋ˨˩ ʂu˥ tɕi˥˩", "syllable_count": 3, "sentences": [{"text": "总书记今天来到我们学校。", "target_word": "总书记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位总书记很关心年轻人。", "target_word": "总书记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总书记在大会上讲了话。", "target_word": "总书记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是这个党的总书记。", "target_word": "总书记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总书记请大家坐下来。", "target_word": "总书记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们都想见一见总书记。", "target_word": "总书记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的总书记工作很认真。", "target_word": "总书记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总书记每年都去农村看看。", "target_word": "总书记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家选他当总书记。", "target_word": "总书记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总书记在电视上说了新计划。", "target_word": "总书记", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词（一位总书记）"}, {"form": "總書記", "label": "繁体"}], "register": "正式", "sense_fingerprint": "大团体里最主要的负责人（指人）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03e574a3-d7c0-4022-bfe0-96ccccca3dcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94857, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "总书记", "is_correct": true, "explanation": "正确。“总书记”指政党或组织的主要负责人，可以“来到我们学校”。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会“来到学校”，句子不成立。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“时间”是抽象概念，不能作为来访的主语。"}, {"text": "数学", "is_correct": false, "explanation": "搭配：“来到”的主语应是人或可移动的事物，学科名不与之搭配。"}], "explanations": {"总书记": "正确。“总书记”指政党或组织的主要负责人，可以“来到我们学校”。", "石头": "语义：石头不会“来到学校”，句子不成立。", "时间": "语义：“时间”是抽象概念，不能作为来访的主语。", "数学": "搭配：“来到”的主语应是人或可移动的事物，学科名不与之搭配。"}, "sentence_index": 0, "correct_answer": "总书记"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一只总书记，放在家里养。", "explanation": "这里应该用〈位〉。〈只〉用于动物，“总书记”指人，应用人的量词〈位〉。"}, {"text": "这座总书记很大，里面住着很多人。", "explanation": "这里“总书记”指人的职务，不能指建筑，因此不能用〈座〉来数它，也不能说“很大”“住着很多人”。"}, {"text": "我们的总书记每天负责擦黑板。", "explanation": "这里应该用〈值日生〉。“总书记”指政党或组织中主持全面工作的负责人，不用于班级的值日工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec199dda-ed00-4312-8bc9-b9e17011411e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94857, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "总书记", "is_correct": true, "explanation": "正确。“新来的”修饰人或职务，“总书记”能够“工作很认真”。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不会“工作”，句子不成立。"}, {"text": "空气", "is_correct": false, "explanation": "配价：“工作很认真”需要有施事者，“空气”不能“工作”。"}, {"text": "清晨", "is_correct": false, "explanation": "语义：“清晨”是时间，不能“新来”。"}], "explanations": {"总书记": "正确。“新来的”修饰人或职务，“总书记”能够“工作很认真”。", "桌子": "语义：桌子不会“工作”，句子不成立。", "空气": "配价：“工作很认真”需要有施事者，“空气”不能“工作”。", "清晨": "语义：“清晨”是时间，不能“新来”。"}, "sentence_index": 6, "correct_answer": "总书记"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨天吃了一个总书记，味道很好。", "explanation": "这里应该用〈面包〉等食物。“总书记”指人的职务，不能当食物。"}, {"text": "他把厨房的水龙头换成了总书记。", "explanation": "这里把“总书记”误当成了器具。“总书记”是人的职务，不能指代器具。"}, {"text": "总书记在花园里开花，非常漂亮。", "explanation": "这里把“总书记”误当成了植物。“总书记”指人的职务，不能指植物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec199dda-ed00-4312-8bc9-b9e17011411e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94857, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个位总书记上周来过我们厂。", "corrected_sentence": "这位总书记上周来过我们厂。", "error_description": "错误：“这个位”。“位”是指人的量词，不能与“这个”搭配，应为“这位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec199dda-ed00-4312-8bc9-b9e17011411e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94857, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家都推选了一只总书记。", "corrected_sentence": "大家都推选了一位总书记。", "error_description": "错误：“只”用于动物，“总书记”指人，应用人的量词“位”。正确为“推选了一位总书记”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec199dda-ed00-4312-8bc9-b9e17011411e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
