INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94858, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "政党或组织中主持全面工作的主要负责人的职务名称。", "primary_collocate": null, "pronunciation": "zǒng shū jì", "ipa": "tsʊŋ˨˩ ʂu˥ tɕi˥˩", "syllable_count": 3, "sentences": [{"text": "总书记是这个党最高的职务。", "target_word": "总书记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的职务是总书记。", "target_word": "总书记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个组织设立了总书记一职，负责全面工作。", "target_word": "总书记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他去年当上了总书记。", "target_word": "总书记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总书记这个职务很重要。", "target_word": "总书记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "党的总书记要负责全面工作。", "target_word": "总书记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是第一位女总书记。", "target_word": "总书记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总书记一职由大会选出。", "target_word": "总书记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个组织取消了总书记这一职务。", "target_word": "总书记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做了十年总书记。", "target_word": "总书记", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词（一位总书记）"}, {"form": "總書記", "label": "繁体"}], "register": "正式", "sense_fingerprint": "政党或组织主要负责人的职务名称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03e574a3-d7c0-4022-bfe0-96ccccca3dcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94858, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "总书记", "is_correct": true, "explanation": "正确。“总书记”是政党中主持全面工作的职务名称，可以作“最高的职务”。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资是报酬，不是职务，句子说不通。"}, {"text": "党员", "is_correct": false, "explanation": "语义：党员指党的成员，不是职务名称。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“是……最高的职务”要求职务名称作主语，“颜色”不能作职务。"}], "explanations": {"总书记": "正确。“总书记”是政党中主持全面工作的职务名称，可以作“最高的职务”。", "工资": "语义：工资是报酬，不是职务，句子说不通。", "党员": "语义：党员指党的成员，不是职务名称。", "颜色": "搭配：“是……最高的职务”要求职务名称作主语，“颜色”不能作职务。"}, "sentence_index": 0, "correct_answer": "总书记"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在会议上担任总书记，负责记录会议内容。", "explanation": "这里应该用〈书记员〉。“总书记”是主持全面工作的主要负责人，不负责记录。"}, {"text": "他是我们班的总书记，负责管理纪律。", "explanation": "这里应该用〈班长〉。“总书记”用于政党或组织的最高职务，不用于班级。"}, {"text": "他去年买了一本总书记，很厚。", "explanation": "这里不能用〈本〉。〈本〉用于书籍，“总书记”指职务，不能这样计数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec199dda-ed00-4312-8bc9-b9e17011411e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94858, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "总书记", "is_correct": true, "explanation": "正确。“第一位女”修饰的是人或职务，“总书记”是职务名称。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“第一位女桌子”说不通，桌子不能是人。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“第一位女……”修饰的应是人，“空气”不能与之搭配。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“第一位女石头”说不通。"}], "explanations": {"总书记": "正确。“第一位女”修饰的是人或职务，“总书记”是职务名称。", "桌子": "语义：“第一位女桌子”说不通，桌子不能是人。", "空气": "搭配：“第一位女……”修饰的应是人，“空气”不能与之搭配。", "石头": "语义：“第一位女石头”说不通。"}, "sentence_index": 6, "correct_answer": "总书记"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家的小猫今天当上了总书记。", "explanation": "这里不能用“总书记”，它指人的职务，动物不能担任。"}, {"text": "我周末喜欢去总书记散步。", "explanation": "这里应该用〈公园〉。“总书记”是职务名称，不是地点。"}, {"text": "今天的午饭是总书记，我吃得很饱。", "explanation": "这里应该用〈饭菜〉。“总书记”指人的职务，不能当食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec199dda-ed00-4312-8bc9-b9e17011411e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94858, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他做过两个总书记。", "corrected_sentence": "他做过两任总书记。", "error_description": "错误：“两个总书记”。职务要用“任”计数，应为“两任总书记”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec199dda-ed00-4312-8bc9-b9e17011411e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94858, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她做了五个年总书记。", "corrected_sentence": "她做了五年总书记。", "error_description": "错误：“五个年”。“年”本身就是量词，前面不加“个”，正确为“她做了五年总书记”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec199dda-ed00-4312-8bc9-b9e17011411e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
