INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94862, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "违反法律、应受处罚的犯罪行为。", "primary_collocate": null, "pronunciation": "zuì xíng", "ipa": "tsuei˥˩ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "法院认定他的罪行属实。", "target_word": "罪行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "根据罪行轻重，法院判了他五年。", "target_word": "罪行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这起案件的罪行十分严重。", "target_word": "罪行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他犯下了严重的罪行，必须受到处罚。", "target_word": "罪行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律会惩罚一切罪行。", "target_word": "罪行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "检察官列出了他的三项罪行。", "target_word": "罪行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他因这些罪行进了监狱。", "target_word": "罪行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们不会忘记战争中的罪行。", "target_word": "罪行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "律师说他的罪行不算太重。", "target_word": "罪行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对这样的罪行，法律绝不放过。", "target_word": "罪行", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}, {"form": "桩", "label": "量词"}], "register": "正式", "sense_fingerprint": "违反法律、应受处罚的犯罪行为", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59c51a76-670c-44fa-8b2f-c5c9944b2429') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94862, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "罪行", "is_correct": true, "explanation": "正确：罪行（zuì xíng），指违反法律、应受处罚的犯罪行为。"}, {"text": "嘴型", "is_correct": false, "explanation": "zuǐ（第三声）与 zuì（第四声）声调不同，嘴型指嘴的形状。"}, {"text": "最新", "is_correct": false, "explanation": "xīn（第一声，前鼻音）与 xíng（第二声，后鼻音）不同，最新指最近出现的。"}, {"text": "脆性", "is_correct": false, "explanation": "cuì 与 zuì 声母不同（c 与 z），xìng 与 xíng 声调不同，脆性指物体易碎的性质。"}], "explanations": {"罪行": "正确：罪行（zuì xíng），指违反法律、应受处罚的犯罪行为。", "嘴型": "zuǐ（第三声）与 zuì（第四声）声调不同，嘴型指嘴的形状。", "最新": "xīn（第一声，前鼻音）与 xíng（第二声，后鼻音）不同，最新指最近出现的。", "脆性": "cuì 与 zuì 声母不同（c 与 z），xìng 与 xíng 声调不同，脆性指物体易碎的性质。"}, "sentence_index": null, "correct_answer": "罪行"}, "level_3": {"options": [{"text": "罪行", "is_correct": true, "explanation": "罪行：名词，指违法的犯罪行为，“法院认定他的罪行属实”搭配自然。"}, {"text": "谎言", "is_correct": false, "explanation": "语义：“谎言”本身就是假的，说“谎言属实”自相矛盾。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“属实”用于事实或陈述，不能用来判定“心情”。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”是外形特征，不能由法院认定属实。"}], "explanations": {"罪行": "罪行：名词，指违法的犯罪行为，“法院认定他的罪行属实”搭配自然。", "谎言": "语义：“谎言”本身就是假的，说“谎言属实”自相矛盾。", "心情": "搭配：“属实”用于事实或陈述，不能用来判定“心情”。", "身材": "体貌：“身材”是外形特征，不能由法院认定属实。"}, "sentence_index": 0, "correct_answer": "罪行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次聚会迟到，是我的罪行，我愿意向大家道歉。", "explanation": "这里应该用〈过错〉。罪行指违法的犯罪行为，迟到不是违法，应说“过错”。"}, {"text": "他犯下了一颗罪行，被关进了监狱。", "explanation": "这里应该用〈项〉。“颗”用于圆粒状的小东西，不能用来数“罪行”。"}, {"text": "这次小摩擦是他的罪行，不算大事。", "explanation": "这里应该用〈过失〉。罪行指违法的犯罪行为，与“小摩擦”“不算大事”不相称，应说“过失”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34687fa6-00cd-48ee-851a-715f6055399c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94862, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "罪行", "is_correct": true, "explanation": "罪行：名词，指犯罪的行为，“因这些罪行进了监狱”搭配自然。"}, {"text": "礼物", "is_correct": false, "explanation": "语义：“礼物”不是违法的行为，不会让人因此入狱。"}, {"text": "奖项", "is_correct": false, "explanation": "语义：“奖项”是授予的荣誉，不会导致入狱。"}, {"text": "发型", "is_correct": false, "explanation": "体貌：“发型”属于外貌，不是可以定罪入狱的行为。"}], "explanations": {"罪行": "罪行：名词，指犯罪的行为，“因这些罪行进了监狱”搭配自然。", "礼物": "语义：“礼物”不是违法的行为，不会让人因此入狱。", "奖项": "语义：“奖项”是授予的荣誉，不会导致入狱。", "发型": "体貌：“发型”属于外貌，不是可以定罪入狱的行为。"}, "sentence_index": 6, "correct_answer": "罪行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这是他的一次罪行，只是个小意外。", "explanation": "这里应该用〈过失〉。“罪行”指违法行为，与“只是个小意外”自相矛盾。"}, {"text": "他因这项发明获得了罪行。", "explanation": "这里应该用〈奖励〉。“获得”搭配“奖励”，不能说“获得罪行”。"}, {"text": "他犯下了一张罪行，后来被判了刑。", "explanation": "这里应该用〈项〉。“张”用于纸张、平面物品，不能用来数“罪行”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34687fa6-00cd-48ee-851a-715f6055399c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94862, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只罪行影响很大。", "corrected_sentence": "这桩罪行影响很大。", "error_description": "错误：“罪行”的量词用了“只”。“只”用于动物或单个小物件。正确量词是“桩”，用于案件、事件，应说“这桩罪行”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34687fa6-00cd-48ee-851a-715f6055399c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94862, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他罪行让受害者很愤怒。", "corrected_sentence": "他的罪行让受害者很愤怒。", "error_description": "错误：“他”和“罪行”之间漏了定语标记“的”。正确：应说“他的罪行”，表示所属关系。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34687fa6-00cd-48ee-851a-715f6055399c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
