INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94863, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d94915-20bc-43b4-a99f-f7a049f83d09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94863, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "董事会是一家大公司里做重要决定的一群人。", "primary_collocate": null, "pronunciation": "dǒng shì huì", "ipa": "tʊŋ˨˩ ʂɻ̩˥˩ xweɪ˥˩", "syllable_count": 3, "sentences": [{"text": "这家大公司的董事会今天开会。", "target_word": "董事会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "董事会里有五个人。", "target_word": "董事会", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "买别的公司，要问董事会。", "target_word": "董事会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "董事会决定明年开新店。", "target_word": "董事会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "王先生进了董事会，很高兴。", "target_word": "董事会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "董事会让经理换了新办法。", "target_word": "董事会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们公司的董事会在楼上开会。", "target_word": "董事会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "董事会说，今年不发奖金。", "target_word": "董事会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理把新计划送给了董事会。", "target_word": "董事会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板和董事会都不同意这件事。", "target_word": "董事会", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "董事會", "label": "繁体"}], "register": "正式", "sense_fingerprint": "大公司里做重要决定的一群人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21944ec0-25a1-4e3d-9f77-8f4f59681f20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94863, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "董事会", "is_correct": true, "explanation": "正确：这家大公司的董事会可以在今天开会。"}, {"text": "小狗", "is_correct": false, "explanation": "语义：小狗不是做决定的群体，不能开会。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：「冰箱今天开会」不是常见搭配，冰箱不能作开会的主语。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有开会的能力，与「大公司里做重要决定」的语境不符。"}], "explanations": {"董事会": "正确：这家大公司的董事会可以在今天开会。", "小狗": "语义：小狗不是做决定的群体，不能开会。", "冰箱": "搭配：「冰箱今天开会」不是常见搭配，冰箱不能作开会的主语。", "石头": "语义：石头没有开会的能力，与「大公司里做重要决定」的语境不符。"}, "sentence_index": 0, "correct_answer": "董事会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "董事会昨天在家里做饭，做得很好吃。", "explanation": "这里把董事会当成了会做饭的个人，应该用〈董事长〉指个人；董事会是机构，不能在家做饭。"}, {"text": "公司的董事会去年结婚了，婚礼很热闹。", "explanation": "这里应该用〈董事长〉。结婚的是人，董事会是机构，不能结婚。"}, {"text": "董事会每天在楼下排队吃饭，大家都很饿。", "explanation": "这里把董事会当成了会排队吃饭的人群；董事会是机构，不能排队吃饭，应改用〈职员〉指员工。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d94915-20bc-43b4-a99f-f7a049f83d09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94863, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "董事会", "is_correct": true, "explanation": "正确：我们公司的董事会可以在楼上开会。"}, {"text": "食堂", "is_correct": false, "explanation": "语义：食堂是吃饭的地方，不是做决定的机构，不能「在楼上开会」。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：小猫不能在楼上开会，也不是公司的组织。"}, {"text": "花园", "is_correct": false, "explanation": "搭配：花园不是会议场所，「在楼上开会」的主语不能是花园。"}], "explanations": {"董事会": "正确：我们公司的董事会可以在楼上开会。", "食堂": "语义：食堂是吃饭的地方，不是做决定的机构，不能「在楼上开会」。", "小猫": "语义：小猫不能在楼上开会，也不是公司的组织。", "花园": "搭配：花园不是会议场所，「在楼上开会」的主语不能是花园。"}, "sentence_index": 6, "correct_answer": "董事会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "董事会的脸上写满了笑容。", "explanation": "这里把董事会当成了有脸的人，应该用〈董事长〉指个人；董事会是机构，没有脸，不能有表情。"}, {"text": "这份报告的董事会写得很长。", "explanation": "这里把董事会当成了文件本身，应该用〈文件〉等书面材料表示；董事会是机构，不能说它写得很长。"}, {"text": "董事会昨天生病了，今天请假了。", "explanation": "这里把董事会当成了会生病请假的人，应该用〈董事〉指个人；董事会是机构，不会生病。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d94915-20bc-43b4-a99f-f7a049f83d09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94863, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家大公司有一位董事会，今天开会。", "corrected_sentence": "这家大公司有一个董事会，今天开会。", "error_description": "错误：「一位董事会」中量词「位」用错。「位」用于人，董事会是机构，应说「一个董事会」。正确形式：这家大公司有一个董事会，今天开会。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d94915-20bc-43b4-a99f-f7a049f83d09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94863, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们公司的董事会们在楼下开会，决定了这件事。", "corrected_sentence": "我们公司的董事会在楼下开会，决定了这件事。", "error_description": "错误：「董事会」是机构名称，后面不能加「们」表示复数，应说「董事们」，或直接说「董事会」。正确形式：我们公司的董事会在楼下开会，决定了这件事。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d94915-20bc-43b4-a99f-f7a049f83d09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
