INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94864, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d94915-20bc-43b4-a99f-f7a049f83d09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94864, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "由股东选出的董事组成、负责公司重大决策的机构。", "primary_collocate": null, "pronunciation": "dǒng shì huì", "ipa": "tʊŋ˨˩ ʂɻ̩˥˩ xweɪ˥˩", "syllable_count": 3, "sentences": [{"text": "董事会今天开会，决定新的计划。", "target_word": "董事会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司的董事会有九个人。", "target_word": "董事会", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "董事会同意了新经理的名单。", "target_word": "董事会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "股东们选出了新的董事会。", "target_word": "董事会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大事要先交给董事会决定。", "target_word": "董事会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "董事会每个月开一次会。", "target_word": "董事会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是这家公司董事会的成员。", "target_word": "董事会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "董事会没有通过这个办法。", "target_word": "董事会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "董事会的决定，经理必须执行。", "target_word": "董事会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在董事会上提出了不同意见。", "target_word": "董事会", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "董事會", "label": "繁体"}], "register": "正式", "sense_fingerprint": "公司股东选出董事组成的决策机构", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21944ec0-25a1-4e3d-9f77-8f4f59681f20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94864, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "董事会", "is_correct": true, "explanation": "正确：董事会是有决策权的机构，可以在今天开会并决定新的计划。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：小猫不是有决策能力的组织，不能开会并决定计划。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有开会的能力，与「决定新的计划」的主语不符。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：「开会」的主语应为人或组织，不能说「窗户今天开会」。"}], "explanations": {"董事会": "正确：董事会是有决策权的机构，可以在今天开会并决定新的计划。", "小猫": "语义：小猫不是有决策能力的组织，不能开会并决定计划。", "石头": "语义：石头没有开会的能力，与「决定新的计划」的主语不符。", "窗户": "搭配：「开会」的主语应为人或组织，不能说「窗户今天开会」。"}, "sentence_index": 0, "correct_answer": "董事会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他昨天和公司的董事会结婚了。", "explanation": "这里把董事会当成了一个人，应该用〈董事〉指个人；董事会是机构，不能结婚。"}, {"text": "他这个月当选为公司的董事会，负责签字。", "explanation": "这里把只能用于个人的「当选」用在了机构上，应该用〈董事〉指个人；董事会是机构，不能当选。"}, {"text": "董事会负责公司的日常管理，每天都来上班。", "explanation": "这里应该用〈经理〉。董事会负责重大决策，日常管理由经理负责，董事会不每天上班处理具体事务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d94915-20bc-43b4-a99f-f7a049f83d09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94864, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "董事会", "is_correct": true, "explanation": "正确：他是这家公司董事会的成员，「董事会」是公司的决策机构，可以有成员。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是场所，不能有「成员」这一身份。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室不是公司的组织，不能说「这家公司教室的成员」。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：「厨房的成员」不是常见搭配，厨房指场所，不说有成员。"}], "explanations": {"董事会": "正确：他是这家公司董事会的成员，「董事会」是公司的决策机构，可以有成员。", "花园": "语义：花园是场所，不能有「成员」这一身份。", "教室": "语义：教室不是公司的组织，不能说「这家公司教室的成员」。", "厨房": "搭配：「厨房的成员」不是常见搭配，厨房指场所，不说有成员。"}, "sentence_index": 6, "correct_answer": "董事会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "董事会感冒了，今天在家休息。", "explanation": "这里把董事会当成了会生病的人，应该用〈董事〉指个人；董事会是机构，不会感冒。"}, {"text": "他把新产品放进了董事会，卖得很好。", "explanation": "这里把董事会当成了存放物品的场所，应该用〈仓库〉之类表示存放的地方；董事会是决策机构，不是场所或容器。"}, {"text": "我昨天吃了董事会，很饱。", "explanation": "这里把董事会当成了可以吃的东西，应该用〈午饭〉等食物；董事会是机构，不能吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d94915-20bc-43b4-a99f-f7a049f83d09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94864, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司的一只董事会有七位成员。", "corrected_sentence": "这家公司的董事会有七位成员。", "error_description": "错误：「一只董事会」中量词「只」用错。「只」用于动物，不能修饰董事会，这里应说「一个董事会」或「一届董事会」。正确形式：这家公司的董事会有七位成员。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d94915-20bc-43b4-a99f-f7a049f83d09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94864, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家大公司的董事会的决定了新的规定。", "corrected_sentence": "这家大公司的董事会决定了新的规定。", "error_description": "错误：「董事会」后多加了「的」，「决定」应直接作谓语，应说「董事会决定了」，不说「董事会的决定了」。正确形式：这家大公司的董事会决定了新的规定。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d94915-20bc-43b4-a99f-f7a049f83d09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
