INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94865, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f15f862-54ec-4f7c-b9bf-4afd8bb7ebdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94865, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "行会是很久以前同一种手艺人的小团体。", "primary_collocate": null, "pronunciation": "háng huì", "ipa": "xɑŋ˧˥ xweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "古时候，同一行的手艺人会组成行会。", "target_word": "行会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个行会规定，新人要跟师傅学三年。", "target_word": "行会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那时候的木匠都加入了当地的行会。", "target_word": "行会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "行会帮手艺人定价格，也不让别人乱卖。", "target_word": "行会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是城里铜匠行会的老师傅。", "target_word": "行会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没加入行会的人，很难在城里开店。", "target_word": "行会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史书里说，中国很早就有行会了。", "target_word": "行会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每年春天，行会都请大家一起吃饭。", "target_word": "行会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里写着，铁匠也有自己的行会。", "target_word": "行会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "行会里的人互相帮忙，也互相管着。", "target_word": "行会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "行会制度", "label": "复合"}, {"form": "行會", "label": "繁体"}], "register": "偏书面", "sense_fingerprint": "古时候同一行手艺人组成的小团体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73c1303b-ce7a-48fa-ac4b-097cecf36469') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94865, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "医院", "is_correct": false, "explanation": "语义：医院是治病的机构，不是手艺人组成的团体，与“组成”不合。"}, {"text": "行会", "is_correct": true, "explanation": "正确：行会是古时同一行手艺人组成的团体，与“古时候”“同一行的手艺人”相合。"}, {"text": "工会", "is_correct": false, "explanation": "语义：工会是现代工人的组织，与“古时候”不合。"}, {"text": "班级", "is_correct": false, "explanation": "搭配：“班级”是学校的编制，不能说手艺人组成班级。"}], "explanations": {"医院": "语义：医院是治病的机构，不是手艺人组成的团体，与“组成”不合。", "行会": "正确：行会是古时同一行手艺人组成的团体，与“古时候”“同一行的手艺人”相合。", "工会": "语义：工会是现代工人的组织，与“古时候”不合。", "班级": "搭配：“班级”是学校的编制，不能说手艺人组成班级。"}, "sentence_index": 0, "correct_answer": "行会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这所大学的摄影行会每个星期都会办一次展览。", "explanation": "这里应该用〈协会〉。行会指古时同一行手艺人组成的团体，现代的兴趣组织用协会。"}, {"text": "我们厂的行会每个月开一次会，讨论工人的工资。", "explanation": "这里应该用〈工会〉。行会是古时手艺人的团体，现代工厂里为工人争取权益的是工会。"}, {"text": "我们班的书法行会每周六都一起练字。", "explanation": "这里应该用〈社团〉。行会指古时同行业的团体，学生的兴趣小组叫社团。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f15f862-54ec-4f7c-b9bf-4afd8bb7ebdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94865, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "互联网", "is_correct": false, "explanation": "语义：互联网是现代的技术，与“历史书里说”“很早”的时代矛盾。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是现代的通讯工具，与“很早就有”不合。"}, {"text": "行会", "is_correct": true, "explanation": "正确：行会是古时手艺人的团体，与“历史书里说”“很早就有”相合。"}, {"text": "哥们", "is_correct": false, "explanation": "语域：“哥们”是口语词，不适合历史书这样的书面语。"}], "explanations": {"互联网": "语义：互联网是现代的技术，与“历史书里说”“很早”的时代矛盾。", "手机": "语义：手机是现代的通讯工具，与“很早就有”不合。", "行会": "正确：行会是古时手艺人的团体，与“历史书里说”“很早就有”相合。", "哥们": "语域：“哥们”是口语词，不适合历史书这样的书面语。"}, "sentence_index": 6, "correct_answer": "行会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们镇上的行会每天放三场电影。", "explanation": "这里应该用〈电影院〉。行会是旧时手艺人的团体，不放映电影；放映电影的是电影院。"}, {"text": "我们行会今年招了两百名员工。", "explanation": "这里应该用〈公司〉。行会是旧时手艺人的团体，不招“员工”；现代企业招员工才用公司。"}, {"text": "行会每个学期都组织春游。", "explanation": "这里应该用〈学校〉。学期和春游是学校的活动，行会是旧时手艺人的团体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f15f862-54ec-4f7c-b9bf-4afd8bb7ebdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94865, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "各地的行会们都有自己的规矩。", "corrected_sentence": "各地的行会都有自己的规矩。", "error_description": "错误形式：“行会们”；正确形式：“行会”。行会是组织，不能加“们”，表示多个要说“各地的行会”“几个行会”等。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f15f862-54ec-4f7c-b9bf-4afd8bb7ebdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94865, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只行会的师傅教我们做木工。", "corrected_sentence": "那个行会的师傅教我们做木工。", "error_description": "错误形式：“那只行会”；正确形式：“那个行会”。行会是组织，量词应用“个”，不用“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f15f862-54ec-4f7c-b9bf-4afd8bb7ebdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
