INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94866, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f15f862-54ec-4f7c-b9bf-4afd8bb7ebdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94866, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "旧时同行业手工业者或商人为保护共同利益而组成的团体。", "primary_collocate": null, "pronunciation": "háng huì", "ipa": "xɑŋ˧˥ xweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "旧时，布商们组成行会来保护自己的生意。", "target_word": "行会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "行会的规矩很多，外地人不容易做生意。", "target_word": "行会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在古代城市里，每个行业都有自己的行会。", "target_word": "行会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他爷爷的爷爷是当地银匠行会的会长。", "target_word": "行会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "行会常常一起向官府提出要求。", "target_word": "行会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种行会到了清朝末年慢慢没有了。", "target_word": "行会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想在城里卖盐，得先交钱给行会。", "target_word": "行会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师讲了欧洲中世纪行会的故事。", "target_word": "行会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "行会里的师傅不让别人随便降价。", "target_word": "行会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当时的商人靠行会互相保护，不怕被欺负。", "target_word": "行会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "行会制度", "label": "复合"}, {"form": "行會", "label": "繁体"}], "register": "书面", "sense_fingerprint": "旧时同行业的手工业者或商人为保护共同利益组成的团体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73c1303b-ce7a-48fa-ac4b-097cecf36469') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94866, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "医院", "is_correct": false, "explanation": "语义：医院是治病的机构，与“保护自己的生意”不合。"}, {"text": "工会", "is_correct": false, "explanation": "语义：工会是现代的组织，不适用于“旧时”的布商。"}, {"text": "行会", "is_correct": true, "explanation": "正确：行会是旧时同行业商人或手工业者的团体，与“旧时”“组成”“保护自己的生意”相合。"}, {"text": "股份", "is_correct": false, "explanation": "搭配：“组成”后面不能接“股份”，不说“组成股份”。"}], "explanations": {"医院": "语义：医院是治病的机构，与“保护自己的生意”不合。", "工会": "语义：工会是现代的组织，不适用于“旧时”的布商。", "行会": "正确：行会是旧时同行业商人或手工业者的团体，与“旧时”“组成”“保护自己的生意”相合。", "股份": "搭配：“组成”后面不能接“股份”，不说“组成股份”。"}, "sentence_index": 0, "correct_answer": "行会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们小区的摄影行会每个月办一次展览。", "explanation": "这里应该用〈协会〉。行会指旧时同行业的人组成的团体，业余爱好的组织用协会。"}, {"text": "我叔叔是工厂的行会主席，负责工人的福利。", "explanation": "这里应该用〈工会〉。行会是旧时的行业团体，现代工厂为工人服务的是工会。"}, {"text": "我们班的围棋行会每周五都活动。", "explanation": "这里应该用〈俱乐部〉。行会是旧时的行业团体，爱好者的组织多叫俱乐部。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f15f862-54ec-4f7c-b9bf-4afd8bb7ebdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94866, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "学校", "is_correct": false, "explanation": "语义：卖盐的人不用向学校交钱，与句意不合。"}, {"text": "电脑", "is_correct": false, "explanation": "搭配：“交钱给”的对象应是人或机构，不能说“交钱给电脑”。"}, {"text": "战场", "is_correct": false, "explanation": "语义：战场不是收钱的机构，这句话说不通。"}, {"text": "行会", "is_correct": true, "explanation": "正确：行会是旧时的商人团体，要入行先向行会交钱，与“想在城里卖盐”相合。"}], "explanations": {"学校": "语义：卖盐的人不用向学校交钱，与句意不合。", "电脑": "搭配：“交钱给”的对象应是人或机构，不能说“交钱给电脑”。", "战场": "语义：战场不是收钱的机构，这句话说不通。", "行会": "正确：行会是旧时的商人团体，要入行先向行会交钱，与“想在城里卖盐”相合。"}, "sentence_index": 6, "correct_answer": "行会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "行会里每天都有很多病人。", "explanation": "这里应该用〈医院〉。行会是旧时同行业人为保护利益组成的团体，不接收病人；看病要去医院。"}, {"text": "我们行会今年招了两百名员工。", "explanation": "这里应该用〈公司〉。行会是旧时同行业人的团体，不招“员工”；现代企业招员工才用公司。"}, {"text": "行会每个学期都组织春游。", "explanation": "这里应该用〈学校〉。学期和春游是学校的活动，行会是旧时同行业人的团体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f15f862-54ec-4f7c-b9bf-4afd8bb7ebdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94866, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只行会的老师傅教徒弟做木工活。", "corrected_sentence": "那个行会的老师傅教徒弟做木工活。", "error_description": "错误形式：“那只行会”；正确形式：“那个行会”。行会是组织，量词应用“个”，不用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f15f862-54ec-4f7c-b9bf-4afd8bb7ebdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94866, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "几个行会们联名向官府递了状子。", "corrected_sentence": "几个行会联名向官府递了状子。", "error_description": "错误形式：“行会们”；正确形式：“行会”。行会是组织，不能加“们”，表示多个要说“几个行会”“各个行会”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f15f862-54ec-4f7c-b9bf-4afd8bb7ebdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94867, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "真话", "is_correct": true, "explanation": "真话是真实的话，与“谎言”意思相反。"}, {"text": "天空", "is_correct": false, "explanation": "天空与“谎言”没有反义关系。"}, {"text": "电脑", "is_correct": false, "explanation": "电脑与“谎言”没有反义关系。"}, {"text": "作文", "is_correct": false, "explanation": "作文与“谎言”没有反义关系。"}], "correct_answer": "真话", "explanations": {"真话": "真话是真实的话，与“谎言”意思相反。", "天空": "天空与“谎言”没有反义关系。", "电脑": "电脑与“谎言”没有反义关系。", "作文": "作文与“谎言”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf47c05-ff6e-4ac9-8a71-e8a1aae506d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94867, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "真话", "is_correct": true, "explanation": "真话是真实的话，与“谎言”意思相反。"}, {"text": "灯泡", "is_correct": false, "explanation": "灯泡与“谎言”没有反义关系。"}, {"text": "老虎", "is_correct": false, "explanation": "老虎与“谎言”没有反义关系。"}, {"text": "果汁", "is_correct": false, "explanation": "果汁与“谎言”没有反义关系。"}], "correct_answer": "真话", "explanations": {"真话": "真话是真实的话，与“谎言”意思相反。", "灯泡": "灯泡与“谎言”没有反义关系。", "老虎": "老虎与“谎言”没有反义关系。", "果汁": "果汁与“谎言”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf47c05-ff6e-4ac9-8a71-e8a1aae506d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94867, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "谎言是不真的话，是骗人的话。", "primary_collocate": null, "pronunciation": "huǎng yán", "ipa": "xwɑŋ˨˩˦ jɛn˧˥", "syllable_count": 2, "sentences": [{"text": "你为什么要用谎言骗我？", "target_word": "谎言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直生活在谎言里。", "target_word": "谎言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些话都是谎言，别相信。", "target_word": "谎言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她发现丈夫对她说了很多谎言。", "target_word": "谎言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个谎言需要更多谎言来保护。", "target_word": "谎言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的谎言很快就没人信了。", "target_word": "谎言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子为了不挨骂，编了一个谎言。", "target_word": "谎言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不喜欢谎言，只想听真话。", "target_word": "谎言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好朋友之间不能有谎言。", "target_word": "谎言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新闻里的那个谎言，大家都知道了。", "target_word": "谎言", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一句谎言", "label": "量词"}, {"form": "一个谎言", "label": "量词"}, {"form": "謊言", "label": "繁体"}], "register": "中性", "sense_fingerprint": "不真实、骗人的话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c775263-ec78-4df2-815b-c2b3a153698a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94867, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "谎言", "is_correct": true, "explanation": "谎言是骗人的话，放在“你为什么要用___骗我？”中，“用”的宾语是骗人的手段，语义相符。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙不是骗人的手段，“用钥匙骗我”语义不通。"}, {"text": "空调", "is_correct": false, "explanation": "语义：空调不能用来骗人，句中“骗”需要的是话或假象。"}, {"text": "钢琴", "is_correct": false, "explanation": "搭配：钢琴不能作为骗人的手段，“用钢琴骗我”搭配不当。"}], "explanations": {"谎言": "谎言是骗人的话，放在“你为什么要用___骗我？”中，“用”的宾语是骗人的手段，语义相符。", "钥匙": "语义：钥匙不是骗人的手段，“用钥匙骗我”语义不通。", "空调": "语义：空调不能用来骗人，句中“骗”需要的是话或假象。", "钢琴": "搭配：钢琴不能作为骗人的手段，“用钢琴骗我”搭配不当。"}, "sentence_index": 0, "correct_answer": "谎言"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她找了个谎言，说自己要出差，就不来了。", "explanation": "这里应该用〈借口〉。“找借口”是固定搭配；谎言是编造出来的假话，不说“找”。"}, {"text": "丈夫对她说了一张谎言，她没有相信。", "explanation": "这里应该用〈句〉或〈个〉。“张”用于纸张、桌面等平面的东西，不能用来计量谎言。"}, {"text": "丈夫给她讲了一根谎言，她很快就发现了。", "explanation": "这里应该用〈句〉或〈个〉。“根”用于细长的东西，不能用来计量谎言。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf47c05-ff6e-4ac9-8a71-e8a1aae506d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94867, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "谎言", "is_correct": true, "explanation": "“编了一个___”中，谎言是可以编造的内容，语义相符。"}, {"text": "皮鞋", "is_correct": false, "explanation": "语义：皮鞋不是可以编造的内容，“编了一个皮鞋”语义不通。"}, {"text": "房子", "is_correct": false, "explanation": "配价：“编”的宾语多为故事、谎话、歌曲等，“房子”不能被编。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟不是可以编造的内容，句中需要的是假话。"}], "explanations": {"谎言": "“编了一个___”中，谎言是可以编造的内容，语义相符。", "皮鞋": "语义：皮鞋不是可以编造的内容，“编了一个皮鞋”语义不通。", "房子": "配价：“编”的宾语多为故事、谎话、歌曲等，“房子”不能被编。", "闹钟": "语义：闹钟不是可以编造的内容，句中需要的是假话。"}, "sentence_index": 6, "correct_answer": "谎言"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把谎言切成了几块，装进盘子里。", "explanation": "谎言是抽象的假话，不能切开装盘，这里把它当成了食物。"}, {"text": "那个谎言在桌子上跑来跑去，很可爱。", "explanation": "谎言不会自己跑动，也不可爱，这里把它当成了有生命的东西。"}, {"text": "那个谎言被雨淋湿了，颜色变深了。", "explanation": "谎言是抽象的话，没有实体，不会被雨淋湿，这里把它当成了有实体的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf47c05-ff6e-4ac9-8a71-e8a1aae506d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94867, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的那张谎言很快就被拆穿了。", "corrected_sentence": "他的那个谎言很快就被拆穿了。", "error_description": "量词错误：“张”用于纸张、桌面等平面的东西，不能计量谎言，这里应改为“那个谎言”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf47c05-ff6e-4ac9-8a71-e8a1aae506d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94867, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她听到了一本谎言，心里很难过。", "corrected_sentence": "她听到了一句谎言，心里很难过。", "error_description": "错误：“谎言”的量词用“本”。“本”用于书籍，谎言是话，应用量词“句”，说“一句谎言”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf47c05-ff6e-4ac9-8a71-e8a1aae506d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
