INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94868, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "虚假的、用来骗人的话。", "primary_collocate": null, "pronunciation": "huǎng yán", "ipa": "xwɑŋ˨˩˦ jɛn˧˥", "syllable_count": 2, "sentences": [{"text": "他说的是谎言，我们都不信。", "target_word": "谎言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谎言总有一天会被戳穿。", "target_word": "谎言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不想再听他的谎言了。", "target_word": "谎言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明说了一个谎言，妈妈很生气。", "target_word": "谎言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师告诉孩子们，不能编造谎言。", "target_word": "谎言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用谎言骗了朋友。", "target_word": "谎言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个谎言让大家很难过。", "target_word": "谎言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谎言一旦被揭穿，就很难再让人相信。", "target_word": "谎言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，谎言会伤害别人。", "target_word": "谎言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我听出来了，这是一句谎言。", "target_word": "谎言", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一句谎言", "label": "量词"}, {"form": "一个谎言", "label": "量词"}, {"form": "謊言", "label": "繁体"}], "register": "中性", "sense_fingerprint": "虚假的、用来骗人的话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c775263-ec78-4df2-815b-c2b3a153698a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94868, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "谎言", "is_correct": true, "explanation": "谎言指虚假的、用来骗人的话，放在“他说的是___，我们都不信”中，与“不信”相符。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：“他说的是歌曲”虽合语法，但歌曲不是可以相信或不相信的内容，与“我们都不信”搭配不起来。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是可以说出来的内容，“他说的是冰箱，我们都不信”语义不通。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不存在真假可辨的内容，与“我们都不信”搭配不起来。"}], "explanations": {"谎言": "谎言指虚假的、用来骗人的话，放在“他说的是___，我们都不信”中，与“不信”相符。", "歌曲": "语义：“他说的是歌曲”虽合语法，但歌曲不是可以相信或不相信的内容，与“我们都不信”搭配不起来。", "冰箱": "语义：冰箱不是可以说出来的内容，“他说的是冰箱，我们都不信”语义不通。", "汽车": "语义：汽车不存在真假可辨的内容，与“我们都不信”搭配不起来。"}, "sentence_index": 0, "correct_answer": "谎言"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他找了个谎言，说自己生病了，不去上班。", "explanation": "这里应该用〈借口〉。“找借口”是固定搭配；谎言是编造出来的假话，不说“找”。"}, {"text": "妈妈听了一把谎言，心里很难过。", "explanation": "这里应该用〈句〉或〈个〉。“把”用于有柄的器具，不能用来计量谎言。"}, {"text": "他编了一根谎言，很快就被拆穿了。", "explanation": "这里应该用〈句〉或〈个〉。“根”用于细长的东西，不能用来计量谎言。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf47c05-ff6e-4ac9-8a71-e8a1aae506d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94868, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "谎言", "is_correct": true, "explanation": "谎言能引起大家难过，放在“这个___让大家很难过”中语义通顺。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能让大家难过，句中需要能引起情绪的人或事。"}, {"text": "白菜", "is_correct": false, "explanation": "语义：白菜不能让大家难过，句子说的是引起情绪的事。"}, {"text": "眼镜", "is_correct": false, "explanation": "搭配：“眼镜”与“让大家很难过”搭配不当，也不是令人难过的事。"}], "explanations": {"谎言": "谎言能引起大家难过，放在“这个___让大家很难过”中语义通顺。", "桌子": "语义：桌子不能让大家难过，句中需要能引起情绪的人或事。", "白菜": "语义：白菜不能让大家难过，句子说的是引起情绪的事。", "眼镜": "搭配：“眼镜”与“让大家很难过”搭配不当，也不是令人难过的事。"}, "sentence_index": 6, "correct_answer": "谎言"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把谎言放进冰箱里，怕它坏掉。", "explanation": "谎言是抽象的假话，不是食物或物品，不能放进冰箱，这里把它当成了具体的东西。"}, {"text": "这个谎言昨天去超市买了三斤苹果。", "explanation": "谎言是抽象的假话，不会自己去超市买东西，这里把它当成了人。"}, {"text": "这个谎言开花了，颜色很漂亮。", "explanation": "谎言不是植物，不能开花，这里误用了词义。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf47c05-ff6e-4ac9-8a71-e8a1aae506d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94868, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只谎言被大家识破了。", "corrected_sentence": "那个谎言被大家识破了。", "error_description": "量词错误：“谎言”的量词应用“个”或“句”，“只”用于动物等，这里应改为“那个谎言”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf47c05-ff6e-4ac9-8a71-e8a1aae506d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94868, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他说了一本谎言，大家都不信。", "corrected_sentence": "他说了一句谎言，大家都不信。", "error_description": "错误：“谎言”的量词用“本”。“本”用于书籍，谎言是话，应用量词“句”，说“一句谎言”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf47c05-ff6e-4ac9-8a71-e8a1aae506d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94869, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '607e29e9-b1d6-4274-a4c2-ecaae7dee8f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
