INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94869, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "赌场是大人用钱来玩输赢游戏的地方。", "primary_collocate": null, "pronunciation": "dǔ chǎng", "ipa": "tu˨˩˦ ʈʂʰaŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "爸爸说，赌场不是小孩子去的地方。", "target_word": "赌场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "赌场里的灯很亮，声音也很吵。", "target_word": "赌场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他第一次去赌场，只玩了一个小时。", "target_word": "赌场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "赌场是大人玩牌赢钱的地方。", "target_word": "赌场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们旅行时参观过那个有名的赌场。", "target_word": "赌场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "进赌场的人都想赢钱，可是常常会输。", "target_word": "赌场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "赌场里不能带小孩进去。", "target_word": "赌场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "赌场老板每天都能收到很多钱。", "target_word": "赌场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从赌场出来，口袋里一分钱也没有了。", "target_word": "赌场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "澳门有很多大赌场，游客也很多。", "target_word": "赌场", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}, {"form": "賭場", "label": "繁体"}], "register": "中性", "sense_fingerprint": "大人用钱玩输赢游戏的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd4c21aa-a6d3-4972-9722-723031958938') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94869, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "赌场", "is_correct": true, "explanation": "赌场（dǔ chǎng）指大人用钱玩输赢游戏的地方，是正确答案。"}, {"text": "独唱", "is_correct": false, "explanation": "独唱（dú chàng）两个音节的声调都与“赌场”不同，意思是一个人演唱。"}, {"text": "肚肠", "is_correct": false, "explanation": "肚肠（dù cháng）两个音节的声调都与“赌场”不同，意思是胃肠等内脏。"}, {"text": "谷场", "is_correct": false, "explanation": "谷场（gǔ chǎng）只有声母不同：g 与“赌”的 d 不同，意思是打谷子用的场地。"}], "explanations": {"赌场": "赌场（dǔ chǎng）指大人用钱玩输赢游戏的地方，是正确答案。", "独唱": "独唱（dú chàng）两个音节的声调都与“赌场”不同，意思是一个人演唱。", "肚肠": "肚肠（dù cháng）两个音节的声调都与“赌场”不同，意思是胃肠等内脏。", "谷场": "谷场（gǔ chǎng）只有声母不同：g 与“赌”的 d 不同，意思是打谷子用的场地。"}, "sentence_index": null, "correct_answer": "赌场"}, "level_3": {"options": [{"text": "赌场", "is_correct": true, "explanation": "赌场是大人去的地方，与“不是小孩子去的地方”的语境相合。"}, {"text": "幼儿园", "is_correct": false, "explanation": "语义：幼儿园正是小孩子去的地方，与“不是小孩子去的地方”矛盾。"}, {"text": "游乐场", "is_correct": false, "explanation": "语义：游乐场是小孩子常去的地方，与句意矛盾。"}, {"text": "冰淇淋", "is_correct": false, "explanation": "搭配：“去的地方”要求处所，“冰淇淋”不是处所。"}], "explanations": {"赌场": "赌场是大人去的地方，与“不是小孩子去的地方”的语境相合。", "幼儿园": "语义：幼儿园正是小孩子去的地方，与“不是小孩子去的地方”矛盾。", "游乐场": "语义：游乐场是小孩子常去的地方，与句意矛盾。", "冰淇淋": "搭配：“去的地方”要求处所，“冰淇淋”不是处所。"}, "sentence_index": 0, "correct_answer": "赌场"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们下了一大笔赌场。", "explanation": "这里应该用〈赌注〉。赌注是下注的钱，赌场是场所，不能用来下注。"}, {"text": "他把赌场押在桌上。", "explanation": "这里应该用〈筹码〉。筹码是下注时押在桌上的小件，赌场是场所，不能当作筹码押上桌。"}, {"text": "他们安排了一场赌场。", "explanation": "这里应该用〈赌局〉。赌局指一场赌博活动，赌场是供人赌博的场所，不能说“一场赌场”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '607e29e9-b1d6-4274-a4c2-ecaae7dee8f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94869, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "赌场", "is_correct": true, "explanation": "赌场是可以进去的处所，“里”指场所内部，与“进去”相合。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：“进去”要求能进入的处所，书包不能让人“进去”。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不是能让人进去的地方，句意不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不能让小孩进去，句意不通。"}], "explanations": {"赌场": "赌场是可以进去的处所，“里”指场所内部，与“进去”相合。", "书包": "搭配：“进去”要求能进入的处所，书包不能让人“进去”。", "手机": "语义：手机不是能让人进去的地方，句意不通。", "冰箱": "语义：冰箱不能让小孩进去，句意不通。"}, "sentence_index": 6, "correct_answer": "赌场"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他为了还赌场，卖掉了房子。", "explanation": "这里应该用〈赌债〉。赌债指赌博欠下的债，赌场是场所，不能说“还赌场”。"}, {"text": "他输光了所有的赌场，连回家的车钱都没了。", "explanation": "这里应该用〈赌资〉。赌资指用于赌博的钱，赌场是场所，不能说“输光了赌场”。"}, {"text": "他的赌场是跟父亲学的。", "explanation": "这里应该用〈赌术〉。赌术指赌博的技巧，赌场是场所，不是可以学的技能。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '607e29e9-b1d6-4274-a4c2-ecaae7dee8f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94869, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只赌场只有成年人能进。", "corrected_sentence": "这家赌场只有成年人能进。", "error_description": "量词错误：“这只赌场”中的“只”用于动物，赌场应用“家”，应说“这家赌场”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '607e29e9-b1d6-4274-a4c2-ecaae7dee8f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94869, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在赌场走出来，手里还拿着几张牌。", "corrected_sentence": "他从赌场走出来，手里还拿着几张牌。", "error_description": "介词错误：表示离开某个处所的起点要用“从”，不能用“在”，应说“从赌场走出来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '607e29e9-b1d6-4274-a4c2-ecaae7dee8f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94871, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "反对", "is_correct": true, "explanation": "“反对”与“赞成”意思相反，是其反义词，表示不同意。"}, {"text": "思考", "is_correct": false, "explanation": "“思考”指用脑子想问题，与“赞成”没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "“散步”指在户外慢慢走，与“赞成”没有反义关系。"}, {"text": "游泳", "is_correct": false, "explanation": "“游泳”指在水中活动，与“赞成”没有反义关系。"}], "correct_answer": "反对", "explanations": {"反对": "“反对”与“赞成”意思相反，是其反义词，表示不同意。", "思考": "“思考”指用脑子想问题，与“赞成”没有反义关系。", "散步": "“散步”指在户外慢慢走，与“赞成”没有反义关系。", "游泳": "“游泳”指在水中活动，与“赞成”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e79ecf5c-5410-4911-8680-f65e8db16a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94871, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "反对", "is_correct": true, "explanation": "“反对”与“赞成”意思相反，是其反义词，表示不同意。"}, {"text": "唱歌", "is_correct": false, "explanation": "“唱歌”指用声音表演音乐，与“赞成”没有反义关系。"}, {"text": "读书", "is_correct": false, "explanation": "“读书”指看书学习，与“赞成”没有反义关系。"}, {"text": "吃饭", "is_correct": false, "explanation": "“吃饭”指进食，与“赞成”没有反义关系。"}], "correct_answer": "反对", "explanations": {"反对": "“反对”与“赞成”意思相反，是其反义词，表示不同意。", "唱歌": "“唱歌”指用声音表演音乐，与“赞成”没有反义关系。", "读书": "“读书”指看书学习，与“赞成”没有反义关系。", "吃饭": "“吃饭”指进食，与“赞成”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e79ecf5c-5410-4911-8680-f65e8db16a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94871, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "赞成是觉得别人说得对，同意。", "primary_collocate": null, "pronunciation": "zàn chéng", "ipa": "tsan˥˩ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "我觉得他说得对，所以我赞成。", "target_word": "赞成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都说要早点出发，我也赞成。", "target_word": "赞成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说周末去爬山，我完全赞成。", "target_word": "赞成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的看法很有道理，我赞成你的看法。", "target_word": "赞成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我赞成他的看法，因为他说得很清楚。", "target_word": "赞成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说得很好，我们都赞成。", "target_word": "赞成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听了她的话，我马上举手赞成。", "target_word": "赞成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友说多运动对身体好，我很赞成。", "target_word": "赞成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说的话有道理，同学们都赞成。", "target_word": "赞成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从来不赞成他那样说。", "target_word": "赞成", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "赞成了", "label": "体标（了）"}, {"form": "赞成过", "label": "体标（过）"}, {"form": "贊成", "label": "繁体"}], "register": "中性", "sense_fingerprint": "觉得别人的话或看法对，表示同意", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a411a526-522a-48ad-8c7c-56a20b15b9e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94871, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "赞成", "is_correct": true, "explanation": "“赞成”表示认同别人说得对，与句中“觉得他说得对”的判断一致。"}, {"text": "反对", "is_correct": false, "explanation": "语义：“反对”表示不同意，与“觉得他说得对”的判断相反。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：“讨厌”表示厌恶，与对他说法的认可相矛盾。"}, {"text": "同情", "is_correct": false, "explanation": "搭配：“同情”用于对人的遭遇表示怜悯，不用来表示认可别人的说法。"}], "explanations": {"赞成": "“赞成”表示认同别人说得对，与句中“觉得他说得对”的判断一致。", "反对": "语义：“反对”表示不同意，与“觉得他说得对”的判断相反。", "讨厌": "语义：“讨厌”表示厌恶，与对他说法的认可相矛盾。", "同情": "搭配：“同情”用于对人的遭遇表示怜悯，不用来表示认可别人的说法。"}, "sentence_index": 0, "correct_answer": "赞成"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师赞成了他的努力。", "explanation": "这里应该用〈赞美〉。赞成用于同意别人的看法或主张，称赞别人的努力要用赞美。"}, {"text": "我们都赞成新来的同学。", "explanation": "这里应该用〈欢迎〉。赞成的对象是看法、主张或计划，不能用来接纳人，欢迎新同学要用欢迎。"}, {"text": "我赞成你的帮助。", "explanation": "这里应该用〈感谢〉。赞成表示同意看法，对别人的帮助表示谢意要用感谢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e79ecf5c-5410-4911-8680-f65e8db16a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94871, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "赞成", "is_correct": true, "explanation": "“赞成”表示同意，举手表示同意，符合“马上举手”的句意。"}, {"text": "散步", "is_correct": false, "explanation": "语义：举手表态与“散步”无关，句子表达的是表决时的态度。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“听了她的话，我马上举手睡觉”意思不通，与表态的语境不符。"}, {"text": "生气", "is_correct": false, "explanation": "搭配：“举手”后接表态性动作，“生气”是情绪，与举手表决的语境不搭配。"}], "explanations": {"赞成": "“赞成”表示同意，举手表示同意，符合“马上举手”的句意。", "散步": "语义：举手表态与“散步”无关，句子表达的是表决时的态度。", "睡觉": "语义：“听了她的话，我马上举手睡觉”意思不通，与表态的语境不符。", "生气": "搭配：“举手”后接表态性动作，“生气”是情绪，与举手表决的语境不搭配。"}, "sentence_index": 6, "correct_answer": "赞成"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我非常赞成他的勇气。", "explanation": "这里应该用〈佩服〉。赞成的对象是看法、主张或做法，对别人的勇气表示敬佩要用佩服。"}, {"text": "我们都赞成他的生日。", "explanation": "这里应该用〈庆祝〉。赞成针对看法和主张，不能用于生日这类喜事，庆祝生日要用庆祝。"}, {"text": "我赞成他的身高。", "explanation": "这里应该用〈羡慕〉。赞成表示同意看法或主张，对别人的身材表示羡慕要用羡慕。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e79ecf5c-5410-4911-8680-f65e8db16a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94871, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我没赞成了这个计划。", "corrected_sentence": "我没赞成这个计划。", "error_description": "“没”否定动作时，“赞成”后面不能再加“了”。正确说法是“我没赞成这个计划”，不能说“我没赞成了这个计划”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e79ecf5c-5410-4911-8680-f65e8db16a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94871, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师没赞成了这个计划。", "corrected_sentence": "老师没赞成过这个计划。", "error_description": "“没”否定经历时，动词后要用“过”，应说“没赞成过这个计划”，不能用“了”说“没赞成了这个计划”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e79ecf5c-5410-4911-8680-f65e8db16a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
