INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94873, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "军方指军队这一方，常与政府或民间相对。", "primary_collocate": null, "pronunciation": "jūn fāng", "ipa": "tɕyn˥ faŋ˥", "syllable_count": 2, "sentences": [{"text": "谈判时，军方和政府意见不同。", "target_word": "军方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军方表示，会派人帮助救灾。", "target_word": "军方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军方和民间都参加了这次活动。", "target_word": "军方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军方发言人回答了记者的问题。", "target_word": "军方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司和军方有长期的合作。", "target_word": "军方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事需要军方同意才能做。", "target_word": "军方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个项目由军方和学校一起做。", "target_word": "军方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军方的训练基地离城市很远。", "target_word": "军方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "民间和军方的关系一直很好。", "target_word": "军方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有军方的背景，大家都很尊重他。", "target_word": "军方", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "正式", "sense_fingerprint": "和军队有关的一边", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59c51a76-670c-44fa-8b2f-c5c9944b2429') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94873, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "军方", "is_correct": true, "explanation": "军方（jūn fāng）指和军队有关的一边，是正确答案。"}, {"text": "均分", "is_correct": false, "explanation": "fēn（分）与 fāng（方）韵母不同（前鼻音与后鼻音），意思是平均分配。"}, {"text": "军风", "is_correct": false, "explanation": "fēng（风）与 fāng（方）韵母不同（eng 与 ang），军风指军队的作风。"}, {"text": "军防", "is_correct": false, "explanation": "fáng（防）与 fāng（方）声调不同（第二声与第一声），意思是军事防守。"}], "explanations": {"军方": "军方（jūn fāng）指和军队有关的一边，是正确答案。", "均分": "fēn（分）与 fāng（方）韵母不同（前鼻音与后鼻音），意思是平均分配。", "军风": "fēng（风）与 fāng（方）韵母不同（eng 与 ang），军风指军队的作风。", "军防": "fáng（防）与 fāng（方）声调不同（第二声与第一声），意思是军事防守。"}, "sentence_index": null, "correct_answer": "军方"}, "level_3": {"options": [{"text": "军方", "is_correct": true, "explanation": "军方指和军队有关的一边，能与政府在谈判中意见不同，符合语境。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是场所，不能在谈判中与政府持不同意见。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户没有立场，不能与政府意见不同。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材指人的体形，不能持有意见。"}], "explanations": {"军方": "军方指和军队有关的一边，能与政府在谈判中意见不同，符合语境。", "厨房": "语义：厨房是场所，不能在谈判中与政府持不同意见。", "窗户": "语义：窗户没有立场，不能与政府意见不同。", "身材": "体貌：身材指人的体形，不能持有意见。"}, "sentence_index": 0, "correct_answer": "军方"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "军方今年三岁了，还不太会说话。", "explanation": "这里应该用〈孩子〉。军方是和军队有关的一边，是抽象的关系，不能说年龄。"}, {"text": "这个超市的军方很多，我每天都去。", "explanation": "这里应该用〈商品〉。军方是和军队有关的一方，不能指超市里的商品，也不能说「很多军方」。"}, {"text": "他把军方借给了朋友。", "explanation": "这里应该用〈资料〉。军方是抽象的一方，不能像物品一样借出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34687fa6-00cd-48ee-851a-715f6055399c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94873, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "军方", "is_correct": true, "explanation": "军方指和军队有关的一边，可以与学校一起承担项目，符合语境。"}, {"text": "天空", "is_correct": false, "explanation": "配价：“由……做”要求能做事的主体，天空不能承担项目，与学校并列也不成立。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车是交通工具，不能承担或完成项目。"}, {"text": "镜子", "is_correct": false, "explanation": "语义：镜子是物品，不能承担或完成项目。"}], "explanations": {"军方": "军方指和军队有关的一边，可以与学校一起承担项目，符合语境。", "天空": "配价：“由……做”要求能做事的主体，天空不能承担项目，与学校并列也不成立。", "汽车": "语义：汽车是交通工具，不能承担或完成项目。", "镜子": "语义：镜子是物品，不能承担或完成项目。"}, "sentence_index": 6, "correct_answer": "军方"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "军方跑得很快，大家都追不上。", "explanation": "这里应该用〈选手〉。军方是和军队有关的一边，是抽象的关系，不能像人一样跑步。"}, {"text": "我们的食堂用军方做饭。", "explanation": "这里应该用〈食材〉。军方是抽象的一方，不能作为做饭的材料。"}, {"text": "窗外的军方在唱歌，很好听。", "explanation": "这里应该用〈小鸟〉。军方是和军队有关的一边，不会唱歌，不能作为唱歌的主体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34687fa6-00cd-48ee-851a-715f6055399c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94873, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "军方得代表今天很忙。", "corrected_sentence": "军方的代表今天很忙。", "error_description": "错误形式“军方得代表”，正确形式“军方的代表”：“的”连接定语“军方”和中心语“代表”，“得”用于补语，不能用于此处。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34687fa6-00cd-48ee-851a-715f6055399c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94873, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事，军方的同意了我们的请求。", "corrected_sentence": "这件事，军方同意了我们的请求。", "error_description": "错误形式「军方的同意了」，正确形式「军方同意了」：「的」后面接的是动词「同意」，这里应直接作谓语，去掉「的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34687fa6-00cd-48ee-851a-715f6055399c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
