INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94875, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "辩护是替别人说话，说他没有错。", "primary_collocate": null, "pronunciation": "biàn hù", "ipa": "pjɛn˥˩ xu˥˩", "syllable_count": 2, "sentences": [{"text": "他的朋友站出来替他辩护。", "target_word": "辩护", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "律师在法庭上为小王辩护。", "target_word": "辩护", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都批评他时，只有妈妈为他辩护。", "target_word": "辩护", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师相信她，所以一直替她辩护。", "target_word": "辩护", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哥哥做错了事，姐姐还帮他辩护。", "target_word": "辩护", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她不想听别人为那个人辩护。", "target_word": "辩护", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "面对记者的批评，经理的同事出来为他辩护。", "target_word": "辩护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁来替这个孩子辩护一下呢？", "target_word": "辩护", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他为了朋友，在会上辩护了半个小时。", "target_word": "辩护", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我愿意为你辩护，因为我知道你没有说谎。", "target_word": "辩护", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "辩护了", "label": "完成体"}, {"form": "辩护过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "替别人说话，说明他没有错", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73c1303b-ce7a-48fa-ac4b-097cecf36469') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94875, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "辩护", "is_correct": true, "explanation": "正确答案。辩护指替别人说话，说他没有错。"}, {"text": "变化", "is_correct": false, "explanation": "huà 比 hù 多一个元音 a，韵母不同，意思是改变、变化，不是替别人说话。"}, {"text": "遍布", "is_correct": false, "explanation": "bù 与 hù 声母不同（b 与 h），意思是散布到各处，不是替别人说话。"}, {"text": "变故", "is_correct": false, "explanation": "gù 与 hù 声母不同（g 与 h），意思是意外发生的事情，不是替别人说话。"}], "explanations": {"辩护": "正确答案。辩护指替别人说话，说他没有错。", "变化": "huà 比 hù 多一个元音 a，韵母不同，意思是改变、变化，不是替别人说话。", "遍布": "bù 与 hù 声母不同（b 与 h），意思是散布到各处，不是替别人说话。", "变故": "gù 与 hù 声母不同（g 与 h），意思是意外发生的事情，不是替别人说话。"}, "sentence_index": null, "correct_answer": "辩护"}, "level_3": {"options": [{"text": "辩护", "is_correct": true, "explanation": "正确。“替他辩护”指替他说话、说他没有错，符合句意。"}, {"text": "躲藏", "is_correct": false, "explanation": "语义：“躲藏”与“站出来”的行为相反，说不通。"}, {"text": "逃跑", "is_correct": false, "explanation": "语义：“逃跑”与“站出来”的行为相反，替人逃跑说不通。"}, {"text": "发胖", "is_correct": false, "explanation": "体貌：“发胖”说的是体形变化，与替人说话无关。"}], "explanations": {"辩护": "正确。“替他辩护”指替他说话、说他没有错，符合句意。", "躲藏": "语义：“躲藏”与“站出来”的行为相反，说不通。", "逃跑": "语义：“逃跑”与“站出来”的行为相反，替人逃跑说不通。", "发胖": "体貌：“发胖”说的是体形变化，与替人说话无关。"}, "sentence_index": 0, "correct_answer": "辩护"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "战士们冲上去，用身体辩护那个受伤的孩子。", "explanation": "这里应该用〈保护〉。辩护是用言语替人说话、说他没有错，不能用身体去做。"}, {"text": "放学后，妈妈轻轻辩护他，他就不哭了。", "explanation": "这里应该用〈安慰〉。辩护是替人说话、说他没有错，不是用来安抚情绪。"}, {"text": "全家人出发前都辩护他一路平安。", "explanation": "这里应该用〈祝福〉。辩护是替人说话、说他没有错，不能用来表示祝愿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f15f862-54ec-4f7c-b9bf-4afd8bb7ebdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94875, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "辩护", "is_correct": true, "explanation": "正确答案。辩护指替别人说话，说他没有错。"}, {"text": "变速", "is_correct": false, "explanation": "sù 与 hù 声母不同（s 与 h），意思是改变速度，不是替别人说话。"}, {"text": "变数", "is_correct": false, "explanation": "shù 与 hù 声母不同（sh 与 h），意思是不确定的因素，不是替别人说话。"}, {"text": "遍布", "is_correct": false, "explanation": "bù 与 hù 声母不同（b 与 h），意思是散布到各处，不是替别人说话。"}], "explanations": {"辩护": "正确答案。辩护指替别人说话，说他没有错。", "变速": "sù 与 hù 声母不同（s 与 h），意思是改变速度，不是替别人说话。", "变数": "shù 与 hù 声母不同（sh 与 h），意思是不确定的因素，不是替别人说话。", "遍布": "bù 与 hù 声母不同（b 与 h），意思是散布到各处，不是替别人说话。"}, "sentence_index": null, "correct_answer": "辩护"}, "level_3": {"options": [{"text": "辩护", "is_correct": true, "explanation": "正确。“出来为他辩护”指站出来替他说话、说他没有错，符合句意。"}, {"text": "沉默", "is_correct": false, "explanation": "语义：“沉默”是不说话，与“出来为他”说话的动作矛盾。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”是讥讽别人，与面对批评时出来替他说话的意思相反。"}, {"text": "长大", "is_correct": false, "explanation": "体貌：“长大”说的是年龄和身体的成长，与替人说话无关。"}], "explanations": {"辩护": "正确。“出来为他辩护”指站出来替他说话、说他没有错，符合句意。", "沉默": "语义：“沉默”是不说话，与“出来为他”说话的动作矛盾。", "嘲笑": "语义：“嘲笑”是讥讽别人，与面对批评时出来替他说话的意思相反。", "长大": "体貌：“长大”说的是年龄和身体的成长，与替人说话无关。"}, "sentence_index": 6, "correct_answer": "辩护"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈一直辩护着生病的弟弟，寸步不离。", "explanation": "这里应该用〈陪伴〉。辩护是替人说话、说他没有错，不指守在身边。"}, {"text": "教练每天辩护运动员，让他们变得更强。", "explanation": "这里应该用〈训练〉。辩护是替人说话、说他没有错，不能用来指督促练习。"}, {"text": "他蹲在门口，认真地辩护那扇门。", "explanation": "这里应该用〈修理〉。辩护是替人说话、说他没有错，不能用来指修理门窗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f15f862-54ec-4f7c-b9bf-4afd8bb7ebdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94875, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她在法庭上朋友辩护。", "corrected_sentence": "她在法庭上为朋友辩护。", "error_description": "“辩护”引出受益的人时，前面要加介词“为”，应说“为朋友辩护”；漏掉“为”，直接说“朋友辩护”不对。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f15f862-54ec-4f7c-b9bf-4afd8bb7ebdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94875, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我替他辩护了过一次，所以他很感激。", "corrected_sentence": "我替他辩护过一次，所以他很感激。", "error_description": "“过”是表示经历的体标记，紧接动词“辩护”，不能再加“了”。应说“辩护过一次”，“辩护了过一次”错在多加了“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f15f862-54ec-4f7c-b9bf-4afd8bb7ebdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
