INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94876, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "为他人或自己的行为提出理由，说明其无过错。", "primary_collocate": null, "pronunciation": "biàn hù", "ipa": "pjɛn˥˩ xu˥˩", "syllable_count": 2, "sentences": [{"text": "他总是为自己的错误辩护。", "target_word": "辩护", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你不用再辩护了，我已经明白了。", "target_word": "辩护", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他找了很多理由为自己辩护。", "target_word": "辩护", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她想辩护几句，但没有人听。", "target_word": "辩护", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师问他为什么迟到，他开始辩护。", "target_word": "辩护", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事是你不对，别再辩护了。", "target_word": "辩护", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他为自己的做法辩护，说这样最省钱。", "target_word": "辩护", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小李没有为自己辩护，只是安静地听着。", "target_word": "辩护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每次做错事，弟弟都会辩护几句。", "target_word": "辩护", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法官让他有机会为自己辩护。", "target_word": "辩护", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "辩护了", "label": "完成体"}, {"form": "辩护过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "为自己或他人的行为提出理由，说明没有过错", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73c1303b-ce7a-48fa-ac4b-097cecf36469') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94876, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "辩护", "is_correct": true, "explanation": "正确答案。辩护指提出理由，说明行为没有过错。"}, {"text": "变化", "is_correct": false, "explanation": "huà 比 hù 多一个元音 a，韵母不同，意思是改变、变化，不是提出理由。"}, {"text": "遍布", "is_correct": false, "explanation": "bù 与 hù 声母不同（b 与 h），意思是散布到各处，不是提出理由。"}, {"text": "变故", "is_correct": false, "explanation": "gù 与 hù 声母不同（g 与 h），意思是意外发生的事情，不是提出理由。"}], "explanations": {"辩护": "正确答案。辩护指提出理由，说明行为没有过错。", "变化": "huà 比 hù 多一个元音 a，韵母不同，意思是改变、变化，不是提出理由。", "遍布": "bù 与 hù 声母不同（b 与 h），意思是散布到各处，不是提出理由。", "变故": "gù 与 hù 声母不同（g 与 h），意思是意外发生的事情，不是提出理由。"}, "sentence_index": null, "correct_answer": "辩护"}, "level_3": {"options": [{"text": "辩护", "is_correct": true, "explanation": "正确。“为自己的错误辩护”指提出理由，说明自己没有过错，符合句意。"}, {"text": "庆祝", "is_correct": false, "explanation": "语义：“庆祝”是为喜事欢庆，不能用来对待错误，句子说不通。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”与“错误”无关，“为自己的错误散步”说不通。"}, {"text": "长高", "is_correct": false, "explanation": "体貌：“长高”说的是身高的变化，与错误无关。"}], "explanations": {"辩护": "正确。“为自己的错误辩护”指提出理由，说明自己没有过错，符合句意。", "庆祝": "语义：“庆祝”是为喜事欢庆，不能用来对待错误，句子说不通。", "散步": "语义：“散步”与“错误”无关，“为自己的错误散步”说不通。", "长高": "体貌：“长高”说的是身高的变化，与错误无关。"}, "sentence_index": 0, "correct_answer": "辩护"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他向老师辩护道歉，希望老师别生气。", "explanation": "这里应该用〈认错〉。辩护是为行为提出理由、说明没有过错，不能用来表示承认错误并赔罪。"}, {"text": "老师耐心地辩护他的功课。", "explanation": "这里应该用〈辅导〉。辩护用于替人或行为提出理由，不能用于功课。"}, {"text": "工人一个一个地辩护那台新机器的零件。", "explanation": "这里应该用〈检查〉。辩护是提出理由、说明没有过错，不能用来指逐一查看机器零件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f15f862-54ec-4f7c-b9bf-4afd8bb7ebdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94876, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "辩护", "is_correct": true, "explanation": "正确答案。辩护指提出理由，说明行为没有过错。"}, {"text": "变速", "is_correct": false, "explanation": "sù 与 hù 声母不同（s 与 h），意思是改变速度，不是提出理由。"}, {"text": "变数", "is_correct": false, "explanation": "shù 与 hù 声母不同（sh 与 h），意思是不确定的因素，不是提出理由。"}, {"text": "遍布", "is_correct": false, "explanation": "bù 与 hù 声母不同（b 与 h），意思是散布到各处，不是提出理由。"}], "explanations": {"辩护": "正确答案。辩护指提出理由，说明行为没有过错。", "变速": "sù 与 hù 声母不同（s 与 h），意思是改变速度，不是提出理由。", "变数": "shù 与 hù 声母不同（sh 与 h），意思是不确定的因素，不是提出理由。", "遍布": "bù 与 hù 声母不同（b 与 h），意思是散布到各处，不是提出理由。"}, "sentence_index": null, "correct_answer": "辩护"}, "level_3": {"options": [{"text": "辩护", "is_correct": true, "explanation": "正确。“为自己的做法辩护”指提出理由，说明做法没有过错，与后面的理由一致。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”是讥讽别人，与后面“说这样最省钱”的理由矛盾。"}, {"text": "放弃", "is_correct": false, "explanation": "配价：“放弃”要带放弃的对象，“为自己的做法放弃”不成立，也与后面的理由矛盾。"}, {"text": "检讨", "is_correct": false, "explanation": "语义：“检讨”是承认自己的错误并自我批评，与“说这样最省钱”的理由矛盾。"}], "explanations": {"辩护": "正确。“为自己的做法辩护”指提出理由，说明做法没有过错，与后面的理由一致。", "嘲笑": "语义：“嘲笑”是讥讽别人，与后面“说这样最省钱”的理由矛盾。", "放弃": "配价：“放弃”要带放弃的对象，“为自己的做法放弃”不成立，也与后面的理由矛盾。", "检讨": "语义：“检讨”是承认自己的错误并自我批评，与“说这样最省钱”的理由矛盾。"}, "sentence_index": 6, "correct_answer": "辩护"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她真诚地辩护朋友的帮助。", "explanation": "这里应该用〈感谢〉。辩护是提出理由说明没有过错，不能用来表示感谢。"}, {"text": "全班热烈辩护他的生日。", "explanation": "这里应该用〈庆祝〉。辩护只用于替人或行为提出理由，不能用于生日等喜事。"}, {"text": "妈妈认真地辩护那个童话故事。", "explanation": "这里应该用〈讲述〉。辩护是提出理由、说明没有过错，不能用来指讲故事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f15f862-54ec-4f7c-b9bf-4afd8bb7ebdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94876, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她为自己辩护很冷静，老师没有再追问。", "corrected_sentence": "她为自己辩护得很冷静，老师没有再追问。", "error_description": "补语前漏了“得”。“辩护很冷静”应为“辩护得很冷静”，动词后带描写状态的补语时要用“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f15f862-54ec-4f7c-b9bf-4afd8bb7ebdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94876, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他为自己辩护了过几次，可是老师都不相信。", "corrected_sentence": "他为自己辩护过几次，可是老师都不相信。", "error_description": "“过”是表示经历的体标记，紧接动词“辩护”，不能再加“了”。应说“辩护过几次”，“辩护了过几次”错在多加了“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f15f862-54ec-4f7c-b9bf-4afd8bb7ebdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
