INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94878, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "物体呈现出的外形或创造出来的形象。", "primary_collocate": null, "pronunciation": "zào xíng", "ipa": "tsɑu˥˩ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这个电影里的人物造型很有意思。", "target_word": "造型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她今天换了一个新造型。", "target_word": "造型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏的角色造型很可爱。", "target_word": "造型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演员的造型让大家笑了。", "target_word": "造型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他请人帮他设计新造型。", "target_word": "造型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "广场上有一个小熊造型的雕像。", "target_word": "造型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们喜欢这个卡通造型。", "target_word": "造型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的舞台造型很漂亮。", "target_word": "造型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小丑的造型像一只大鸟。", "target_word": "造型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个歌手的新造型很好看。", "target_word": "造型", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "外形或设计出的形象，如人物、角色造型", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '904ff82c-9949-44d4-8c88-d63d71ef0a8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94878, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "价格", "is_correct": false, "explanation": "语义：人物没有价格，「人物的价格很有意思」说不通。"}, {"text": "造型", "is_correct": true, "explanation": "造型指人物的装扮或形象，「人物的造型很有意思」符合句意。"}, {"text": "体温", "is_correct": false, "explanation": "语义：「体温」指人或动物的温度，不用来评价人物的形象。"}, {"text": "重量", "is_correct": false, "explanation": "搭配：「重量」不用来描述人物的形象，「很有意思」与之不搭。"}], "explanations": {"价格": "语义：人物没有价格，「人物的价格很有意思」说不通。", "造型": "造型指人物的装扮或形象，「人物的造型很有意思」符合句意。", "体温": "语义：「体温」指人或动物的温度，不用来评价人物的形象。", "重量": "搭配：「重量」不用来描述人物的形象，「很有意思」与之不搭。"}, "sentence_index": 0, "correct_answer": "造型"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "演员的一只造型让大家笑了。", "explanation": "这里的量词应用〈个〉或〈种〉。「只」不用于「造型」。"}, {"text": "演员的造型很好听。", "explanation": "这里应该用〈声音〉。造型指外表装扮，不能用来说好听。"}, {"text": "这个杯子的造型会唱歌。", "explanation": "「会唱歌」是人或动物的能力，造型指外形，不能用来说会唱歌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80ec9804-5013-493b-b350-1068aecf33b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94878, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "温度", "is_correct": false, "explanation": "搭配：卡通不说「温度」，「卡通温度」说不通。"}, {"text": "硬度", "is_correct": false, "explanation": "搭配：卡通不说「硬度」，「卡通硬度」说不通。"}, {"text": "造型", "is_correct": true, "explanation": "造型指卡通角色的形象，「孩子们喜欢这个卡通造型」符合句意。"}, {"text": "湿度", "is_correct": false, "explanation": "语义：湿度与卡通形象无关，句意不通。"}], "explanations": {"温度": "搭配：卡通不说「温度」，「卡通温度」说不通。", "硬度": "搭配：卡通不说「硬度」，「卡通硬度」说不通。", "造型": "造型指卡通角色的形象，「孩子们喜欢这个卡通造型」符合句意。", "湿度": "语义：湿度与卡通形象无关，句意不通。"}, "sentence_index": 6, "correct_answer": "造型"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个歌手有一把很好看的新造型。", "explanation": "这里的量词应用〈个〉或〈种〉。「把」多用于有柄或有靠背的东西，不用来数「造型」。"}, {"text": "这个手机的造型很快。", "explanation": "这里应该用〈反应〉。造型指外观，不能用来说快慢。"}, {"text": "这座桥的造型很甜。", "explanation": "造型指外形，不能用来形容味道；「很甜」说的是食物的滋味，桥不是食物，二者都不搭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80ec9804-5013-493b-b350-1068aecf33b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94878, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个演员每次演出都换一只新造型。", "corrected_sentence": "这个演员每次演出都换一种新造型。", "error_description": "错误：「造型」的量词用错。「只」不搭配「造型」，应改为「种」，写作「换一种新造型」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80ec9804-5013-493b-b350-1068aecf33b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94878, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他给这个角色设计了一把新造型。", "corrected_sentence": "他给这个角色设计了一个新造型。", "error_description": "错误：「造型」的量词用错。「把」用于有柄或有靠背的东西，不用来数「造型」，应改为「个」，写作「设计了一个新造型」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80ec9804-5013-493b-b350-1068aecf33b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
