INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94879, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "锁是关门时用来锁住门的小铁东西。", "primary_collocate": null, "pronunciation": "suǒ", "ipa": "swo˨˩˦", "syllable_count": 1, "sentences": [{"text": "这把锁很旧，钥匙也找不到了。", "target_word": "锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门上有一把小锁。", "target_word": "锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我买了一把新锁。", "target_word": "锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把锁是铁做的，很重。", "target_word": "锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用钥匙打开了门上的锁。", "target_word": "锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小锁坏了，门锁不上了。", "target_word": "锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老锁生锈了，钥匙转不动。", "target_word": "锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟把钥匙放进锁里。", "target_word": "锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把锁太小，挡不住小偷。", "target_word": "锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸给大门买了一把新锁。", "target_word": "锁", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一把锁", "label": "量词"}, {"form": "鎖", "label": "繁体"}], "register": "中性", "sense_fingerprint": "关门用的小铁锁，用钥匙开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c775263-ec78-4df2-815b-c2b3a153698a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94879, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "锁", "is_correct": true, "explanation": "正确：锁（suǒ），关门时用来锁门的小铁器具，要用钥匙开。"}, {"text": "缩", "is_correct": false, "explanation": "suō（第一声）与 suǒ（第三声）声调不同，意思是收缩。"}, {"text": "朵", "is_correct": false, "explanation": "duǒ 与 suǒ 只差声母（d／s），声调相同，意思是花朵。"}, {"text": "左", "is_correct": false, "explanation": "zuǒ 与 suǒ 声母不同（z／s），声调相同，意思是左边。"}, {"text": "果", "is_correct": false, "explanation": "guǒ 与 suǒ 只差声母（g／s），声调相同，意思是水果或结果。"}], "explanations": {"锁": "正确：锁（suǒ），关门时用来锁门的小铁器具，要用钥匙开。", "缩": "suō（第一声）与 suǒ（第三声）声调不同，意思是收缩。", "朵": "duǒ 与 suǒ 只差声母（d／s），声调相同，意思是花朵。", "左": "zuǒ 与 suǒ 声母不同（z／s），声调相同，意思是左边。", "果": "guǒ 与 suǒ 只差声母（g／s），声调相同，意思是水果或结果。"}, "sentence_index": null, "correct_answer": "锁"}, "level_3": {"options": [{"text": "锁", "is_correct": true, "explanation": "正确：锁很旧，钥匙也找不到，前后相合。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：“钥匙”与“钥匙也找不到了”重复，句子不通。"}, {"text": "伞", "is_correct": false, "explanation": "语义：伞与钥匙无关，“钥匙也找不到了”前后不衔接。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子与钥匙没有关联，这一语境不合。"}], "explanations": {"锁": "正确：锁很旧，钥匙也找不到，前后相合。", "钥匙": "语义：“钥匙”与“钥匙也找不到了”重复，句子不通。", "伞": "语义：伞与钥匙无关，“钥匙也找不到了”前后不衔接。", "椅子": "语义：椅子与钥匙没有关联，这一语境不合。"}, "sentence_index": 0, "correct_answer": "锁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一只锁。", "explanation": "这里应该用〈把〉。“锁”是器具，量词要用“把”，“只”多用于动物等。"}, {"text": "他撕开了锁，拿出了信。", "explanation": "这里应该用〈信封〉。锁是金属器具，不能撕开，撕开的是信封。"}, {"text": "他用锁打开了门。", "explanation": "这里应该用〈钥匙〉。锁是被打开的东西，开门要用钥匙，不能用锁去开门。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf47c05-ff6e-4ac9-8a71-e8a1aae506d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94879, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "锁", "is_correct": true, "explanation": "正确：锁（suǒ），关门时用来锁门的小铁器具，要用钥匙开。"}, {"text": "梭", "is_correct": false, "explanation": "suō（第一声）与 suǒ（第三声）只差声调，意思是梭子。"}, {"text": "朵", "is_correct": false, "explanation": "duǒ 与 suǒ 只差声母（d／s），声调相同，意思是花朵。"}, {"text": "火", "is_correct": false, "explanation": "huǒ 与 suǒ 只差声母（h／s），声调相同，意思是火。"}], "explanations": {"锁": "正确：锁（suǒ），关门时用来锁门的小铁器具，要用钥匙开。", "梭": "suō（第一声）与 suǒ（第三声）只差声调，意思是梭子。", "朵": "duǒ 与 suǒ 只差声母（d／s），声调相同，意思是花朵。", "火": "huǒ 与 suǒ 只差声母（h／s），声调相同，意思是火。"}, "sentence_index": null, "correct_answer": "锁"}, "level_3": {"options": [{"text": "锁", "is_correct": true, "explanation": "正确：锁生锈后钥匙转不动，合理。"}, {"text": "水壶", "is_correct": false, "explanation": "语义：水壶不靠钥匙转动，“钥匙转不动”与之不符。"}, {"text": "刀", "is_correct": false, "explanation": "语义：刀没有钥匙，“钥匙转不动”不合语境。"}, {"text": "铁锅", "is_correct": false, "explanation": "语义：铁锅不用钥匙开，“钥匙转不动”不合语境。"}], "explanations": {"锁": "正确：锁生锈后钥匙转不动，合理。", "水壶": "语义：水壶不靠钥匙转动，“钥匙转不动”与之不符。", "刀": "语义：刀没有钥匙，“钥匙转不动”不合语境。", "铁锅": "语义：铁锅不用钥匙开，“钥匙转不动”不合语境。"}, "sentence_index": 6, "correct_answer": "锁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他推开了锁，走进了房间。", "explanation": "这里应该用〈门〉。锁是器具，不能推开，推开的是门。"}, {"text": "他按了一下锁，想让人来开门。", "explanation": "这里应该用〈门铃〉。锁不能按，按的是门铃。"}, {"text": "他拉开了锁，取出了钱。", "explanation": "这里应该用〈抽屉〉。锁不能拉开，拉开的是抽屉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf47c05-ff6e-4ac9-8a71-e8a1aae506d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_