INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94880, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "装在门、箱、抽屉等上面，用钥匙才能打开的金属器具。", "primary_collocate": null, "pronunciation": "suǒ", "ipa": "swo˨˩˦", "syllable_count": 1, "sentences": [{"text": "抽屉上有一把锁，我没有钥匙。", "target_word": "锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个箱子的锁坏了。", "target_word": "锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他找到钥匙，打开了箱子上的锁。", "target_word": "锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把锁只能用钥匙打开。", "target_word": "锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日记本上有一把小锁。", "target_word": "锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门上的锁很结实，小偷进不来。", "target_word": "锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给旅行箱换了一把新锁。", "target_word": "锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种锁很安全，别人打不开。", "target_word": "锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把钥匙插进锁里。", "target_word": "锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那把锁是金属做的，有点冷。", "target_word": "锁", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一把锁", "label": "量词"}, {"form": "鎖", "label": "繁体"}], "register": "中性", "sense_fingerprint": "装在门、箱、抽屉上，要钥匙才能开的金属器具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c775263-ec78-4df2-815b-c2b3a153698a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94880, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "锁", "is_correct": true, "explanation": "正确：锁（suǒ），装在门、箱、抽屉上，要用钥匙才能打开的金属器具。"}, {"text": "缩", "is_correct": false, "explanation": "suō（第一声）与 suǒ（第三声）声调不同，意思是收缩。"}, {"text": "左", "is_correct": false, "explanation": "zuǒ 与 suǒ 声母不同（z／s），声调相同，意思是左边。"}, {"text": "果", "is_correct": false, "explanation": "guǒ 与 suǒ 只差声母（g／s），声调相同，意思是水果或结果。"}], "explanations": {"锁": "正确：锁（suǒ），装在门、箱、抽屉上，要用钥匙才能打开的金属器具。", "缩": "suō（第一声）与 suǒ（第三声）声调不同，意思是收缩。", "左": "zuǒ 与 suǒ 声母不同（z／s），声调相同，意思是左边。", "果": "guǒ 与 suǒ 只差声母（g／s），声调相同，意思是水果或结果。"}, "sentence_index": null, "correct_answer": "锁"}, "level_3": {"options": [{"text": "锁", "is_correct": true, "explanation": "正确：抽屉上的锁需要钥匙，我没有钥匙，前后合理。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：若抽屉上有钥匙，就与“我没有钥匙”矛盾。"}, {"text": "椅子", "is_correct": false, "explanation": "搭配：椅子不放在抽屉上，“抽屉上有椅子”不合常理。"}, {"text": "扫帚", "is_correct": false, "explanation": "搭配：扫帚与抽屉、钥匙的语境无关，搭配不当。"}], "explanations": {"锁": "正确：抽屉上的锁需要钥匙，我没有钥匙，前后合理。", "钥匙": "语义：若抽屉上有钥匙，就与“我没有钥匙”矛盾。", "椅子": "搭配：椅子不放在抽屉上，“抽屉上有椅子”不合常理。", "扫帚": "搭配：扫帚与抽屉、钥匙的语境无关，搭配不当。"}, "sentence_index": 0, "correct_answer": "锁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我撕开了锁，取出了信。", "explanation": "这里应该用〈信封〉。锁是金属器具，不能撕开，撕开的是信封。"}, {"text": "我买了一只锁。", "explanation": "这里应该用〈把〉。“锁”是器具，量词要用“把”，不用“只”。"}, {"text": "我用锁打开了箱子。", "explanation": "这里应该用〈钥匙〉。锁是被打开的东西，开箱子要用钥匙。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf47c05-ff6e-4ac9-8a71-e8a1aae506d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94880, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "锁", "is_correct": true, "explanation": "正确：锁（suǒ），装在门、箱、抽屉上，要用钥匙才能打开的金属器具。"}, {"text": "梭", "is_correct": false, "explanation": "suō（第一声）与 suǒ（第三声）只差声调，意思是梭子。"}, {"text": "朵", "is_correct": false, "explanation": "duǒ 与 suǒ 只差声母（d／s），声调相同，意思是花朵。"}, {"text": "火", "is_correct": false, "explanation": "huǒ 与 suǒ 只差声母（h／s），声调相同，意思是火。"}], "explanations": {"锁": "正确：锁（suǒ），装在门、箱、抽屉上，要用钥匙才能打开的金属器具。", "梭": "suō（第一声）与 suǒ（第三声）只差声调，意思是梭子。", "朵": "duǒ 与 suǒ 只差声母（d／s），声调相同，意思是花朵。", "火": "huǒ 与 suǒ 只差声母（h／s），声调相同，意思是火。"}, "sentence_index": null, "correct_answer": "锁"}, "level_3": {"options": [{"text": "锁", "is_correct": true, "explanation": "正确：旅行箱换锁，合理。"}, {"text": "刀", "is_correct": false, "explanation": "语义：旅行箱不换刀，“换一把新刀”不合语境。"}, {"text": "伞", "is_correct": false, "explanation": "语义：旅行箱不换伞，句子不通。"}, {"text": "锤子", "is_correct": false, "explanation": "搭配：“换锤子”不能用于旅行箱，搭配不当。"}], "explanations": {"锁": "正确：旅行箱换锁，合理。", "刀": "语义：旅行箱不换刀，“换一把新刀”不合语境。", "伞": "语义：旅行箱不换伞，句子不通。", "锤子": "搭配：“换锤子”不能用于旅行箱，搭配不当。"}, "sentence_index": 6, "correct_answer": "锁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我拉开了锁，拿出了日记本。", "explanation": "这里应该用〈抽屉〉。锁不能拉开，拉开的是抽屉。"}, {"text": "我按了一下锁，等着有人来开门。", "explanation": "这里应该用〈门铃〉。锁不能按，按的是门铃。"}, {"text": "我推开了锁，走进了屋子。", "explanation": "这里应该用〈门〉。锁是器具，不能推开，推开的是门。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf47c05-ff6e-4ac9-8a71-e8a1aae506d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
