INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94880, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把箱子上的两锁都修好了。", "corrected_sentence": "我把箱子上的两把锁都修好了。", "error_description": "错误：“两锁”；正确：“两把锁”。数词和名词之间需要量词，“锁”前应加“把”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf47c05-ff6e-4ac9-8a71-e8a1aae506d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
