INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94882, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "扣动扳机，使枪射出子弹。", "primary_collocate": null, "pronunciation": "kāi qiāng", "ipa": "kʰaɪ˥ tɕʰjɑŋ˥", "syllable_count": 2, "sentences": [{"text": "他扣动扳机，开枪了。", "target_word": "开枪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要先瞄准，再开枪。", "target_word": "开枪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察大声说：“不许动，不然我开枪！”", "target_word": "开枪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没想到，朋友会对他开枪。", "target_word": "开枪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老兵说，开枪以前要想清楚。", "target_word": "开枪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他怕得手发抖，不敢开枪。", "target_word": "开枪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "枪响了，是谁开枪了？", "target_word": "开枪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在比赛中开枪，打中了目标。", "target_word": "开枪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她举起枪，瞄准了目标，然后开枪。", "target_word": "开枪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开枪以后，他听见很大的响声。", "target_word": "开枪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "开了枪", "label": "体标"}, {"form": "开过枪", "label": "体标"}, {"form": "開槍", "label": "繁体"}], "register": "中性", "sense_fingerprint": "扣动扳机，使枪射出子弹", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c775263-ec78-4df2-815b-c2b3a153698a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94882, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开枪", "is_correct": true, "explanation": "“扣动扳机，开枪了”中，开枪是扣动扳机后的动作，语义相符。"}, {"text": "开灯", "is_correct": false, "explanation": "语义：扣动扳机后不会开灯，句中的动作必须是射击。"}, {"text": "开门", "is_correct": false, "explanation": "语义：扣动扳机与开门无关，“扣动扳机，开门了”语义不通。"}, {"text": "开饭", "is_correct": false, "explanation": "搭配：“开饭”不能接在“扣动扳机”之后，搭配不当。"}], "explanations": {"开枪": "“扣动扳机，开枪了”中，开枪是扣动扳机后的动作，语义相符。", "开灯": "语义：扣动扳机后不会开灯，句中的动作必须是射击。", "开门": "语义：扣动扳机与开门无关，“扣动扳机，开门了”语义不通。", "开饭": "搭配：“开饭”不能接在“扣动扳机”之后，搭配不当。"}, "sentence_index": 0, "correct_answer": "开枪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "春节时大家在门口开枪。", "explanation": "这里应该用〈放炮〉。放炮指燃放鞭炮，不是用枪打出子弹，不能说“开枪”。"}, {"text": "他拿起石头，用力向远处开枪。", "explanation": "这里应该用〈扔〉。扔是把东西抛出去，开枪只用于枪械。"}, {"text": "他在山里开枪做饭。", "explanation": "这里应该用〈生火〉。开枪是用枪射击，做饭时生火要说“生火”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf47c05-ff6e-4ac9-8a71-e8a1aae506d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94882, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开枪", "is_correct": true, "explanation": "“枪响了，是谁开枪了？”指有人射击，语义与枪声相符。"}, {"text": "开学", "is_correct": false, "explanation": "语义：开学是学校的活动，与枪响无关。"}, {"text": "开会", "is_correct": false, "explanation": "语义：开会与枪响没有关系，“是谁开会了”语义不通。"}, {"text": "开花", "is_correct": false, "explanation": "搭配：“开花”是植物的动作，不能用于询问枪响后是谁做的动作。"}], "explanations": {"开枪": "“枪响了，是谁开枪了？”指有人射击，语义与枪声相符。", "开学": "语义：开学是学校的活动，与枪响无关。", "开会": "语义：开会与枪响没有关系，“是谁开会了”语义不通。", "开花": "搭配：“开花”是植物的动作，不能用于询问枪响后是谁做的动作。"}, "sentence_index": 6, "correct_answer": "开枪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈开枪擦了地板，屋子干干净净的。", "explanation": "“开枪”只表示扣动扳机使枪射出子弹，不能指擦拭的动作，这里把它当成了擦拭。"}, {"text": "孩子们开枪唱歌，声音很好听。", "explanation": "“开枪”只表示扣动扳机使枪射出子弹，不能用来指演唱，这里把它当成了演唱的动作。"}, {"text": "他开枪给花浇水，花长得很快。", "explanation": "“开枪”只表示扣动扳机使枪射出子弹，不能指给植物供水，这里把它当成了浇灌的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf47c05-ff6e-4ac9-8a71-e8a1aae506d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94882, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他昨天在靶场开枪了一枪。", "corrected_sentence": "他昨天在靶场开了一枪。", "error_description": "离合词错误：“开枪”拆开后，“了”应放在“开”和“枪”之间，且“枪”不能重复，应说“开了一枪”，不能说“开枪了一枪”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf47c05-ff6e-4ac9-8a71-e8a1aae506d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94882, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他开枪得很准。", "corrected_sentence": "他开枪开得很准。", "error_description": "补语错误：“开枪”带“得”字补语时，动词要重复，应说“开枪开得很准”，不能只说“开枪得很准”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf47c05-ff6e-4ac9-8a71-e8a1aae506d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
