INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94883, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "开玩笑是说好笑的话让大家笑。", "primary_collocate": null, "pronunciation": "kāi wán xiào", "ipa": "kʰaɪ˥ wan˧˥ ɕiɑʊ˥˩", "syllable_count": 3, "sentences": [{"text": "他很爱开玩笑。", "target_word": "开玩笑", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师常常开玩笑，课上很有意思。", "target_word": "开玩笑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸一开玩笑，全家人都笑起来。", "target_word": "开玩笑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他开玩笑的时候，大家笑个不停。", "target_word": "开玩笑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她喜欢在聚会上开玩笑，让大家高兴。", "target_word": "开玩笑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小王很幽默，总爱跟朋友开玩笑。", "target_word": "开玩笑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "会议很无聊，他开玩笑，大家才笑了。", "target_word": "开玩笑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我同事很会开玩笑，办公室里总有笑声。", "target_word": "开玩笑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个演员在台上开玩笑，观众笑个不停。", "target_word": "开玩笑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他开玩笑说自己是明星，大家都笑了。", "target_word": "开玩笑", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "开个玩笑", "label": "离合"}, {"form": "开过玩笑", "label": "体标"}], "register": "口语", "sense_fingerprint": "说好笑的话，逗大家发笑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9844ebf-71c6-485b-8194-50a304b0844d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94883, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开玩笑", "is_correct": true, "explanation": "正确：“开玩笑”指说有趣的话逗人发笑，符合“他很爱”的语境。"}, {"text": "开学", "is_correct": false, "explanation": "语义：“开学”指学校开始上课，不能说“很爱开学”，句子不通。"}, {"text": "失踪", "is_correct": false, "explanation": "语义：“失踪”指人不见了，与“很爱”搭配不合，句子不通。"}, {"text": "加入", "is_correct": false, "explanation": "配价：“加入”需要宾语，如“加入球队”，此处不完整。"}], "explanations": {"开玩笑": "正确：“开玩笑”指说有趣的话逗人发笑，符合“他很爱”的语境。", "开学": "语义：“开学”指学校开始上课，不能说“很爱开学”，句子不通。", "失踪": "语义：“失踪”指人不见了，与“很爱”搭配不合，句子不通。", "加入": "配价：“加入”需要宾语，如“加入球队”，此处不完整。"}, "sentence_index": 0, "correct_answer": "开玩笑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我说要辞职，其实只是开玩笑，你别当真。", "explanation": "这里的“开玩笑”表示不是认真的，属于另一个义项，与本句要表达的“说好笑的话逗人发笑”不同。"}, {"text": "他把这件大事当成开玩笑，大家都很着急。", "explanation": "这里的“开玩笑”表示不当真，属于另一个义项，与“说好笑的话逗人发笑”不同。"}, {"text": "这件事不是开玩笑的，请你认真对待。", "explanation": "这里的“开玩笑”表示不是认真的，属于另一个义项，与“说好笑的话逗人发笑”不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746e8ceb-58e7-40b0-a07d-a29ffe73e13b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94883, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开玩笑", "is_correct": true, "explanation": "正确：“开玩笑”让大家笑起来，与“会议很无聊”的前后因果相合。"}, {"text": "开会", "is_correct": false, "explanation": "语义：会议中再“开会”，句意重复不通。"}, {"text": "做饭", "is_correct": false, "explanation": "语义：会议上做饭与句意无关，无法让大家笑起来。"}, {"text": "挂断", "is_correct": false, "explanation": "配价：“挂断”需要宾语，如“挂断电话”，此处不完整。"}], "explanations": {"开玩笑": "正确：“开玩笑”让大家笑起来，与“会议很无聊”的前后因果相合。", "开会": "语义：会议中再“开会”，句意重复不通。", "做饭": "语义：会议上做饭与句意无关，无法让大家笑起来。", "挂断": "配价：“挂断”需要宾语，如“挂断电话”，此处不完整。"}, "sentence_index": 6, "correct_answer": "开玩笑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我跟你说的是认真的，不是开玩笑。", "explanation": "这里的“开玩笑”表示不是认真的，属于另一个义项，与“说好笑的话逗人发笑”不同。"}, {"text": "他把我的请求当成开玩笑，没有答应。", "explanation": "这里的“开玩笑”表示不当真，属于另一个义项，与“说好笑的话逗人发笑”不同。"}, {"text": "他帮我开玩笑，电脑很快就修好了。", "explanation": "这里应该用〈修理〉。开玩笑不能表示修理，不能用来指“电脑”的修复。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746e8ceb-58e7-40b0-a07d-a29ffe73e13b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94883, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他开玩笑个，大家都笑了。", "corrected_sentence": "他开玩笑，大家都笑了。", "error_description": "错误：“开玩笑个”。开玩笑是离合词，量词“个”要放在“开”和“玩笑”之间（开个玩笑），不能放在后面；这里也可直接说“他开玩笑”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746e8ceb-58e7-40b0-a07d-a29ffe73e13b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94883, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他开玩笑个说自己是厨师，大家都笑了。", "corrected_sentence": "他开玩笑说自己是厨师，大家都笑了。", "error_description": "错误：“开玩笑个说”。开玩笑是离合词，“个”只能插在“开”和“玩笑”之间（开个玩笑），不能放在后面；这里应直接说“他开玩笑说自己是厨师”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746e8ceb-58e7-40b0-a07d-a29ffe73e13b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
