INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94884, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "说着玩儿，不是认真的。", "primary_collocate": null, "pronunciation": "kāi wán xiào", "ipa": "kʰaɪ˥ wan˧˥ ɕiɑʊ˥˩", "syllable_count": 3, "sentences": [{"text": "别生气，我只是开玩笑。", "target_word": "开玩笑", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我是开玩笑的，你别当真。", "target_word": "开玩笑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说要辞职，其实是开玩笑。", "target_word": "开玩笑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种事不能开玩笑，太严重了。", "target_word": "开玩笑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你是在开玩笑吧？我不相信。", "target_word": "开玩笑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他笑着说：“我开玩笑呢，别紧张。”", "target_word": "开玩笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友跟我开玩笑，说我中了大奖。", "target_word": "开玩笑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她以为我在开玩笑，没有认真听。", "target_word": "开玩笑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我哥哥总爱跟我开玩笑，他说的话我从来不当真。", "target_word": "开玩笑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说得很认真，不像是在开玩笑。", "target_word": "开玩笑", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "开个玩笑", "label": "离合"}, {"form": "开过玩笑", "label": "体标"}], "register": "口语", "sense_fingerprint": "说着玩儿，不当真", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9844ebf-71c6-485b-8194-50a304b0844d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94884, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开玩笑", "is_correct": true, "explanation": "正确：“开玩笑”表示不是认真的，与“别生气”的语境相合。"}, {"text": "发脾气", "is_correct": false, "explanation": "语义：“发脾气”与前一句“别生气”矛盾，句子不通。"}, {"text": "翻脸", "is_correct": false, "explanation": "语义：“翻脸”与“别生气”的劝慰语境矛盾，句子不通。"}, {"text": "追", "is_correct": false, "explanation": "配价：“追”需要宾语，如“追他”，此处单独使用不完整。"}], "explanations": {"开玩笑": "正确：“开玩笑”表示不是认真的，与“别生气”的语境相合。", "发脾气": "语义：“发脾气”与前一句“别生气”矛盾，句子不通。", "翻脸": "语义：“翻脸”与“别生气”的劝慰语境矛盾，句子不通。", "追": "配价：“追”需要宾语，如“追他”，此处单独使用不完整。"}, "sentence_index": 0, "correct_answer": "开玩笑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他开玩笑了我一本书。", "explanation": "这里应该用〈送〉。开玩笑是离合词，不能带“书”这样的物品宾语。"}, {"text": "他每天开玩笑，房间就打扫干净了。", "explanation": "这里应该用〈打扫〉。开玩笑不能表示打扫，也不能与“房间”搭配。"}, {"text": "他会开玩笑，车也能修好。", "explanation": "这里应该用〈修〉。开玩笑不能表示修理，也不能与“车”搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746e8ceb-58e7-40b0-a07d-a29ffe73e13b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94884, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开玩笑", "is_correct": true, "explanation": "正确：“开玩笑”指朋友用玩笑话逗我，与后半句的内容相合。"}, {"text": "失踪", "is_correct": false, "explanation": "语义：“失踪”指人不见了，与“跟我”的情境不合，句子不通。"}, {"text": "发布", "is_correct": false, "explanation": "配价：“发布”需要宾语，如“发布消息”，此处不完整。"}, {"text": "哭泣", "is_correct": false, "explanation": "语义：“哭泣”与“说我中了大奖”的情境相反，句子不通。"}], "explanations": {"开玩笑": "正确：“开玩笑”指朋友用玩笑话逗我，与后半句的内容相合。", "失踪": "语义：“失踪”指人不见了，与“跟我”的情境不合，句子不通。", "发布": "配价：“发布”需要宾语，如“发布消息”，此处不完整。", "哭泣": "语义：“哭泣”与“说我中了大奖”的情境相反，句子不通。"}, "sentence_index": 6, "correct_answer": "开玩笑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把这个苹果开玩笑了。", "explanation": "这里应该用〈吃〉。开玩笑不能处置“苹果”这样的物品，不能用在把字句里。"}, {"text": "妈妈开玩笑了一顿晚饭。", "explanation": "这里应该用〈做〉。开玩笑不能带“晚饭”作宾语。"}, {"text": "我每天坐公交车去开玩笑。", "explanation": "这里应该用〈上班〉。开玩笑是说着玩儿，不是每天坐车去做的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746e8ceb-58e7-40b0-a07d-a29ffe73e13b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94884, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我只是开玩笑个，你别当真。", "corrected_sentence": "我只是开玩笑，你别当真。", "error_description": "错误：“开玩笑个”。“玩笑”后不能接量词“个”，正确说法是“我只是开玩笑”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746e8ceb-58e7-40b0-a07d-a29ffe73e13b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94884, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事我说得很认真，不是在开玩笑个。", "corrected_sentence": "这件事我说得很认真，不是在开玩笑。", "error_description": "错误：“开玩笑个”。“玩笑”后不能接量词“个”，正确说法是“不是在开玩笑”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746e8ceb-58e7-40b0-a07d-a29ffe73e13b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
