INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94885, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "颇是很，比较多。", "primary_collocate": null, "pronunciation": "pō", "ipa": "pʰo˥", "syllable_count": 1, "sentences": [{"text": "他在这方面颇有经验。", "target_word": "颇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市颇有名气。", "target_word": "颇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师颇受学生欢迎。", "target_word": "颇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事让我感触颇多。", "target_word": "颇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他读过很多书，收获颇多。", "target_word": "颇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的生意颇有起色。", "target_word": "颇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的话让大家颇有感触。", "target_word": "颇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小镇颇具特色，游客不少。", "target_word": "颇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对历史颇有研究。", "target_word": "颇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影颇受好评。", "target_word": "颇", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "颇为", "label": "复合"}, {"form": "颇有", "label": "复合"}, {"form": "颇多", "label": "复合"}], "register": "书面", "sense_fingerprint": "副词，用在有、多、受等词前，表示数量或程度比较多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8674e63a-393f-4d84-bf8a-ca1ff6fc6749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94885, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "颇", "is_correct": true, "explanation": "本词：副词，表示数量或程度比较多，用在“有”“受”等词前，如“颇有经验”。"}, {"text": "婆", "is_correct": false, "explanation": "pó（第二声）与 pō（第一声）声母韵母相同、只差声调，意思是“婆婆”。"}, {"text": "破", "is_correct": false, "explanation": "pò（第四声）与 pō（第一声）声母韵母相同、只差声调，意思是“破坏”。"}, {"text": "摸", "is_correct": false, "explanation": "mō（第一声）与 pō 只差声母（m 与 p），声调相同，意思是“触摸”。"}, {"text": "拨", "is_correct": false, "explanation": "bō（第一声）与 pō 声母不同（b 与 p），意思是“拨打”。"}], "explanations": {"颇": "本词：副词，表示数量或程度比较多，用在“有”“受”等词前，如“颇有经验”。", "婆": "pó（第二声）与 pō（第一声）声母韵母相同、只差声调，意思是“婆婆”。", "破": "pò（第四声）与 pō（第一声）声母韵母相同、只差声调，意思是“破坏”。", "摸": "mō（第一声）与 pō 只差声母（m 与 p），声调相同，意思是“触摸”。", "拨": "bō（第一声）与 pō 声母不同（b 与 p），意思是“拨打”。"}, "sentence_index": null, "correct_answer": "颇"}, "level_3": {"options": [{"text": "颇", "is_correct": true, "explanation": "颇：表示程度比较多，修饰“有”，与“有经验”相符。"}, {"text": "把", "is_correct": false, "explanation": "语法：“把”是介词，须带宾语再接动词，“他在这方面把有经验”不成立。"}, {"text": "不", "is_correct": false, "explanation": "搭配：“不”不能直接修饰动词“有”（应说“没有”），“不有经验”不成立。"}, {"text": "并", "is_correct": false, "explanation": "搭配：“并”多与否定词连用（并不、并非），肯定句“并有经验”不成立。"}], "explanations": {"颇": "颇：表示程度比较多，修饰“有”，与“有经验”相符。", "把": "语法：“把”是介词，须带宾语再接动词，“他在这方面把有经验”不成立。", "不": "搭配：“不”不能直接修饰动词“有”（应说“没有”），“不有经验”不成立。", "并": "搭配：“并”多与否定词连用（并不、并非），肯定句“并有经验”不成立。"}, "sentence_index": 0, "correct_answer": "颇"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他颇去过北京。", "explanation": "这里应该用〈曾经〉。颇修饰形容词或“有”“受”等词，不修饰“去过”这类动作；表示经历要用〈曾经〉。"}, {"text": "他颇去图书馆。", "explanation": "这里应该用〈经常〉。颇表示程度，不修饰“去”这类动作；表示经常发生要用〈经常〉。"}, {"text": "他昨天颇来过这里。", "explanation": "这里应该用〈曾经〉。颇表示程度，不修饰“来过”这类表示经历的动作；表示经历要用〈曾经〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02bbc78d-1e95-4345-8942-46b25251613e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94885, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "颇", "is_correct": true, "explanation": "本词：副词，表示数量或程度比较多，用在“有”“受”等词前。"}, {"text": "玻", "is_correct": false, "explanation": "bō（第一声）与 pō 只差声母（b 与 p），意思是“玻璃”。"}, {"text": "迫", "is_correct": false, "explanation": "pò（第四声）与 pō（第一声）声母韵母相同、只差声调，意思是“逼迫”。"}, {"text": "播", "is_correct": false, "explanation": "bō（第一声）与 pō 只差声母（b 与 p），意思是“播种”。"}, {"text": "魄", "is_correct": false, "explanation": "pò（第四声）与 pō（第一声）声母韵母相同、只差声调，意思是“魄力”。"}], "explanations": {"颇": "本词：副词，表示数量或程度比较多，用在“有”“受”等词前。", "玻": "bō（第一声）与 pō 只差声母（b 与 p），意思是“玻璃”。", "迫": "pò（第四声）与 pō（第一声）声母韵母相同、只差声调，意思是“逼迫”。", "播": "bō（第一声）与 pō 只差声母（b 与 p），意思是“播种”。", "魄": "pò（第四声）与 pō（第一声）声母韵母相同、只差声调，意思是“魄力”。"}, "sentence_index": null, "correct_answer": "颇"}, "level_3": {"options": [{"text": "颇", "is_correct": true, "explanation": "颇：表示程度比较多，修饰“有”，与“有感触”相符。"}, {"text": "把", "is_correct": false, "explanation": "语法：“把”是介词，须带宾语再接动词，“大家把有感触”不成立。"}, {"text": "了", "is_correct": false, "explanation": "语法：“了”是动态助词，须附在动词之后，“大家了有感触”不成立。"}, {"text": "偏", "is_correct": false, "explanation": "语义：“偏”表示与常理相反，句中没有与常理相反的语境。"}], "explanations": {"颇": "颇：表示程度比较多，修饰“有”，与“有感触”相符。", "把": "语法：“把”是介词，须带宾语再接动词，“大家把有感触”不成立。", "了": "语法：“了”是动态助词，须附在动词之后，“大家了有感触”不成立。", "偏": "语义：“偏”表示与常理相反，句中没有与常理相反的语境。"}, "sentence_index": 6, "correct_answer": "颇"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他颇走了。", "explanation": "这里应该用〈已经〉。颇表示程度，不表示动作完成的时间，不能像“已经”那样说明动作已完成。"}, {"text": "我颇去北京。", "explanation": "这里应该用〈打算〉。颇修饰形容词或心理动词，不修饰“去”这类动作；表示计划要用〈打算〉。"}, {"text": "电影快开始了，我们颇出发吧。", "explanation": "这里应该用〈马上〉。颇表示程度，不修饰“出发”这类动作；表示即刻发生要用〈马上〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02bbc78d-1e95-4345-8942-46b25251613e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94885, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份工作有颇前途。", "corrected_sentence": "这份工作颇有前途。", "error_description": "错误形式：“有颇”。正确形式：“颇有”。原因：“颇”要放在“有”前面组成“颇有”，不能放在“有”后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02bbc78d-1e95-4345-8942-46b25251613e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94885, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位老师颇有受大家喜爱。", "corrected_sentence": "这位老师颇受大家喜爱。", "error_description": "错误形式：“颇有受”。正确形式：“颇受”。原因：“颇受”是固定搭配，多出的“有”不能插在“颇”和“受”之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02bbc78d-1e95-4345-8942-46b25251613e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
