INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94886, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "相当，很，表示程度较高。", "primary_collocate": null, "pronunciation": "pō", "ipa": "pʰo˥", "syllable_count": 1, "sentences": [{"text": "这个问题颇难，我想了很久。", "target_word": "颇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对这个结果颇不满意。", "target_word": "颇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆的菜颇贵。", "target_word": "颇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师听了颇感意外。", "target_word": "颇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书写得颇有意思。", "target_word": "颇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她唱歌颇动听，大家都爱听。", "target_word": "颇", "complexity_tier": "T3", "furigana": "tā chàng gē pō dòngtīng, dàjiā dōu ài tīng.", "sentence_source": "generated"}, {"text": "路上的雪颇厚，车开得很慢。", "target_word": "颇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的冬天颇冷，要多穿衣服。", "target_word": "颇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛颇激烈，大家都很紧张。", "target_word": "颇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他中文说得颇流利。", "target_word": "颇", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "颇为", "label": "复合"}, {"form": "颇有", "label": "复合"}, {"form": "颇多", "label": "复合"}], "register": "书面", "sense_fingerprint": "副词，用在形容词或心理动词前，表示程度相当高", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8674e63a-393f-4d84-bf8a-ca1ff6fc6749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94886, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "颇", "is_correct": true, "explanation": "本词：副词，表示程度相当高，用在形容词前，如“颇难”。"}, {"text": "波", "is_correct": false, "explanation": "bō（第一声）与 pō 声母不同（b 与 p），意思是“波浪”。"}, {"text": "破", "is_correct": false, "explanation": "pò（第四声）与 pō（第一声）声调不同，意思是“破坏”。"}, {"text": "婆", "is_correct": false, "explanation": "pó（第二声）与 pō（第一声）声调不同，意思是“婆婆”。"}, {"text": "摸", "is_correct": false, "explanation": "mō（第一声）与 pō 声母不同（m 与 p），意思是“触摸”。"}, {"text": "拨", "is_correct": false, "explanation": "bō（第一声）与 pō 只差声母（b 与 p），意思是“拨打”。"}], "explanations": {"颇": "本词：副词，表示程度相当高，用在形容词前，如“颇难”。", "波": "bō（第一声）与 pō 声母不同（b 与 p），意思是“波浪”。", "破": "pò（第四声）与 pō（第一声）声调不同，意思是“破坏”。", "婆": "pó（第二声）与 pō（第一声）声调不同，意思是“婆婆”。", "摸": "mō（第一声）与 pō 声母不同（m 与 p），意思是“触摸”。", "拨": "bō（第一声）与 pō 只差声母（b 与 p），意思是“拨打”。"}, "sentence_index": null, "correct_answer": "颇"}, "level_3": {"options": [{"text": "颇", "is_correct": true, "explanation": "颇：表示程度相当高，修饰形容词“难”，与“想了很久”相符。"}, {"text": "不", "is_correct": false, "explanation": "语义：“不难”否定了问题的难度，与后句“想了很久”所暗示的困难矛盾。"}, {"text": "都", "is_correct": false, "explanation": "搭配：“都”要求复数或全体主语，“这个问题”是单数，“都难”不成立。"}, {"text": "并", "is_correct": false, "explanation": "搭配：“并”多与否定词连用（并不、并非），“这个问题并难”的肯定用法不成立。"}], "explanations": {"颇": "颇：表示程度相当高，修饰形容词“难”，与“想了很久”相符。", "不": "语义：“不难”否定了问题的难度，与后句“想了很久”所暗示的困难矛盾。", "都": "搭配：“都”要求复数或全体主语，“这个问题”是单数，“都难”不成立。", "并": "搭配：“并”多与否定词连用（并不、并非），“这个问题并难”的肯定用法不成立。"}, "sentence_index": 0, "correct_answer": "颇"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他颇离开了北京。", "explanation": "这里应该用〈立刻〉。颇是程度副词，修饰形容词或心理动词，不修饰“离开”这类动作动词；表示时间的“立刻”才能与动作动词连用。"}, {"text": "妈妈颇做了三个菜。", "explanation": "这里应该用〈一共〉。颇表示程度，不修饰“做”这类动作，也不表示数量的总计；表示总数要用〈一共〉。"}, {"text": "我颇买了三本书。", "explanation": "这里应该用〈大约〉。颇表示程度，不表示数量的估计，不能与“买了”连用来修饰数量；表示大致数目要用〈大约〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02bbc78d-1e95-4345-8942-46b25251613e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94886, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "颇", "is_correct": true, "explanation": "本词：副词，表示程度相当高，修饰形容词或心理动词。"}, {"text": "玻", "is_correct": false, "explanation": "bō（第一声）与 pō 只差声母（b 与 p），意思是“玻璃”。"}, {"text": "迫", "is_correct": false, "explanation": "pò（第四声）与 pō（第一声）声母韵母相同、只差声调，意思是“逼迫”。"}, {"text": "播", "is_correct": false, "explanation": "bō（第一声）与 pō 只差声母（b 与 p），意思是“播种”。"}, {"text": "魄", "is_correct": false, "explanation": "pò（第四声）与 pō（第一声）声母韵母相同、只差声调，意思是“魄力”。"}], "explanations": {"颇": "本词：副词，表示程度相当高，修饰形容词或心理动词。", "玻": "bō（第一声）与 pō 只差声母（b 与 p），意思是“玻璃”。", "迫": "pò（第四声）与 pō（第一声）声母韵母相同、只差声调，意思是“逼迫”。", "播": "bō（第一声）与 pō 只差声母（b 与 p），意思是“播种”。", "魄": "pò（第四声）与 pō（第一声）声母韵母相同、只差声调，意思是“魄力”。"}, "sentence_index": null, "correct_answer": "颇"}, "level_3": {"options": [{"text": "颇", "is_correct": true, "explanation": "颇：表示程度相当高，修饰形容词“厚”，与“车开得很慢”的路况相符。"}, {"text": "曾", "is_correct": false, "explanation": "体貌：“曾”表示过去的经历，句子描述的是当前路况，时态不协调。"}, {"text": "并", "is_correct": false, "explanation": "搭配：“并”多与否定词连用（并不、并非），“路上的雪并厚”的肯定用法不成立。"}, {"text": "只", "is_correct": false, "explanation": "搭配：“只”表示限定，后面接“厚”需要说明限定的范围，句中没有这样的语境。"}], "explanations": {"颇": "颇：表示程度相当高，修饰形容词“厚”，与“车开得很慢”的路况相符。", "曾": "体貌：“曾”表示过去的经历，句子描述的是当前路况，时态不协调。", "并": "搭配：“并”多与否定词连用（并不、并非），“路上的雪并厚”的肯定用法不成立。", "只": "搭配：“只”表示限定，后面接“厚”需要说明限定的范围，句中没有这样的语境。"}, "sentence_index": 6, "correct_answer": "颇"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "下课了，他颇回家。", "explanation": "这里应该用〈马上〉。颇表示程度，不修饰“回家”这类动作；表示即刻发生要用〈马上〉。"}, {"text": "她今天没空，明天颇来。", "explanation": "这里应该用〈再〉。颇表示程度，不表示动作推迟或重复；表示以后再做要用〈再〉。"}, {"text": "他颇在北京工作。", "explanation": "这里应该用〈一直〉。颇表示程度，不修饰“在北京工作”这类动作；表示持续的状态要用〈一直〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02bbc78d-1e95-4345-8942-46b25251613e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94886, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她对这次考试颇很不满意。", "corrected_sentence": "她对这次考试颇不满意。", "error_description": "错误形式：“颇很”。正确形式：“颇不满意”。原因：“颇”与“很”都表示程度，不能叠用，应去掉“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02bbc78d-1e95-4345-8942-46b25251613e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94886, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这场演出颇的精彩。", "corrected_sentence": "这场演出颇精彩。", "error_description": "错误形式：“颇的精彩”。正确形式：“颇精彩”。原因：“颇”是程度副词，修饰形容词时直接放在形容词前，中间不能加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02bbc78d-1e95-4345-8942-46b25251613e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94887, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "安静", "is_correct": true, "explanation": "反义：“闹”指吵得别人不能安静，与“安静”相对。"}, {"text": "干净", "is_correct": false, "explanation": "与“闹”没有反义关系，“干净”说的是清洁，不是声音。"}, {"text": "明亮", "is_correct": false, "explanation": "与“闹”没有反义关系，“明亮”说的是光线。"}, {"text": "高兴", "is_correct": false, "explanation": "与“闹”没有反义关系，“高兴”说的是心情。"}], "correct_answer": "安静", "explanations": {"安静": "反义：“闹”指吵得别人不能安静，与“安静”相对。", "干净": "与“闹”没有反义关系，“干净”说的是清洁，不是声音。", "明亮": "与“闹”没有反义关系，“明亮”说的是光线。", "高兴": "与“闹”没有反义关系，“高兴”说的是心情。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babba5e0-0b28-42d0-8f55-614438535d6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94887, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "安静", "is_correct": true, "explanation": "反义：“闹”指吵闹，使别人不能安静，与“安静”相对。"}, {"text": "整齐", "is_correct": false, "explanation": "与“闹”没有反义关系，“整齐”说的是排列。"}, {"text": "清楚", "is_correct": false, "explanation": "与“闹”没有反义关系，“清楚”说的是明白、不模糊。"}, {"text": "快乐", "is_correct": false, "explanation": "与“闹”没有反义关系，“快乐”说的是心情。"}], "correct_answer": "安静", "explanations": {"安静": "反义：“闹”指吵闹，使别人不能安静，与“安静”相对。", "整齐": "与“闹”没有反义关系，“整齐”说的是排列。", "清楚": "与“闹”没有反义关系，“清楚”说的是明白、不模糊。", "快乐": "与“闹”没有反义关系，“快乐”说的是心情。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babba5e0-0b28-42d0-8f55-614438535d6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94887, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "闹是发出很大声音，吵得别人不能安静。", "primary_collocate": null, "pronunciation": "nào", "ipa": "nɑʊ˥˩", "syllable_count": 1, "sentences": [{"text": "孩子们在客厅里又跳又闹。", "target_word": "闹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别闹了，爸爸在睡觉。", "target_word": "闹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "楼上的小孩一直在闹，我睡不着。", "target_word": "闹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟闹得我没法写作业。", "target_word": "闹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们在教室里闹，老师很生气。", "target_word": "闹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "隔壁的孩子在院子里闹了一晚上，我一直没睡好。", "target_word": "闹", "complexity_tier": "T3", "furigana": "gé bì de hái zi zài yuàn zi lǐ nào le yì wǎn shang, wǒ yì zhí méi shuì hǎo.", "sentence_source": "generated"}, {"text": "他们在隔壁闹到十二点。", "target_word": "闹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你们小声点，不要在图书馆里闹。", "target_word": "闹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上请不要在楼道里闹，邻居都睡了。", "target_word": "闹", "complexity_tier": "T3", "furigana": "wǎn shang qǐng bú yào zài lóu dào lǐ nào, lín jū dōu shuì le.", "sentence_source": "generated"}, {"text": "孩子们闹了一下午，妈妈头都疼了。", "target_word": "闹", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "闹了", "label": "体标"}, {"form": "闹着", "label": "体标"}, {"form": "闹过", "label": "体标"}], "register": "口语", "sense_fingerprint": "闹：发出很大声音，吵得别人不能安静", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9338e44a-02f0-4ff6-8511-9734bc7b6a50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94887, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "闹", "is_correct": true, "explanation": "闹（nào，第四声）：发出很大声音，吵得别人不能安静，是本词的读音。"}, {"text": "挠", "is_correct": false, "explanation": "挠（náo，第二声）与 nào 声调不同，意思是抓、搔。"}, {"text": "脑", "is_correct": false, "explanation": "脑（nǎo，第三声）与 nào 声调不同，意思是大脑。"}, {"text": "涝", "is_correct": false, "explanation": "涝（lào，第四声）与 nào 声母不同（l 与 n），意思是积水成灾。"}, {"text": "那", "is_correct": false, "explanation": "那（nà，第四声）与 nào 韵母不同（a 与 ao），意思是那个。"}], "explanations": {"闹": "闹（nào，第四声）：发出很大声音，吵得别人不能安静，是本词的读音。", "挠": "挠（náo，第二声）与 nào 声调不同，意思是抓、搔。", "脑": "脑（nǎo，第三声）与 nào 声调不同，意思是大脑。", "涝": "涝（lào，第四声）与 nào 声母不同（l 与 n），意思是积水成灾。", "那": "那（nà，第四声）与 nào 韵母不同（a 与 ao），意思是那个。"}, "sentence_index": null, "correct_answer": "闹"}, "level_3": {"options": [{"text": "睡", "is_correct": false, "explanation": "语义：“跳”和“睡”不能并列描述同时进行的动作，“又……又……”不成立。"}, {"text": "闹", "is_correct": true, "explanation": "闹指发出很大声音，“又跳又闹”描述孩子吵吵嚷嚷的样子。"}, {"text": "写", "is_correct": false, "explanation": "配价：“写”需要宾语，如“写字”，此处缺少宾语，句子不完整。"}, {"text": "修", "is_correct": false, "explanation": "语义：“修”指修理，与“跳”不构成描述孩子动作的并列。"}], "explanations": {"睡": "语义：“跳”和“睡”不能并列描述同时进行的动作，“又……又……”不成立。", "闹": "闹指发出很大声音，“又跳又闹”描述孩子吵吵嚷嚷的样子。", "写": "配价：“写”需要宾语，如“写字”，此处缺少宾语，句子不完整。", "修": "语义：“修”指修理，与“跳”不构成描述孩子动作的并列。"}, "sentence_index": 0, "correct_answer": "闹"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天晚上闹作业，写到十点。", "explanation": "这里应该用〈做〉。“闹”指吵闹，不能与“作业”搭配，完成作业要说“做作业”。"}, {"text": "我闹了一本书，很有意思。", "explanation": "这里应该用〈看〉。“闹”不能用于“书”，读书要用“看”。"}, {"text": "我每天闹澡，很舒服。", "explanation": "这里应该用〈洗〉。“闹”不能与“澡”搭配，洗澡要用“洗”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babba5e0-0b28-42d0-8f55-614438535d6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94887, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "闹", "is_correct": true, "explanation": "闹（nào，第四声）：发出很大声音，吵得别人不能安静，是本词的读音。"}, {"text": "恼", "is_correct": false, "explanation": "恼（nǎo，第三声）与 nào 声调不同，意思是生气。"}, {"text": "烙", "is_correct": false, "explanation": "烙（lào，第四声）与 nào 声母不同（l 与 n），意思是用热器具加热食物。"}, {"text": "怒", "is_correct": false, "explanation": "怒（nù，第四声）与 nào 韵母不同（u 与 ao），意思是生气、愤怒。"}], "explanations": {"闹": "闹（nào，第四声）：发出很大声音，吵得别人不能安静，是本词的读音。", "恼": "恼（nǎo，第三声）与 nào 声调不同，意思是生气。", "烙": "烙（lào，第四声）与 nào 声母不同（l 与 n），意思是用热器具加热食物。", "怒": "怒（nù，第四声）与 nào 韵母不同（u 与 ao），意思是生气、愤怒。"}, "sentence_index": null, "correct_answer": "闹"}, "level_3": {"options": [{"text": "飞", "is_correct": false, "explanation": "语义：人不能在隔壁“飞”到十二点，句子的主语是人。"}, {"text": "闹", "is_correct": true, "explanation": "闹指发出很大声音，“他们在隔壁闹到十二点”描述持续吵闹。"}, {"text": "发光", "is_correct": false, "explanation": "语义：人不会在隔壁“发光”一直到十二点。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：“下雨”是天气现象，主语不能是“他们”，不能说“他们在隔壁下雨”。"}], "explanations": {"飞": "语义：人不能在隔壁“飞”到十二点，句子的主语是人。", "闹": "闹指发出很大声音，“他们在隔壁闹到十二点”描述持续吵闹。", "发光": "语义：人不会在隔壁“发光”一直到十二点。", "下雨": "语义：“下雨”是天气现象，主语不能是“他们”，不能说“他们在隔壁下雨”。"}, "sentence_index": 6, "correct_answer": "闹"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天放学后都闹篮球。", "explanation": "这里应该用〈打〉。“闹”不能与“篮球”搭配，打篮球要用“打”。"}, {"text": "我闹了一首歌，很好听。", "explanation": "这里应该用〈听〉。“闹”不能用于“歌”，听歌要用“听”。"}, {"text": "老师闹了一句话，大家都笑了。", "explanation": "这里应该用〈说〉。“闹”不能指说话，说一句话要用“说”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babba5e0-0b28-42d0-8f55-614438535d6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94887, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "弟弟闹的我没法看书。", "corrected_sentence": "弟弟闹得我没法看书。", "error_description": "结构助词误用：表示结果的补语要用“得”，不能用“的”。应说“弟弟闹得我没法看书。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babba5e0-0b28-42d0-8f55-614438535d6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94887, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈被孩子们闹头都疼了。", "corrected_sentence": "妈妈被孩子们闹得头都疼了。", "error_description": "补语缺失：“闹得……”中的“得”不能省，去掉后句子不通顺。应说“妈妈被孩子们闹得头都疼了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babba5e0-0b28-42d0-8f55-614438535d6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
