INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94889, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec199dda-ed00-4312-8bc9-b9e17011411e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94889, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "麦是一种田里种的、能磨成粉的粮食。", "primary_collocate": null, "pronunciation": "mài", "ipa": "mai̯˥˩", "syllable_count": 1, "sentences": [{"text": "春天他在田里种了麦。", "target_word": "麦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说，这些麦是自己家种的。", "target_word": "麦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天一到，村里人都去割麦。", "target_word": "麦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里水少，适合种麦，不适合种稻。", "target_word": "麦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "麦熟的时候，田里一片金黄。", "target_word": "麦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年的麦长得很好。", "target_word": "麦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家的麦已经收完了。", "target_word": "麦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "麦磨成粉以后才能做面包。", "target_word": "麦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸一早就下地去看麦。", "target_word": "麦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民把今年的麦卖给了粮站。", "target_word": "麦", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "麥", "label": "繁体"}, {"form": "小麦", "label": "复合"}, {"form": "大麦", "label": "复合"}, {"form": "麦子", "label": "复合"}], "register": "中性", "sense_fingerprint": "田里种的、能磨成粉的粮食", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03e574a3-d7c0-4022-bfe0-96ccccca3dcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94889, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "麦", "is_correct": true, "explanation": "正确：麦（mài）是田里种的、能磨成粉的粮食。"}, {"text": "买", "is_correct": false, "explanation": "mǎi（第三声）与 mài（第四声）声调不同，意思是「买」。"}, {"text": "埋", "is_correct": false, "explanation": "mái（第二声）与 mài（第四声）声调不同，意思是「埋」。"}, {"text": "慢", "is_correct": false, "explanation": "màn 与 mài 韵母不同（an 与 ai），意思是「慢」。"}, {"text": "拜", "is_correct": false, "explanation": "bài 与 mài 声母不同（b 与 m），意思是「拜访」。"}], "explanations": {"麦": "正确：麦（mài）是田里种的、能磨成粉的粮食。", "买": "mǎi（第三声）与 mài（第四声）声调不同，意思是「买」。", "埋": "mái（第二声）与 mài（第四声）声调不同，意思是「埋」。", "慢": "màn 与 mài 韵母不同（an 与 ai），意思是「慢」。", "拜": "bài 与 mài 声母不同（b 与 m），意思是「拜访」。"}, "sentence_index": null, "correct_answer": "麦"}, "level_3": {"options": [{"text": "麦", "is_correct": true, "explanation": "正确：「种了」接农作物，「田里」提示种的是能磨粉的粮食。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：「种」接植物或种子，不能说「种了石头」。"}, {"text": "椅子", "is_correct": false, "explanation": "搭配：「种」不接家具，与「种了」不搭配。"}, {"text": "电视", "is_correct": false, "explanation": "语义：「田里」指农田，电视不是能种在田里的东西。"}], "explanations": {"麦": "正确：「种了」接农作物，「田里」提示种的是能磨粉的粮食。", "石头": "搭配：「种」接植物或种子，不能说「种了石头」。", "椅子": "搭配：「种」不接家具，与「种了」不搭配。", "电视": "语义：「田里」指农田，电视不是能种在田里的东西。"}, "sentence_index": 0, "correct_answer": "麦"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "歌手把麦举到嘴边，开始唱歌。", "explanation": "这里的「麦」是〈话筒〉的意思，不是粮食作物。粮食的「麦」指田里种的作物。"}, {"text": "他从地里运回了一条麦。", "explanation": "这里应该用〈袋〉。「条」用于鱼、裤子等长条形的东西，粮食不用它计量。"}, {"text": "农场主运来了一匹麦。", "explanation": "这里应该用〈袋〉。「匹」用于马、布等，不用于粮食。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec199dda-ed00-4312-8bc9-b9e17011411e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94889, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "麦", "is_correct": true, "explanation": "正确：麦（mài）是田里种的、能磨成粉的粮食。"}, {"text": "帽", "is_correct": false, "explanation": "mào 与 mài 韵母不同（ao 与 ai），意思是「帽子」。"}, {"text": "冒", "is_correct": false, "explanation": "mào 与 mài 韵母不同（ao 与 ai），意思是「冒出」或「冒险」。"}, {"text": "妹", "is_correct": false, "explanation": "mèi 与 mài 韵母不同（ei 与 ai），意思是「妹妹」。"}, {"text": "败", "is_correct": false, "explanation": "bài 与 mài 声母不同（b 与 m），意思是「失败」。"}], "explanations": {"麦": "正确：麦（mài）是田里种的、能磨成粉的粮食。", "帽": "mào 与 mài 韵母不同（ao 与 ai），意思是「帽子」。", "冒": "mào 与 mài 韵母不同（ao 与 ai），意思是「冒出」或「冒险」。", "妹": "mèi 与 mài 韵母不同（ei 与 ai），意思是「妹妹」。", "败": "bài 与 mài 声母不同（b 与 m），意思是「失败」。"}, "sentence_index": null, "correct_answer": "麦"}, "level_3": {"options": [{"text": "麦", "is_correct": true, "explanation": "正确：「收完了」接收获的农作物，「麦」符合语境。"}, {"text": "玻璃", "is_correct": false, "explanation": "搭配：「收完」用于收割庄稼，不能说「收完玻璃」。"}, {"text": "空调", "is_correct": false, "explanation": "语义：「收完了」指收获的东西，空调不属于收割对象。"}, {"text": "钢琴", "is_correct": false, "explanation": "搭配：「收完」与钢琴不搭配，农田语境中不说收钢琴。"}], "explanations": {"麦": "正确：「收完了」接收获的农作物，「麦」符合语境。", "玻璃": "搭配：「收完」用于收割庄稼，不能说「收完玻璃」。", "空调": "语义：「收完了」指收获的东西，空调不属于收割对象。", "钢琴": "搭配：「收完」与钢琴不搭配，农田语境中不说收钢琴。"}, "sentence_index": 6, "correct_answer": "麦"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们用麦做了一锅面条。", "explanation": "这里应该用〈面粉〉。麦是没磨过的粮食，要先磨成面粉才能做面条。"}, {"text": "他姓麦，是我们学校的老师。", "explanation": "这里的「麦」是姓氏，表示人的姓，不是粮食作物。"}, {"text": "农民卖了一座麦给粮站。", "explanation": "这里应该用〈袋〉或〈斤〉。「座」用于山、房屋等大型固定的东西，不用于粮食。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec199dda-ed00-4312-8bc9-b9e17011411e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94889, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们家今年种了五条麦。", "corrected_sentence": "他们家今年种了五亩麦。", "error_description": "错误：量词「条」用于长条形的东西，不用于麦。种植面积应用「亩」，正确为「种了五亩麦」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec199dda-ed00-4312-8bc9-b9e17011411e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94889, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们去年收麦过。", "corrected_sentence": "他们去年收过麦。", "error_description": "错误：经历体「过」应紧跟动词，不能放在宾语「麦」后面。正确：「收过麦」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec199dda-ed00-4312-8bc9-b9e17011411e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
