INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94890, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "小麦、大麦等粮食作物的统称，籽粒可磨面。", "primary_collocate": null, "pronunciation": "mài", "ipa": "mai̯˥˩", "syllable_count": 1, "sentences": [{"text": "农民正在地里割麦。", "target_word": "麦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年夏天雨少，麦熟得早。", "target_word": "麦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷每年十月在山坡上种麦。", "target_word": "麦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天晴了，大家都忙着收麦。", "target_word": "麦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把刚割下的麦晒在院子里。", "target_word": "麦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里人会把麦磨成面粉做馒头。", "target_word": "麦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块地去年种的是麦，不是玉米。", "target_word": "麦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "麦黄了，该准备镰刀了。", "target_word": "麦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨前，父亲急着把麦收回家。", "target_word": "麦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北方人多种麦，南方人多种稻。", "target_word": "麦", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "麥", "label": "繁体"}, {"form": "小麦", "label": "复合"}, {"form": "大麦", "label": "复合"}, {"form": "麦子", "label": "复合"}], "register": "中性", "sense_fingerprint": "小麦、大麦等粮食作物的统称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03e574a3-d7c0-4022-bfe0-96ccccca3dcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94890, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "麦", "is_correct": true, "explanation": "正确：麦（mài）指小麦、大麦等粮食作物的统称，籽粒可磨面。"}, {"text": "买", "is_correct": false, "explanation": "mǎi（第三声）与 mài（第四声）声调不同，意思是「买」。"}, {"text": "埋", "is_correct": false, "explanation": "mái（第二声）与 mài（第四声）声调不同，意思是「埋」。"}, {"text": "妹", "is_correct": false, "explanation": "mèi 与 mài 韵母不同（ei 与 ai），意思是「妹妹」。"}, {"text": "败", "is_correct": false, "explanation": "bài 与 mài 声母不同（b 与 m），意思是「失败」。"}], "explanations": {"麦": "正确：麦（mài）指小麦、大麦等粮食作物的统称，籽粒可磨面。", "买": "mǎi（第三声）与 mài（第四声）声调不同，意思是「买」。", "埋": "mái（第二声）与 mài（第四声）声调不同，意思是「埋」。", "妹": "mèi 与 mài 韵母不同（ei 与 ai），意思是「妹妹」。", "败": "bài 与 mài 声母不同（b 与 m），意思是「失败」。"}, "sentence_index": null, "correct_answer": "麦"}, "level_3": {"options": [{"text": "麦", "is_correct": true, "explanation": "正确：「割」后接收割的庄稼，「麦」是麦子，符合「地里」的语境。"}, {"text": "水", "is_correct": false, "explanation": "搭配：「割」用于收割庄稼或草，不能说「割水」。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：「地里」指田间，电脑不是会在田里被割的东西。"}, {"text": "书", "is_correct": false, "explanation": "语义：「农民正在地里」描述田间劳动，书与这个场景不符。"}], "explanations": {"麦": "正确：「割」后接收割的庄稼，「麦」是麦子，符合「地里」的语境。", "水": "搭配：「割」用于收割庄稼或草，不能说「割水」。", "电脑": "语义：「地里」指田间，电脑不是会在田里被割的东西。", "书": "语义：「农民正在地里」描述田间劳动，书与这个场景不符。"}, "sentence_index": 0, "correct_answer": "麦"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一上台就抢麦，大家都笑了。", "explanation": "这里的「麦」是〈话筒〉的意思，如「抢麦」，不是粮食作物。粮食的「麦」指小麦、大麦等作物。"}, {"text": "妈妈从地里带回了一只麦。", "explanation": "这里应该用〈粒〉。「只」用于鸟、猫等动物，不用于粮食颗粒。"}, {"text": "爸爸在仓库里买了一辆麦。", "explanation": "这里应该用〈袋〉。「辆」用于车辆，粮食按袋或斤计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec199dda-ed00-4312-8bc9-b9e17011411e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94890, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "麦", "is_correct": true, "explanation": "正确：麦（mài）指小麦、大麦等粮食作物的统称，籽粒可磨面。"}, {"text": "帽", "is_correct": false, "explanation": "mào 与 mài 韵母不同（ao 与 ai），意思是「帽子」。"}, {"text": "冒", "is_correct": false, "explanation": "mào 与 mài 韵母不同（ao 与 ai），意思是「冒出」或「冒险」。"}, {"text": "拜", "is_correct": false, "explanation": "bài 与 mài 声母不同（b 与 m），意思是「拜访」。"}, {"text": "慢", "is_correct": false, "explanation": "màn 与 mài 韵母不同（an 与 ai），意思是「慢」。"}], "explanations": {"麦": "正确：麦（mài）指小麦、大麦等粮食作物的统称，籽粒可磨面。", "帽": "mào 与 mài 韵母不同（ao 与 ai），意思是「帽子」。", "冒": "mào 与 mài 韵母不同（ao 与 ai），意思是「冒出」或「冒险」。", "拜": "bài 与 mài 声母不同（b 与 m），意思是「拜访」。", "慢": "màn 与 mài 韵母不同（an 与 ai），意思是「慢」。"}, "sentence_index": null, "correct_answer": "麦"}, "level_3": {"options": [{"text": "麦", "is_correct": true, "explanation": "正确：「种的是」后接农作物，「麦」与「不是玉米」形成对比，符合语境。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：「种」接植物或种子，不能说「种石头」。"}, {"text": "椅子", "is_correct": false, "explanation": "搭配：「种」不接家具，与「种的是」后的农作物不搭配。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是能种下的东西，与「这块地」的农作语境冲突。"}], "explanations": {"麦": "正确：「种的是」后接农作物，「麦」与「不是玉米」形成对比，符合语境。", "石头": "搭配：「种」接植物或种子，不能说「种石头」。", "椅子": "搭配：「种」不接家具，与「种的是」后的农作物不搭配。", "空气": "语义：空气不是能种下的东西，与「这块地」的农作语境冲突。"}, "sentence_index": 6, "correct_answer": "麦"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈用麦做了一锅馒头。", "explanation": "这里应该用〈面粉〉。麦是没磨过的粮食，要先磨成面粉才能做馒头。"}, {"text": "他每天早上喝一杯麦。", "explanation": "这里应该用〈麦片〉。麦粒不能直接喝，要先加工成麦片。"}, {"text": "农民卖了一本麦给粮站。", "explanation": "这里应该用〈袋〉或〈斤〉。「本」用于书、本子等，不用于粮食。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec199dda-ed00-4312-8bc9-b9e17011411e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94890, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他家今年种了三只麦。", "corrected_sentence": "他家今年种了三亩麦。", "error_description": "错误：「麦」的量词用了「只」，而「只」用于动物。正确：种植面积用「亩」，应说「种了三亩麦」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec199dda-ed00-4312-8bc9-b9e17011411e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94890, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "农民已经收了许多麦们。", "corrected_sentence": "农民已经收了许多麦。", "error_description": "错误：「麦」后面加了复数标记「们」。「麦」是粮食名词，不能用「们」表示复数，应说「收了许多麦」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec199dda-ed00-4312-8bc9-b9e17011411e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
