INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94891, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "不仅仅是不只是这一个，还有别的。", "primary_collocate": null, "pronunciation": "bù jǐn jǐn", "ipa": "pu˥˩ tɕin˨˩ tɕin˨˩", "syllable_count": 3, "sentences": [{"text": "他不仅仅会说中文，还会说法语。", "target_word": "不仅仅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢的不仅仅是苹果，还有香蕉。", "target_word": "不仅仅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个计划不仅仅是我的想法，还有大家的建议。", "target_word": "不仅仅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北京不仅仅有长城，还有很多公园。", "target_word": "不仅仅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不仅仅是我的老师，也是我的朋友。", "target_word": "不仅仅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不仅仅喜欢唱歌，还喜欢跳舞。", "target_word": "不仅仅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习不仅仅是看书，还要多练习。", "target_word": "不仅仅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们家不仅仅有一只猫，还有两条狗。", "target_word": "不仅仅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不仅仅去过上海，还去过广州。", "target_word": "不仅仅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店不仅仅卖水果，还卖菜。", "target_word": "不仅仅", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不僅僅", "label": "繁体"}], "register": "中性", "sense_fingerprint": "不只这一个，还有别的（后常接“还／也”）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03e574a3-d7c0-4022-bfe0-96ccccca3dcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94891, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不仅仅", "is_correct": true, "explanation": "正确：“不仅仅”表示不只这一个，后面的“还会说法语”引出补充，与句意一致。"}, {"text": "只", "is_correct": false, "explanation": "语义：“只”表示唯一，“只会说中文”与后面的“还会说法语”相矛盾。"}, {"text": "突然", "is_correct": false, "explanation": "语义：“突然”表示忽然发生，不能用来修饰表示能力的“会”。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”多与否定或已经发生的经历连用，不与表示能力的“会”搭配。"}], "explanations": {"不仅仅": "正确：“不仅仅”表示不只这一个，后面的“还会说法语”引出补充，与句意一致。", "只": "语义：“只”表示唯一，“只会说中文”与后面的“还会说法语”相矛盾。", "突然": "语义：“突然”表示忽然发生，不能用来修饰表示能力的“会”。", "从来": "搭配：“从来”多与否定或已经发生的经历连用，不与表示能力的“会”搭配。"}, "sentence_index": 0, "correct_answer": "不仅仅"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间教室不仅仅有三把椅子，没有别的东西。", "explanation": "这里应该用〈仅仅〉。“不仅仅”要引出三把椅子之外的补充，句中却说没有别的东西，前后矛盾，所以用错。"}, {"text": "北京不仅仅有长城，只有长城。", "explanation": "这里应该用〈仅仅〉。“不仅仅”要引出长城之外的内容，句中却说“只有长城”，前后矛盾，所以用错。"}, {"text": "他不仅仅是个学生，别的身份一概没有。", "explanation": "这里应该用〈仅仅〉。“不仅仅”要引出学生之外的补充，句中却说别的身份一概没有，前后矛盾，所以用错。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec199dda-ed00-4312-8bc9-b9e17011411e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94891, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不仅仅", "is_correct": true, "explanation": "正确：“不仅仅”表示不只是看书，后面的“还要多练习”补充了另一方面，与句意一致。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：“非常”修饰形容词或心理动词，不能修饰判断动词“是”。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不定时发生，与“学习是看书”这种对本质的判断不合。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示很快发生，不能用来做关于学习本质的判断。"}], "explanations": {"不仅仅": "正确：“不仅仅”表示不只是看书，后面的“还要多练习”补充了另一方面，与句意一致。", "非常": "搭配：“非常”修饰形容词或心理动词，不能修饰判断动词“是”。", "偶尔": "语义：“偶尔”表示不定时发生，与“学习是看书”这种对本质的判断不合。", "马上": "语义：“马上”表示很快发生，不能用来做关于学习本质的判断。"}, "sentence_index": 6, "correct_answer": "不仅仅"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个房间不仅仅有一张床，别的东西一样也没有。", "explanation": "这里应该用〈仅仅〉。“不仅仅”要引出床之外的补充，句中却说别的东西一样也没有，前后矛盾，所以用错。"}, {"text": "他不仅仅会说中文，却一句外语也不会。", "explanation": "这里应该用〈仅仅〉。“不仅仅”要引出中文之外的补充，句中却说一句外语也不会，前后矛盾，所以用错。"}, {"text": "这家店不仅仅卖水果，只卖水果。", "explanation": "这里应该用〈仅仅〉。“不仅仅”要引出水果之外的内容，句中却说只卖水果，前后矛盾，所以用错。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec199dda-ed00-4312-8bc9-b9e17011411e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94891, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这所学校不仅仅的有图书馆，还有体育馆。", "corrected_sentence": "这所学校不仅仅有图书馆，还有体育馆。", "error_description": "错误：“不仅仅”后多加了“的”，写成“不仅仅的有图书馆”。正确：“不仅仅有图书馆”，“不仅仅”直接修饰后面的谓语，中间不能加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec199dda-ed00-4312-8bc9-b9e17011411e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94891, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我妹妹不仅仅不仅仅会弹钢琴，还会画画。", "corrected_sentence": "我妹妹不仅仅会弹钢琴，还会画画。", "error_description": "错误：“不仅仅”重复出现，写成“不仅仅不仅仅会弹钢琴”。正确：“我妹妹不仅仅会弹钢琴，还会画画”，“不仅仅”只用一次。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec199dda-ed00-4312-8bc9-b9e17011411e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94893, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "在乎", "is_correct": true, "explanation": "“在乎”表示放在心上、重视，与“不在乎”意思相反。"}, {"text": "游泳", "is_correct": false, "explanation": "“游泳”是一种运动，与“不在乎”没有反义关系。"}, {"text": "旅行", "is_correct": false, "explanation": "“旅行”指出门游览，与“不在乎”没有反义关系。"}, {"text": "参加", "is_correct": false, "explanation": "“参加”指加入某项活动，与“不在乎”没有反义关系。"}], "correct_answer": "在乎", "explanations": {"在乎": "“在乎”表示放在心上、重视，与“不在乎”意思相反。", "游泳": "“游泳”是一种运动，与“不在乎”没有反义关系。", "旅行": "“旅行”指出门游览，与“不在乎”没有反义关系。", "参加": "“参加”指加入某项活动，与“不在乎”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babba5e0-0b28-42d0-8f55-614438535d6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94893, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "在乎", "is_correct": true, "explanation": "“在乎”表示放在心上、重视，与“不在乎”意思相反。"}, {"text": "唱歌", "is_correct": false, "explanation": "“唱歌”指发声演唱，与“不在乎”没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "“散步”指慢慢走路，与“不在乎”没有反义关系。"}, {"text": "写信", "is_correct": false, "explanation": "“写信”指用文字与人通信，与“不在乎”没有反义关系。"}], "correct_answer": "在乎", "explanations": {"在乎": "“在乎”表示放在心上、重视，与“不在乎”意思相反。", "唱歌": "“唱歌”指发声演唱，与“不在乎”没有反义关系。", "散步": "“散步”指慢慢走路，与“不在乎”没有反义关系。", "写信": "“写信”指用文字与人通信，与“不在乎”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babba5e0-0b28-42d0-8f55-614438535d6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94893, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "不在乎是心里不放在心上，不觉得有关系。", "primary_collocate": null, "pronunciation": "bù zài hū", "ipa": "pu˥˩ tsai˥˩ xu˥", "syllable_count": 3, "sentences": [{"text": "别人怎么说，他一点儿也不在乎。", "target_word": "不在乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不在乎钱多钱少。", "target_word": "不在乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不在乎天气，每天都去跑步。", "target_word": "不在乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不在乎别人的看法。", "target_word": "不在乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不在乎输赢，只想玩得高兴。", "target_word": "不在乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟不在乎成绩，天天玩游戏。", "target_word": "不在乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板不在乎我迟到几分钟。", "target_word": "不在乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他穿什么衣服都不在乎。", "target_word": "不在乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷不在乎吃得好不好。", "target_word": "不在乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我才不在乎他怎么想呢。", "target_word": "不在乎", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "不在乎：不放在心上，不觉得有关系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9338e44a-02f0-4ff6-8511-9734bc7b6a50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94893, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不在乎", "is_correct": true, "explanation": "“不在乎”表示不放在心上、不觉得有关系，与“别人怎么说，他一点儿也”的语气相合。"}, {"text": "在乎", "is_correct": false, "explanation": "搭配：“一点儿也”后面要用否定，不能说“一点儿也在乎”。"}, {"text": "喜欢", "is_correct": false, "explanation": "搭配：“一点儿也”后面要用否定，不能说“一点儿也喜欢”。"}, {"text": "生气", "is_correct": false, "explanation": "语义：“生气”表示发怒，与“别人怎么说，他一点儿也”后面满不在乎的语气相反。"}], "explanations": {"不在乎": "“不在乎”表示不放在心上、不觉得有关系，与“别人怎么说，他一点儿也”的语气相合。", "在乎": "搭配：“一点儿也”后面要用否定，不能说“一点儿也在乎”。", "喜欢": "搭配：“一点儿也”后面要用否定，不能说“一点儿也喜欢”。", "生气": "语义：“生气”表示发怒，与“别人怎么说，他一点儿也”后面满不在乎的语气相反。"}, "sentence_index": 0, "correct_answer": "不在乎"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他刚才不在乎在厨房，我们都没看见他。", "explanation": "这里应该用〈不在〉。“不在乎”表示不放在心上，后面不能接“在厨房”这样的地点；说人不在某处要用“不在”。"}, {"text": "他的病已经好了，现在却不在乎吃药了，每天还是按时吃。", "explanation": "这里应该用〈不再〉。“不在乎”表示不放在心上，与“每天还是按时吃”矛盾；表示以后不再做某事要用“不再”。"}, {"text": "他的腿受伤了，他很想去公园散步，却不在乎走路。", "explanation": "这里应该用〈不能〉。前句说他想去散步，“不在乎”表示不放在心上，与此矛盾；腿伤造成的限制要用“不能”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babba5e0-0b28-42d0-8f55-614438535d6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94893, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不在乎", "is_correct": true, "explanation": "“不在乎”表示老板不把迟到几分钟放在心上，与句意相合。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：“感谢”表示感激，迟到不值得感谢，与句意不合。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：“赞美”表示称赞，迟到不值得称赞，与句意不合。"}, {"text": "欢迎", "is_correct": false, "explanation": "搭配：“欢迎”多用于人、客人或意见，不说“欢迎我迟到几分钟”。"}], "explanations": {"不在乎": "“不在乎”表示老板不把迟到几分钟放在心上，与句意相合。", "感谢": "语义：“感谢”表示感激，迟到不值得感谢，与句意不合。", "赞美": "语义：“赞美”表示称赞，迟到不值得称赞，与句意不合。", "欢迎": "搭配：“欢迎”多用于人、客人或意见，不说“欢迎我迟到几分钟”。"}, "sentence_index": 6, "correct_answer": "不在乎"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很怕黑，不在乎一个人走夜路。", "explanation": "这里应该用〈不敢〉。前句说他怕黑，“不在乎”表示不放在心上，与“怕”矛盾，表达的是害怕的意思时要用“不敢”。"}, {"text": "他很想道歉，却不在乎开口。", "explanation": "这里应该用〈不愿〉或〈不好意思〉。“很想道歉”与“不在乎”矛盾；“不在乎”表示不放在心上，不表示不肯。"}, {"text": "妈妈很爱这个孩子，却不在乎他的生日，每年都为他的生日忙个不停。", "explanation": "这里应该用〈在乎〉。前句说“每年都为他的生日忙个不停”，与“不在乎”（不放在心上）矛盾；表示放在心上要用“在乎”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babba5e0-0b28-42d0-8f55-614438535d6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94893, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她不不在乎别人笑她。", "corrected_sentence": "她不在乎别人笑她。", "error_description": "错误形式是“不不在乎”，正确形式是“不在乎”。“不在乎”本身已含否定词“不”，多写一个“不”会使句子不通，应删去多余的“不”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babba5e0-0b28-42d0-8f55-614438535d6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94893, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈不在乎了我的话。", "corrected_sentence": "妈妈不在乎我的话。", "error_description": "“了”放错了位置。“不在乎”后面直接接宾语时，“了”不能放在“乎”和宾语之间，应删去或放到句末。正确形式为“妈妈不在乎我的话”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babba5e0-0b28-42d0-8f55-614438535d6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94894, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "在乎", "is_correct": true, "explanation": "“在乎”表示放在心上、重视，与“不在乎”意思相反。"}, {"text": "散步", "is_correct": false, "explanation": "“散步”指慢慢走路，与“不在乎”没有反义关系。"}, {"text": "写字", "is_correct": false, "explanation": "“写字”指用笔写字，与“不在乎”没有反义关系。"}, {"text": "跑步", "is_correct": false, "explanation": "“跑步”指快速跑动，与“不在乎”没有反义关系。"}], "correct_answer": "在乎", "explanations": {"在乎": "“在乎”表示放在心上、重视，与“不在乎”意思相反。", "散步": "“散步”指慢慢走路，与“不在乎”没有反义关系。", "写字": "“写字”指用笔写字，与“不在乎”没有反义关系。", "跑步": "“跑步”指快速跑动，与“不在乎”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babba5e0-0b28-42d0-8f55-614438535d6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94894, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "在乎", "is_correct": true, "explanation": "“在乎”表示放在心上、重视，与“不在乎”意思相反。"}, {"text": "唱歌", "is_correct": false, "explanation": "“唱歌”指发声演唱，与“不在乎”没有反义关系。"}, {"text": "游泳", "is_correct": false, "explanation": "“游泳”是一种运动，与“不在乎”没有反义关系。"}, {"text": "看书", "is_correct": false, "explanation": "“看书”指阅读书籍，与“不在乎”没有反义关系。"}], "correct_answer": "在乎", "explanations": {"在乎": "“在乎”表示放在心上、重视，与“不在乎”意思相反。", "唱歌": "“唱歌”指发声演唱，与“不在乎”没有反义关系。", "游泳": "“游泳”是一种运动，与“不在乎”没有反义关系。", "看书": "“看书”指阅读书籍，与“不在乎”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babba5e0-0b28-42d0-8f55-614438535d6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94894, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "不放在心上，认为没有关系。", "primary_collocate": null, "pronunciation": "bù zài hū", "ipa": "pu˥˩ tsai˥˩ xu˥", "syllable_count": 3, "sentences": [{"text": "下雨了，可是我们都不在乎。", "target_word": "不在乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说自己不在乎这件小事。", "target_word": "不在乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友迟到了，我一点儿也不在乎。", "target_word": "不在乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明不在乎别人笑他，继续唱歌。", "target_word": "不在乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈不在乎花多少时间，只要孩子高兴。", "target_word": "不在乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他好像什么都不在乎。", "target_word": "不在乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不在乎我的话，我就不说了。", "target_word": "不在乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这点小钱，他根本不在乎。", "target_word": "不在乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们都不在乎谁先到。", "target_word": "不在乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不在乎吃苦，只想学好中文。", "target_word": "不在乎", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "不在乎：不放在心上，认为没有关系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9338e44a-02f0-4ff6-8511-9734bc7b6a50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94894, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不在乎", "is_correct": true, "explanation": "“不在乎”表示不放在心上，与“下雨了，可是我们都”的转折语气相合。"}, {"text": "在乎", "is_correct": false, "explanation": "语义：“在乎”表示放在心上，与“可是”前后转折的语意不合。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：“感谢”表示感激，下雨不值得感谢，与句意不合。"}, {"text": "欢迎", "is_correct": false, "explanation": "搭配：“欢迎”多用于人、客人或意见，不说“欢迎下雨”。"}], "explanations": {"不在乎": "“不在乎”表示不放在心上，与“下雨了，可是我们都”的转折语气相合。", "在乎": "语义：“在乎”表示放在心上，与“可是”前后转折的语意不合。", "感谢": "语义：“感谢”表示感激，下雨不值得感谢，与句意不合。", "欢迎": "搭配：“欢迎”多用于人、客人或意见，不说“欢迎下雨”。"}, "sentence_index": 0, "correct_answer": "不在乎"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小明刚才不在乎在操场，我们都没看见他。", "explanation": "这里应该用〈不在〉。“不在乎”表示不放在心上，后面不能接“在操场”这样的地点；说人不在某处要用“不在”。"}, {"text": "小明的腿已经好了，现在却不在乎跑步了，每天还是天天跑。", "explanation": "这里应该用〈不再〉。“不在乎”表示不放在心上，与“每天还是天天跑”矛盾；表示以后不再做某事要用“不再”。"}, {"text": "小明的嗓子坏了，他很想参加合唱，却不在乎唱歌。", "explanation": "这里应该用〈不能〉。前句说他想参加合唱，“不在乎”表示不放在心上，与此矛盾；嗓子坏了造成的限制要用“不能”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babba5e0-0b28-42d0-8f55-614438535d6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94894, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不在乎", "is_correct": true, "explanation": "“不在乎”表示不放在心上，与“你……我的话，我就不说了”的语境相合。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能带“话”作宾语，不能说“吃我的话”。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌，不能说“唱我的话”。"}, {"text": "生气", "is_correct": false, "explanation": "配价：“生气”是不及物动词，不能直接带“我的话”作宾语，应说“生……的气”。"}], "explanations": {"不在乎": "“不在乎”表示不放在心上，与“你……我的话，我就不说了”的语境相合。", "吃": "搭配：“吃”不能带“话”作宾语，不能说“吃我的话”。", "唱": "搭配：“唱”的对象是歌，不能说“唱我的话”。", "生气": "配价：“生气”是不及物动词，不能直接带“我的话”作宾语，应说“生……的气”。"}, "sentence_index": 6, "correct_answer": "不在乎"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他发烧了，很想去上课，却不在乎起床。", "explanation": "这里应该用〈不能〉。前句说他很想去上课，发烧使他起不来；“不在乎”表示不放在心上，与此矛盾。"}, {"text": "他看见狗就发抖，却不在乎走进院子。", "explanation": "这里应该用〈不敢〉。前句写他害怕，“不在乎”表示不放在心上，与害怕的语境矛盾。"}, {"text": "他的钱包丢了，很想买票，却不在乎买。", "explanation": "这里应该用〈没法〉。钱包丢了使他买不了票；“不在乎”表示不放在心上，与“很想买票”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babba5e0-0b28-42d0-8f55-614438535d6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94894, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我姐姐不不在乎别人的眼光。", "corrected_sentence": "我姐姐不在乎别人的眼光。", "error_description": "错误形式是“不不在乎”，正确形式是“不在乎”。“不在乎”本身已含否定词“不”，多写一个“不”会使句子不通，应删去多余的“不”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babba5e0-0b28-42d0-8f55-614438535d6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94894, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们不在乎了这点小钱。", "corrected_sentence": "我们不在乎这点小钱。", "error_description": "“了”放错了位置。“不在乎”后面直接接宾语时，“了”不能放在“乎”和宾语之间，应删去。正确形式为“我们不在乎这点小钱”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babba5e0-0b28-42d0-8f55-614438535d6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
