INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94895, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '285ed9d0-33bc-43e9-8b33-d3745b24d339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94895, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "主演是在电影或电视剧里演最主要的角色。", "primary_collocate": null, "pronunciation": "zhǔ yǎn", "ipa": "ʈʂu˨˩˦ jɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "这部电影是谁主演的？", "target_word": "主演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他主演了一部很有名的电影。", "target_word": "主演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她第一次主演电视剧，心里很紧张。", "target_word": "主演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个电影明星主演过很多故事片。", "target_word": "主演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最喜欢的演员主演了这部新电影。", "target_word": "主演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不但会唱歌，还主演了两部电影。", "target_word": "主演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影由成龙主演，很多人去看。", "target_word": "主演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她主演的电影明天晚上上映。", "target_word": "主演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导演请他主演这部电影里的老人。", "target_word": "主演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他主演的那部电影得了大奖。", "target_word": "主演", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "主演了", "label": "完成体"}, {"form": "主演过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "在电影或电视剧里担任主角", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '702d0700-d623-41b2-b926-c6455e91f03f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94895, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "主演", "is_correct": true, "explanation": "主演指在电影里担任主要角色，问“是谁主演的”正合语境。"}, {"text": "修理", "is_correct": false, "explanation": "语义：修理针对器物，电影不能被修理，“谁修理的电影”说不通。"}, {"text": "出版", "is_correct": false, "explanation": "搭配：出版多用于书籍、报刊，不说“出版电影”，这里说不通。"}, {"text": "摘", "is_correct": false, "explanation": "语义：摘是采摘果实或取下物件，与电影无关，句子不成立。"}], "explanations": {"主演": "主演指在电影里担任主要角色，问“是谁主演的”正合语境。", "修理": "语义：修理针对器物，电影不能被修理，“谁修理的电影”说不通。", "出版": "搭配：出版多用于书籍、报刊，不说“出版电影”，这里说不通。", "摘": "语义：摘是采摘果实或取下物件，与电影无关，句子不成立。"}, "sentence_index": 0, "correct_answer": "主演"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在这部电影里主演了一个路人。", "explanation": "这里应该用〈出演〉。主演指担任主要角色，路人是次要角色，要用出演。"}, {"text": "他主演了这次全班的大扫除。", "explanation": "这里应该用〈组织〉。主演指在电影、话剧等作品中担任主角，大扫除不是表演，要用组织。"}, {"text": "她在学校的运动会上主演了开幕式。", "explanation": "这里应该用〈主持〉。主演指在戏剧、电影中担任主角，开幕式不是作品，要用主持。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '285ed9d0-33bc-43e9-8b33-d3745b24d339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94895, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "主演", "is_correct": true, "explanation": "主演指担任电影的主要角色，“由某人主演”是常见说法。"}, {"text": "吃", "is_correct": false, "explanation": "语义：吃是进食动作，电影不能被吃，句子不成立。"}, {"text": "煮", "is_correct": false, "explanation": "语义：煮用于烹调食物，与电影无关。"}, {"text": "切", "is_correct": false, "explanation": "搭配：切的对象多为食物或物体，不能说“由成龙切”电影。"}], "explanations": {"主演": "主演指担任电影的主要角色，“由某人主演”是常见说法。", "吃": "语义：吃是进食动作，电影不能被吃，句子不成立。", "煮": "语义：煮用于烹调食物，与电影无关。", "切": "搭配：切的对象多为食物或物体，不能说“由成龙切”电影。"}, "sentence_index": 6, "correct_answer": "主演"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司主演了这部电影，观众都很喜欢。", "explanation": "这里应该用〈出品〉。主演的主语必须是演员，公司出资制作要用出品。"}, {"text": "观众主演了这部电影，每个人都哭了。", "explanation": "这里应该用〈欣赏〉。主演要求主语是演员，观众是欣赏电影的人，不能说观众主演电影。"}, {"text": "这台摄影机主演了这部电影，效果很好。", "explanation": "这里应该用〈拍摄〉。主演要求主语是演员，摄影机是拍摄工具，不能担任角色，要用拍摄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '285ed9d0-33bc-43e9-8b33-d3745b24d339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94895, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她明年要主演过一部新电视剧。", "corrected_sentence": "她明年要主演一部新电视剧。", "error_description": "错误：“明年要”表示将来的事，“主演”后面不能加表示经历的“过”。去掉“过”，应为“明年要主演一部新电视剧”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '285ed9d0-33bc-43e9-8b33-d3745b24d339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94895, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她正在主演了两部很受欢迎的电视剧。", "corrected_sentence": "她正在主演两部很受欢迎的电视剧。", "error_description": "错误：“正在”表示动作进行，不能与“了”同用；正确是“正在主演”，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '285ed9d0-33bc-43e9-8b33-d3745b24d339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
