INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94897, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "以此是用这个作为办法或原因。", "primary_collocate": null, "pronunciation": "yǐ cǐ", "ipa": "i˨˩ tsʰɨ˨˩", "syllable_count": 2, "sentences": [{"text": "他写了一封信，以此表达谢意。", "target_word": "以此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了一份保险，以此保护家人。", "target_word": "以此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师讲了一个故事，以此提醒大家。", "target_word": "以此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天练字，以此放松心情。", "target_word": "以此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他送了一束花，以此表示祝贺。", "target_word": "以此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司降低了价格，以此吸引客人。", "target_word": "以此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸戒了烟，以此给孩子做榜样。", "target_word": "以此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们办了一场比赛，以此鼓励大家学习。", "target_word": "以此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿出一张照片，以此证明自己去过那里。", "target_word": "以此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他常常帮助别人，以此回报社会。", "target_word": "以此", "complexity_tier": "T3", "furigana": "tā chángcháng bāngzhù biérén, yǐ cǐ huíbào shèhuì.", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "以此＋动词：用前面说的做法或事情来达到某个目的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8674e63a-393f-4d84-bf8a-ca1ff6fc6749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94897, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "以此", "is_correct": true, "explanation": "本词：连词，表示用前面说的做法来达到某个目的，如“以此表达谢意”。"}, {"text": "一次", "is_correct": false, "explanation": "yí（第二声）与 yǐ（第三声）声调不同，cì（第四声）与 cǐ（第三声）声调不同，意思是“一次”。"}, {"text": "依次", "is_correct": false, "explanation": "yī（第一声）与 yǐ（第三声）声调不同，cì（第四声）与 cǐ（第三声）声调不同，意思是“依次”。"}, {"text": "亿次", "is_correct": false, "explanation": "yì（第四声）与 yǐ（第三声）声调不同，cì（第四声）与 cǐ（第三声）声调不同，意思是“亿次”。"}], "explanations": {"以此": "本词：连词，表示用前面说的做法来达到某个目的，如“以此表达谢意”。", "一次": "yí（第二声）与 yǐ（第三声）声调不同，cì（第四声）与 cǐ（第三声）声调不同，意思是“一次”。", "依次": "yī（第一声）与 yǐ（第三声）声调不同，cì（第四声）与 cǐ（第三声）声调不同，意思是“依次”。", "亿次": "yì（第四声）与 yǐ（第三声）声调不同，cì（第四声）与 cǐ（第三声）声调不同，意思是“亿次”。"}, "sentence_index": null, "correct_answer": "以此"}, "level_3": {"options": [{"text": "以此", "is_correct": true, "explanation": "以此：连词，表示用写信的做法达到表达谢意的目的，与句意相符。"}, {"text": "以免", "is_correct": false, "explanation": "语义：“以免”表示避免某种后果，与“表达谢意”的目的正相反。"}, {"text": "不料", "is_correct": false, "explanation": "语义：“不料”引出出乎意料的结果，“表达谢意”是有意的目的，不能用“不料”引出。"}, {"text": "否则", "is_correct": false, "explanation": "搭配：“否则”引出另一种选择或后果，前文“写了一封信”不是可被替代的条件。"}], "explanations": {"以此": "以此：连词，表示用写信的做法达到表达谢意的目的，与句意相符。", "以免": "语义：“以免”表示避免某种后果，与“表达谢意”的目的正相反。", "不料": "语义：“不料”引出出乎意料的结果，“表达谢意”是有意的目的，不能用“不料”引出。", "否则": "搭配：“否则”引出另一种选择或后果，前文“写了一封信”不是可被替代的条件。"}, "sentence_index": 0, "correct_answer": "以此"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他迟到了，以此被老师批评。", "explanation": "这里应该用〈所以〉。以此表示用某种做法来达到目的，不能表示“被老师批评”这种自然的结果。"}, {"text": "她很努力，以此很开心。", "explanation": "这里应该用〈因此〉。以此后面要接动词表示做法，不能接形容词“很开心”。"}, {"text": "天下雨了，以此我们回家了。", "explanation": "这里应该用〈于是〉。以此后面要接动词表示做法，不能直接接主语“我们”；引出后续动作要用〈于是〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02bbc78d-1e95-4345-8942-46b25251613e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94897, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "以此", "is_correct": true, "explanation": "本词：连词，表示用前面说的做法达到某个目的，后接动词。"}, {"text": "以死", "is_correct": false, "explanation": "sǐ（第三声）与 cǐ（第三声）只差声母（s 与 c），意思是“以死”。"}, {"text": "以次", "is_correct": false, "explanation": "cì（第四声）与 cǐ（第三声）只差声调，意思是“按次序”。"}, {"text": "依此", "is_correct": false, "explanation": "yī（第一声）与 yǐ（第三声）只差第一音节声调，cǐ 相同，意思是“依此”。"}], "explanations": {"以此": "本词：连词，表示用前面说的做法达到某个目的，后接动词。", "以死": "sǐ（第三声）与 cǐ（第三声）只差声母（s 与 c），意思是“以死”。", "以次": "cì（第四声）与 cǐ（第三声）只差声调，意思是“按次序”。", "依此": "yī（第一声）与 yǐ（第三声）只差第一音节声调，cǐ 相同，意思是“依此”。"}, "sentence_index": null, "correct_answer": "以此"}, "level_3": {"options": [{"text": "以此", "is_correct": true, "explanation": "以此：连词，表示戒烟的做法达到做榜样的目的，与句意相符。"}, {"text": "不料", "is_correct": false, "explanation": "语义：“不料”表示出乎意料，“做榜样”是有意的行为，不能用“不料”引出。"}, {"text": "但是", "is_correct": false, "explanation": "语义：“但是”表示转折，“戒烟”与“做榜样”之间没有对立关系。"}, {"text": "何况", "is_correct": false, "explanation": "搭配：“何况”要在前文有更低层次的事情作铺垫，此处没有这样的铺垫。"}], "explanations": {"以此": "以此：连词，表示戒烟的做法达到做榜样的目的，与句意相符。", "不料": "语义：“不料”表示出乎意料，“做榜样”是有意的行为，不能用“不料”引出。", "但是": "语义：“但是”表示转折，“戒烟”与“做榜样”之间没有对立关系。", "何况": "搭配：“何况”要在前文有更低层次的事情作铺垫，此处没有这样的铺垫。"}, "sentence_index": 6, "correct_answer": "以此"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他忘了带钥匙，以此进不了门。", "explanation": "这里应该用〈因此〉。以此表示用某种做法来达到目的，不能表示“进不了门”这种结果。"}, {"text": "天气很好，以此很多人去公园。", "explanation": "这里应该用〈因此〉。以此不能直接接主语“很多人”，表示结果要用〈因此〉。"}, {"text": "这是一本好书，以此的作者很有名。", "explanation": "这里应该用〈它〉。以此不能修饰名词“作者”，指代前面的书要用〈它〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02bbc78d-1e95-4345-8942-46b25251613e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94897, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她每天跑步，以此健康。", "corrected_sentence": "她每天跑步，以此保持健康。", "error_description": "错误形式：“以此健康”。正确形式：“以此保持健康”。原因：“以此”后面要接动词，省略“保持”后句子不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02bbc78d-1e95-4345-8942-46b25251613e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94897, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每天练琴，以此为提高水平。", "corrected_sentence": "他每天练琴，以此提高水平。", "error_description": "错误形式：“以此为提高水平”。正确形式：“以此提高水平”。原因：“以此”后接动词时不加“为”；“为”只接名词性成分，如“以此为依据”“以此为目标”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02bbc78d-1e95-4345-8942-46b25251613e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94898, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02bbc78d-1e95-4345-8942-46b25251613e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94898, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02bbc78d-1e95-4345-8942-46b25251613e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94898, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "用这个，拿这个作为凭借或依据。", "primary_collocate": null, "pronunciation": "yǐ cǐ", "ipa": "i˨˩ tsʰɨ˨˩", "syllable_count": 2, "sentences": [{"text": "公司发布了新规定，员工以此为准。", "target_word": "以此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给出了答案，学生以此为依据检查作业。", "target_word": "以此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有一份合同，以此为凭去银行。", "target_word": "以此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是官方的数据，大家可以以此作参考。", "target_word": "以此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些数据很可靠，我们以此做判断。", "target_word": "以此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把地图放在桌上，以此为依据讲路线。", "target_word": "以此", "complexity_tier": "T3", "furigana": "tā bǎ dìtú fàng zài zhuōshàng, yǐ cǐ wéi yījù jiǎng lùxiàn.", "sentence_source": "generated"}, {"text": "请你以此为依据，再写一个句子。", "target_word": "以此", "complexity_tier": "T3", "furigana": "qǐng nǐ yǐ cǐ wéi yījù, zài xiě yí gè jùzi.", "sentence_source": "generated"}, {"text": "校长说今年要节约用水，并以此为依据制定计划。", "target_word": "以此", "complexity_tier": "T3", "furigana": "xiàozhǎng shuō jīnnián yào jiéyuē yòngshuǐ, bìng yǐ cǐ wéi yījù zhìdìng jìhuà.", "sentence_source": "generated"}, {"text": "她留下一张字条，以此为证。", "target_word": "以此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以此为凭，你可以领取礼物。", "target_word": "以此", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "以此为准、以此为依据：拿前面提到的事物作凭借或依据", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8674e63a-393f-4d84-bf8a-ca1ff6fc6749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94898, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "以此", "is_correct": true, "explanation": "本词：连词，用这个作为凭借或依据，如“以此为准”。"}, {"text": "一次", "is_correct": false, "explanation": "yí（第二声）与 yǐ（第三声）声调不同，cì（第四声）与 cǐ（第三声）声调不同，意思是“一次”。"}, {"text": "依次", "is_correct": false, "explanation": "yī（第一声）与 yǐ（第三声）声调不同，cì（第四声）与 cǐ 声调不同，意思是“依次”。"}, {"text": "亿次", "is_correct": false, "explanation": "yì（第四声）与 yǐ（第三声）声调不同，cì（第四声）与 cǐ（第三声）声调不同，意思是“亿次”。"}, {"text": "依此", "is_correct": false, "explanation": "yī（第一声）与 yǐ（第三声）只差第一音节声调，cǐ 相同，意思是“依此”。"}], "explanations": {"以此": "本词：连词，用这个作为凭借或依据，如“以此为准”。", "一次": "yí（第二声）与 yǐ（第三声）声调不同，cì（第四声）与 cǐ（第三声）声调不同，意思是“一次”。", "依次": "yī（第一声）与 yǐ（第三声）声调不同，cì（第四声）与 cǐ 声调不同，意思是“依次”。", "亿次": "yì（第四声）与 yǐ（第三声）声调不同，cì（第四声）与 cǐ（第三声）声调不同，意思是“亿次”。", "依此": "yī（第一声）与 yǐ（第三声）只差第一音节声调，cǐ 相同，意思是“依此”。"}, "sentence_index": null, "correct_answer": "以此"}, "level_3": {"options": [{"text": "以此", "is_correct": true, "explanation": "以此：连词，表示拿前面的规定作依据，与“员工以此为准”相符。"}, {"text": "所以", "is_correct": false, "explanation": "语义：“所以”引出结果，“员工所以为准”没有可推出的结果，句意不通。"}, {"text": "而且", "is_correct": false, "explanation": "搭配：“而且”要连接并列成分，“员工”后面没有可以并列的内容。"}, {"text": "否则", "is_correct": false, "explanation": "语义：“否则”引出相反的条件，“员工否则为准”不成立。"}], "explanations": {"以此": "以此：连词，表示拿前面的规定作依据，与“员工以此为准”相符。", "所以": "语义：“所以”引出结果，“员工所以为准”没有可推出的结果，句意不通。", "而且": "搭配：“而且”要连接并列成分，“员工”后面没有可以并列的内容。", "否则": "语义：“否则”引出相反的条件，“员工否则为准”不成立。"}, "sentence_index": 0, "correct_answer": "以此"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天气突然变冷，以此我们多穿了衣服。", "explanation": "这里应该用〈因此〉。以此表示凭借或依据，不表示“多穿衣服”是“变冷”的结果。"}, {"text": "他以此很快地跑步。", "explanation": "这里应该用〈因此〉。以此只能引出凭借或依据，不表示“跑步很快”这种性状，也不修饰副词“很快地”。"}, {"text": "老师走进教室，以此同学们都站起来了。", "explanation": "这里应该用〈于是〉。以此后面不能直接接主语“同学们”，引出后续动作要用〈于是〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02bbc78d-1e95-4345-8942-46b25251613e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94898, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "以此", "is_correct": true, "explanation": "本词：连词，用这个作为凭借或依据，如“以此为凭”。"}, {"text": "以死", "is_correct": false, "explanation": "sǐ（第三声）与 cǐ（第三声）只差声母（s 与 c），意思是“以死”。"}, {"text": "以次", "is_correct": false, "explanation": "cì（第四声）与 cǐ（第三声）只差声调，意思是“按次序”。"}, {"text": "依次", "is_correct": false, "explanation": "yī（第一声）与 yǐ（第三声）声调不同，cì（第四声）与 cǐ（第三声）声调不同，意思是“依次”。"}], "explanations": {"以此": "本词：连词，用这个作为凭借或依据，如“以此为凭”。", "以死": "sǐ（第三声）与 cǐ（第三声）只差声母（s 与 c），意思是“以死”。", "以次": "cì（第四声）与 cǐ（第三声）只差声调，意思是“按次序”。", "依次": "yī（第一声）与 yǐ（第三声）声调不同，cì（第四声）与 cǐ（第三声）声调不同，意思是“依次”。"}, "sentence_index": null, "correct_answer": "以此"}, "level_3": {"options": [{"text": "以此", "is_correct": true, "explanation": "以此：连词，表示拿前面的内容作依据，与“请你……为依据”相符。"}, {"text": "以免", "is_correct": false, "explanation": "语义：“以免”表示避免某种后果，与“为依据”的凭借义不符。"}, {"text": "况且", "is_correct": false, "explanation": "搭配：“况且”要接在已成立的理由之后作补充，句首“请你”后面没有这样的理由。"}, {"text": "不料", "is_correct": false, "explanation": "语义：“不料”表示出乎意料，与“请你……为依据”的指令语气矛盾。"}], "explanations": {"以此": "以此：连词，表示拿前面的内容作依据，与“请你……为依据”相符。", "以免": "语义：“以免”表示避免某种后果，与“为依据”的凭借义不符。", "况且": "搭配：“况且”要接在已成立的理由之后作补充，句首“请你”后面没有这样的理由。", "不料": "语义：“不料”表示出乎意料，与“请你……为依据”的指令语气矛盾。"}, "sentence_index": 6, "correct_answer": "以此"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他没有复习，以此考得不好。", "explanation": "这里应该用〈所以〉。以此表示凭借或依据，不表示因果上的结果。"}, {"text": "外面下大雨，以此比赛取消了。", "explanation": "这里应该用〈因此〉。以此表示凭借或依据，不表示因果上的结果。"}, {"text": "他很有礼貌，以此的人都很喜欢他。", "explanation": "这里应该用〈这样〉。以此不能修饰名词“人”，指代性修饰要用〈这样〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02bbc78d-1e95-4345-8942-46b25251613e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94898, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "医生给出了诊断，病人以此是依据选药。", "corrected_sentence": "医生给出了诊断，病人以此为依据选药。", "error_description": "错误形式：“以此是依据”。正确形式：“以此为依据”。原因：“以此为依据”是固定搭配，“为”不能换成“是”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02bbc78d-1e95-4345-8942-46b25251613e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94898, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一切以此准，大家照做。", "corrected_sentence": "一切以此为准，大家照做。", "error_description": "错误形式：“以此准”。正确形式：“以此为准”。原因：“以此为准”中的“为”不能省略，省略后句子不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02bbc78d-1e95-4345-8942-46b25251613e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
