INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94899, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "企业家是开大公司做生意的人。", "primary_collocate": null, "pronunciation": "qǐ yè jiā", "ipa": "tɕʰi˨˩˦ je˥˩ tɕja˥", "syllable_count": 3, "sentences": [{"text": "他开了一家大公司，是有名的企业家。", "target_word": "企业家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位企业家每年都要见很多客人。", "target_word": "企业家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个企业家的公司有两千个工人。", "target_word": "企业家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "企业家常常很忙，没有时间休息。", "target_word": "企业家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的爸爸想当一个企业家。", "target_word": "企业家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位企业家请我们去他的公司参观。", "target_word": "企业家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就想做企业家，所以努力工作。", "target_word": "企业家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上有一个企业家的故事，很有意思。", "target_word": "企业家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市有很多年轻的企业家。", "target_word": "企业家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位企业家把新产品卖到了很多国家。", "target_word": "企业家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "企业家精神", "label": "复合"}], "register": "中性", "sense_fingerprint": "开大公司做生意的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8a6e1b4-4957-4aa2-bef8-2e14d4c5083b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94899, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "学生", "is_correct": false, "explanation": "语义：学生不能开办大公司，与“开了一家大公司”矛盾。"}, {"text": "企业家", "is_correct": true, "explanation": "开办、经营大公司的人就是企业家，与“开了一家大公司”相符。"}, {"text": "农民", "is_correct": false, "explanation": "语义：农民一般不经营大公司，与前半句“开了一家大公司”不符。"}, {"text": "工人", "is_correct": false, "explanation": "搭配：“开了一家大公司”说明他是经营者，“工人”与此搭配不上。"}], "explanations": {"学生": "语义：学生不能开办大公司，与“开了一家大公司”矛盾。", "企业家": "开办、经营大公司的人就是企业家，与“开了一家大公司”相符。", "农民": "语义：农民一般不经营大公司，与前半句“开了一家大公司”不符。", "工人": "搭配：“开了一家大公司”说明他是经营者，“工人”与此搭配不上。"}, "sentence_index": 0, "correct_answer": "企业家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的邻居是一只企业家，每天都很忙。", "explanation": "这里应该用〈位〉。企业家指人，量词要用“位”，“只”多用于动物，不能用来数人。"}, {"text": "这家企业家在城里很有名，有很多工人。", "explanation": "量词“家”多用于公司、商店等机构，这里误用于指人的“企业家”，应改用量词“位”。"}, {"text": "我父亲在那家企业家工作了十年。", "explanation": "这里应该用〈公司〉。“在……工作”的地点要用公司、企业这类机构，“企业家”指人，不能作工作场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e402e0-dd95-4f05-86c6-0c1f5bc6d908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94899, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小孩", "is_correct": false, "explanation": "语义：小孩是年龄阶段，不是人可以“想做”的身份，与句意不符。"}, {"text": "病人", "is_correct": false, "explanation": "语义：“病人”是生病的人，不是职业，与“努力工作”的语境矛盾。"}, {"text": "企业家", "is_correct": true, "explanation": "“想做企业家”指想成为经营企业的人，与“努力工作”相符。"}, {"text": "房子", "is_correct": false, "explanation": "语义：“想做……”此处指成为某种身份，“房子”不是身份，句意不通。"}], "explanations": {"小孩": "语义：小孩是年龄阶段，不是人可以“想做”的身份，与句意不符。", "病人": "语义：“病人”是生病的人，不是职业，与“努力工作”的语境矛盾。", "企业家": "“想做企业家”指想成为经营企业的人，与“努力工作”相符。", "房子": "语义：“想做……”此处指成为某种身份，“房子”不是身份，句意不通。"}, "sentence_index": 6, "correct_answer": "企业家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "街角那位企业家每天早上五点就出来卖煎饼。", "explanation": "这里应该用〈小商贩〉。企业家指开大公司、做大生意的人，在街角卖煎饼的人规模不符，要用“小商贩”。"}, {"text": "他大学毕业后就创办了一位企业家。", "explanation": "这里应该用〈公司〉。“创办”的对象是公司这类组织，不能创办一个人。"}, {"text": "那位企业家每天骑电动车送外卖，一个月只挣两千块。", "explanation": "这里应该用〈外卖员〉。企业家指开大公司做生意的人，送外卖的人规模不符，要用“外卖员”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e402e0-dd95-4f05-86c6-0c1f5bc6d908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94899, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我认识一只企业家，他开了很多工厂。", "corrected_sentence": "我认识一位企业家，他开了很多工厂。", "error_description": "量词错误：指人的“企业家”应用量词“位”，不能用“只”（“只”多用于动物）。应改为“一位企业家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e402e0-dd95-4f05-86c6-0c1f5bc6d908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94899, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那条企业家的公司有两千个工人。", "corrected_sentence": "那位企业家的公司有两千个工人。", "error_description": "量词错误：“企业家”指人，量词不能用“条”（“条”多用于长条形的东西），应改为“位”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e402e0-dd95-4f05-86c6-0c1f5bc6d908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
