INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94901, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '285ed9d0-33bc-43e9-8b33-d3745b24d339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94901, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "保卫是保护好，不让坏人来抢。", "primary_collocate": null, "pronunciation": "bǎo wèi", "ipa": "pɑu˨˩˦ wei˥˩", "syllable_count": 2, "sentences": [{"text": "狗晚上保卫着我们的院子。", "target_word": "保卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村民们拿着棍子保卫自己的粮食。", "target_word": "保卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战士们日夜保卫着这座城市。", "target_word": "保卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几个保安保卫着银行的大门。", "target_word": "保卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坏人来抢钱，店主拼命保卫自己的店。", "target_word": "保卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们保卫了村子，坏人都跑了。", "target_word": "保卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只大狗是来保卫房子的。", "target_word": "保卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌人来了，大家一起保卫自己的家。", "target_word": "保卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了保卫家人，爸爸站在门口。", "target_word": "保卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上有人保卫仓库，小偷不敢来。", "target_word": "保卫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "保卫了", "label": "完成体"}, {"form": "保卫着", "label": "持续体"}, {"form": "保卫过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "守住自己的东西或家人，不让坏人抢走", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '702d0700-d623-41b2-b926-c6455e91f03f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94901, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "保卫", "is_correct": true, "explanation": "保卫指守住自己的东西不让坏人抢走，狗守院子正符合语境。"}, {"text": "修理", "is_correct": false, "explanation": "语义：狗不能修理院子，句子不成立。"}, {"text": "咬", "is_correct": false, "explanation": "搭配：咬多用于人、食物或物体，不说咬院子。"}, {"text": "种", "is_correct": false, "explanation": "语义：种是种植的动作，狗晚上种院子说不通。"}], "explanations": {"保卫": "保卫指守住自己的东西不让坏人抢走，狗守院子正符合语境。", "修理": "语义：狗不能修理院子，句子不成立。", "咬": "搭配：咬多用于人、食物或物体，不说咬院子。", "种": "语义：种是种植的动作，狗晚上种院子说不通。"}, "sentence_index": 0, "correct_answer": "保卫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "门将保卫了对手的进球。", "explanation": "这里应该用〈阻止〉。保卫是守住自己的东西不让坏人来抢，阻止对手进球不能用保卫。"}, {"text": "村民们保卫着小偷的抢夺。", "explanation": "这里应该用〈抵抗〉。保卫的对象是自己的东西，不能用来指小偷的抢夺。"}, {"text": "警察保卫了歹徒的逃跑。", "explanation": "这里应该用〈阻拦〉。保卫是守护自己或他人的东西，不能用来指阻止歹徒逃跑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '285ed9d0-33bc-43e9-8b33-d3745b24d339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94901, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "保卫", "is_correct": true, "explanation": "保卫指守住房子不让坏人进入，符合“大狗是来……的”的用途。"}, {"text": "烧", "is_correct": false, "explanation": "语义：烧是焚毁房屋，与“大狗是来……的”的目的相反。"}, {"text": "设计", "is_correct": false, "explanation": "语义：设计是绘制图纸的工作，大狗不能设计房子。"}, {"text": "粉刷", "is_correct": false, "explanation": "语义：粉刷是给墙面涂漆的工作，大狗来做的是看守，与“大狗是来……的”的用途不符。"}], "explanations": {"保卫": "保卫指守住房子不让坏人进入，符合“大狗是来……的”的用途。", "烧": "语义：烧是焚毁房屋，与“大狗是来……的”的目的相反。", "设计": "语义：设计是绘制图纸的工作，大狗不能设计房子。", "粉刷": "语义：粉刷是给墙面涂漆的工作，大狗来做的是看守，与“大狗是来……的”的用途不符。"}, "sentence_index": 6, "correct_answer": "保卫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "风保卫了桌上的蜡烛。", "explanation": "这里应该用〈吹灭〉。保卫是守住东西不让坏人抢走，风吹灭蜡烛是破坏，不能用保卫。"}, {"text": "大火保卫了那座房子。", "explanation": "这里应该用〈烧毁〉。保卫是保护好不让坏人来抢，大火烧毁房子是破坏，不能用保卫。"}, {"text": "学生们保卫了考试。", "explanation": "这里应该用〈参加〉。保卫的对象是东西或人，考试是活动，不能说保卫考试。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '285ed9d0-33bc-43e9-8b33-d3745b24d339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94901, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爸爸拼命着保卫自己的房子。", "corrected_sentence": "爸爸拼命保卫自己的房子。", "error_description": "错误：“着”放在了动词“保卫”前面；“着”应紧跟动词之后表示持续，此句语境不需要“着”，去掉即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '285ed9d0-33bc-43e9-8b33-d3745b24d339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94901, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只狗每晚都在保卫了我们的家。", "corrected_sentence": "这只狗每晚都在保卫我们的家。", "error_description": "错误：“在”与“了”不能同用；表示正在进行的动作用“在”，不能再加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '285ed9d0-33bc-43e9-8b33-d3745b24d339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
