INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94902, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '285ed9d0-33bc-43e9-8b33-d3745b24d339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94902, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "保护并使其不受侵犯。", "primary_collocate": null, "pronunciation": "bǎo wèi", "ipa": "pɑu˨˩˦ wei˥˩", "syllable_count": 2, "sentences": [{"text": "战士们保卫着祖国的边境。", "target_word": "保卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要保卫自己的国家。", "target_word": "保卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们为保卫和平而努力工作。", "target_word": "保卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵们保卫了这座城市。", "target_word": "保卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了保卫家乡，他参了军。", "target_word": "保卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人说，保卫祖国是每个人的责任。", "target_word": "保卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用生命保卫了自己的土地。", "target_word": "保卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家需要年轻人来保卫。", "target_word": "保卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战士们把保卫边疆当作最大的事。", "target_word": "保卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直保卫着这个国家的安全。", "target_word": "保卫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "保卫了", "label": "完成体"}, {"form": "保卫着", "label": "持续体"}, {"form": "保卫过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "保护国家、家乡、和平等不受侵犯", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '702d0700-d623-41b2-b926-c6455e91f03f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94902, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "保卫", "is_correct": true, "explanation": "保卫指保护国家不受侵犯，与“祖国的边境”搭配，“着”表示持续。"}, {"text": "修理", "is_correct": false, "explanation": "语义：修理针对器物或设备，不能用来指守卫边境。"}, {"text": "吃", "is_correct": false, "explanation": "语义：吃是进食动作，与边境无关，句子不成立。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：擦用于擦拭物体表面，不说擦祖国的边境。"}], "explanations": {"保卫": "保卫指保护国家不受侵犯，与“祖国的边境”搭配，“着”表示持续。", "修理": "语义：修理针对器物或设备，不能用来指守卫边境。", "吃": "语义：吃是进食动作，与边境无关，句子不成立。", "擦": "搭配：擦用于擦拭物体表面，不说擦祖国的边境。"}, "sentence_index": 0, "correct_answer": "保卫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "球队在下半场保卫了对手的进球。", "explanation": "这里应该用〈阻止〉。保卫的对象是己方要守护的东西，对手的进球是要阻止的，不能用保卫。"}, {"text": "战士们奋力保卫敌人的进攻。", "explanation": "这里应该用〈抵抗〉。保卫的对象是自己的国家或土地，不能用来指敌人的进攻。"}, {"text": "大坝保卫了洪水。", "explanation": "这里应该用〈阻挡〉。保卫的对象是需要守护的事物，大坝是阻挡洪水，不能说保卫洪水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '285ed9d0-33bc-43e9-8b33-d3745b24d339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94902, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "保卫", "is_correct": true, "explanation": "保卫指用力量守护不受侵犯，与“用生命”“自己的土地”相符。"}, {"text": "出售", "is_correct": false, "explanation": "语义：出售是卖掉，与“用生命”守护土地的意思相反。"}, {"text": "测量", "is_correct": false, "explanation": "语义：测量是量度距离和面积，用生命去测量土地说不通。"}, {"text": "翻修", "is_correct": false, "explanation": "搭配：翻修用于房屋、设施，不说翻修土地。"}], "explanations": {"保卫": "保卫指用力量守护不受侵犯，与“用生命”“自己的土地”相符。", "出售": "语义：出售是卖掉，与“用生命”守护土地的意思相反。", "测量": "语义：测量是量度距离和面积，用生命去测量土地说不通。", "翻修": "搭配：翻修用于房屋、设施，不说翻修土地。"}, "sentence_index": 6, "correct_answer": "保卫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "台风保卫了庄稼。", "explanation": "这里应该用〈毁坏〉。保卫是保护不受侵犯，台风毁坏庄稼是破坏，不能用保卫。"}, {"text": "坏人保卫了公园里的花草。", "explanation": "这里应该用〈破坏〉。保卫是保护使其不受侵犯，坏人对花草的行为是破坏，不能用保卫。"}, {"text": "敌人保卫了我们的边境。", "explanation": "这里应该用〈入侵〉。保卫的是己方要守护的国土，敌人不能保卫我方的边境。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '285ed9d0-33bc-43e9-8b33-d3745b24d339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94902, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们了保卫自己的家园。", "corrected_sentence": "我们保卫自己的家园。", "error_description": "错误：“了”放在了动词“保卫”前面；“了”应放在动词后面表示完成，此句不需要“了”，去掉即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '285ed9d0-33bc-43e9-8b33-d3745b24d339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94902, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们一直在保卫了这片边境。", "corrected_sentence": "他们一直在保卫这片边境。", "error_description": "错误：“一直在”表示动作正在进行，“保卫”后面不能再加表示完成的“了”。去掉“了”，应为“一直在保卫这片边境”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '285ed9d0-33bc-43e9-8b33-d3745b24d339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
