INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94903, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "公约是很多国家说好大家都要遵守的话。", "primary_collocate": null, "pronunciation": "gōng yuē", "ipa": "kʊŋ˥ ɥe˥", "syllable_count": 2, "sentences": [{"text": "很多国家都签了这个公约。", "target_word": "公约", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公约里写着大家要做的事。", "target_word": "公约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们都要遵守公约。", "target_word": "公约", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这份公约有二十个国家参加。", "target_word": "公约", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们在会上读了公约。", "target_word": "公约", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公约规定，不能把垃圾倒进海里。", "target_word": "公约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有的国家没有遵守公约。", "target_word": "公约", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个公约是为了保护海洋。", "target_word": "公约", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "各国代表在公约上签了字。", "target_word": "公约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把公约的内容讲给我们听。", "target_word": "公约", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}, {"form": "国际公约", "label": "复合"}, {"form": "公約", "label": "繁体"}], "register": "书面", "sense_fingerprint": "很多国家说好要一起遵守的约定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '109ed30c-9583-414f-9809-33e9e60b7ef0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94903, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公约", "is_correct": true, "explanation": "正确：公约是很多国家说好要遵守的约定，可以签。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是学生的功课，国家之间不会签署。"}, {"text": "地图", "is_correct": false, "explanation": "搭配：“签”接的是协议、条约一类文件，不能说签地图。"}, {"text": "菜单", "is_correct": false, "explanation": "语义：菜单是饭店的点菜单，与国家之间签的文件无关。"}], "explanations": {"公约": "正确：公约是很多国家说好要遵守的约定，可以签。", "作业": "语义：作业是学生的功课，国家之间不会签署。", "地图": "搭配：“签”接的是协议、条约一类文件，不能说签地图。", "菜单": "语义：菜单是饭店的点菜单，与国家之间签的文件无关。"}, "sentence_index": 0, "correct_answer": "公约"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两家公司签了一份公约。", "explanation": "这里应该用〈协议〉。公约指很多国家共同遵守的约定，两家公司之间的约定用协议。"}, {"text": "这个公约可以用来计算圆的面积。", "explanation": "这里应该用〈公式〉。公约指多国共同遵守的约定，计算用的算式要用公式。"}, {"text": "学校门口贴着一份公约，通知明天放假。", "explanation": "这里应该用〈通知〉。公约指共同遵守的约定，发布放假消息要用通知。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dedbc29c-746d-487f-b362-bdc472522b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94903, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公约", "is_correct": true, "explanation": "正确：公约是国家之间的约定，可以遵守。"}, {"text": "钢琴", "is_correct": false, "explanation": "搭配：“遵守”接的是规则、约定，不能说遵守钢琴。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是可以被遵守的规定，与句意不合。"}, {"text": "镜子", "is_correct": false, "explanation": "语义：镜子不是可以遵守的东西，与“有的国家没有遵守”不符。"}], "explanations": {"公约": "正确：公约是国家之间的约定，可以遵守。", "钢琴": "搭配：“遵守”接的是规则、约定，不能说遵守钢琴。", "天气": "语义：天气不是可以被遵守的规定，与句意不合。", "镜子": "语义：镜子不是可以遵守的东西，与“有的国家没有遵守”不符。"}, "sentence_index": 6, "correct_answer": "公约"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "餐厅门口挂着一份公约，列着今天的菜名。", "explanation": "这里应该用〈菜单〉。公约是共同遵守的约定，列出菜名的要用菜单。"}, {"text": "各国领导人发表了一份公约。", "explanation": "这里应该用〈宣言〉。公约需要签署、遵守，发表的是宣言、声明。"}, {"text": "他向妈妈做出了公约。", "explanation": "这里应该用〈承诺〉。公约是多方共同订立的约定，对家人的保证用承诺。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dedbc29c-746d-487f-b362-bdc472522b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94903, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们都要遵守三只公约。", "corrected_sentence": "我们都要遵守三项公约。", "error_description": "“公约”的量词应用“项”，不能用“只”。正确的说法是“三项公约”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dedbc29c-746d-487f-b362-bdc472522b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94903, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们都遵守公约们。", "corrected_sentence": "他们都遵守公约。", "error_description": "“们”只用于指人的名词，不能加在“公约”后面。正确的说法是“他们都遵守公约”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dedbc29c-746d-487f-b362-bdc472522b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
