INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94904, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dedbc29c-746d-487f-b362-bdc472522b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94904, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "多国或多方共同订立、共同遵守的条约或规定。", "primary_collocate": null, "pronunciation": "gōng yuē", "ipa": "kʊŋ˥ ɥe˥", "syllable_count": 2, "sentences": [{"text": "中国已经加入了这项公约。", "target_word": "公约", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公约自下月起对各国生效。", "target_word": "公约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "违反公约的国家会受到批评。", "target_word": "公约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一项保护儿童的国际公约。", "target_word": "公约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各方共同订立了新的公约。", "target_word": "公约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公约的内容要写得清楚。", "target_word": "公约", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公约规定了每个国家应尽的责任。", "target_word": "公约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他研究过国际公约的历史。", "target_word": "公约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十多个国家在会上通过了公约。", "target_word": "公约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都要按公约办事。", "target_word": "公约", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}, {"form": "国际公约", "label": "复合"}, {"form": "公約", "label": "繁体"}], "register": "书面", "sense_fingerprint": "多国或多方共同订立并遵守的条约或规定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '109ed30c-9583-414f-9809-33e9e60b7ef0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94904, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公约", "is_correct": true, "explanation": "正确：公约是条约或规定，可以加入。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是可以加入的条约或规定。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不是可以加入的条约或规定。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语义：“玩意儿”指东西、物件，不是可以加入的条约，也不能用“项”计量。"}], "explanations": {"公约": "正确：公约是条约或规定，可以加入。", "天气": "语义：天气不是可以加入的条约或规定。", "手机": "语义：手机不是可以加入的条约或规定。", "玩意儿": "语义：“玩意儿”指东西、物件，不是可以加入的条约，也不能用“项”计量。"}, "sentence_index": 0, "correct_answer": "公约"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "政府发表了一份公约。", "explanation": "这里应该用〈声明〉。公约需要签署、遵守，发表的是声明。"}, {"text": "这个公约可以用来解一元二次方程。", "explanation": "这里应该用〈公式〉。公约指多国或多方共同遵守的约定，解方程要用的是公式。"}, {"text": "这份公约写着，他欠我三百元。", "explanation": "这里应该用〈欠条〉。公约指多方共同遵守的约定，写明欠钱的要用欠条。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dedbc29c-746d-487f-b362-bdc472522b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94904, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公约", "is_correct": true, "explanation": "正确：公约是国家之间的书面约定，可以规定责任。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶不能规定国家应尽的责任。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕不能规定国家应尽的责任。"}, {"text": "饭碗", "is_correct": false, "explanation": "语义：饭碗是吃饭用的碗，不能规定国家应尽的责任。"}], "explanations": {"公约": "正确：公约是国家之间的书面约定，可以规定责任。", "花瓶": "语义：花瓶不能规定国家应尽的责任。", "蛋糕": "语义：蛋糕不能规定国家应尽的责任。", "饭碗": "语义：饭碗是吃饭用的碗，不能规定国家应尽的责任。"}, "sentence_index": 6, "correct_answer": "公约"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "饭店的墙上贴着一份公约，写着今天有什么菜。", "explanation": "这里应该用〈菜单〉。公约是共同遵守的约定，列出菜品的要用菜单。"}, {"text": "我和房东签了一份公约。", "explanation": "这里应该用〈协议〉。公约指多方共同订立的约定，我和房东之间的约定用协议。"}, {"text": "他向朋友许下了公约。", "explanation": "这里应该用〈诺言〉。公约需要多方共同订立，个人之间的许诺用诺言。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dedbc29c-746d-487f-b362-bdc472522b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94904, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "中国签了两只公约。", "corrected_sentence": "中国签了两项公约。", "error_description": "“公约”的量词应用“项”，不能用“只”。正确的说法是“两项公约”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dedbc29c-746d-487f-b362-bdc472522b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94904, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "各国都遵守公约们。", "corrected_sentence": "各国都遵守公约。", "error_description": "“们”只用于指人的名词，不能加在“公约”后面。正确的说法是“各国都遵守公约”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dedbc29c-746d-487f-b362-bdc472522b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
