INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94905, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02bbc78d-1e95-4345-8942-46b25251613e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94905, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "再一次是又做一回。", "primary_collocate": null, "pronunciation": "zài yí cì", "ipa": "tsai˥˩ i˧˥ tsʰɨ˥˩", "syllable_count": 3, "sentences": [{"text": "他再一次打开了门。", "target_word": "再一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想再一次试试这道题。", "target_word": "再一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她再一次站在了老家门口。", "target_word": "再一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这段话我没听懂，能再一次解释给我听吗？", "target_word": "再一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师再一次提醒大家带书。", "target_word": "再一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们再一次见面了，都很高兴。", "target_word": "再一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想再一次去那个公园玩。", "target_word": "再一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈再一次检查了一下门窗。", "target_word": "再一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他再一次拿起了笔。", "target_word": "再一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店我还想再一次来尝尝。", "target_word": "再一次", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "副词，用在动词前，表示把同一个动作再做一回", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8674e63a-393f-4d84-bf8a-ca1ff6fc6749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94905, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示动作进行中，与“打开了门”这一已完成的动作冲突。"}, {"text": "再一次", "is_correct": true, "explanation": "“再一次”表示又做一回，与句意相符。"}, {"text": "同时", "is_correct": false, "explanation": "语义：“同时”要求两件事并列发生，句中只有“打开门”一个动作。"}, {"text": "从不", "is_correct": false, "explanation": "语义：“从不”表示从未发生，与“打开了门”这一已发生的动作矛盾。"}], "explanations": {"正在": "体貌：“正在”表示动作进行中，与“打开了门”这一已完成的动作冲突。", "再一次": "“再一次”表示又做一回，与句意相符。", "同时": "语义：“同时”要求两件事并列发生，句中只有“打开门”一个动作。", "从不": "语义：“从不”表示从未发生，与“打开了门”这一已发生的动作矛盾。"}, "sentence_index": 0, "correct_answer": "再一次"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我第一次来这座城市，就想再一次逛逛这条老街。", "explanation": "这里把“再一次”误用成了“首次”的意思。“再一次”要求此前已经做过同样的动作，而句中说这是第一次来这座城市，二者冲突。"}, {"text": "他这辈子从未骑过马，今天却再一次骑上了马。", "explanation": "这里把“再一次”误用成了“头一回”的意思。“再一次”要求此前已经骑过马，而句中说他这辈子从未骑过。"}, {"text": "这是我们公司的新产品，我们准备再一次推出它。", "explanation": "这里把“再一次”误用成了“首次”的意思。新产品是首次推出，“再一次”预设此前已经推出过，不能用于此处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02bbc78d-1e95-4345-8942-46b25251613e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94905, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "已经", "is_correct": false, "explanation": "体貌：“已经”表示动作已经完成，与“想去”所表达的未来意愿冲突。"}, {"text": "再一次", "is_correct": true, "explanation": "“再一次”表示又做一回，与“我想……去那个公园玩”的语境相符。"}, {"text": "刚刚", "is_correct": false, "explanation": "体貌：“刚刚”指过去不久发生的事，与“想去”的将来意愿冲突。"}, {"text": "竟然", "is_correct": false, "explanation": "语义：“竟然”表示出乎意料，与“想去”这种主动的意愿不合。"}], "explanations": {"已经": "体貌：“已经”表示动作已经完成，与“想去”所表达的未来意愿冲突。", "再一次": "“再一次”表示又做一回，与“我想……去那个公园玩”的语境相符。", "刚刚": "体貌：“刚刚”指过去不久发生的事，与“想去”的将来意愿冲突。", "竟然": "语义：“竟然”表示出乎意料，与“想去”这种主动的意愿不合。"}, "sentence_index": 6, "correct_answer": "再一次"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨天去了游泳池，今天再一次画了画。", "explanation": "这里把“再一次”误用成了“又另做一件事”的意思。“再一次”只能表示重复同一个动作，不能用来连接游泳与画画这两件不同的事。"}, {"text": "他昨天吃了饭，今天再一次看了书。", "explanation": "这里把“再一次”误用成了“又另做一件事”的意思。“再一次”要求重复同一个动作，吃饭与看书不是同一个动作。"}, {"text": "她昨天唱了歌，今天再一次写了作业。", "explanation": "这里把“再一次”误用成了“又另做一件事”的意思。“再一次”只能重复前面的同一动作，唱歌与写作业属于不同的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02bbc78d-1e95-4345-8942-46b25251613e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94905, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我妈妈再一次的打开了那扇窗。", "corrected_sentence": "我妈妈再一次打开了那扇窗。", "error_description": "“再一次”是副词，后面不能加“的”，应直接放在动词“打开”之前。错误形式：再一次的打开了那扇窗；正确形式：再一次打开了那扇窗。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02bbc78d-1e95-4345-8942-46b25251613e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94905, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那本小说太好看了，我想很再一次读它。", "corrected_sentence": "那本小说太好看了，我想再一次读它。", "error_description": "“很”是程度副词，不能修饰“再一次”。错误形式：很再一次读它；正确形式：再一次读它。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02bbc78d-1e95-4345-8942-46b25251613e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
