INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94906, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "又一次，表示重复。", "primary_collocate": null, "pronunciation": "zài yí cì", "ipa": "tsai˥˩ i˧˥ tsʰɨ˥˩", "syllable_count": 3, "sentences": [{"text": "昨天他再一次迟到了。", "target_word": "再一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个队再一次赢得了比赛。", "target_word": "再一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机再一次坏了，真让人生气。", "target_word": "再一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他再一次忘了带钥匙。", "target_word": "再一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨再一次下了起来。", "target_word": "再一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她再一次考了第一名。", "target_word": "再一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月公司再一次提高了价格。", "target_word": "再一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟再一次把杯子打破了。", "target_word": "再一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气再一次变冷了。", "target_word": "再一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他再一次对我说了谢谢。", "target_word": "再一次", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "副词，表示同样的事情又发生了一次，多指已经发生的重复", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8674e63a-393f-4d84-bf8a-ca1ff6fc6749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94906, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "从不", "is_correct": false, "explanation": "语义：“从不”表示从未发生，与“昨天迟到了”这一已发生的事实矛盾。"}, {"text": "再一次", "is_correct": true, "explanation": "“再一次”表示同样的事情又发生了一次，与句意相符。"}, {"text": "将要", "is_correct": false, "explanation": "时间：“将要”表示动作即将发生，与“昨天……迟到了”这一已发生的事实冲突。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示进行中，与“迟到了”的完成态冲突。"}], "explanations": {"从不": "语义：“从不”表示从未发生，与“昨天迟到了”这一已发生的事实矛盾。", "再一次": "“再一次”表示同样的事情又发生了一次，与句意相符。", "将要": "时间：“将要”表示动作即将发生，与“昨天……迟到了”这一已发生的事实冲突。", "正在": "体貌：“正在”表示进行中，与“迟到了”的完成态冲突。"}, "sentence_index": 0, "correct_answer": "再一次"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这是他第一次忘带钥匙，可他这次再一次忘了带钥匙。", "explanation": "这里把“再一次”误用成了“首次”的意思。“再一次”要求此前已经忘过同样的事，而句中说这是他第一次忘带钥匙。"}, {"text": "这是我们第一次光顾这家餐厅，我们却再一次来到了这里。", "explanation": "这里把“再一次”误用成了“头一回”的意思。“再一次”要求此前已经来过，而句中说这是第一次光顾，二者冲突。"}, {"text": "他这辈子从未忘带过钥匙，昨天却再一次忘了带。", "explanation": "这里把“再一次”误用成了“头一回”的意思。“再一次”要求此前已经发生过同样的事，而句中说他从未忘带过钥匙。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02bbc78d-1e95-4345-8942-46b25251613e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94906, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示进行中，与“提高了”的完成态冲突。"}, {"text": "再一次", "is_correct": true, "explanation": "“再一次”表示又发生了一次，与“提高了价格”的语境相符。"}, {"text": "再也", "is_correct": false, "explanation": "搭配：“再也”须与否定词“不”搭配，不能直接修饰“提高了”。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”须与否定词连用，表示一向不曾，不能用于已经发生的提价。"}], "explanations": {"正在": "体貌：“正在”表示进行中，与“提高了”的完成态冲突。", "再一次": "“再一次”表示又发生了一次，与“提高了价格”的语境相符。", "再也": "搭配：“再也”须与否定词“不”搭配，不能直接修饰“提高了”。", "从来": "搭配：“从来”须与否定词连用，表示一向不曾，不能用于已经发生的提价。"}, "sentence_index": 6, "correct_answer": "再一次"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天都再一次迟到。", "explanation": "这里把“再一次”误用成了“反复多次”的意思。“再一次”只指又发生一次，不能表示反复发生多次。"}, {"text": "他常常再一次忘带钥匙。", "explanation": "这里把“再一次”误用成了“经常性发生”的意思。“再一次”只指又发生一次，不能表示经常性的动作。"}, {"text": "他年年都再一次拿第一名。", "explanation": "这里把“再一次”误用成了“每年如此”的意思。“再一次”只指又发生一次，不能用来表示年年重复。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02bbc78d-1e95-4345-8942-46b25251613e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94906, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个冬天他再再一次感冒了。", "corrected_sentence": "这个冬天他再一次感冒了。", "error_description": "重复冗余：“再一次”前多加了一个“再”，“再”与“再一次”重复表义，应去掉多余的“再”。错误形式：再再一次感冒了；正确形式：再一次感冒了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02bbc78d-1e95-4345-8942-46b25251613e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94906, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她再一次的把伞忘在了地铁上。", "corrected_sentence": "她再一次把伞忘在了地铁上。", "error_description": "“再一次”是副词，后面不能加“的”，应直接修饰动词。错误形式：再一次的把伞忘在了地铁上；正确形式：再一次把伞忘在了地铁上。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02bbc78d-1e95-4345-8942-46b25251613e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
