INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94909, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "原创是自己想出来、自己做出来的。", "primary_collocate": null, "pronunciation": "yuán chuàng", "ipa": "ɥɛn˧˥ ʈʂʰuɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这是一部原创电影，不是别人的故事。", "target_word": "原创", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的节目都是原创的。", "target_word": "原创", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张图是原创的，请不要乱用。", "target_word": "原创", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "原创作品要写上作者的名字。", "target_word": "原创", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的故事是原创的，不是电影改的。", "target_word": "原创", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个网站只发原创文章。", "target_word": "原创", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她喜欢看原创小说。", "target_word": "原创", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "原创的东西比较难做。", "target_word": "原创", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问这首歌是原创还是翻唱？", "target_word": "原创", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上有很多原创视频。", "target_word": "原创", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "原创性", "label": "复合"}, {"form": "原创作品", "label": "复合"}, {"form": "原创者", "label": "复合"}], "register": "中性", "sense_fingerprint": "自己想出来、做出来的，非抄袭（属性）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '904ff82c-9949-44d4-8c88-d63d71ef0a8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94909, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "原创", "is_correct": true, "explanation": "原创指自己想出来、做出来的作品，是这个音节组合对应的词。"}, {"text": "原状", "is_correct": false, "explanation": "原状 yuánzhuàng 与原创只差送气（ch 与 zh），意思是原来的状态。"}, {"text": "原装", "is_correct": false, "explanation": "原装 yuánzhuāng 与原创的声母不同（ch 与 zh），声调也不同，意思是出厂时的原样。"}, {"text": "原唱", "is_correct": false, "explanation": "原唱 yuánchàng 与原创的第二音节少了介音 u，意思是歌曲的最初演唱者。"}], "explanations": {"原创": "原创指自己想出来、做出来的作品，是这个音节组合对应的词。", "原状": "原状 yuánzhuàng 与原创只差送气（ch 与 zh），意思是原来的状态。", "原装": "原装 yuánzhuāng 与原创的声母不同（ch 与 zh），声调也不同，意思是出厂时的原样。", "原唱": "原唱 yuánchàng 与原创的第二音节少了介音 u，意思是歌曲的最初演唱者。"}, "sentence_index": null, "correct_answer": "原创"}, "level_3": {"options": [{"text": "盗版", "is_correct": false, "explanation": "语义：盗版指未经授权复制他人作品，与「不是别人的故事」相矛盾。"}, {"text": "原创", "is_correct": true, "explanation": "原创作定语修饰电影，指不是抄来的，符合句意。"}, {"text": "假", "is_correct": false, "explanation": "搭配：「假」指伪造，一般不用来说电影的来源。"}, {"text": "仿制", "is_correct": false, "explanation": "语义：仿制指照别人的样子做，与「不是别人的故事」相矛盾。"}], "explanations": {"盗版": "语义：盗版指未经授权复制他人作品，与「不是别人的故事」相矛盾。", "原创": "原创作定语修饰电影，指不是抄来的，符合句意。", "假": "搭配：「假」指伪造，一般不用来说电影的来源。", "仿制": "语义：仿制指照别人的样子做，与「不是别人的故事」相矛盾。"}, "sentence_index": 0, "correct_answer": "原创"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家店卖的是原创的古董。", "explanation": "这里应该用〈仿制〉。古董是已经存在的老物件，原创指自己首次创作，不能用来说古董。"}, {"text": "这首歌是原创的，其实是翻唱的。", "explanation": "翻唱的歌不是自己首次创作，「原创」与「翻唱」自相矛盾。"}, {"text": "他的画都是原创的，其实是临摹的。", "explanation": "临摹是照着别人的画来画，不是自己首次创作，「原创」与之自相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80ec9804-5013-493b-b350-1068aecf33b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94909, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "透明", "is_correct": false, "explanation": "搭配：「透明」形容物体，小说不说透明。"}, {"text": "坚硬", "is_correct": false, "explanation": "搭配：「坚硬」形容物质，不用来描述小说。"}, {"text": "原创", "is_correct": true, "explanation": "原创作定语修饰小说，指作品出自作者自己，符合句意。"}, {"text": "潮湿", "is_correct": false, "explanation": "搭配：「潮湿」描写物体或环境的状态，不用来形容小说。"}], "explanations": {"透明": "搭配：「透明」形容物体，小说不说透明。", "坚硬": "搭配：「坚硬」形容物质，不用来描述小说。", "原创": "原创作定语修饰小说，指作品出自作者自己，符合句意。", "潮湿": "搭配：「潮湿」描写物体或环境的状态，不用来形容小说。"}, "sentence_index": 6, "correct_answer": "原创"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部电影是原创的，其实是翻拍的老片。", "explanation": "翻拍是重拍别人的作品，不是首次创作，「原创」与「翻拍」自相矛盾。"}, {"text": "这把椅子是原创的复制品。", "explanation": "复制品是照原件做出来的，不是首次创作，「原创」不能修饰「复制品」，二者自相矛盾。"}, {"text": "这条路是原创的，是照着别的城市抄来的。", "explanation": "照着别的城市抄来的设计不是首次创作，与「原创」自相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80ec9804-5013-493b-b350-1068aecf33b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94909, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个计划是原创地，没有抄别人。", "corrected_sentence": "这个计划是原创的，没有抄别人。", "error_description": "错误：形容词「原创」作谓语时，后面应用「的」，不能用「地」。「地」用于修饰动词，应改为「原创的」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80ec9804-5013-493b-b350-1068aecf33b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94909, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个网站上有很多原创地视频。", "corrected_sentence": "这个网站上有很多原创视频。", "error_description": "错误：形容词「原创」修饰名词时不能用「地」，「地」用于修饰动词。应去掉「地」，说「原创视频」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80ec9804-5013-493b-b350-1068aecf33b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
