INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94910, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "首次创作；独立创作而不是模仿他人。", "primary_collocate": null, "pronunciation": "yuán chuàng", "ipa": "ɥɛn˧˥ ʈʂʰuɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这首歌是我自己原创的。", "target_word": "原创", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他原创了一个很有名的故事。", "target_word": "原创", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她决定自己原创一部小说。", "target_word": "原创", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些画都是他原创的，没有模仿别人。", "target_word": "原创", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我原创过一首短歌。", "target_word": "原创", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想要原创，就要多想，多写。", "target_word": "原创", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天晚上都在家原创音乐。", "target_word": "原创", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说作文要自己原创，不能抄。", "target_word": "原创", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏是一家小公司原创的。", "target_word": "原创", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她原创的歌在网上很受欢迎。", "target_word": "原创", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "原创了", "label": "体标"}, {"form": "原创过", "label": "体标"}, {"form": "原创性", "label": "复合"}, {"form": "原创者", "label": "复合"}], "register": "中性", "sense_fingerprint": "独立首次创作，不模仿别人（动词）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '904ff82c-9949-44d4-8c88-d63d71ef0a8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94910, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "原创", "is_correct": true, "explanation": "原创指首次、独立地创作，是这个音节组合对应的词。"}, {"text": "原状", "is_correct": false, "explanation": "原状 yuánzhuàng 与原创只差送气（ch 与 zh），意思是原来的状态。"}, {"text": "原装", "is_correct": false, "explanation": "原装 yuánzhuāng 与原创的声母不同（ch 与 zh），声调也不同，意思是出厂时的原样。"}, {"text": "原唱", "is_correct": false, "explanation": "原唱 yuánchàng 与原创的第二音节少了介音 u，意思是歌曲的最初演唱者。"}], "explanations": {"原创": "原创指首次、独立地创作，是这个音节组合对应的词。", "原状": "原状 yuánzhuàng 与原创只差送气（ch 与 zh），意思是原来的状态。", "原装": "原装 yuánzhuāng 与原创的声母不同（ch 与 zh），声调也不同，意思是出厂时的原样。", "原唱": "原唱 yuánchàng 与原创的第二音节少了介音 u，意思是歌曲的最初演唱者。"}, "sentence_index": null, "correct_answer": "原创"}, "level_3": {"options": [{"text": "抄袭", "is_correct": false, "explanation": "语义：抄袭是拿别人的成果据为己有，与句中的「自己」相冲突。"}, {"text": "原创", "is_correct": true, "explanation": "原创指自己首次创作，与「自己……的」搭配，符合句意。"}, {"text": "开", "is_correct": false, "explanation": "搭配：歌曲不能被「开」，「开」不能带歌曲作宾语。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：「吃」不能带歌曲作宾语，「吃的歌」说不通。"}], "explanations": {"抄袭": "语义：抄袭是拿别人的成果据为己有，与句中的「自己」相冲突。", "原创": "原创指自己首次创作，与「自己……的」搭配，符合句意。", "开": "搭配：歌曲不能被「开」，「开」不能带歌曲作宾语。", "吃": "搭配：「吃」不能带歌曲作宾语，「吃的歌」说不通。"}, "sentence_index": 0, "correct_answer": "原创"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他原创了一家公司。", "explanation": "这里应该用〈创办〉。原创用于歌曲、文章等作品，不用来说创立公司。"}, {"text": "他原创了一首别人的诗。", "explanation": "这里应该用〈翻译〉。翻译别人的作品不是原创，原创指自己首次创作。"}, {"text": "他原创了这部名著的译本。", "explanation": "译本是把他人作品译成另一种文字，不是首次独立创作，与「原创」自相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80ec9804-5013-493b-b350-1068aecf33b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94910, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "喝", "is_correct": false, "explanation": "搭配：音乐不能被「喝」，「喝音乐」说不通。"}, {"text": "搬", "is_correct": false, "explanation": "搭配：「搬」只用于实物，音乐不能被搬。"}, {"text": "原创", "is_correct": true, "explanation": "原创指首次创作，能带「音乐」作宾语，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：「吃」不能带音乐作宾语，「吃音乐」说不通。"}], "explanations": {"喝": "搭配：音乐不能被「喝」，「喝音乐」说不通。", "搬": "搭配：「搬」只用于实物，音乐不能被搬。", "原创": "原创指首次创作，能带「音乐」作宾语，符合句意。", "吃": "搭配：「吃」不能带音乐作宾语，「吃音乐」说不通。"}, "sentence_index": 6, "correct_answer": "原创"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很会原创别人的声音。", "explanation": "这里应该用〈模仿〉。原创指首次创作，不是模仿别人，「原创别人的声音」自相矛盾。"}, {"text": "她原创了这首别人的歌。", "explanation": "这里应该用〈演唱〉。原创是创作，不能用来说演唱别人的歌。"}, {"text": "他原创了这幅古画。", "explanation": "这里应该用〈修复〉。古画是已有的作品，修复是使其恢复原样，不是原创。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80ec9804-5013-493b-b350-1068aecf33b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94910, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想很原创一部动画片。", "corrected_sentence": "我想原创一部动画片。", "error_description": "错误：在动词「原创」前加了副词「很」。「很」不能修饰动词「原创」，应删去，改为「我想原创一部动画片。」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80ec9804-5013-493b-b350-1068aecf33b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94910, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从来没原创歌过。", "corrected_sentence": "他从来没原创过歌。", "error_description": "错误：体标「过」的位置不对。「过」应紧接动词「原创」，写作「没原创过歌」，不能放在宾语「歌」的后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80ec9804-5013-493b-b350-1068aecf33b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94911, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec199dda-ed00-4312-8bc9-b9e17011411e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
