INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94911, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "同胞是同一个国家的人，像兄弟姐妹。", "primary_collocate": null, "pronunciation": "tóng bāo", "ipa": "tʰʊŋ˧˥ pau˥", "syllable_count": 2, "sentences": [{"text": "海外的同胞都很想念家乡。", "target_word": "同胞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要帮助受灾的同胞。", "target_word": "同胞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在国外遇到同胞，他很高兴。", "target_word": "同胞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同胞们一起过春节。", "target_word": "同胞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他给远方的同胞写了一封信。", "target_word": "同胞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各位同胞，大家好！", "target_word": "同胞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里住着很多海外同胞。", "target_word": "同胞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同胞有难，大家都来帮忙。", "target_word": "同胞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在机场见到了一位同胞。", "target_word": "同胞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们都是同胞，应该互相帮助。", "target_word": "同胞", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "同胞们", "label": "复数形式"}], "register": "书面", "sense_fingerprint": "同一个国家的人，彼此像兄弟姐妹", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03e574a3-d7c0-4022-bfe0-96ccccca3dcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94911, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "同胞", "is_correct": true, "explanation": "正确：“同胞”指同一个国家的人，与“海外的……都很想念家乡”的语境相符。"}, {"text": "本地人", "is_correct": false, "explanation": "语义：“本地人”指当地的居民，与“海外”的语境矛盾。"}, {"text": "敌人", "is_correct": false, "explanation": "语义：“敌人”不会想念家乡，与句意不合。"}, {"text": "对手", "is_correct": false, "explanation": "语义：“对手”指竞争的对象，不能说想念家乡，与句意不合。"}], "explanations": {"同胞": "正确：“同胞”指同一个国家的人，与“海外的……都很想念家乡”的语境相符。", "本地人": "语义：“本地人”指当地的居民，与“海外”的语境矛盾。", "敌人": "语义：“敌人”不会想念家乡，与句意不合。", "对手": "语义：“对手”指竞争的对象，不能说想念家乡，与句意不合。"}, "sentence_index": 0, "correct_answer": "同胞"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班来了一只新同胞。", "explanation": "这里应该用〈位〉。“同胞”指人，量词要用“位”或“个”，不能用动物量词“只”。"}, {"text": "我在法国遇到一位外国同胞。", "explanation": "这里应该用〈外国人〉。“同胞”指同一个国家的人，外国人不是我的同胞，所以用错。"}, {"text": "我的同胞是美国人，我是中国人。", "explanation": "这里应该用〈朋友〉。“同胞”指同一个国家的人，“我的同胞是美国人”与“我是中国人”矛盾，所以用错。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec199dda-ed00-4312-8bc9-b9e17011411e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94911, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "同胞", "is_correct": true, "explanation": "正确：“同胞”指同一个国家的人，“海外的同胞”符合句意。"}, {"text": "蔬菜", "is_correct": false, "explanation": "语义：“蔬菜”不是人，不能说住在海外。"}, {"text": "机器人", "is_correct": false, "explanation": "语义：“机器人”不能说是同一国家的人，与句意不合。"}, {"text": "树木", "is_correct": false, "explanation": "语义：“住着”后面应是居住的人，“树木”不会“住”，与句意不合。"}], "explanations": {"同胞": "正确：“同胞”指同一个国家的人，“海外的同胞”符合句意。", "蔬菜": "语义：“蔬菜”不是人，不能说住在海外。", "机器人": "语义：“机器人”不能说是同一国家的人，与句意不合。", "树木": "语义：“住着”后面应是居住的人，“树木”不会“住”，与句意不合。"}, "sentence_index": 6, "correct_answer": "同胞"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位日本游客是我的同胞。", "explanation": "这里应该用〈外国人〉。“同胞”指同一个国家的人，日本游客不是我的同胞，所以用错。"}, {"text": "我的德国朋友都是我的同胞。", "explanation": "这里应该用〈外国人〉。“同胞”指同一个国家的人，德国朋友不属于同胞，所以用错。"}, {"text": "他是一支同胞。", "explanation": "这里的量词用错了。“同胞”指人，应用“位”或“个”，不能用指物的“支”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec199dda-ed00-4312-8bc9-b9e17011411e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94911, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只同胞都很友好。", "corrected_sentence": "那些同胞都很友好。", "error_description": "错误：“那只同胞”；正确：“那些同胞”。“同胞”指人，量词应用“些”或“位”，不能用指动物的“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec199dda-ed00-4312-8bc9-b9e17011411e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94911, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是我的同胞们，我们一起长大。", "corrected_sentence": "他是我的同胞，我们一起长大。", "error_description": "错误：“同胞们”是复数形式，不能指单个的人“他”。正确：“他是我的同胞”，指一个人时不加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec199dda-ed00-4312-8bc9-b9e17011411e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
