INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94916, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "疑问代词，用于在若干人或事物中询问选择对象。", "primary_collocate": null, "pronunciation": "nǎ yí gè", "ipa": "na˨˩˦ i˧˥ kɤ˥˩", "syllable_count": 3, "sentences": [{"text": "两种手机，你想买哪一个？", "target_word": "哪一个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这四道菜里，哪一个最辣？", "target_word": "哪一个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问我们，哪一个答案是对的。", "target_word": "哪一个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红茶和绿茶，你喝哪一个？", "target_word": "哪一个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想去哪一个城市工作？", "target_word": "哪一个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班有三个女孩，你说的是哪一个？", "target_word": "哪一个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，哪一个房间是你的？", "target_word": "哪一个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几种水果，哪一个更好吃？", "target_word": "哪一个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不知道该选哪一个。", "target_word": "哪一个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哪一个学生昨天没来上课？", "target_word": "哪一个", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "哪个", "label": "口语形式"}], "register": "中性", "sense_fingerprint": "疑问代词，在若干人或事物中询问选择对象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03e574a3-d7c0-4022-bfe0-96ccccca3dcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94916, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "哪一个", "is_correct": true, "explanation": "正确：哪一个（nǎ yí gè）是疑问代词，在若干人或事物中询问选择对象。"}, {"text": "那一个", "is_correct": false, "explanation": "nà（第四声）与 nǎ（第三声）声调不同，「那一个」指示「那个」，不表示疑问。"}, {"text": "拿一个", "is_correct": false, "explanation": "ná（第二声）与 nǎ（第三声）声调不同，「拿一个」是拿取的意思。"}, {"text": "哪一课", "is_correct": false, "explanation": "kè 与 gè 声母不同（k 与 g），「哪一课」问的是哪一节课程。"}], "explanations": {"哪一个": "正确：哪一个（nǎ yí gè）是疑问代词，在若干人或事物中询问选择对象。", "那一个": "nà（第四声）与 nǎ（第三声）声调不同，「那一个」指示「那个」，不表示疑问。", "拿一个": "ná（第二声）与 nǎ（第三声）声调不同，「拿一个」是拿取的意思。", "哪一课": "kè 与 gè 声母不同（k 与 g），「哪一课」问的是哪一节课程。"}, "sentence_index": null, "correct_answer": "哪一个"}, "level_3": {"options": [{"text": "哪一个", "is_correct": true, "explanation": "正确：两种手机中选择购买，「哪一个」表示选择疑问，符合语境。"}, {"text": "谁", "is_correct": false, "explanation": "语义：「谁」问人，手机不是人，不能用于问购买的对象。"}, {"text": "哪位", "is_correct": false, "explanation": "搭配：量词「位」只用于人，不能修饰手机。"}, {"text": "他", "is_correct": false, "explanation": "语义：「他」指人，不能作为购买的对象。"}], "explanations": {"哪一个": "正确：两种手机中选择购买，「哪一个」表示选择疑问，符合语境。", "谁": "语义：「谁」问人，手机不是人，不能用于问购买的对象。", "哪位": "搭配：量词「位」只用于人，不能修饰手机。", "他": "语义：「他」指人，不能作为购买的对象。"}, "sentence_index": 0, "correct_answer": "哪一个"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的杯子里只有一杯茶，你喝哪一个？", "explanation": "这里应该用〈吗〉。只有一杯茶时，「哪一个」预设了多个选项，应改用是非问「你喝吗？」"}, {"text": "我只有一个哥哥，你说的是哪一个哥哥？", "explanation": "这里不应该用〈哪一个〉。我只有一个哥哥，没有可以选择的对象，「哪一个」预设了多个选项。"}, {"text": "这本书是哪一个写的？", "explanation": "这里应该用〈谁〉。问作者时没有给定的选择范围，不能用「哪一个」，应说「谁写的」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec199dda-ed00-4312-8bc9-b9e17011411e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94916, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "哪一个", "is_correct": true, "explanation": "正确：「请问」之后问房间的归属，「哪一个房间」中的「哪一个」表示选择疑问。"}, {"text": "我", "is_correct": false, "explanation": "语义：「我」指说话人，「我是你的」在句中不成立。"}, {"text": "它", "is_correct": false, "explanation": "搭配：「它」需指代前文的事物，此处没有指代对象。"}, {"text": "咱们", "is_correct": false, "explanation": "语义：「咱们」指说话的人群，与问房间归属不符。"}], "explanations": {"哪一个": "正确：「请问」之后问房间的归属，「哪一个房间」中的「哪一个」表示选择疑问。", "我": "语义：「我」指说话人，「我是你的」在句中不成立。", "它": "搭配：「它」需指代前文的事物，此处没有指代对象。", "咱们": "语义：「咱们」指说话的人群，与问房间归属不符。"}, "sentence_index": 6, "correct_answer": "哪一个"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他只有一辆车，你问的是哪一个车？", "explanation": "这里不应该用〈哪一个〉。他只有一辆车，没有可选择的对象，而且「车」的量词应是「辆」。"}, {"text": "他哪一个天没来上课？", "explanation": "「天」前应说「哪一天」，「哪一个」不能直接修饰「天」。"}, {"text": "这个班只有一个学生，哪一个学生昨天没来？", "explanation": "这里应该用〈谁〉。只有一个学生时，「哪一个」预设了有多个候选，应直接问「谁昨天没来」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec199dda-ed00-4312-8bc9-b9e17011411e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94916, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两种手机里，你觉得哪一个哪一个更好用？", "corrected_sentence": "两种手机里，你觉得哪一个更好用？", "error_description": "错误：「哪一个」重复出现，写成「哪一个哪一个更好用」。正确：「你觉得哪一个更好用」，「哪一个」只说一次。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec199dda-ed00-4312-8bc9-b9e17011411e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94916, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几个学生里，哪一个个最聪明？", "corrected_sentence": "这几个学生里，哪一个最聪明？", "error_description": "错误：「哪一个」后多加了一个「个」，写成「哪一个个最聪明」。正确：「哪一个最聪明」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec199dda-ed00-4312-8bc9-b9e17011411e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
