INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94918, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "城市和农村的合称。", "primary_collocate": null, "pronunciation": "chéng xiāng", "ipa": "ʈʂʰɤŋ˧˥ ɕi̯ɑŋ˥˥", "syllable_count": 2, "sentences": [{"text": "这条新路把城乡连在一起。", "target_word": "城乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城乡的生活水平越来越接近。", "target_word": "城乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府想让城乡孩子都能上好学校。", "target_word": "城乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城乡之间的差距正在变小。", "target_word": "城乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条高速公路方便了城乡来往。", "target_word": "城乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城乡的医院都要买新机器。", "target_word": "城乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在城乡都能上网。", "target_word": "城乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络让城乡的人联系更多。", "target_word": "城乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家正在改善城乡交通。", "target_word": "城乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的快递送到城乡各地。", "target_word": "城乡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "城鄉", "label": "繁体"}], "register": "书面", "sense_fingerprint": "城市和农村的合称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03e574a3-d7c0-4022-bfe0-96ccccca3dcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94918, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "城乡", "is_correct": true, "explanation": "正确。“城乡”指城市和农村的合称，与听到的读音一致。"}, {"text": "成像", "is_correct": false, "explanation": "chéng xiàng（第四声）与 chéng xiāng（第一声）声调不同，“成像”指形成影像。"}, {"text": "沉香", "is_correct": false, "explanation": "chén（第二声）与 chéng（第二声）韵尾不同，ng 变为 n，“沉香”是一种香料。"}, {"text": "成仙", "is_correct": false, "explanation": "xiān（第一声）与 xiāng（第一声）韵尾不同，an 与 ang 相对，“成仙”指成为神仙。"}, {"text": "承想", "is_correct": false, "explanation": "xiǎng（第三声）与 xiāng（第一声）声调不同，“承想”多用于“没承想”，意为没有料到。"}], "explanations": {"城乡": "正确。“城乡”指城市和农村的合称，与听到的读音一致。", "成像": "chéng xiàng（第四声）与 chéng xiāng（第一声）声调不同，“成像”指形成影像。", "沉香": "chén（第二声）与 chéng（第二声）韵尾不同，ng 变为 n，“沉香”是一种香料。", "成仙": "xiān（第一声）与 xiāng（第一声）韵尾不同，an 与 ang 相对，“成仙”指成为神仙。", "承想": "xiǎng（第三声）与 xiāng（第一声）声调不同，“承想”多用于“没承想”，意为没有料到。"}, "sentence_index": null, "correct_answer": "城乡"}, "level_3": {"options": [{"text": "城乡", "is_correct": true, "explanation": "正确。“城乡”是城市和农村的合称，可以被“连在一起”。"}, {"text": "时间", "is_correct": false, "explanation": "语义：道路可以连接具体的地方，“时间”是抽象概念，不能被道路连在一起。"}, {"text": "语文", "is_correct": false, "explanation": "语义：“语文”是学科名，不是地区，这条路无法把它连起来。"}, {"text": "数学", "is_correct": false, "explanation": "搭配：“把……连在一起”的宾语应是可以相连的地域或事物，“数学”不与这一结构搭配。"}], "explanations": {"城乡": "正确。“城乡”是城市和农村的合称，可以被“连在一起”。", "时间": "语义：道路可以连接具体的地方，“时间”是抽象概念，不能被道路连在一起。", "语文": "语义：“语文”是学科名，不是地区，这条路无法把它连起来。", "数学": "搭配：“把……连在一起”的宾语应是可以相连的地域或事物，“数学”不与这一结构搭配。"}, "sentence_index": 0, "correct_answer": "城乡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座城乡有很多高楼和公园。", "explanation": "这里应该用〈城市〉。“城乡”是城市和农村的合称，指两类地区，不能只指一座城市。"}, {"text": "我们村的城乡很安静，只有几户人家。", "explanation": "这里应该用〈农村〉。“城乡”包括城市，不能只指村子。"}, {"text": "这个公园在城乡，周末很多人来散步。", "explanation": "这里应该用〈城郊〉。“城乡”是城市与农村的合称，不能指城市边缘的一个具体地点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec199dda-ed00-4312-8bc9-b9e17011411e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94918, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "城乡", "is_correct": true, "explanation": "正确。“城乡”作主语，指城市和农村两类地区，都能上网。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”不是可以上网的对象，“现在石头都能上网”不成立。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“上网”的主语应为人、设备或地区，“体温”不能与“上网”搭配。"}, {"text": "清晨", "is_correct": false, "explanation": "语义：“清晨”是时间，不能作为“都能上网”的主语。"}], "explanations": {"城乡": "正确。“城乡”作主语，指城市和农村两类地区，都能上网。", "石头": "语义：“石头”不是可以上网的对象，“现在石头都能上网”不成立。", "体温": "搭配：“上网”的主语应为人、设备或地区，“体温”不能与“上网”搭配。", "清晨": "语义：“清晨”是时间，不能作为“都能上网”的主语。"}, "sentence_index": 6, "correct_answer": "城乡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的邻居是城乡人，每天早上都打太极。", "explanation": "这里应该用〈城里人〉或〈农村人〉。“城乡”指地区，不指人。"}, {"text": "妈妈给我买了一本城乡。", "explanation": "这里不能用〈本〉。〈本〉用于书籍，“城乡”是地区概念，不能这样计数。"}, {"text": "城乡会写作业。", "explanation": "“城乡”是地区，不能做“写作业”这类动作的主语，这里应该用指人的词，如〈学生〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec199dda-ed00-4312-8bc9-b9e17011411e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94918, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "城乡们的公共汽车都开通了新线路。", "corrected_sentence": "城乡的公共汽车都开通了新线路。", "error_description": "错误：“城乡们”。“城乡”是地区名词，不能加“们”表示复数，应改为“城乡的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec199dda-ed00-4312-8bc9-b9e17011411e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94918, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座城乡的往来越来越方便。", "corrected_sentence": "城乡的往来越来越方便。", "error_description": "错误：「城乡」指城市和农村两类地区，不能用量词「座」计量，应去掉「这座」，说「城乡的往来」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec199dda-ed00-4312-8bc9-b9e17011411e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94919, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e79ecf5c-5410-4911-8680-f65e8db16a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
