INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94919, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "报复是别人对你不好，你也对他不好。", "primary_collocate": null, "pronunciation": "bào fù", "ipa": "pɑʊ˥˩ fu˥˩", "syllable_count": 2, "sentences": [{"text": "他骂了我，我也想报复他。", "target_word": "报复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不理我，我就报复她一下。", "target_word": "报复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟拿走我的玩具，我就报复他，也拿走了他的。", "target_word": "报复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友骗了我，我不想报复他。", "target_word": "报复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对我不好，我没有报复他。", "target_word": "报复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别人对你不好，不要总想着报复。", "target_word": "报复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同桌弄坏了我的笔，我就报复他。", "target_word": "报复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他以前打过我，现在我想报复他。", "target_word": "报复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说我坏话，我报复她，也说了她的坏话。", "target_word": "报复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候哥哥骗我，我长大后也报复过他。", "target_word": "报复", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "报复了", "label": "体标（了）"}, {"form": "报复过", "label": "体标（过）"}, {"form": "報復", "label": "繁体"}], "register": "中性", "sense_fingerprint": "别人对自己不好，自己也用同样的方式对待他", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a411a526-522a-48ad-8c7c-56a20b15b9e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94919, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "报复", "is_correct": true, "explanation": "“报复”指别人对自己不好，自己也以同样方式回击，与“他骂了我”的情境一致。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：“赞美”表示称赞，与“他骂了我”的情境正好相反。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：“感谢”表示谢意，与被骂后的心情不相符。"}, {"text": "请教", "is_correct": false, "explanation": "搭配：“请教”指向人求教，不能与被骂后的心态搭配。"}], "explanations": {"报复": "“报复”指别人对自己不好，自己也以同样方式回击，与“他骂了我”的情境一致。", "赞美": "语义：“赞美”表示称赞，与“他骂了我”的情境正好相反。", "感谢": "语义：“感谢”表示谢意，与被骂后的心情不相符。", "请教": "搭配：“请教”指向人求教，不能与被骂后的心态搭配。"}, "sentence_index": 0, "correct_answer": "报复"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司报复了客户的损失。", "explanation": "这里应该用〈补偿〉。报复的对象是伤害自己的人，不能接事物；弥补损失要用补偿。"}, {"text": "工人报复了这个好消息。", "explanation": "这里应该用〈庆祝〉。报复指因怨恨而反击，不能用于好消息；对好消息表示高兴要用庆祝。"}, {"text": "我报复他的帮助。", "explanation": "这里应该用〈感谢〉。报复是对伤害自己的人的反击，不能用于别人的帮助；对帮助表示谢意要用感谢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e79ecf5c-5410-4911-8680-f65e8db16a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94919, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "报复", "is_correct": true, "explanation": "“报复”指因对方的行为而反击，与“弄坏了我的笔”后的反应一致。"}, {"text": "夸奖", "is_correct": false, "explanation": "语义：“夸奖”表示称赞，与“弄坏了我的笔”的情境不符。"}, {"text": "招待", "is_correct": false, "explanation": "语义：“招待”指款待客人，与弄坏别人东西的情境不符。"}, {"text": "祝贺", "is_correct": false, "explanation": "搭配：“祝贺”用于值得庆贺的喜事，弄坏东西不是可庆贺的事。"}], "explanations": {"报复": "“报复”指因对方的行为而反击，与“弄坏了我的笔”后的反应一致。", "夸奖": "语义：“夸奖”表示称赞，与“弄坏了我的笔”的情境不符。", "招待": "语义：“招待”指款待客人，与弄坏别人东西的情境不符。", "祝贺": "搭配：“祝贺”用于值得庆贺的喜事，弄坏东西不是可庆贺的事。"}, "sentence_index": 6, "correct_answer": "报复"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我常常报复童年的时光。", "explanation": "这里应该用〈怀念〉。报复指因怨恨而反击，不能用于时光；思念过去的时光要用怀念。"}, {"text": "公司报复了新业务。", "explanation": "这里应该用〈发展〉。报复不能用于业务；扩大业务、使其进步要用发展。"}, {"text": "老师报复他的画。", "explanation": "这里应该用〈欣赏〉。报复是针对伤害的反击，不能用于画作；赞赏艺术作品要用欣赏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e79ecf5c-5410-4911-8680-f65e8db16a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94919, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我从没报复了他。", "corrected_sentence": "我从没报复过他。", "error_description": "“从没”否定经历时，动词后要用“过”，应说“从没报复过他”，不能用“了”说“从没报复了他”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e79ecf5c-5410-4911-8680-f65e8db16a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94919, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他没报复了我。", "corrected_sentence": "他没报复我。", "error_description": "“没”否定动作时，“报复”后面不能加“了”。正确说法是“他没报复我”，不能说“他没报复了我”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e79ecf5c-5410-4911-8680-f65e8db16a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94921, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "内资", "is_correct": true, "explanation": "正确：内资指本国投资者投入的资金，与外资相对。"}, {"text": "国债", "is_correct": false, "explanation": "国债是国家发行的债券，与外资不构成反义关系。"}, {"text": "利息", "is_correct": false, "explanation": "利息是存款或借款产生的钱，与外资不构成反义关系。"}, {"text": "储蓄", "is_correct": false, "explanation": "储蓄是把钱存起来的行为或结果，与外资不构成反义关系。"}], "correct_answer": "内资", "explanations": {"内资": "正确：内资指本国投资者投入的资金，与外资相对。", "国债": "国债是国家发行的债券，与外资不构成反义关系。", "利息": "利息是存款或借款产生的钱，与外资不构成反义关系。", "储蓄": "储蓄是把钱存起来的行为或结果，与外资不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dedbc29c-746d-487f-b362-bdc472522b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94921, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "内资", "is_correct": true, "explanation": "正确：内资指本国投资者投入的资金，与外资相对。"}, {"text": "存款", "is_correct": false, "explanation": "存款是存入银行的钱，与外资不构成反义关系。"}, {"text": "利率", "is_correct": false, "explanation": "利率是利息与本金的比率，与外资不构成反义关系。"}, {"text": "税款", "is_correct": false, "explanation": "税款是交给国家的税，与外资不构成反义关系。"}], "correct_answer": "内资", "explanations": {"内资": "正确：内资指本国投资者投入的资金，与外资相对。", "存款": "存款是存入银行的钱，与外资不构成反义关系。", "利率": "利率是利息与本金的比率，与外资不构成反义关系。", "税款": "税款是交给国家的税，与外资不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dedbc29c-746d-487f-b362-bdc472522b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94921, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "外资是外国人拿来做生意的钱。", "primary_collocate": null, "pronunciation": "wài zī", "ipa": "wai˥˩ tsɿ˥", "syllable_count": 2, "sentences": [{"text": "这家工厂用的是外资，老板住在国外。", "target_word": "外资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府欢迎外资来本地开公司。", "target_word": "外资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年城市引进了很多外资。", "target_word": "外资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座大楼是用外资盖起来的。", "target_word": "外资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外资进来以后，工人多了。", "target_word": "外资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们公司的钱都是外资，不是本地的。", "target_word": "外资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小城想吸引外资，所以修了新路。", "target_word": "外资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家银行的外资占一半。", "target_word": "外资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的发展很大程度上靠外资。", "target_word": "外资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说有外资要来这里办厂。", "target_word": "外资", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "外资企业", "label": "复合词"}, {"form": "外资银行", "label": "复合词"}], "register": "中性", "sense_fingerprint": "外国人拿来做生意的钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '109ed30c-9583-414f-9809-33e9e60b7ef0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94921, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外资", "is_correct": true, "explanation": "正确：外资是外国人拿来做生意的钱，可以用来盖楼。"}, {"text": "外套", "is_correct": false, "explanation": "语义：外套不是钱，工厂“用的是”后面接的应是资金或材料。"}, {"text": "外卖", "is_correct": false, "explanation": "语义：外卖是送到家的餐食，工厂用的不是它，与句意不合。"}, {"text": "外星人", "is_correct": false, "explanation": "语义：外星人不是工厂使用的东西，与句意不合。"}], "explanations": {"外资": "正确：外资是外国人拿来做生意的钱，可以用来盖楼。", "外套": "语义：外套不是钱，工厂“用的是”后面接的应是资金或材料。", "外卖": "语义：外卖是送到家的餐食，工厂用的不是它，与句意不合。", "外星人": "语义：外星人不是工厂使用的东西，与句意不合。"}, "sentence_index": 0, "correct_answer": "外资"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他去国外旅游，换了一些外资。", "explanation": "这里应该用〈外汇〉。外资是外国人投入做生意的钱，不能用来换钱旅游，换钱要用外汇。"}, {"text": "他向银行申请了一笔外资。", "explanation": "这里应该用〈贷款〉。外资是外国人拿来做生意的钱，向银行借钱要用贷款。"}, {"text": "我们公司赚了一大笔外资。", "explanation": "这里应该用〈利润〉。外资是外国人拿来做生意的钱，公司赚到的钱要用利润。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dedbc29c-746d-487f-b362-bdc472522b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94921, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外资", "is_correct": true, "explanation": "正确：小城想吸引的是外国人投入做生意的钱，所以修了新路。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：小城不会想吸引垃圾，与“吸引”后的目的不符。"}, {"text": "噪音", "is_correct": false, "explanation": "搭配：“吸引”接的是投资、人才一类，不能说吸引噪音。"}, {"text": "病毒", "is_correct": false, "explanation": "语义：病毒不是小城想吸引的对象，与修路的目的相悖。"}], "explanations": {"外资": "正确：小城想吸引的是外国人投入做生意的钱，所以修了新路。", "垃圾": "语义：小城不会想吸引垃圾，与“吸引”后的目的不符。", "噪音": "搭配：“吸引”接的是投资、人才一类，不能说吸引噪音。", "病毒": "语义：病毒不是小城想吸引的对象，与修路的目的相悖。"}, "sentence_index": 6, "correct_answer": "外资"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他向灾区捐了一笔外资。", "explanation": "这里应该用〈捐款〉。外资是外国人拿来做生意的钱，捐给灾区要用捐款。"}, {"text": "租房时他交了一笔外资。", "explanation": "这里应该用〈押金〉。外资是做生意的钱，租房时交的钱要用押金。"}, {"text": "他去年的外资很高。", "explanation": "这里应该用〈收入〉。外资是外国人拿来做生意的钱，个人一年的所得要用收入。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dedbc29c-746d-487f-b362-bdc472522b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94921, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个城市吸引了三只外资。", "corrected_sentence": "这个城市吸引了三笔外资。", "error_description": "“外资”的量词应用“笔”，不能用“只”。正确的说法是“三笔外资”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dedbc29c-746d-487f-b362-bdc472522b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94921, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个城市吸引外资们。", "corrected_sentence": "这个城市吸引外资。", "error_description": "“们”只用于指人的名词，不能加在“外资”后面。正确的说法是“这个城市吸引外资”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dedbc29c-746d-487f-b362-bdc472522b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94922, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "内资", "is_correct": true, "explanation": "正确：内资指本国投资者投入的资金，与外资相对。"}, {"text": "房租", "is_correct": false, "explanation": "房租是租房要付的钱，与外资不构成反义关系。"}, {"text": "薪水", "is_correct": false, "explanation": "薪水是工作的报酬，与外资不构成反义关系。"}, {"text": "股息", "is_correct": false, "explanation": "股息是股东分得的利润，与外资不构成反义关系。"}], "correct_answer": "内资", "explanations": {"内资": "正确：内资指本国投资者投入的资金，与外资相对。", "房租": "房租是租房要付的钱，与外资不构成反义关系。", "薪水": "薪水是工作的报酬，与外资不构成反义关系。", "股息": "股息是股东分得的利润，与外资不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dedbc29c-746d-487f-b362-bdc472522b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94922, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "内资", "is_correct": true, "explanation": "正确：内资指本国投资者投入的资金，与外资相对。"}, {"text": "存款", "is_correct": false, "explanation": "存款是存入银行的钱，与外资不构成反义关系。"}, {"text": "利率", "is_correct": false, "explanation": "利率是利息与本金的比率，与外资不构成反义关系。"}, {"text": "税款", "is_correct": false, "explanation": "税款是交给国家的税，与外资不构成反义关系。"}], "correct_answer": "内资", "explanations": {"内资": "正确：内资指本国投资者投入的资金，与外资相对。", "存款": "存款是存入银行的钱，与外资不构成反义关系。", "利率": "利率是利息与本金的比率，与外资不构成反义关系。", "税款": "税款是交给国家的税，与外资不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dedbc29c-746d-487f-b362-bdc472522b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94922, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "外国投资者投入的资金。", "primary_collocate": null, "pronunciation": "wài zī", "ipa": "wai˥˩ tsɿ˥", "syllable_count": 2, "sentences": [{"text": "这个省去年吸引了大量外资。", "target_word": "外资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府要求外资必须遵守本国法律。", "target_word": "外资", "complexity_tier": "T3", "furigana": "zhèng fǔ yāo qiú wài zī bì xū zūn shǒu běn guó fǎ lǜ.", "sentence_source": "generated"}, {"text": "新政策让外资更容易进入市场。", "target_word": "外资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外资流入使当地经济发展很快。", "target_word": "外资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的外资比例超过百分之五十。", "target_word": "外资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家认为外资对就业有帮助。", "target_word": "外资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了利用外资，政府建了开发区。", "target_word": "外资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "近年来外资主要投向高科技产业。", "target_word": "外资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外资撤出后，工厂只好关门。", "target_word": "外资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家银行专门为外资提供服务。", "target_word": "外资", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "外资企业", "label": "复合词"}, {"form": "外资银行", "label": "复合词"}], "register": "书面", "sense_fingerprint": "外国投资者投入的资金", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '109ed30c-9583-414f-9809-33e9e60b7ef0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94922, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外资", "is_correct": true, "explanation": "正确：外资是外国投资者投入的资金，可以被吸引来。"}, {"text": "洪水", "is_correct": false, "explanation": "语义：洪水不是可以被吸引来的东西，与“吸引大量”的句意不合。"}, {"text": "病毒", "is_correct": false, "explanation": "语义：病毒不是省里想吸引的对象，与句意不合。"}, {"text": "颜料", "is_correct": false, "explanation": "搭配：“吸引”接的是投资、人才、游客一类，不能说吸引颜料。"}], "explanations": {"外资": "正确：外资是外国投资者投入的资金，可以被吸引来。", "洪水": "语义：洪水不是可以被吸引来的东西，与“吸引大量”的句意不合。", "病毒": "语义：病毒不是省里想吸引的对象，与句意不合。", "颜料": "搭配：“吸引”接的是投资、人才、游客一类，不能说吸引颜料。"}, "sentence_index": 0, "correct_answer": "外资"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他向灾区捐了一笔外资。", "explanation": "这里应该用〈捐款〉。外资是外国投资者投入的资金，捐给灾区要用捐款。"}, {"text": "他每个月都领外资。", "explanation": "这里应该用〈工资〉。外资是投入的资金，每月领取的薪水要用工资。"}, {"text": "这场演唱会的外资很贵。", "explanation": "这里应该用〈票价〉。外资是外国投资者投入的资金，演唱会的收费要用票价。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dedbc29c-746d-487f-b362-bdc472522b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94922, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外资", "is_correct": true, "explanation": "正确：利用外资是指利用外国投资者投入的资金。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干不能被政府拿来建开发区，“利用”的对象应是资源或资金。"}, {"text": "笑话", "is_correct": false, "explanation": "语义：笑话不是可以利用来建开发区的东西，与句意不合。"}, {"text": "老头儿", "is_correct": false, "explanation": "语义：“老头儿”是人，不是可以利用来建开发区的资金。"}], "explanations": {"外资": "正确：利用外资是指利用外国投资者投入的资金。", "饼干": "语义：饼干不能被政府拿来建开发区，“利用”的对象应是资源或资金。", "笑话": "语义：笑话不是可以利用来建开发区的东西，与句意不合。", "老头儿": "语义：“老头儿”是人，不是可以利用来建开发区的资金。"}, "sentence_index": 6, "correct_answer": "外资"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "银行每年付给我三百元外资。", "explanation": "这里应该用〈利息〉。外资是外国投资者投入的资金，银行付给储户的钱要用利息。"}, {"text": "他租房时交了外资。", "explanation": "这里应该用〈押金〉。外资是投入的资金，租房时交的钱要用押金。"}, {"text": "他每学期要交外资。", "explanation": "这里应该用〈学费〉。外资是投入的资金，学校收取的费用要用学费。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dedbc29c-746d-487f-b362-bdc472522b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94922, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个省今年吸引了三台外资。", "corrected_sentence": "这个省今年吸引了三笔外资。", "error_description": "“外资”的量词应用“笔”，不能用“台”。正确的说法是“三笔外资”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dedbc29c-746d-487f-b362-bdc472522b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94922, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "政府引进外资们。", "corrected_sentence": "政府引进外资。", "error_description": "“们”只用于指人的名词，不能加在“外资”后面。正确的说法是“政府引进外资”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dedbc29c-746d-487f-b362-bdc472522b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
