INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94923, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "大厦是又高又大的楼房。", "primary_collocate": null, "pronunciation": "dà shà", "ipa": "ta˥˩ ʂa˥˩", "syllable_count": 2, "sentences": [{"text": "市中心有一座很高的大厦。", "target_word": "大厦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座大厦有五十层。", "target_word": "大厦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在大厦里的一家公司工作。", "target_word": "大厦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司在那座新大厦的十楼。", "target_word": "大厦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大厦前面有一个很大的广场。", "target_word": "大厦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上，大厦的灯都亮着。", "target_word": "大厦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她站在大厦下面，抬头看着楼顶。", "target_word": "大厦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座大厦是去年建好的。", "target_word": "大厦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，去这座大厦怎么走？", "target_word": "大厦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大厦门口站着一位保安。", "target_word": "大厦", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "幢", "label": "量词"}, {"form": "高楼大厦", "label": "复合"}, {"form": "大廈", "label": "繁体"}], "register": "中性", "sense_fingerprint": "又高又大的楼房，多用作办公或商用建筑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9338e44a-02f0-4ff6-8511-9734bc7b6a50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94923, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大厦", "is_correct": true, "explanation": "“大厦”（dà shà）指又高又大的楼房，是正确答案。"}, {"text": "大使", "is_correct": false, "explanation": "大使 dà shǐ 与 dà shà 的第二音节韵母（i 与 a）和声调（第三声与第四声）都不同，意思是一国派驻他国的外交代表。"}, {"text": "大蛇", "is_correct": false, "explanation": "大蛇 dà shé 与 dà shà 的第二音节韵母（e 与 a）和声调（第二声与第四声）都不同，意思是很大的蛇。"}, {"text": "大赦", "is_correct": false, "explanation": "dà shè 与 dà shà 只有第二音节韵母不同（e 与 a），意思是赦免罪犯。"}, {"text": "大傻", "is_correct": false, "explanation": "dà shǎ 与 dà shà 只有第二音节声调不同（第三声与第四声），意思是非常傻。"}], "explanations": {"大厦": "“大厦”（dà shà）指又高又大的楼房，是正确答案。", "大使": "大使 dà shǐ 与 dà shà 的第二音节韵母（i 与 a）和声调（第三声与第四声）都不同，意思是一国派驻他国的外交代表。", "大蛇": "大蛇 dà shé 与 dà shà 的第二音节韵母（e 与 a）和声调（第二声与第四声）都不同，意思是很大的蛇。", "大赦": "dà shè 与 dà shà 只有第二音节韵母不同（e 与 a），意思是赦免罪犯。", "大傻": "dà shǎ 与 dà shà 只有第二音节声调不同（第三声与第四声），意思是非常傻。"}, "sentence_index": null, "correct_answer": "大厦"}, "level_3": {"options": [{"text": "大厦", "is_correct": true, "explanation": "“大厦”指又高又大的楼房，可以说“一座很高的大厦”，与“市中心”相合。"}, {"text": "树", "is_correct": false, "explanation": "量词：树的量词用“棵”，不说“一座”，与“一座很高的”不合。"}, {"text": "河", "is_correct": false, "explanation": "搭配：“河”的量词用“条”，不说“一座”；河也不能说“很高”。"}, {"text": "海", "is_correct": false, "explanation": "搭配：“海”的量词用“片”，不说“一座”，也不能说“很高的海”。"}], "explanations": {"大厦": "“大厦”指又高又大的楼房，可以说“一座很高的大厦”，与“市中心”相合。", "树": "量词：树的量词用“棵”，不说“一座”，与“一座很高的”不合。", "河": "搭配：“河”的量词用“条”，不说“一座”；河也不能说“很高”。", "海": "搭配：“海”的量词用“片”，不说“一座”，也不能说“很高的海”。"}, "sentence_index": 0, "correct_answer": "大厦"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们公司在那只新大厦的十楼。", "explanation": "这里应该用〈座〉。“大厦”是建筑，量词用“座”；“只”多用于动物、船等。"}, {"text": "我们家的大厦很小，只有两个房间。", "explanation": "这里应该用〈房子〉。“大厦”指又高又大的办公或商用楼，不能用来指小的家庭住宅。"}, {"text": "我们坐大厦去了岛上。", "explanation": "这里应该用〈船〉。“大厦”是建筑物，不是交通工具，不能用“坐”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babba5e0-0b28-42d0-8f55-614438535d6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94923, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大厦", "is_correct": true, "explanation": "“大厦”是又高又大的楼房，人可以站在它下面抬头看楼顶，与句意相合。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包不能让人站在它下面抬头看楼顶，与句中的场景不合。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶没有楼顶，人站在它下面抬头看楼顶的场景不成立。"}, {"text": "电视", "is_correct": false, "explanation": "语义：电视没有楼顶，人站在它下面抬头看楼顶的场景不成立。"}], "explanations": {"大厦": "“大厦”是又高又大的楼房，人可以站在它下面抬头看楼顶，与句意相合。", "书包": "语义：书包不能让人站在它下面抬头看楼顶，与句中的场景不合。", "花瓶": "语义：花瓶没有楼顶，人站在它下面抬头看楼顶的场景不成立。", "电视": "语义：电视没有楼顶，人站在它下面抬头看楼顶的场景不成立。"}, "sentence_index": 6, "correct_answer": "大厦"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座大厦是一间草房，只有一层。", "explanation": "这里的“大厦”指又高又大的楼房，不能用来指一层的草房，应该用〈茅屋〉之类的说法。"}, {"text": "我们在大厦的水面上划船。", "explanation": "这里应该用〈湖面〉。“大厦”是楼房，不能指水面，与“划船”的场景不合。"}, {"text": "我们在大厦里养了一群羊。", "explanation": "这里的“大厦”是楼房，不能用来养羊，应该用“牧场”之类的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babba5e0-0b28-42d0-8f55-614438535d6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94923, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "城东新建了一只大厦。", "corrected_sentence": "城东新建了一座大厦。", "error_description": "错误形式是“一只大厦”，正确形式是“一座大厦”。“大厦”是建筑，量词用“座”；“只”多用于动物、船等。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babba5e0-0b28-42d0-8f55-614438535d6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94923, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是我们去年建好大厦。", "corrected_sentence": "这是我们去年建好的大厦。", "error_description": "缺少“的”。“去年建好的”是修饰“大厦”的定语，要用“的”连接，应写作“去年建好的大厦”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babba5e0-0b28-42d0-8f55-614438535d6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
