INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94924, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "高大的楼房。", "primary_collocate": null, "pronunciation": "dà shà", "ipa": "ta˥˩ ʂa˥˩", "syllable_count": 2, "sentences": [{"text": "这座大厦是城里最高的楼。", "target_word": "大厦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天坐电梯上大厦的二十层。", "target_word": "大厦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大厦旁边新开了一家咖啡店。", "target_word": "大厦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我朋友住在海边的一座大厦里。", "target_word": "大厦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那幢大厦的外面都是玻璃。", "target_word": "大厦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们正在大厦外面洗窗户。", "target_word": "大厦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "站在大厦的楼顶，可以看到整个城市。", "target_word": "大厦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座大厦里有很多银行和公司。", "target_word": "大厦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大厦的电梯坏了，我们只好走楼梯。", "target_word": "大厦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们准备在河边建一座新大厦。", "target_word": "大厦", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "幢", "label": "量词"}, {"form": "高楼大厦", "label": "复合"}, {"form": "大廈", "label": "繁体"}], "register": "中性", "sense_fingerprint": "高大的楼房", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9338e44a-02f0-4ff6-8511-9734bc7b6a50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94924, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大厦", "is_correct": true, "explanation": "“大厦”（dà shà）指高大的楼房，是正确答案。"}, {"text": "大使", "is_correct": false, "explanation": "大使 dà shǐ 与 dà shà 的第二音节韵母（i 与 a）和声调（第三声与第四声）都不同，意思是一国派驻他国的外交代表。"}, {"text": "大蛇", "is_correct": false, "explanation": "大蛇 dà shé 与 dà shà 的第二音节韵母（e 与 a）和声调（第二声与第四声）都不同，意思是很大的蛇。"}, {"text": "大赦", "is_correct": false, "explanation": "dà shè 与 dà shà 只有第二音节韵母不同（e 与 a），意思是赦免罪犯。"}, {"text": "大傻", "is_correct": false, "explanation": "dà shǎ 与 dà shà 只有第二音节声调不同（第三声与第四声），意思是非常傻。"}], "explanations": {"大厦": "“大厦”（dà shà）指高大的楼房，是正确答案。", "大使": "大使 dà shǐ 与 dà shà 的第二音节韵母（i 与 a）和声调（第三声与第四声）都不同，意思是一国派驻他国的外交代表。", "大蛇": "大蛇 dà shé 与 dà shà 的第二音节韵母（e 与 a）和声调（第二声与第四声）都不同，意思是很大的蛇。", "大赦": "dà shè 与 dà shà 只有第二音节韵母不同（e 与 a），意思是赦免罪犯。", "大傻": "dà shǎ 与 dà shà 只有第二音节声调不同（第三声与第四声），意思是非常傻。"}, "sentence_index": null, "correct_answer": "大厦"}, "level_3": {"options": [{"text": "大厦", "is_correct": true, "explanation": "“大厦”指高大的楼房，可以说“这座大厦是城里最高的楼”。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园不是楼，不能说“是城里最高的楼”。"}, {"text": "树", "is_correct": false, "explanation": "搭配：树的量词用“棵”，不能说“这座树”；树也不是楼。"}, {"text": "公园", "is_correct": false, "explanation": "语义：公园不是楼，与“城里最高的楼”不合。"}], "explanations": {"大厦": "“大厦”指高大的楼房，可以说“这座大厦是城里最高的楼”。", "花园": "语义：花园不是楼，不能说“是城里最高的楼”。", "树": "搭配：树的量词用“棵”，不能说“这座树”；树也不是楼。", "公园": "语义：公园不是楼，与“城里最高的楼”不合。"}, "sentence_index": 0, "correct_answer": "大厦"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我朋友把大厦放在书包里带到学校。", "explanation": "这里应该用〈照片〉之类的说法。“大厦”是高大的楼房，不能放进书包里。"}, {"text": "我朋友家门口有一棵大厦。", "explanation": "这里应该用〈座〉。“大厦”是建筑，量词用“座”；“棵”用于树，不能用于大厦。"}, {"text": "我朋友每天在大厦的河里游泳。", "explanation": "这里应该用〈游泳池〉。“大厦”是楼房，没有河，也不能在楼里游泳。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babba5e0-0b28-42d0-8f55-614438535d6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94924, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大厦", "is_correct": true, "explanation": "“大厦”是高大的楼房，人可以站在它的楼顶看城市，与句意相合。"}, {"text": "书", "is_correct": false, "explanation": "语义：书没有楼顶，人不能站在书的楼顶上看城市。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车没有楼顶，人不能站在汽车的楼顶上看城市。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子没有楼顶，与“站在……的楼顶”的场景不合。"}], "explanations": {"大厦": "“大厦”是高大的楼房，人可以站在它的楼顶看城市，与句意相合。", "书": "语义：书没有楼顶，人不能站在书的楼顶上看城市。", "汽车": "语义：汽车没有楼顶，人不能站在汽车的楼顶上看城市。", "桌子": "语义：桌子没有楼顶，与“站在……的楼顶”的场景不合。"}, "sentence_index": 6, "correct_answer": "大厦"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们准备在河边建一座新大厦，然后在大厦的门口喂马。", "explanation": "这里应该用〈马厩〉。“大厦”是楼房，不能用来喂马，与“喂马”的场景不合。"}, {"text": "他们准备在河边建一座新大厦，然后骑着大厦去城里。", "explanation": "这里应该用〈车〉。“大厦”是建筑物，不是交通工具，不能用“骑”。"}, {"text": "他们准备在河边建一座新大厦，然后把大厦装进了包里带走。", "explanation": "这里应该用〈模型〉。“大厦”是真实的建筑，不能装进包里带走，与“装进包里”的情境不合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babba5e0-0b28-42d0-8f55-614438535d6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94924, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "城北有一只大厦，是最高的楼。", "corrected_sentence": "城北有一座大厦，是最高的楼。", "error_description": "错误形式是“一只大厦”，正确形式是“一座大厦”。“大厦”是建筑，量词用“座”；“只”多用于动物、船等。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babba5e0-0b28-42d0-8f55-614438535d6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94924, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座大厦是今年建好了。", "corrected_sentence": "这座大厦是今年建好的。", "error_description": "“是……的”句式强调动作发生的时间，应用“的”，不用“了”。错误形式是“建好了”，正确形式是“建好的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babba5e0-0b28-42d0-8f55-614438535d6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
