INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94925, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "守是待在一个地方看着，不让离开。", "primary_collocate": null, "pronunciation": "shǒu", "ipa": "ʂoʊ̯˨˩˦", "syllable_count": 1, "sentences": [{"text": "妈妈守在孩子的床边。", "target_word": "守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一晚上都守着电话。", "target_word": "守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗守在门口等主人。", "target_word": "守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生守着病人一夜没睡。", "target_word": "守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她守在电话旁边等消息。", "target_word": "守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他守在电视机前看比赛。", "target_word": "守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶守着炉子，等水开。", "target_word": "守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别守着手机，出去走走吧。", "target_word": "守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他守在病床前，一直没离开。", "target_word": "守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在门外守了三个小时。", "target_word": "守", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "守了", "label": "体标（了）"}, {"form": "守着", "label": "体标（着）"}, {"form": "守过", "label": "体标（过）"}, {"form": "守住", "label": "结果补语"}], "register": "中性", "sense_fingerprint": "待在某处看着、陪着不离开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8ab8815-7ec2-46b3-9bde-62defb4a82b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94925, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "守", "is_correct": true, "explanation": "守 shǒu：待在某处看着，不让离开。"}, {"text": "售", "is_correct": false, "explanation": "shòu（第四声）与 shǒu 声调不同，意思是出售。"}, {"text": "收", "is_correct": false, "explanation": "shōu（第一声）与 shǒu 声调不同，意思是收起。"}, {"text": "肘", "is_correct": false, "explanation": "zhǒu 与 shǒu 声母不同（zh/sh），意思是手肘。"}], "explanations": {"守": "守 shǒu：待在某处看着，不让离开。", "售": "shòu（第四声）与 shǒu 声调不同，意思是出售。", "收": "shōu（第一声）与 shǒu 声调不同，意思是收起。", "肘": "zhǒu 与 shǒu 声母不同（zh/sh），意思是手肘。"}, "sentence_index": null, "correct_answer": "守"}, "level_3": {"options": [{"text": "守", "is_correct": true, "explanation": "守：待在床边看着，与“床边”搭配，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：吃是把食物咽下，不能吃在床边。"}, {"text": "讲", "is_correct": false, "explanation": "语义：讲是说话，不能讲在床边。"}, {"text": "违", "is_correct": false, "explanation": "搭配：“违”不能直接带处所，“违在床边”不成立。"}], "explanations": {"守": "守：待在床边看着，与“床边”搭配，符合句意。", "吃": "语义：吃是把食物咽下，不能吃在床边。", "讲": "语义：讲是说话，不能讲在床边。", "违": "搭配：“违”不能直接带处所，“违在床边”不成立。"}, "sentence_index": 0, "correct_answer": "守"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他守了一封信。", "explanation": "这里应该用〈写〉。守是待在一处看着，写信要说写，不能说守。"}, {"text": "他守了一杯水。", "explanation": "这里应该用〈喝〉。守是待在一处看着，喝水要说喝，不能说守。"}, {"text": "她守了一件衣服。", "explanation": "这里应该用〈洗〉。守是待在一处看着，洗衣服要说洗，不能说守。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b85754-4e02-48ba-91d9-02715c9bae66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94925, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "守", "is_correct": true, "explanation": "守 shǒu：待在某处看着，不让离开。"}, {"text": "兽", "is_correct": false, "explanation": "shòu（第四声）与 shǒu 声调不同，意思是野兽。"}, {"text": "瘦", "is_correct": false, "explanation": "shòu（第四声）与 shǒu 声调不同，意思是瘦弱。"}, {"text": "寿", "is_correct": false, "explanation": "shòu（第四声）与 shǒu 声调不同，意思是寿命。"}], "explanations": {"守": "守 shǒu：待在某处看着，不让离开。", "兽": "shòu（第四声）与 shǒu 声调不同，意思是野兽。", "瘦": "shòu（第四声）与 shǒu 声调不同，意思是瘦弱。", "寿": "shòu（第四声）与 shǒu 声调不同，意思是寿命。"}, "sentence_index": null, "correct_answer": "守"}, "level_3": {"options": [{"text": "守", "is_correct": true, "explanation": "守：待在炉子旁看着，等水开，符合句意。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱是唱歌，不能唱炉子。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：煮的对象是食物，炉子不能被煮。"}, {"text": "咬", "is_correct": false, "explanation": "语义：咬是用牙齿夹住，炉子不能被咬。"}], "explanations": {"守": "守：待在炉子旁看着，等水开，符合句意。", "唱": "语义：唱是唱歌，不能唱炉子。", "煮": "搭配：煮的对象是食物，炉子不能被煮。", "咬": "语义：咬是用牙齿夹住，炉子不能被咬。"}, "sentence_index": 6, "correct_answer": "守"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他守了一条消息。", "explanation": "这里应该用〈发〉。守是待在一处看着，发消息要说发，不能说守。"}, {"text": "他守了一件外套。", "explanation": "这里应该用〈买〉。守是待在一处看着，买衣服要说买，不能说守。"}, {"text": "他守了一件礼物。", "explanation": "这里应该用〈送〉。守是待在一处看着，送礼物要说送，不能说守。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b85754-4e02-48ba-91d9-02715c9bae66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94925, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他着守门口，不让陌生人进来。", "corrected_sentence": "他守着门口，不让陌生人进来。", "error_description": "体标位置错误：“着”是动态助词，必须紧跟动词“守”，应说“守着门口”，不能放在动词前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b85754-4e02-48ba-91d9-02715c9bae66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94925, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在车站了守两个小时。", "corrected_sentence": "他在车站守了两个小时。", "error_description": "体标位置错误：“了”应紧跟动词“守”，应说“守了两个小时”，不能放在“守”前面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b85754-4e02-48ba-91d9-02715c9bae66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94926, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "违反", "is_correct": true, "explanation": "违反：与“遵守”相反，指不遵守规定或承诺。"}, {"text": "吃", "is_correct": false, "explanation": "吃与“守”的任何义项都没有反义关系。"}, {"text": "唱", "is_correct": false, "explanation": "唱与“守”的任何义项都没有反义关系。"}, {"text": "跑", "is_correct": false, "explanation": "跑与“守”的任何义项都没有反义关系。"}], "correct_answer": "违反", "explanations": {"违反": "违反：与“遵守”相反，指不遵守规定或承诺。", "吃": "吃与“守”的任何义项都没有反义关系。", "唱": "唱与“守”的任何义项都没有反义关系。", "跑": "跑与“守”的任何义项都没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b85754-4e02-48ba-91d9-02715c9bae66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
