INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94926, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "看护，防备；也指遵照、遵守。", "primary_collocate": null, "pronunciation": "shǒu", "ipa": "ʂoʊ̯˨˩˦", "syllable_count": 1, "sentences": [{"text": "孩子要守规矩。", "target_word": "守", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在门口守着大门。", "target_word": "守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过马路要守交通规则。", "target_word": "守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直守着自己的诺言。", "target_word": "守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战士们守在边境上。", "target_word": "守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他守住了阵地，没有后退。", "target_word": "守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛时，他负责守球门。", "target_word": "守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作为员工，我们都要守公司的制度。", "target_word": "守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都守纪律，教室很安静。", "target_word": "守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保安晚上守着仓库。", "target_word": "守", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "守了", "label": "体标（了）"}, {"form": "守着", "label": "体标（着）"}, {"form": "守过", "label": "体标（过）"}, {"form": "守住", "label": "结果补语"}], "register": "中性", "sense_fingerprint": "看护防备，或遵照规矩、承诺", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8ab8815-7ec2-46b3-9bde-62defb4a82b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94926, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "守", "is_correct": true, "explanation": "守 shǒu：遵照、遵守规矩或承诺。"}, {"text": "受", "is_correct": false, "explanation": "shòu（第四声）与 shǒu 声调不同，意思是接受。"}, {"text": "收", "is_correct": false, "explanation": "shōu（第一声）与 shǒu 声调不同，意思是收起。"}, {"text": "肘", "is_correct": false, "explanation": "zhǒu 与 shǒu 声母不同（zh/sh），意思是手肘。"}, {"text": "寿", "is_correct": false, "explanation": "shòu（第四声）与 shǒu 声调不同，意思是寿命。"}], "explanations": {"守": "守 shǒu：遵照、遵守规矩或承诺。", "受": "shòu（第四声）与 shǒu 声调不同，意思是接受。", "收": "shōu（第一声）与 shǒu 声调不同，意思是收起。", "肘": "zhǒu 与 shǒu 声母不同（zh/sh），意思是手肘。", "寿": "shòu（第四声）与 shǒu 声调不同，意思是寿命。"}, "sentence_index": null, "correct_answer": "守"}, "level_3": {"options": [{"text": "守", "is_correct": true, "explanation": "守：遵照、遵守规矩，与“规矩”搭配。"}, {"text": "吃", "is_correct": false, "explanation": "语义：吃是把食物咽下，不能吃规矩。"}, {"text": "违", "is_correct": false, "explanation": "语义：“违”表示违反，“孩子要违规矩”与句意相反，不符合劝导的语境。"}, {"text": "撞", "is_correct": false, "explanation": "语义：撞是猛烈冲击，不能撞规矩。"}], "explanations": {"守": "守：遵照、遵守规矩，与“规矩”搭配。", "吃": "语义：吃是把食物咽下，不能吃规矩。", "违": "语义：“违”表示违反，“孩子要违规矩”与句意相反，不符合劝导的语境。", "撞": "语义：撞是猛烈冲击，不能撞规矩。"}, "sentence_index": 0, "correct_answer": "守"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把书守在桌上。", "explanation": "这里应该用〈放〉。守是看护、遵守，把书放在桌上要说放，不能说守。"}, {"text": "他守了一顿饭。", "explanation": "这里应该用〈吃〉。守是看护、遵守，吃饭要说吃，不能说守。"}, {"text": "他守了一双鞋。", "explanation": "这里应该用〈买〉。守是看护、遵守，买东西要说买，不能说守。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b85754-4e02-48ba-91d9-02715c9bae66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94926, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "守", "is_correct": true, "explanation": "守 shǒu：看护、防备，或遵照、遵守。"}, {"text": "售", "is_correct": false, "explanation": "shòu（第四声）与 shǒu 声调不同，意思是出售。"}, {"text": "兽", "is_correct": false, "explanation": "shòu（第四声）与 shǒu 声调不同，意思是野兽。"}, {"text": "瘦", "is_correct": false, "explanation": "shòu（第四声）与 shǒu 声调不同，意思是瘦弱。"}], "explanations": {"守": "守 shǒu：看护、防备，或遵照、遵守。", "售": "shòu（第四声）与 shǒu 声调不同，意思是出售。", "兽": "shòu（第四声）与 shǒu 声调不同，意思是野兽。", "瘦": "shòu（第四声）与 shǒu 声调不同，意思是瘦弱。"}, "sentence_index": null, "correct_answer": "守"}, "level_3": {"options": [{"text": "守", "is_correct": true, "explanation": "守：防守，把守球门，与“球门”搭配。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱是唱歌，不能唱球门。"}, {"text": "吹", "is_correct": false, "explanation": "语义：吹是吹气，不能吹球门。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：煮的对象是食物，球门不能被煮。"}], "explanations": {"守": "守：防守，把守球门，与“球门”搭配。", "唱": "语义：唱是唱歌，不能唱球门。", "吹": "语义：吹是吹气，不能吹球门。", "煮": "搭配：煮的对象是食物，球门不能被煮。"}, "sentence_index": 6, "correct_answer": "守"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他守掉了旧书。", "explanation": "这里应该用〈扔〉。守是看护、遵守，丢掉旧书要说扔，不能说守。"}, {"text": "他守开了窗户。", "explanation": "这里应该用〈打开〉。守是看护、遵守，把窗户打开要说打开，不能说守。"}, {"text": "她守了一首歌。", "explanation": "这里应该用〈唱〉。守是看护、遵守，唱歌要说唱，不能说守。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b85754-4e02-48ba-91d9-02715c9bae66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94926, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他守了住自己的承诺。", "corrected_sentence": "他守住了自己的承诺。", "error_description": "结果补语位置错误：“了”应放在结果补语“住”之后，应说“守住了”，不能插在“守”和“住”之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b85754-4e02-48ba-91d9-02715c9bae66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94926, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们过守这块地。", "corrected_sentence": "我们守过这块地。", "error_description": "体标位置错误：“过”是动态助词，必须紧跟动词“守”，应说“守过”，不能放在动词前面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b85754-4e02-48ba-91d9-02715c9bae66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
