INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94927, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "审核是认真查看，确认对不对。", "primary_collocate": null, "pronunciation": "shěn hé", "ipa": "ʂən˨˩˦ xɤ˧˥", "syllable_count": 2, "sentences": [{"text": "请先审核这份文件，看看有没有错。", "target_word": "审核", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理正在审核今年的账目。", "target_word": "审核", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这篇稿子要先审核，再发出去。", "target_word": "审核", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "合同签字以前，律师会仔细审核。", "target_word": "审核", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我已经审核了三遍，没有发现错误。", "target_word": "审核", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "财务人员把报销单审核了一遍。", "target_word": "审核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "编辑审核完文章，才可以上网发表。", "target_word": "审核", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些数据还没审核，不知道对不对。", "target_word": "审核", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他审核过很多份报告，经验很丰富。", "target_word": "审核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你帮我审核一下，看有没有错字。", "target_word": "审核", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "审核了", "label": "体标"}, {"form": "审核过", "label": "体标"}, {"form": "审核审核", "label": "重叠"}, {"form": "审核员", "label": "复合"}], "register": "正式", "sense_fingerprint": "审核：认真查看文件、数据等，确认有没有错", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f7b11e6-f8b1-44fd-9869-ef9467b2bef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94927, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "审核", "is_correct": true, "explanation": "正确。“审核”指认真查看，确认有没有错，与“看看有没有错”相符。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”表示烧掉，与“看看有没有错”的核查意思不符。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”表示丢弃，与核对文件无关，句意矛盾。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能带“文件”作宾语，说“唱这份文件”不通。"}], "explanations": {"审核": "正确。“审核”指认真查看，确认有没有错，与“看看有没有错”相符。", "烧": "语义：“烧”表示烧掉，与“看看有没有错”的核查意思不符。", "扔": "语义：“扔”表示丢弃，与核对文件无关，句意矛盾。", "唱": "搭配：“唱”不能带“文件”作宾语，说“唱这份文件”不通。"}, "sentence_index": 0, "correct_answer": "审核"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生审核病人的身体，看有没有问题。", "explanation": "这里应该用〈检查〉。审核用于文件、资料、申请等，检查身体要用〈检查〉。"}, {"text": "我在字典里审核这个生词。", "explanation": "这里应该用〈查〉。审核指认真核对文件、申请等，查字典要用〈查〉。"}, {"text": "实验室审核河里的水质。", "explanation": "这里应该用〈检测〉。审核用于文件、资料，检验水质要用〈检测〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '181cd7c8-eea7-4335-8e9c-3f32a868aace') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94927, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "审核", "is_correct": true, "explanation": "正确。“审核完文章”指认真检查后再发表，与“才可以上网发表”相符。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”的宾语是衣物等，不能说“穿文章”，句意不通。"}, {"text": "染", "is_correct": false, "explanation": "搭配：“染”的对象是布料、头发等，不能说“染文章”。"}, {"text": "烤", "is_correct": false, "explanation": "搭配：“烤”的对象是食物，不能说“烤完文章”。"}], "explanations": {"审核": "正确。“审核完文章”指认真检查后再发表，与“才可以上网发表”相符。", "穿": "搭配：“穿”的宾语是衣物等，不能说“穿文章”，句意不通。", "染": "搭配：“染”的对象是布料、头发等，不能说“染文章”。", "烤": "搭配：“烤”的对象是食物，不能说“烤完文章”。"}, "sentence_index": 6, "correct_answer": "审核"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈认真审核水果，挑了最甜的。", "explanation": "这里应该用〈挑选〉。审核指核查文件、资料是否正确，挑选水果要用〈挑选〉。"}, {"text": "护士认真审核病人，一刻也不离开。", "explanation": "这里应该用〈照顾〉。审核的对象是文件、申请等，照顾病人要用〈照顾〉。"}, {"text": "我在河边审核那只小鸟。", "explanation": "这里应该用〈观察〉。审核指认真核对文件、申请等，观察小鸟要用〈观察〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '181cd7c8-eea7-4335-8e9c-3f32a868aace') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94927, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我已经把这份文件审核。", "corrected_sentence": "我已经把这份文件审核了。", "error_description": "错误：“把”字句中，动词后必须有其他成分（如“了”），不能只说“把……审核”。正确：“我已经把这份文件审核了。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '181cd7c8-eea7-4335-8e9c-3f32a868aace') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94927, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请你帮我审核了一下。", "corrected_sentence": "请你帮我审核一下。", "error_description": "错误：祈使句“请你……一下”中，“审核”后不能加“了”，应说“审核一下”。正确：“请你帮我审核一下。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '181cd7c8-eea7-4335-8e9c-3f32a868aace') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
