INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94928, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "仔细检查、核对并做出判断。", "primary_collocate": null, "pronunciation": "shěn hé", "ipa": "ʂən˨˩˦ xɤ˧˥", "syllable_count": 2, "sentences": [{"text": "银行正在审核他的贷款申请。", "target_word": "审核", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你的申请已经审核通过。", "target_word": "审核", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师会审核每个人的参赛资格。", "target_word": "审核", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司要审核新员工的身份证明。", "target_word": "审核", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工作人员审核后，决定是否发放补贴。", "target_word": "审核", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网站会先审核评论，再决定能不能显示。", "target_word": "审核", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们审核了所有投标公司，选出三家。", "target_word": "审核", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生审核病人的资料，判断能不能做手术。", "target_word": "审核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的签证正在审核，还不知道结果。", "target_word": "审核", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校审核过他的材料，同意他入学。", "target_word": "审核", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "审核了", "label": "体标"}, {"form": "审核过", "label": "体标"}, {"form": "审核审核", "label": "重叠"}, {"form": "审核员", "label": "复合"}], "register": "正式", "sense_fingerprint": "审核：检查核对申请、资格等，并决定是否通过", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f7b11e6-f8b1-44fd-9869-ef9467b2bef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94928, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "审核", "is_correct": true, "explanation": "正确。“审核贷款申请”指查看并决定是否通过，与句意相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语应是食物，不能说“吃贷款申请”。"}, {"text": "烤", "is_correct": false, "explanation": "搭配：“烤”的对象是食物，与“贷款申请”搭配不通。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”表示烧掉，与“正在查看并决定是否通过”的意思不符。"}], "explanations": {"审核": "正确。“审核贷款申请”指查看并决定是否通过，与句意相符。", "吃": "搭配：“吃”的宾语应是食物，不能说“吃贷款申请”。", "烤": "搭配：“烤”的对象是食物，与“贷款申请”搭配不通。", "烧": "语义：“烧”表示烧掉，与“正在查看并决定是否通过”的意思不符。"}, "sentence_index": 0, "correct_answer": "审核"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生每天审核病人的身体，看有没有问题。", "explanation": "这里应该用〈检查〉。审核用于申请、资格、资料等，身体状况要用〈检查〉。"}, {"text": "厨师审核这道菜的味道，然后端上桌。", "explanation": "这里应该用〈品尝〉。审核针对申请和资料，尝味道要用〈品尝〉。"}, {"text": "我审核了一下午的天气。", "explanation": "这里应该用〈观察〉。审核指核查申请、资格等材料后作出判断，观察天气要用〈观察〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '181cd7c8-eea7-4335-8e9c-3f32a868aace') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94928, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "审核", "is_correct": true, "explanation": "正确。“审核了所有投标公司，选出三家”指逐一检查后做出选择，与句意相符。"}, {"text": "喂", "is_correct": false, "explanation": "搭配：“喂”的对象是人或动物，不能用于“投标公司”。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”的对象是桌面、玻璃等，不能用于“投标公司”。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象是衣物、身体等，不能说“洗投标公司”。"}], "explanations": {"审核": "正确。“审核了所有投标公司，选出三家”指逐一检查后做出选择，与句意相符。", "喂": "搭配：“喂”的对象是人或动物，不能用于“投标公司”。", "擦": "搭配：“擦”的对象是桌面、玻璃等，不能用于“投标公司”。", "洗": "搭配：“洗”的对象是衣物、身体等，不能说“洗投标公司”。"}, "sentence_index": 6, "correct_answer": "审核"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈审核了一筐苹果，挑出了最甜的。", "explanation": "这里应该用〈挑选〉。审核用于文件、申请等，挑苹果要用〈挑选〉。"}, {"text": "他审核了房间，把东西整理好了。", "explanation": "这里应该用〈收拾〉。审核用于申请、资料，整理房间要用〈收拾〉。"}, {"text": "我审核了那辆公交车。", "explanation": "这里应该用〈检查〉。审核的对象是文件、申请、资料等，检查公交车要用〈检查〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '181cd7c8-eea7-4335-8e9c-3f32a868aace') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94928, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的申请已经审核了完。", "corrected_sentence": "他的申请已经审核完了。", "error_description": "错误：结果补语“完”应紧跟在动词“审核”后，“了”放在最后，说“审核完了”。“了”放在了“完”之前，不能说“审核了完”。正确：“他的申请已经审核完了。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '181cd7c8-eea7-4335-8e9c-3f32a868aace') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94928, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校审核了过他的材料，就同意了。", "corrected_sentence": "学校审核过他的材料，就同意了。", "error_description": "错误：“了”和“过”不能同时用在同一个动词后面。表示曾经做过要说“审核过”。正确：“学校审核过他的材料”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '181cd7c8-eea7-4335-8e9c-3f32a868aace') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
