INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94931, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "恋爱是两个人互相喜欢，常在一起。", "primary_collocate": null, "pronunciation": "liàn ài", "ipa": "ljɛn˥˩ aɪ̯˥˩", "syllable_count": 2, "sentences": [{"text": "他们恋爱三年了。", "target_word": "恋爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不想在上学时恋爱。", "target_word": "恋爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和他在大学恋爱了。", "target_word": "恋爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们俩正在恋爱。", "target_word": "恋爱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们恋爱以后很少吵架。", "target_word": "恋爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们恋爱的时候常去公园。", "target_word": "恋爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她第一次恋爱是在十八岁。", "target_word": "恋爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说你在恋爱，是真的吗？", "target_word": "恋爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人恋爱后，常常一起吃饭。", "target_word": "恋爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们恋爱过两年，后来分开了。", "target_word": "恋爱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "恋爱了", "label": "体标（了）"}, {"form": "恋爱过", "label": "体标（过）"}, {"form": "谈恋爱", "label": "复合"}], "register": "中性", "sense_fingerprint": "两人互相喜欢并常在一起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8ab8815-7ec2-46b3-9bde-62defb4a82b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94931, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "恋爱", "is_correct": true, "explanation": "正确：“恋爱”指两人互相喜欢、交往，可与“三年了”的时长搭配。"}, {"text": "下雨", "is_correct": false, "explanation": "搭配：“下雨”是天气现象，不能以“他们”作主语。"}, {"text": "怀孕", "is_correct": false, "explanation": "语义：“怀孕”只能指女性，不能用于“他们”这样的复数主语。"}, {"text": "发芽", "is_correct": false, "explanation": "语义：“发芽”是植物的变化，不能用于“他们”。"}], "explanations": {"恋爱": "正确：“恋爱”指两人互相喜欢、交往，可与“三年了”的时长搭配。", "下雨": "搭配：“下雨”是天气现象，不能以“他们”作主语。", "怀孕": "语义：“怀孕”只能指女性，不能用于“他们”这样的复数主语。", "发芽": "语义：“发芽”是植物的变化，不能用于“他们”。"}, "sentence_index": 0, "correct_answer": "恋爱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们上个月去民政局恋爱了。", "explanation": "这里应该用〈结婚〉。“恋爱”指两人互相喜欢、交往，不指办理结婚登记。"}, {"text": "他带女朋友回家恋爱了。", "explanation": "这里应该用〈见家长〉。“恋爱”不能用来表示带对方回家见父母这一场合。"}, {"text": "他们上个月在法院恋爱了。", "explanation": "这里应该用〈离婚〉。“恋爱”不指办理离婚手续。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b85754-4e02-48ba-91d9-02715c9bae66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94931, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "恋爱", "is_correct": true, "explanation": "正确：“恋爱”指两人互相喜欢、交往，与“第一次……是在十八岁”的叙述相符。"}, {"text": "出生", "is_correct": false, "explanation": "语义：“出生”只发生一次，不能说“第一次出生”。"}, {"text": "发芽", "is_correct": false, "explanation": "语义：“发芽”是植物的变化，不能用于人，与句意不符。"}, {"text": "下雪", "is_correct": false, "explanation": "语义：“下雪”是天气现象，不能以“她”作主语。"}], "explanations": {"恋爱": "正确：“恋爱”指两人互相喜欢、交往，与“第一次……是在十八岁”的叙述相符。", "出生": "语义：“出生”只发生一次，不能说“第一次出生”。", "发芽": "语义：“发芽”是植物的变化，不能用于人，与句意不符。", "下雪": "语义：“下雪”是天气现象，不能以“她”作主语。"}, "sentence_index": 6, "correct_answer": "恋爱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两国外交官在会议室恋爱了三天。", "explanation": "这里应该用〈交往〉。“恋爱”指男女之间的感情交往，不用于国家代表之间的接触。"}, {"text": "为了这个项目，他们每周恋爱一次。", "explanation": "这里应该用〈开会〉。“恋爱”只用于两人之间的感情交往，不用于工作项目。"}, {"text": "工人们在车间恋爱了两个小时。", "explanation": "这里应该用〈讨论〉。“恋爱”指两人之间的感情交往，不用于车间里的商讨。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b85754-4e02-48ba-91d9-02715c9bae66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94931, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们在毕业以后很恋爱。", "corrected_sentence": "他们在毕业以后才恋爱。", "error_description": "“很”是程度副词，不能修饰动词“恋爱”。这里表示时间，应用“才”，正确说法是“他们在毕业以后才恋爱”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b85754-4e02-48ba-91d9-02715c9bae66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94931, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们俩恋爱了过一段时间。", "corrected_sentence": "我们俩恋爱过一段时间。", "error_description": "“恋爱”后只能用一个体标。表示经历要用“恋爱过”，“了”和“过”不能同时用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b85754-4e02-48ba-91d9-02715c9bae66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
