INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94932, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "男女双方互相爱慕并发展感情的过程。", "primary_collocate": null, "pronunciation": "liàn ài", "ipa": "ljɛn˥˩ aɪ̯˥˩", "syllable_count": 2, "sentences": [{"text": "他们的恋爱很甜蜜。", "target_word": "恋爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一段美好的恋爱。", "target_word": "恋爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很快结束了这段恋爱。", "target_word": "恋爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "恋爱让他变得开心。", "target_word": "恋爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的恋爱没有公开。", "target_word": "恋爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校园里的恋爱常常很单纯。", "target_word": "恋爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影讲的是一场恋爱。", "target_word": "恋爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "恋爱需要互相了解。", "target_word": "恋爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不让父母知道她的恋爱。", "target_word": "恋爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过三年的恋爱，他们结婚了。", "target_word": "恋爱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一段恋爱", "label": "量词（段）"}, {"form": "一场恋爱", "label": "量词（场）"}, {"form": "恋爱关系", "label": "复合"}], "register": "中性", "sense_fingerprint": "男女互相爱慕、发展感情的过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8ab8815-7ec2-46b3-9bde-62defb4a82b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94932, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "恋爱", "is_correct": true, "explanation": "正确：“恋爱”作名词，指男女交往的过程，可与“甜蜜”搭配。"}, {"text": "考试", "is_correct": false, "explanation": "搭配：“甜蜜”形容感情或生活，不能形容“考试”。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”是一个数值，不能是“甜蜜”的。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”是地方，不能说“很甜蜜”。"}], "explanations": {"恋爱": "正确：“恋爱”作名词，指男女交往的过程，可与“甜蜜”搭配。", "考试": "搭配：“甜蜜”形容感情或生活，不能形容“考试”。", "体重": "语义：“体重”是一个数值，不能是“甜蜜”的。", "厨房": "语义：“厨房”是地方，不能说“很甜蜜”。"}, "sentence_index": 0, "correct_answer": "恋爱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是我的恋爱。", "explanation": "这里应该用〈恋人〉。“恋爱”指交往的过程，不指人。"}, {"text": "我最近遇到了一只恋爱。", "explanation": "这里应该用〈段〉。“只”不用于“恋爱”，应说“一段恋爱”。"}, {"text": "画画是他的恋爱。", "explanation": "这里应该用〈爱好〉。“恋爱”是男女交往的过程，不能当作兴趣爱好。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b85754-4e02-48ba-91d9-02715c9bae66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94932, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "恋爱", "is_correct": true, "explanation": "正确：“恋爱”作名词，与“一场”搭配，指一次恋爱经历。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不能作为电影讲述的内容。"}, {"text": "眼睛", "is_correct": false, "explanation": "搭配：量词“一场”不能修饰“眼睛”。"}, {"text": "数学", "is_correct": false, "explanation": "语义：“数学”是学科，电影不能讲一场数学。"}], "explanations": {"恋爱": "正确：“恋爱”作名词，与“一场”搭配，指一次恋爱经历。", "天气": "语义：“天气”不能作为电影讲述的内容。", "眼睛": "搭配：量词“一场”不能修饰“眼睛”。", "数学": "语义：“数学”是学科，电影不能讲一场数学。"}, "sentence_index": 6, "correct_answer": "恋爱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这门恋爱很有意思。", "explanation": "这里应该用〈段〉。“门”用于课程、学科，不用于“恋爱”。"}, {"text": "这本恋爱我看了两遍。", "explanation": "这里应该用〈小说〉。“恋爱”是男女交往的过程，不是能用“本”计量、能读的书。"}, {"text": "这场比赛的恋爱很激烈。", "explanation": "这里应该用〈竞争〉。“恋爱”指男女互相喜欢、交往，不指比赛中的竞争。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b85754-4e02-48ba-91d9-02715c9bae66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94932, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这段恋爱过让他很快乐。", "corrected_sentence": "这段恋爱让他很快乐。", "error_description": "“过”是经历体标记，只能紧跟动词，不能附在名词“恋爱”后。应去掉“过”，说“这段恋爱让他很快乐”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b85754-4e02-48ba-91d9-02715c9bae66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94932, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只恋爱让他很开心。", "corrected_sentence": "这段恋爱让他很开心。", "error_description": "“恋爱”的量词应为“段”。“只”只用于动物或成对物件中的一个，不能修饰“恋爱”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b85754-4e02-48ba-91d9-02715c9bae66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
