INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94933, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "招聘是找人来上班做事。", "primary_collocate": null, "pronunciation": "zhāo pìn", "ipa": "tʂɑʊ̯˥ pʰin˥˩", "syllable_count": 2, "sentences": [{"text": "我们公司想招聘两个新员工。", "target_word": "招聘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饭店最近在招聘服务员。", "target_word": "招聘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家商店招聘了三个新人。", "target_word": "招聘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们正在网上招聘新同事。", "target_word": "招聘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校招聘过一位英语老师。", "target_word": "招聘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说下个月要招聘工人。", "target_word": "招聘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司招聘新人时，先看经验。", "target_word": "招聘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂为什么招聘这么多工人？", "target_word": "招聘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们公司招聘会计吗？", "target_word": "招聘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月我们不招聘新人了。", "target_word": "招聘", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "招聘了", "label": "体标（完成）"}, {"form": "招聘过", "label": "体标（经历）"}, {"form": "招聘会", "label": "复合"}, {"form": "招聘广告", "label": "复合"}], "register": "中性", "sense_fingerprint": "公司或店铺找人来上班做事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '904ff82c-9949-44d4-8c88-d63d71ef0a8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94933, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "招聘", "is_correct": true, "explanation": "“招聘”表示公司找人来上班做事，与“我们公司想”和“两个新员工”搭配，符合句意。"}, {"text": "生产", "is_correct": false, "explanation": "语义：“生产”的对象是产品，不能用来指招人。"}, {"text": "研发", "is_correct": false, "explanation": "语义：“研发”针对技术或产品，不能用于人员。"}, {"text": "办理", "is_correct": false, "explanation": "搭配：“办理”的对象是手续或业务，不能说“办理两个新员工”。"}], "explanations": {"招聘": "“招聘”表示公司找人来上班做事，与“我们公司想”和“两个新员工”搭配，符合句意。", "生产": "语义：“生产”的对象是产品，不能用来指招人。", "研发": "语义：“研发”针对技术或产品，不能用于人员。", "办理": "搭配：“办理”的对象是手续或业务，不能说“办理两个新员工”。"}, "sentence_index": 0, "correct_answer": "招聘"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们公司招聘了一批新设备。", "explanation": "这里应该用〈采购〉。招聘指公开招人做事，买进设备要用采购。"}, {"text": "他招聘朋友来家里吃饭。", "explanation": "这里应该用〈邀请〉。招聘指公开找人担任职位，请朋友来吃饭要用邀请。"}, {"text": "我们招聘了一套办公室。", "explanation": "这里应该用〈租用〉。招聘用于招人，租一套办公室要用租用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80ec9804-5013-493b-b350-1068aecf33b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94933, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "招聘", "is_correct": true, "explanation": "“招聘”表示公司找人来上班做事，与“公司”和“新人”搭配，符合句意。"}, {"text": "出售", "is_correct": false, "explanation": "语义：“出售”是卖东西，不能用于招收新人。"}, {"text": "打印", "is_correct": false, "explanation": "语义：“打印”的对象是文件，与“新人”不相符。"}, {"text": "装修", "is_correct": false, "explanation": "搭配：“装修”的对象是房屋或场所，不能说“装修新人”。"}], "explanations": {"招聘": "“招聘”表示公司找人来上班做事，与“公司”和“新人”搭配，符合句意。", "出售": "语义：“出售”是卖东西，不能用于招收新人。", "打印": "语义：“打印”的对象是文件，与“新人”不相符。", "装修": "搭配：“装修”的对象是房屋或场所，不能说“装修新人”。"}, "sentence_index": 6, "correct_answer": "招聘"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校今年招聘了一百名学生。", "explanation": "这里应该用〈招生〉。招聘指招收员工，招收学生要用招生。"}, {"text": "我们招聘了一份合同。", "explanation": "这里应该用〈寄送〉。招聘用于招人，寄出合同要用寄送。"}, {"text": "商店招聘了很多水果。", "explanation": "这里应该用〈出售〉。招聘用于招人，商店卖水果要用出售。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80ec9804-5013-493b-b350-1068aecf33b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94933, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们这个月很招聘新人。", "corrected_sentence": "我们这个月不招聘新人。", "error_description": "副词错误：「很」不能修饰「招聘」这类动作动词，此处应用否定副词「不」。应把「很」改为「不」，说「我们这个月不招聘新人」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80ec9804-5013-493b-b350-1068aecf33b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94933, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下个月公司招聘过新人。", "corrected_sentence": "下个月公司招聘新人。", "error_description": "时态错误：“过”表示曾经发生的动作，不能用于将来的“下个月”，应去掉“过”，说“下个月公司招聘新人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80ec9804-5013-493b-b350-1068aecf33b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
