INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94934, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "公开征召人员担任职位。", "primary_collocate": null, "pronunciation": "zhāo pìn", "ipa": "tʂɑʊ̯˥ pʰin˥˩", "syllable_count": 2, "sentences": [{"text": "市政府公开招聘十名工作人员。", "target_word": "招聘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院向社会招聘一名院长。", "target_word": "招聘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所大学正在招聘新老师。", "target_word": "招聘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司在网上公开招聘经理。", "target_word": "招聘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上说，银行要招聘职员。", "target_word": "招聘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校今年招聘了五位老师。", "target_word": "招聘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看到医院招聘护士的消息。", "target_word": "招聘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司想招聘一位总经理。", "target_word": "招聘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府向全国招聘专家。", "target_word": "招聘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要把招聘的消息发到网上。", "target_word": "招聘", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "招聘了", "label": "体标（完成）"}, {"form": "招聘过", "label": "体标（经历）"}, {"form": "招聘会", "label": "复合"}, {"form": "招聘信息", "label": "复合"}], "register": "中性", "sense_fingerprint": "机构公开征召人员担任某个职位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '904ff82c-9949-44d4-8c88-d63d71ef0a8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94934, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "招聘", "is_correct": true, "explanation": "“招聘”表示机构公开征召人员担任职位，与“市政府公开”和“十名工作人员”搭配，符合句意。"}, {"text": "出版", "is_correct": false, "explanation": "语义：“出版”是印行书刊，不能用于征召人员。"}, {"text": "发放", "is_correct": false, "explanation": "搭配：“发放”的对象是补贴或物资，不能说“发放十名工作人员”。"}, {"text": "开采", "is_correct": false, "explanation": "语义：“开采”针对矿藏或资源，与征召人员无关。"}], "explanations": {"招聘": "“招聘”表示机构公开征召人员担任职位，与“市政府公开”和“十名工作人员”搭配，符合句意。", "出版": "语义：“出版”是印行书刊，不能用于征召人员。", "发放": "搭配：“发放”的对象是补贴或物资，不能说“发放十名工作人员”。", "开采": "语义：“开采”针对矿藏或资源，与征召人员无关。"}, "sentence_index": 0, "correct_answer": "招聘"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校招聘了一批作品。", "explanation": "这里应该用〈征集〉。招聘指公开征召人员担任职位，征集作品要用征集。"}, {"text": "报社招聘了一条新闻。", "explanation": "这里应该用〈发布〉。招聘用于征召人员，报社发布新闻要用发布。"}, {"text": "学校招聘了考试成绩。", "explanation": "这里应该用〈公布〉。招聘用于征召人员，公开考试成绩要用公布。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80ec9804-5013-493b-b350-1068aecf33b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94934, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "招聘", "is_correct": true, "explanation": "“招聘”表示机构公开征召人员担任职位，与“他看到医院”和“护士的消息”搭配，符合句意。"}, {"text": "收购", "is_correct": false, "explanation": "语义：“收购”是买进物品，与“护士的消息”不相符。"}, {"text": "批发", "is_correct": false, "explanation": "语义：“批发”是按批卖货，不能用于消息。"}, {"text": "烹饪", "is_correct": false, "explanation": "搭配：“烹饪”的对象是食物，不能说“烹饪护士的消息”。"}], "explanations": {"招聘": "“招聘”表示机构公开征召人员担任职位，与“他看到医院”和“护士的消息”搭配，符合句意。", "收购": "语义：“收购”是买进物品，与“护士的消息”不相符。", "批发": "语义：“批发”是按批卖货，不能用于消息。", "烹饪": "搭配：“烹饪”的对象是食物，不能说“烹饪护士的消息”。"}, "sentence_index": 6, "correct_answer": "招聘"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司招聘了一家工厂。", "explanation": "这里应该用〈收购〉。招聘指征召人员，买下一家工厂要用收购。"}, {"text": "画廊招聘了一幅名画。", "explanation": "这里应该用〈收藏〉。招聘用于征召人员，画廊买进并保存名画要用收藏。"}, {"text": "出版社招聘了一本新书。", "explanation": "这里应该用〈出版〉。招聘用于征召人员，出版社印行书籍要用出版。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80ec9804-5013-493b-b350-1068aecf33b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94934, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市政府去年向社会招聘着两名会计。", "corrected_sentence": "市政府去年向社会招聘过两名会计。", "error_description": "体标错误：“去年”指已经发生的招聘，表示经历应用“过”；“着”表示动作持续或状态保持，与已完成的时间状语不相容。“招聘着”应改为“招聘过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80ec9804-5013-493b-b350-1068aecf33b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94934, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医院去年招聘着两名护士。", "corrected_sentence": "医院去年招聘过两名护士。", "error_description": "体标错误：“去年”指已经发生过的招聘，表示经历要用“过”，“着”表示持续状态，不能用于已完成的动作。“招聘着”应改为“招聘过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80ec9804-5013-493b-b350-1068aecf33b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
