INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94935, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "挖是用手或工具把土往外拿出来。", "primary_collocate": null, "pronunciation": "wā", "ipa": "wa˥", "syllable_count": 1, "sentences": [{"text": "爸爸用铁锹在院子里挖了一个坑。", "target_word": "挖", "sentence_source": "generated"}, {"text": "孩子们在沙滩上挖沙子玩。", "target_word": "挖", "sentence_source": "generated"}, {"text": "他们要挖一条小河，把水引过来。", "target_word": "挖", "sentence_source": "generated"}, {"text": "农民正在地里挖土豆。", "target_word": "挖", "sentence_source": "generated"}, {"text": "小狗用爪子挖地，想找骨头。", "target_word": "挖", "sentence_source": "generated"}, {"text": "我们在树下挖了很久，什么也没找到。", "target_word": "挖", "sentence_source": "generated"}, {"text": "他挖了一个深洞，把树种在里面。", "target_word": "挖", "sentence_source": "generated"}, {"text": "工人们正在路边挖沟。", "target_word": "挖", "sentence_source": "generated"}, {"text": "请你帮我把这块地挖开。", "target_word": "挖", "sentence_source": "generated"}, {"text": "春天到了，奶奶在门口挖野菜。", "target_word": "挖", "sentence_source": "generated"}], "morphological_forms": [{"form": "挖了", "label": "体标"}, {"form": "挖着", "label": "体标"}, {"form": "挖过", "label": "体标"}, {"form": "挖掘", "label": "复合"}], "register": "口语", "sense_fingerprint": "用手或工具把土拿出来，挖坑、挖沟", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce87e407-f827-4d11-8490-1be803ed23ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94935, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "挖", "is_correct": true, "explanation": "正确答案：挖（wā，第一声），指用手或工具把土往外拿。"}, {"text": "瓦", "is_correct": false, "explanation": "wǎ（第三声）与 wā（第一声）声调不同，意思是瓦片。"}, {"text": "娃", "is_correct": false, "explanation": "wá（第二声）与 wā（第一声）声调不同，意思是娃娃。"}, {"text": "袜", "is_correct": false, "explanation": "wà（第四声）与 wā（第一声）声调不同，意思是袜子。"}, {"text": "歪", "is_correct": false, "explanation": "wāi 与 wā 韵母不同（多一个 i），意思是歪斜。"}], "explanations": {"挖": "正确答案：挖（wā，第一声），指用手或工具把土往外拿。", "瓦": "wǎ（第三声）与 wā（第一声）声调不同，意思是瓦片。", "娃": "wá（第二声）与 wā（第一声）声调不同，意思是娃娃。", "袜": "wà（第四声）与 wā（第一声）声调不同，意思是袜子。", "歪": "wāi 与 wā 韵母不同（多一个 i），意思是歪斜。"}, "sentence_index": null, "correct_answer": "挖"}, "level_3": {"options": [{"text": "挖", "is_correct": true, "explanation": "正确。“挖了一个坑”指用铁锹把土往外拿，形成坑。"}, {"text": "种", "is_correct": false, "explanation": "语义：“种”指栽种植物，不能用来形容挖坑。"}, {"text": "砍", "is_correct": false, "explanation": "语义：“砍”指用刀斧切断，不是把土拿出来。"}, {"text": "扫", "is_correct": false, "explanation": "搭配：“扫”用于扫地、扫落叶等，不能说扫坑。"}], "explanations": {"挖": "正确。“挖了一个坑”指用铁锹把土往外拿，形成坑。", "种": "语义：“种”指栽种植物，不能用来形容挖坑。", "砍": "语义：“砍”指用刀斧切断，不是把土拿出来。", "扫": "搭配：“扫”用于扫地、扫落叶等，不能说扫坑。"}, "sentence_index": 0, "correct_answer": "挖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "农民正在地里挖西红柿。", "explanation": "这里应该用〈摘〉。摘用于果实、蔬菜，西红柿长在枝上，不用挖。"}, {"text": "孩子在树下挖苹果。", "explanation": "这里应该用〈捡〉。苹果掉在地上要说“捡”，挖用于从土里取东西。"}, {"text": "他把水挖进杯子里。", "explanation": "这里应该用〈倒〉。水是液体，要说“倒”，挖用于从土中取出东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a05b7c-f2b6-4f9e-9778-b4e1b1536d57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94935, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "挖", "is_correct": true, "explanation": "正确答案：挖（wā，第一声），指用手或工具把土往外拿。"}, {"text": "花", "is_correct": false, "explanation": "huā 与 wā 声母不同（多了 h），意思是花朵。"}, {"text": "瓜", "is_correct": false, "explanation": "guā 与 wā 声母不同（多了 g），意思是瓜类。"}, {"text": "夸", "is_correct": false, "explanation": "kuā 与 wā 声母不同（k 对 w），意思是夸奖。"}, {"text": "湾", "is_correct": false, "explanation": "wān 与 wā 韵母不同（多了 n），意思是海湾。"}], "explanations": {"挖": "正确答案：挖（wā，第一声），指用手或工具把土往外拿。", "花": "huā 与 wā 声母不同（多了 h），意思是花朵。", "瓜": "guā 与 wā 声母不同（多了 g），意思是瓜类。", "夸": "kuā 与 wā 声母不同（k 对 w），意思是夸奖。", "湾": "wān 与 wā 韵母不同（多了 n），意思是海湾。"}, "sentence_index": null, "correct_answer": "挖"}, "level_3": {"options": [{"text": "挖", "is_correct": true, "explanation": "正确。“挖了一个深洞”指用工具把土往外拿，形成深洞，便于种树。"}, {"text": "拿", "is_correct": false, "explanation": "语义：“拿”指取物，不能拿出一个洞。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”指书写，不能写出一个洞。"}, {"text": "抬", "is_correct": false, "explanation": "搭配：“抬”的对象应是可以搬动的东西，洞不能抬。"}], "explanations": {"挖": "正确。“挖了一个深洞”指用工具把土往外拿，形成深洞，便于种树。", "拿": "语义：“拿”指取物，不能拿出一个洞。", "写": "语义：“写”指书写，不能写出一个洞。", "抬": "搭配：“抬”的对象应是可以搬动的东西，洞不能抬。"}, "sentence_index": 6, "correct_answer": "挖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们在院子里挖落叶。", "explanation": "这里应该用〈烧〉。落叶可以烧或扫，挖用于从土中取东西，不能用于落叶。"}, {"text": "妈妈在厨房挖菜。", "explanation": "这里应该用〈洗〉。菜要用“洗”，挖用于从土中取东西。"}, {"text": "他挖了一杯水。", "explanation": "这里应该用〈喝〉。水是液体，挖用于从土中取东西，不能用于液体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a05b7c-f2b6-4f9e-9778-b4e1b1536d57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94935, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块地太硬了，我们挖动得吗？", "corrected_sentence": "这块地太硬了，我们挖得动吗？", "error_description": "可能补语语序错误：“挖得动”中“得”应放在“挖”和“动”之间，说“挖动得”是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a05b7c-f2b6-4f9e-9778-b4e1b1536d57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94935, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人们把这个坑挖了好。", "corrected_sentence": "工人们把这个坑挖好了。", "error_description": "补语语序错误：结果补语“好”应紧跟动词“挖”，说“挖好了”，不能说“挖了好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a05b7c-f2b6-4f9e-9778-b4e1b1536d57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
