INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94937, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "提起是说到一件事。", "primary_collocate": null, "pronunciation": "tí qǐ", "ipa": "tʰi˧˥ t͡ɕʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "奶奶总爱提起年轻时的故事。", "target_word": "提起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会时，他提起了新计划。", "target_word": "提起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想再提起那次比赛。", "target_word": "提起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "提起北京，我就想到烤鸭。", "target_word": "提起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从没提起过自己的病。", "target_word": "提起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一提起考试就紧张。", "target_word": "提起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们都没提起这个问题。", "target_word": "提起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸偶尔会提起他的老朋友。", "target_word": "提起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为什么突然提起他？", "target_word": "提起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们聊天时，她提起了新工作。", "target_word": "提起", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "提起了", "label": "完成体"}, {"form": "提起过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "在说话时说到、提到某件事或某个人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8ab8815-7ec2-46b3-9bde-62defb4a82b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94937, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "提起", "is_correct": true, "explanation": "正确：“提起”表示说到，与“总爱”搭配，指常常谈起。"}, {"text": "扔", "is_correct": false, "explanation": "搭配：“扔”是抛掉具体的物，不能用于“故事”。"}, {"text": "熄灭", "is_correct": false, "explanation": "搭配：“熄灭”用于火、光等，不能说“熄灭故事”。"}, {"text": "修剪", "is_correct": false, "explanation": "语义：“修剪”是对植物或头发的加工，与“故事”不相干。"}], "explanations": {"提起": "正确：“提起”表示说到，与“总爱”搭配，指常常谈起。", "扔": "搭配：“扔”是抛掉具体的物，不能用于“故事”。", "熄灭": "搭配：“熄灭”用于火、光等，不能说“熄灭故事”。", "修剪": "语义：“修剪”是对植物或头发的加工，与“故事”不相干。"}, "sentence_index": 0, "correct_answer": "提起"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这段时间他的英语水平提起了很多。", "explanation": "这里应该用〈提高〉。“提起”指说到或拿起，不能表示水平上升；水平要用“提高”。"}, {"text": "这个月我的体重提起了三公斤。", "explanation": "这里应该用〈增加〉。“提起”不表示数量上升，体重要用“增加”。"}, {"text": "我们提起吃饭吧。", "explanation": "这里应该用〈开始〉。“提起”是说到，不表示开始做事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b85754-4e02-48ba-91d9-02715c9bae66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94937, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "提起", "is_correct": true, "explanation": "正确：“提起”表示说到，与“都没”搭配，指没有人谈起。"}, {"text": "撞", "is_correct": false, "explanation": "语义：“撞”是碰撞，不能用于谈论“问题”。"}, {"text": "点燃", "is_correct": false, "explanation": "搭配：“点燃”用于火、热情，不能与“问题”搭配。"}, {"text": "喂", "is_correct": false, "explanation": "语义：“喂”的对象是人或动物，不能用于“问题”。"}], "explanations": {"提起": "正确：“提起”表示说到，与“都没”搭配，指没有人谈起。", "撞": "语义：“撞”是碰撞，不能用于谈论“问题”。", "点燃": "搭配：“点燃”用于火、热情，不能与“问题”搭配。", "喂": "语义：“喂”的对象是人或动物，不能用于“问题”。"}, "sentence_index": 6, "correct_answer": "提起"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今年的收入提起了两成。", "explanation": "这里应该用〈增加〉。“提起”指说到或拿起，不能表示收入上升；收入上升要用“增加”。"}, {"text": "她很提起父母。", "explanation": "这里应该用〈想念〉。“提起”指说到，不表示心里挂念。"}, {"text": "她提起了大海，走进了厨房。", "explanation": "这里应该用〈眺望〉。“提起”指拿起或说到，不能用于看向大海。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b85754-4e02-48ba-91d9-02715c9bae66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94937, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爸爸从没提起过这件事了。", "corrected_sentence": "爸爸从没提起过这件事。", "error_description": "错误：“从没……过”表示从未有过的经历，句末多加的“了”与之冲突，应去掉，说“从没提起过这件事”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b85754-4e02-48ba-91d9-02715c9bae66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94937, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她聊天时提起着那件事。", "corrected_sentence": "她聊天时提起了那件事。", "error_description": "错误：“提起”表示已经说到的动作，应用完成体“了”，不能用持续体“着”，应为“提起了那件事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b85754-4e02-48ba-91d9-02715c9bae66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
