INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94939, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "擦是用布来回动，让东西干净。", "primary_collocate": null, "pronunciation": "cā", "ipa": "tsʰa˥", "syllable_count": 1, "sentences": [{"text": "请你把桌子擦干净。", "target_word": "擦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用布擦黑板。", "target_word": "擦", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈每天都擦窗户。", "target_word": "擦", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我擦了擦眼镜。", "target_word": "擦", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子哭了，妈妈给他擦眼泪。", "target_word": "擦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饭后她把桌子擦了一遍。", "target_word": "擦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他正擦着汽车上的灰。", "target_word": "擦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你擦过这块玻璃吗？", "target_word": "擦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "擦完地以后，我们一起吃饭。", "target_word": "擦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地板太脏了，我要用湿布擦。", "target_word": "擦", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "擦了", "label": "体标（了）"}, {"form": "擦着", "label": "体标（着）"}, {"form": "擦过", "label": "体标（过）"}, {"form": "擦擦", "label": "重叠"}], "register": "中性", "sense_fingerprint": "用布来回擦东西使干净", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8ab8815-7ec2-46b3-9bde-62defb4a82b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94939, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "擦", "is_correct": true, "explanation": "擦 cā：用布或手来回擦拭，使东西干净。"}, {"text": "猜", "is_correct": false, "explanation": "cāi（第一声）与 cā 韵母不同（a/ai），意思是猜测。"}, {"text": "叉", "is_correct": false, "explanation": "chā（第一声）与 cā 声母不同（c/ch），意思是叉子。"}, {"text": "插", "is_correct": false, "explanation": "chā（第一声）与 cā 声母不同（c/ch），意思是插入。"}, {"text": "参", "is_correct": false, "explanation": "cān（第一声）与 cā 韵母多一个 n，意思是参加。"}], "explanations": {"擦": "擦 cā：用布或手来回擦拭，使东西干净。", "猜": "cāi（第一声）与 cā 韵母不同（a/ai），意思是猜测。", "叉": "chā（第一声）与 cā 声母不同（c/ch），意思是叉子。", "插": "chā（第一声）与 cā 声母不同（c/ch），意思是插入。", "参": "cān（第一声）与 cā 韵母多一个 n，意思是参加。"}, "sentence_index": null, "correct_answer": "擦"}, "level_3": {"options": [{"text": "擦", "is_correct": true, "explanation": "擦：用布来回擦，使桌子干净，与“干净”搭配。"}, {"text": "切", "is_correct": false, "explanation": "语义：切是割开，不能把桌子切干净。"}, {"text": "抬", "is_correct": false, "explanation": "语义：抬是托起，不能把桌子抬干净。"}, {"text": "嚼", "is_correct": false, "explanation": "搭配：嚼的对象是食物，“嚼干净”不能用于桌子。"}], "explanations": {"擦": "擦：用布来回擦，使桌子干净，与“干净”搭配。", "切": "语义：切是割开，不能把桌子切干净。", "抬": "语义：抬是托起，不能把桌子抬干净。", "嚼": "搭配：嚼的对象是食物，“嚼干净”不能用于桌子。"}, "sentence_index": 0, "correct_answer": "擦"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他擦了一封信给朋友。", "explanation": "这里应该用〈写〉。擦是用布来回动让东西干净，写信要说写，不能说擦。"}, {"text": "他用斧头擦柴。", "explanation": "这里应该用〈砍〉。擦是用布来回动让东西干净，用斧头劈木柴要说砍，不能说擦。"}, {"text": "他把旧报纸擦了。", "explanation": "这里应该用〈扔〉。擦是用布来回动让东西干净，丢掉旧报纸要说扔，不能说擦。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b85754-4e02-48ba-91d9-02715c9bae66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94939, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "擦", "is_correct": true, "explanation": "擦 cā：用布或手来回擦拭，使东西干净。"}, {"text": "操", "is_correct": false, "explanation": "cāo（第一声）与 cā 只多一个韵尾 -o，意思是操练。"}, {"text": "餐", "is_correct": false, "explanation": "cān（第一声）与 cā 韵母多一个 n，意思是餐。"}, {"text": "仓", "is_correct": false, "explanation": "cāng（第一声）与 cā 韵母多一个 ng，意思是仓库。"}], "explanations": {"擦": "擦 cā：用布或手来回擦拭，使东西干净。", "操": "cāo（第一声）与 cā 只多一个韵尾 -o，意思是操练。", "餐": "cān（第一声）与 cā 韵母多一个 n，意思是餐。", "仓": "cāng（第一声）与 cā 韵母多一个 ng，意思是仓库。"}, "sentence_index": null, "correct_answer": "擦"}, "level_3": {"options": [{"text": "擦", "is_correct": true, "explanation": "擦：用布擦拭，使汽车上的灰去掉，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：吃是把食物咽下，不能吃掉灰。"}, {"text": "抱", "is_correct": false, "explanation": "搭配：抱要求对象是可以抱起的东西，灰尘不能被抱。"}, {"text": "搬", "is_correct": false, "explanation": "语义：搬是搬运，灰不能被搬去。"}], "explanations": {"擦": "擦：用布擦拭，使汽车上的灰去掉，符合句意。", "吃": "语义：吃是把食物咽下，不能吃掉灰。", "抱": "搭配：抱要求对象是可以抱起的东西，灰尘不能被抱。", "搬": "语义：搬是搬运，灰不能被搬去。"}, "sentence_index": 6, "correct_answer": "擦"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他擦了一杯茶。", "explanation": "这里应该用〈喝〉。擦是用布来回动让东西干净，喝茶要说喝，不能说擦。"}, {"text": "他擦了一碗面条。", "explanation": "这里应该用〈吃〉。擦是用布来回动让东西干净，吃面条要说吃，不能说擦。"}, {"text": "她擦起了歌。", "explanation": "这里应该用〈唱〉。擦是用布来回动让东西干净，唱歌要说唱，不能说擦。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b85754-4e02-48ba-91d9-02715c9bae66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94939, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把碗完擦了。", "corrected_sentence": "他把碗擦完了。", "error_description": "补语位置错误：“完”是结果补语，必须紧跟动词“擦”，应说“擦完”，不能放在“擦”前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b85754-4e02-48ba-91d9-02715c9bae66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94939, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你过擦那面镜子吗？", "corrected_sentence": "你擦过那面镜子吗？", "error_description": "体标位置错误：“过”是动态助词，必须紧跟动词“擦”，应说“擦过”，不能放在“擦”前面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b85754-4e02-48ba-91d9-02715c9bae66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
