INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94940, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用布、手等在物体表面来回摩擦，使之干净。", "primary_collocate": null, "pronunciation": "cā", "ipa": "tsʰa˥", "syllable_count": 1, "sentences": [{"text": "他用手擦了擦脸上的汗。", "target_word": "擦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃完饭，请用纸巾擦嘴。", "target_word": "擦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她擦干眼泪，笑了。", "target_word": "擦", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的手湿了，要擦一下。", "target_word": "擦", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用袖子擦着额头的汗。", "target_word": "擦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗完手，你用毛巾擦干。", "target_word": "擦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把鞋擦得很亮。", "target_word": "擦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子用手擦鼻子。", "target_word": "擦", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "脸上有水，快擦一擦。", "target_word": "擦", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "跑完步，他拿毛巾擦汗。", "target_word": "擦", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "擦了", "label": "体标（了）"}, {"form": "擦着", "label": "体标（着）"}, {"form": "擦过", "label": "体标（过）"}, {"form": "擦擦", "label": "重叠"}], "register": "中性", "sense_fingerprint": "用布或手在表面来回擦拭", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8ab8815-7ec2-46b3-9bde-62defb4a82b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94940, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "擦", "is_correct": true, "explanation": "擦 cā：用布或手在表面来回擦拭，使之干净。"}, {"text": "操", "is_correct": false, "explanation": "cāo（第一声）与 cā 只多一个韵尾 -o，意思是操练。"}, {"text": "叉", "is_correct": false, "explanation": "chā（第一声）与 cā 声母不同（c/ch），意思是叉子。"}, {"text": "参", "is_correct": false, "explanation": "cān（第一声）与 cā 韵母多一个 n，意思是参加。"}, {"text": "仓", "is_correct": false, "explanation": "cāng（第一声）与 cā 韵母多一个 ng，意思是仓库。"}], "explanations": {"擦": "擦 cā：用布或手在表面来回擦拭，使之干净。", "操": "cāo（第一声）与 cā 只多一个韵尾 -o，意思是操练。", "叉": "chā（第一声）与 cā 声母不同（c/ch），意思是叉子。", "参": "cān（第一声）与 cā 韵母多一个 n，意思是参加。", "仓": "cāng（第一声）与 cā 韵母多一个 ng，意思是仓库。"}, "sentence_index": null, "correct_answer": "擦"}, "level_3": {"options": [{"text": "擦", "is_correct": true, "explanation": "擦：“擦了擦”是动词重叠，表示轻轻擦一下脸上的汗。"}, {"text": "吃", "is_correct": false, "explanation": "语义：吃是把食物咽下，不能吃掉脸上的汗。"}, {"text": "扔", "is_correct": false, "explanation": "搭配：“扔”不能跟“汗”搭配，汗不能被扔掉。"}, {"text": "撒", "is_correct": false, "explanation": "语义：撒是洒落、散开，不能表示擦去汗水。"}], "explanations": {"擦": "擦：“擦了擦”是动词重叠，表示轻轻擦一下脸上的汗。", "吃": "语义：吃是把食物咽下，不能吃掉脸上的汗。", "扔": "搭配：“扔”不能跟“汗”搭配，汗不能被扔掉。", "撒": "语义：撒是洒落、散开，不能表示擦去汗水。"}, "sentence_index": 0, "correct_answer": "擦"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他擦了一场电影。", "explanation": "这里应该用〈看〉。擦是用布或手来回擦拭，看电影要说看，不能说擦。"}, {"text": "他把信擦成了两半。", "explanation": "这里应该用〈撕〉。擦是用布来回动让东西干净，把信撕成两半要说撕，不能说擦。"}, {"text": "他在操场上擦了三圈。", "explanation": "这里应该用〈跑〉。擦是用布来回动让东西干净，绕操场跑圈要说跑，不能说擦。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b85754-4e02-48ba-91d9-02715c9bae66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94940, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "擦", "is_correct": true, "explanation": "擦 cā：用布或手在表面来回擦拭，使之干净。"}, {"text": "猜", "is_correct": false, "explanation": "cāi（第一声）与 cā 韵母不同（a/ai），意思是猜测。"}, {"text": "插", "is_correct": false, "explanation": "chā（第一声）与 cā 声母不同（c/ch），意思是插入。"}, {"text": "餐", "is_correct": false, "explanation": "cān（第一声）与 cā 韵母多一个 n，意思是餐。"}], "explanations": {"擦": "擦 cā：用布或手在表面来回擦拭，使之干净。", "猜": "cāi（第一声）与 cā 韵母不同（a/ai），意思是猜测。", "插": "chā（第一声）与 cā 声母不同（c/ch），意思是插入。", "餐": "cān（第一声）与 cā 韵母多一个 n，意思是餐。"}, "sentence_index": null, "correct_answer": "擦"}, "level_3": {"options": [{"text": "擦", "is_correct": true, "explanation": "擦：用布擦拭，使鞋面变亮，与“得很亮”搭配。"}, {"text": "搬", "is_correct": false, "explanation": "语义：搬是搬运，不能把鞋搬亮。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：唱的对象是歌，“唱得很亮”不能用于鞋。"}, {"text": "咬", "is_correct": false, "explanation": "语义：咬是用牙齿夹住，不能咬出光亮。"}], "explanations": {"擦": "擦：用布擦拭，使鞋面变亮，与“得很亮”搭配。", "搬": "语义：搬是搬运，不能把鞋搬亮。", "唱": "搭配：唱的对象是歌，“唱得很亮”不能用于鞋。", "咬": "语义：咬是用牙齿夹住，不能咬出光亮。"}, "sentence_index": 6, "correct_answer": "擦"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他擦了一本小说。", "explanation": "这里应该用〈看〉。擦是用布或手来回擦拭，看小说要说看，不能说擦。"}, {"text": "他擦了一首曲子。", "explanation": "这里应该用〈弹〉。擦是用布来回动让东西干净，弹奏曲子要说弹，不能说擦。"}, {"text": "他擦上了外套。", "explanation": "这里应该用〈穿〉。擦是用布来回动让东西干净，把外套穿在身上要说穿，不能说擦。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b85754-4e02-48ba-91d9-02715c9bae66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94940, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他擦得一下桌子。", "corrected_sentence": "他擦了一下桌子。", "error_description": "体标用错：表示动作完成的动量补语句中，“擦”后应用“了”，说“擦了一下”，不能用“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b85754-4e02-48ba-91d9-02715c9bae66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94940, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把皮鞋擦明了。", "corrected_sentence": "他把皮鞋擦亮了。", "error_description": "结果补语用错：“擦明”不成立，应说“擦亮”，表示擦得发光。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b85754-4e02-48ba-91d9-02715c9bae66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
