INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94941, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "救援是去帮助有危险的人。", "primary_collocate": null, "pronunciation": "jiù yuán", "ipa": "tɕjoʊ˥˩ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "消防员马上去救援被困的人。", "target_word": "救援", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震以后，很多人来这里救援。", "target_word": "救援", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "救援人员已经到了河边。", "target_word": "救援", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们救援了三天三夜。", "target_word": "救援", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雨中，救援队还在工作。", "target_word": "救援", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次救援很成功。", "target_word": "救援", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们请求救援，可是没有人回答。", "target_word": "救援", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察和医生一起救援受伤的人。", "target_word": "救援", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他参加过那次山上的救援。", "target_word": "救援", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里下雪了，很难去救援被困的人。", "target_word": "救援", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "救援了", "label": "体标"}, {"form": "救援过", "label": "体标"}, {"form": "救援队", "label": "复合"}, {"form": "救援人员", "label": "复合"}], "register": "中性", "sense_fingerprint": "去帮助处在危险中的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9338e44a-02f0-4ff6-8511-9734bc7b6a50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94941, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "救援", "is_correct": true, "explanation": "救援 jiù yuán：去帮助处于危险中的人，是本词的意思。"}, {"text": "旧怨", "is_correct": false, "explanation": "旧怨 jiù yuàn 与救援的第二个音节声调不同（怨是第四声，援是第二声），意思是以前结下的怨恨。"}, {"text": "久远", "is_correct": false, "explanation": "久远 jiǔ yuǎn 与救援的两个音节声调都不同（久、远都是第三声），意思是年代久远。"}, {"text": "九元", "is_correct": false, "explanation": "九元 jiǔ yuán 与救援的第一个音节声调不同（九是第三声，救是第四声），意思是九块钱。"}], "explanations": {"救援": "救援 jiù yuán：去帮助处于危险中的人，是本词的意思。", "旧怨": "旧怨 jiù yuàn 与救援的第二个音节声调不同（怨是第四声，援是第二声），意思是以前结下的怨恨。", "久远": "久远 jiǔ yuǎn 与救援的两个音节声调都不同（久、远都是第三声），意思是年代久远。", "九元": "九元 jiǔ yuán 与救援的第一个音节声调不同（九是第三声，救是第四声），意思是九块钱。"}, "sentence_index": null, "correct_answer": "救援"}, "level_3": {"options": [{"text": "救援", "is_correct": true, "explanation": "救援：到现场去援救被困的人，与消防员的职责和“马上去”相符。"}, {"text": "逃避", "is_correct": false, "explanation": "语义：逃避是躲开，与“马上去”帮助被困的人的意思相反。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”用于地点或展览，不能用来表示去接近并帮助被困的人。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：欢迎是迎接客人，与消防员去营救被困者的情境不符。"}], "explanations": {"救援": "救援：到现场去援救被困的人，与消防员的职责和“马上去”相符。", "逃避": "语义：逃避是躲开，与“马上去”帮助被困的人的意思相反。", "参观": "搭配：“参观”用于地点或展览，不能用来表示去接近并帮助被困的人。", "欢迎": "语义：欢迎是迎接客人，与消防员去营救被困者的情境不符。"}, "sentence_index": 0, "correct_answer": "救援"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天救援同学复习功课。", "explanation": "这里应该用〈帮助〉。救援只用于人处于危险之中的紧急援救，帮同学复习功课要用帮助。"}, {"text": "警察正在救援这起抢劫案。", "explanation": "这里应该用〈调查〉。救援的对象是遇险的人，不能用于案件。"}, {"text": "周末我去医院救援生病的奶奶。", "explanation": "这里应该用〈探望〉。救援指紧急情况下把人救出危险，去医院看望生病的人要用探望。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babba5e0-0b28-42d0-8f55-614438535d6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94941, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "救援", "is_correct": true, "explanation": "救援：请求去援救遇险的人，与后文“没有人回答”的求救语境相符。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：请求和拒绝意思相反，“请求拒绝”的说法不通。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：没有人会请求被嘲笑，与求助的语境相矛盾。"}, {"text": "祝贺", "is_correct": false, "explanation": "搭配：“请求”后面接的是帮助、许可等，不接“祝贺”。"}], "explanations": {"救援": "救援：请求去援救遇险的人，与后文“没有人回答”的求救语境相符。", "拒绝": "语义：请求和拒绝意思相反，“请求拒绝”的说法不通。", "嘲笑": "语义：没有人会请求被嘲笑，与求助的语境相矛盾。", "祝贺": "搭配：“请求”后面接的是帮助、许可等，不接“祝贺”。"}, "sentence_index": 6, "correct_answer": "救援"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天都救援房间，屋子很干净。", "explanation": "这里应该用〈打扫〉。救援只用于把遇险的人救出来，不能用于房间这类物品。"}, {"text": "父母一直救援我的决定。", "explanation": "这里应该用〈支持〉。救援指援救处于危险中的人，不能用于抽象的决定。"}, {"text": "妈妈每天救援孩子上学。", "explanation": "这里应该用〈接送〉。救援指紧急情况下的援救，不用于日常接送孩子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babba5e0-0b28-42d0-8f55-614438535d6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94941, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "消防员赶去把救援被困的司机。", "corrected_sentence": "消防员赶去救援被困的司机。", "error_description": "错误：动词“救援”前多加了介词“把”。“把”字句的“把”后应接被处置的宾语，“救援”是动作动词，不能直接接在“把”后面。正确应为“赶去救援被困的司机”，去掉“把”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babba5e0-0b28-42d0-8f55-614438535d6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94941, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们应该马上被救援被困的人。", "corrected_sentence": "他们应该马上救援被困的人。", "error_description": "错误：动词“救援”前多加了“被”，形成被动式。“救援”是及物动词，后面已带宾语“被困的人”，不能再用“被”字结构。正确应为“应该马上救援被困的人”，去掉“被”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babba5e0-0b28-42d0-8f55-614438535d6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
