INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94942, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babba5e0-0b28-42d0-8f55-614438535d6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94942, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "前去援助处于危险之中的人，使其脱险。", "primary_collocate": null, "pronunciation": "jiù yuán", "ipa": "tɕjoʊ˥˩ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "消防队很快赶到现场救援。", "target_word": "救援", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生坐飞机去山区救援。", "target_word": "救援", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洪水来了，战士们马上去救援。", "target_word": "救援", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "消防车已经出发去救援了。", "target_word": "救援", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用船救援河中的人。", "target_word": "救援", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "救援工作做了一整夜。", "target_word": "救援", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海上的船出事了，别的船赶来救援。", "target_word": "救援", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都在等着救援。", "target_word": "救援", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想学习怎么救援别人。", "target_word": "救援", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震后，国外的医生也来救援我们。", "target_word": "救援", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "救援了", "label": "体标"}, {"form": "救援过", "label": "体标"}, {"form": "救援队", "label": "复合"}, {"form": "救援人员", "label": "复合"}], "register": "中性", "sense_fingerprint": "前往现场援助危险中的人，使其脱离危险", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9338e44a-02f0-4ff6-8511-9734bc7b6a50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94942, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "救援", "is_correct": true, "explanation": "救援 jiù yuán：前去援助处于危险之中的人，使其脱险，是本词的意思。"}, {"text": "旧怨", "is_correct": false, "explanation": "旧怨 jiù yuàn 与救援的第二个音节声调不同（怨是第四声，援是第二声），意思是以前结下的怨恨。"}, {"text": "久远", "is_correct": false, "explanation": "久远 jiǔ yuǎn 与救援的两个音节声调都不同（久、远都是第三声），意思是年代久远。"}, {"text": "九元", "is_correct": false, "explanation": "九元 jiǔ yuán 与救援的第一个音节声调不同（九是第三声，救是第四声），意思是九块钱。"}], "explanations": {"救援": "救援 jiù yuán：前去援助处于危险之中的人，使其脱险，是本词的意思。", "旧怨": "旧怨 jiù yuàn 与救援的第二个音节声调不同（怨是第四声，援是第二声），意思是以前结下的怨恨。", "久远": "久远 jiǔ yuǎn 与救援的两个音节声调都不同（久、远都是第三声），意思是年代久远。", "九元": "九元 jiǔ yuán 与救援的第一个音节声调不同（九是第三声，救是第四声），意思是九块钱。"}, "sentence_index": null, "correct_answer": "救援"}, "level_3": {"options": [{"text": "救援", "is_correct": true, "explanation": "救援：前往现场援助处于危险中的人，与“赶到现场”相符。"}, {"text": "散步", "is_correct": false, "explanation": "语义：散步是悠闲地走，与赶到现场援助危险中的人的紧急情况不符。"}, {"text": "报名", "is_correct": false, "explanation": "语义：报名是登记参加活动，与消防队赶到现场的任务无关。"}, {"text": "结账", "is_correct": false, "explanation": "搭配：“结账”只用于消费场所，不能用于消防队到达事故现场的情境。"}], "explanations": {"救援": "救援：前往现场援助处于危险中的人，与“赶到现场”相符。", "散步": "语义：散步是悠闲地走，与赶到现场援助危险中的人的紧急情况不符。", "报名": "语义：报名是登记参加活动，与消防队赶到现场的任务无关。", "结账": "搭配：“结账”只用于消费场所，不能用于消防队到达事故现场的情境。"}, "sentence_index": 0, "correct_answer": "救援"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师认真救援这道数学题。", "explanation": "这里应该用〈讲解〉。救援的对象是处于危险中的人，不能用于讲解习题。"}, {"text": "周末我去朋友家救援，陪他们聊天。", "explanation": "这里应该用〈陪伴〉。救援指援助遇险的人，陪朋友聊天要用陪伴。"}, {"text": "老师救援我参加比赛。", "explanation": "这里应该用〈邀请〉。救援是对遇险者的援助，不用于请人参加活动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babba5e0-0b28-42d0-8f55-614438535d6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94942, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "救援", "is_correct": true, "explanation": "救援：前去援助遇险的船，与“出事了”以及别的船赶来的情境相符。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：船出事后别的船赶来，不是为了游泳，与救援的情境不符。"}, {"text": "比赛", "is_correct": false, "explanation": "语义：赶来的原因是船出了事，不是为了比赛，句子的意思矛盾。"}, {"text": "报销", "is_correct": false, "explanation": "搭配：“报销”用于费用或票据，不能用于说船赶来帮助出事的船。"}], "explanations": {"救援": "救援：前去援助遇险的船，与“出事了”以及别的船赶来的情境相符。", "游泳": "语义：船出事后别的船赶来，不是为了游泳，与救援的情境不符。", "比赛": "语义：赶来的原因是船出了事，不是为了比赛，句子的意思矛盾。", "报销": "搭配：“报销”用于费用或票据，不能用于说船赶来帮助出事的船。"}, "sentence_index": 6, "correct_answer": "救援"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们救援了远方的客人，大家很开心。", "explanation": "这里应该用〈招待〉。救援用于援助遇险的人，招待远方的客人不能用救援。"}, {"text": "老师救援学生要诚实。", "explanation": "这里应该用〈教育〉。救援是援助遇险的人，不用于对学生讲道理。"}, {"text": "医生定期救援病人的心脏。", "explanation": "这里应该用〈检查〉。救援针对处于危险中的人，不用于检查身体器官。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babba5e0-0b28-42d0-8f55-614438535d6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94942, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "消防员应该马上去把救援遇险的游客。", "corrected_sentence": "消防员应该马上去救援遇险的游客。", "error_description": "错误：动词“救援”前多加了介词“把”。“去”后直接接动词“救援”，“把”字句不能用在这里。正确应为“应该马上去救援遇险的游客”，去掉“把”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babba5e0-0b28-42d0-8f55-614438535d6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94942, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "直升机立刻飞去山区很救援一名受伤的登山者。", "corrected_sentence": "直升机立刻飞去山区救援一名受伤的登山者。", "error_description": "错误：副词“很”不能直接修饰动作动词“救援”，“很”一般只修饰形容词。正确应为“飞去山区救援一名受伤的登山者”，去掉“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babba5e0-0b28-42d0-8f55-614438535d6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
