INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94945, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "新生是刚进学校的学生。", "primary_collocate": null, "pronunciation": "xīn shēng", "ipa": "ɕin˥ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "今天是九月一日，学校来了很多新生。", "target_word": "新生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新生要先去办公室拿课本。", "target_word": "新生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我是新生，还不认识学校里的路。", "target_word": "新生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师带着新生参观了图书馆。", "target_word": "新生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些新生都是从外地来的。", "target_word": "新生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学长帮新生把行李搬到了宿舍。", "target_word": "新生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新生报到的那天，校门口特别热闹。", "target_word": "新生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "班上有二十个新生，大家互相问好。", "target_word": "新生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你是今年的新生吗？", "target_word": "新生", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "新生的第一节课是语文课。", "target_word": "新生", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "新生们", "label": "复数"}], "register": "通用", "sense_fingerprint": "新生：刚进学校的学生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e5eb461-8e2e-4423-8692-ca4884dea8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94945, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "新生", "is_correct": true, "explanation": "正确答案：新生（xīnshēng），指刚进学校的学生。"}, {"text": "先生", "is_correct": false, "explanation": "xiān 与 xīn 韵母不同（-ian / -in），先生是对男子的尊称，也可指老师。"}, {"text": "亲生", "is_correct": false, "explanation": "qīn 与 xīn 声母不同，亲生意思是有血缘关系的（子女）。"}, {"text": "新星", "is_correct": false, "explanation": "xīng 与 shēng 声母（x / sh）和韵母（ing / eng）都不同，新星意思是新出现、崭露头角的明星。"}], "explanations": {"新生": "正确答案：新生（xīnshēng），指刚进学校的学生。", "先生": "xiān 与 xīn 韵母不同（-ian / -in），先生是对男子的尊称，也可指老师。", "亲生": "qīn 与 xīn 声母不同，亲生意思是有血缘关系的（子女）。", "新星": "xīng 与 shēng 声母（x / sh）和韵母（ing / eng）都不同，新星意思是新出现、崭露头角的明星。"}, "sentence_index": null, "correct_answer": "新生"}, "level_3": {"options": [{"text": "新生", "is_correct": true, "explanation": "正确：“新生”指刚入学的学生，与“学校来了很多”搭配。"}, {"text": "新娘", "is_correct": false, "explanation": "语义：“新娘”指结婚的女子，与学校开学的语境不符。"}, {"text": "新郎", "is_correct": false, "explanation": "语义：“新郎”指结婚的男子，学校里来的不会是新郎。"}, {"text": "新居", "is_correct": false, "explanation": "搭配：“新居”是住所，不能说“学校来了很多新居”。"}], "explanations": {"新生": "正确：“新生”指刚入学的学生，与“学校来了很多”搭配。", "新娘": "语义：“新娘”指结婚的女子，与学校开学的语境不符。", "新郎": "语义：“新郎”指结婚的男子，学校里来的不会是新郎。", "新居": "搭配：“新居”是住所，不能说“学校来了很多新居”。"}, "sentence_index": 0, "correct_answer": "新生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "部队来了一批新生，正在训练。", "explanation": "这里应该用〈新兵〉。新生指刚入学的学生，部队里刚入伍的人要说新兵。"}, {"text": "婚礼上，新生把戒指戴在新娘手上。", "explanation": "这里应该用〈新郎〉。新生指刚入学的学生，在婚礼上给新娘戴戒指的是新郎。"}, {"text": "他刚开始学做饭，还是个新生。", "explanation": "这里应该用〈新手〉。新生指刚入学的学生，刚学一门技能的人要说新手。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1dac30-eecb-4430-ba06-76a6654182b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94945, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "新生", "is_correct": true, "explanation": "正确答案：新生（xīnshēng），指刚进学校的学生。"}, {"text": "新兴", "is_correct": false, "explanation": "shēng 与 xīng 声母不同，新兴意思是新近兴起的。"}, {"text": "新风", "is_correct": false, "explanation": "shēng 与 fēng 声母不同，新风意思是新的风气。"}, {"text": "新增", "is_correct": false, "explanation": "shēng 与 zēng 声母不同，新增意思是新添加的。"}], "explanations": {"新生": "正确答案：新生（xīnshēng），指刚进学校的学生。", "新兴": "shēng 与 xīng 声母不同，新兴意思是新近兴起的。", "新风": "shēng 与 fēng 声母不同，新风意思是新的风气。", "新增": "shēng 与 zēng 声母不同，新增意思是新添加的。"}, "sentence_index": null, "correct_answer": "新生"}, "level_3": {"options": [{"text": "新生", "is_correct": true, "explanation": "正确：“新生报到”指刚入学的学生报到，与校门口的语境相符。"}, {"text": "病人", "is_correct": false, "explanation": "语境：校门口热闹的开学场面，病人不会在校门口报到。"}, {"text": "小偷", "is_correct": false, "explanation": "语义：小偷不会在校门口“报到”，与句中的入学语境不符。"}, {"text": "犯人", "is_correct": false, "explanation": "语义：“犯人”与入学报到的语境冲突，句中指的是学生。"}], "explanations": {"新生": "正确：“新生报到”指刚入学的学生报到，与校门口的语境相符。", "病人": "语境：校门口热闹的开学场面，病人不会在校门口报到。", "小偷": "语义：小偷不会在校门口“报到”，与句中的入学语境不符。", "犯人": "语义：“犯人”与入学报到的语境冲突，句中指的是学生。"}, "sentence_index": 6, "correct_answer": "新生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司新来了一位新生，负责接待客户。", "explanation": "这里应该用〈新人〉。新生指刚入学的学生，刚进公司工作的人要说新人。"}, {"text": "他在木匠铺当新生，跟着师傅学了三年手艺。", "explanation": "这里应该用〈学徒〉。新生指刚入学的学生，跟着师傅学手艺的人要说学徒。"}, {"text": "俱乐部来了一位新生，大家热情地欢迎他。", "explanation": "这里应该用〈新会员〉。新生指刚入学的学生，刚加入俱乐部的人要说新会员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1dac30-eecb-4430-ba06-76a6654182b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94945, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校今年录取了两百只新生。", "corrected_sentence": "学校今年录取了两百名新生。", "error_description": "量词错误：“只”用于动物，指人的“新生”应用“名”或“个”。正确应为“两百名新生”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1dac30-eecb-4430-ba06-76a6654182b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94945, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "班上有三十个新生们，大家都很紧张。", "corrected_sentence": "班上有三十个新生，大家都很紧张。", "error_description": "后缀错误：“们”表示复数，不能与“三十个”连用。正确应为“三十个新生”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1dac30-eecb-4430-ba06-76a6654182b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94947, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无聊", "is_correct": true, "explanation": "无聊与“好玩、让人想看想听”相反，是本义的反义词。"}, {"text": "高大", "is_correct": false, "explanation": "高大说身材或体积大，与“好玩”没有反义关系。"}, {"text": "清脆", "is_correct": false, "explanation": "清脆说声音响亮悦耳，与“好玩”没有反义关系。"}, {"text": "宽敞", "is_correct": false, "explanation": "宽敞说空间大，与“好玩”没有反义关系。"}], "correct_answer": "无聊", "explanations": {"无聊": "无聊与“好玩、让人想看想听”相反，是本义的反义词。", "高大": "高大说身材或体积大，与“好玩”没有反义关系。", "清脆": "清脆说声音响亮悦耳，与“好玩”没有反义关系。", "宽敞": "宽敞说空间大，与“好玩”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dad82014-6291-4aef-ad40-dae724446334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94947, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无聊", "is_correct": true, "explanation": "无聊与“好玩、让人想看想听”相反，是本义的反义词。"}, {"text": "复杂", "is_correct": false, "explanation": "复杂说事情繁难，与“好玩”没有反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚说明白、不模糊，与“好玩”没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "安静说没有声音，与“好玩”没有反义关系。"}], "correct_answer": "无聊", "explanations": {"无聊": "无聊与“好玩、让人想看想听”相反，是本义的反义词。", "复杂": "复杂说事情繁难，与“好玩”没有反义关系。", "清楚": "清楚说明白、不模糊，与“好玩”没有反义关系。", "安静": "安静说没有声音，与“好玩”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dad82014-6291-4aef-ad40-dae724446334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94947, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "有意思是让人觉得好玩，想看想听。", "primary_collocate": null, "pronunciation": "yǒu yì si", "ipa": "joʊ˨˩˦ i˥˩ sɨ", "syllable_count": 3, "sentences": [{"text": "这个动画片真有意思，孩子们看得很开心。", "target_word": "有意思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的笑话很有意思，我听了哈哈大笑。", "target_word": "有意思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天的比赛太有意思了，我一直看着电视。", "target_word": "有意思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节目有意思极了，我每周都看。", "target_word": "有意思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友给我讲了一件有意思的事。", "target_word": "有意思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她说话很有意思，我最爱听她讲故事。", "target_word": "有意思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌很有意思，歌词又好玩又好听。", "target_word": "有意思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公园里的表演很有意思，很多人停下来看。", "target_word": "有意思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行中有什么有意思的事吗？", "target_word": "有意思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个广播节目挺有意思，我天天上班路上听。", "target_word": "有意思", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "好玩、让人想看想听", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '063f9b1f-5b36-425e-8fb6-27ef06b3df50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94947, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "有意思", "is_correct": true, "explanation": "正确答案。yǒu yì si 的意思是好玩、让人想看想听。"}, {"text": "有意识", "is_correct": false, "explanation": "shí（第二声）与 sī 声母不同（sh 与 s），意思是有意识、自觉。"}, {"text": "有意义", "is_correct": false, "explanation": "第三个音节 yi 与 si 声母不同，意思是有价值、有意义。"}, {"text": "有意志", "is_correct": false, "explanation": "zhì（第四声）与 si 声母不同（zh 与 s），意思是有决心、有毅力。"}], "explanations": {"有意思": "正确答案。yǒu yì si 的意思是好玩、让人想看想听。", "有意识": "shí（第二声）与 sī 声母不同（sh 与 s），意思是有意识、自觉。", "有意义": "第三个音节 yi 与 si 声母不同，意思是有价值、有意义。", "有意志": "zhì（第四声）与 si 声母不同（zh 与 s），意思是有决心、有毅力。"}, "sentence_index": null, "correct_answer": "有意思"}, "level_3": {"options": [{"text": "有意思", "is_correct": true, "explanation": "正确。“真有意思”说动画好玩，与“孩子们看得很开心”一致。"}, {"text": "枯燥", "is_correct": false, "explanation": "语义：“枯燥”说内容单调，与“孩子们看得很开心”矛盾。"}, {"text": "无聊", "is_correct": false, "explanation": "语义：“无聊”说没意思，与“孩子们看得很开心”矛盾。"}, {"text": "乏味", "is_correct": false, "explanation": "语域：“乏味”偏书面，且与“孩子们看得很开心”矛盾。"}], "explanations": {"有意思": "正确。“真有意思”说动画好玩，与“孩子们看得很开心”一致。", "枯燥": "语义：“枯燥”说内容单调，与“孩子们看得很开心”矛盾。", "无聊": "语义：“无聊”说没意思，与“孩子们看得很开心”矛盾。", "乏味": "语域：“乏味”偏书面，且与“孩子们看得很开心”矛盾。"}, "sentence_index": 0, "correct_answer": "有意思"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "每天喝够水，对身体很有意思。", "explanation": "这里应该用〈有益〉。有意思指有趣，说对身体、对人有好处要用〈有益〉。"}, {"text": "这次改革很有意思，半年后公司的业绩提高了一倍。", "explanation": "这里应该用〈有成效〉。有意思指好玩，说改革、措施取得的成果要用〈有成效〉。"}, {"text": "他为救落水的孩子牺牲了自己，这件事很有意思。", "explanation": "这里应该用〈有意义〉。有意思指好玩，说重大事件、行为的价值要用〈有意义〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dad82014-6291-4aef-ad40-dae724446334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94947, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有意思", "is_correct": true, "explanation": "正确。“很有意思”说歌有趣，与“又好玩又好听”一致。"}, {"text": "难听", "is_correct": false, "explanation": "语义：“难听”说声音不好听，与“又好听”矛盾。"}, {"text": "刺耳", "is_correct": false, "explanation": "搭配：“刺耳”多形容声音尖利，与“又好听”矛盾。"}, {"text": "单调", "is_correct": false, "explanation": "语义：“单调”说内容变化少，与“又好玩”矛盾。"}], "explanations": {"有意思": "正确。“很有意思”说歌有趣，与“又好玩又好听”一致。", "难听": "语义：“难听”说声音不好听，与“又好听”矛盾。", "刺耳": "搭配：“刺耳”多形容声音尖利，与“又好听”矛盾。", "单调": "语义：“单调”说内容变化少，与“又好玩”矛盾。"}, "sentence_index": 6, "correct_answer": "有意思"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种药很有意思，吃了两天病就好了。", "explanation": "这里应该用〈有效〉。有意思指好玩，说药物、治疗的效果要用〈有效〉。"}, {"text": "这次培训很有意思，我们学到了很多工作上用得着的知识。", "explanation": "这里应该用〈有价值〉。有意思指好玩，说培训、课程给人的实际收获要用〈有价值〉。"}, {"text": "这笔钱对他很有意思，帮他还清了所有的债。", "explanation": "这里应该用〈有帮助〉。有意思指有趣，说钱财对人的帮助要用〈有帮助〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dad82014-6291-4aef-ad40-dae724446334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94947, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他给孩子讲了一个很有意思故事。", "corrected_sentence": "他给孩子讲了一个很有意思的故事。", "error_description": "“很有意思”修饰名词时，后面要加“的”，应说“很有意思的故事”，不能说“很有意思故事”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dad82014-6291-4aef-ad40-dae724446334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94947, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次旅行不有意思，大家都很累。", "corrected_sentence": "这次旅行没有意思，大家都很累。", "error_description": "否定“有意思”要用“没有”，不能用“不”。“不”不能直接与“有”组合，应说“没有意思”，不能说“不有意思”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dad82014-6291-4aef-ad40-dae724446334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94948, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无聊", "is_correct": true, "explanation": "无聊与“有趣味”相反，是本义的反义词。"}, {"text": "复杂", "is_correct": false, "explanation": "复杂说事情繁难，与“有趣味”没有反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚说明白、不模糊，与“有趣味”没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "安静说没有声音，与“有趣味”没有反义关系。"}], "correct_answer": "无聊", "explanations": {"无聊": "无聊与“有趣味”相反，是本义的反义词。", "复杂": "复杂说事情繁难，与“有趣味”没有反义关系。", "清楚": "清楚说明白、不模糊，与“有趣味”没有反义关系。", "安静": "安静说没有声音，与“有趣味”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dad82014-6291-4aef-ad40-dae724446334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94948, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无聊", "is_correct": true, "explanation": "无聊与“有趣味”相反，是本义的反义词。"}, {"text": "整齐", "is_correct": false, "explanation": "整齐说排列有序，与“有趣味”没有反义关系。"}, {"text": "宽阔", "is_correct": false, "explanation": "宽阔说空间大，与“有趣味”没有反义关系。"}, {"text": "清晰", "is_correct": false, "explanation": "清晰说辨认容易、不模糊，与“有趣味”没有反义关系。"}], "correct_answer": "无聊", "explanations": {"无聊": "无聊与“有趣味”相反，是本义的反义词。", "整齐": "整齐说排列有序，与“有趣味”没有反义关系。", "宽阔": "宽阔说空间大，与“有趣味”没有反义关系。", "清晰": "清晰说辨认容易、不模糊，与“有趣味”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dad82014-6291-4aef-ad40-dae724446334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94948, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "有趣味，能引起兴趣。", "primary_collocate": null, "pronunciation": "yǒu yì si", "ipa": "joʊ˨˩˦ i˥˩ sɨ", "syllable_count": 3, "sentences": [{"text": "这本书很有意思，我一口气看完了。", "target_word": "有意思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他讲的故事特别有意思，大家都爱听。", "target_word": "有意思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这部电影不太有意思，我看到一半就睡了。", "target_word": "有意思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的课很有意思，同学们都不想下课。", "target_word": "有意思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我觉得学中文很有意思，每天都想学。", "target_word": "有意思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个游戏真有意思，我玩了一个晚上。", "target_word": "有意思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是个很有意思的人，总能让大家笑起来。", "target_word": "有意思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末去山里走走，一定很有意思。", "target_word": "有意思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个问题很有意思，我们一起想想吧。", "target_word": "有意思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本杂志里的文章都很有意思，我常常看。", "target_word": "有意思", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "有趣味、能引起兴趣的事物或人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '063f9b1f-5b36-425e-8fb6-27ef06b3df50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94948, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "有意思", "is_correct": true, "explanation": "正确答案。yǒu yì si 的意思是有趣、能引起兴趣。"}, {"text": "有意识", "is_correct": false, "explanation": "shí（第二声）与 sī 声母不同（sh 与 s），意思是有意识、自觉。"}, {"text": "有意义", "is_correct": false, "explanation": "第三个音节 yi 与 si 声母不同，意思是有价值、有意义。"}, {"text": "有意志", "is_correct": false, "explanation": "zhì（第四声）与 si 声母不同（zh 与 s），意思是有决心、有毅力。"}], "explanations": {"有意思": "正确答案。yǒu yì si 的意思是有趣、能引起兴趣。", "有意识": "shí（第二声）与 sī 声母不同（sh 与 s），意思是有意识、自觉。", "有意义": "第三个音节 yi 与 si 声母不同，意思是有价值、有意义。", "有意志": "zhì（第四声）与 si 声母不同（zh 与 s），意思是有决心、有毅力。"}, "sentence_index": null, "correct_answer": "有意思"}, "level_3": {"options": [{"text": "有意思", "is_correct": true, "explanation": "正确。“很有意思”说书有趣，与“一口气看完了”的投入相符。"}, {"text": "无聊", "is_correct": false, "explanation": "语义：“无聊”说没意思，与“一口气看完了”的投入矛盾。"}, {"text": "乏味", "is_correct": false, "explanation": "语域：“乏味”偏书面，且与“一口气看完了”的投入矛盾。"}, {"text": "沉闷", "is_correct": false, "explanation": "搭配：“沉闷”多形容气氛、环境，很少用来形容书，且与“一口气看完了”矛盾。"}], "explanations": {"有意思": "正确。“很有意思”说书有趣，与“一口气看完了”的投入相符。", "无聊": "语义：“无聊”说没意思，与“一口气看完了”的投入矛盾。", "乏味": "语域：“乏味”偏书面，且与“一口气看完了”的投入矛盾。", "沉闷": "搭配：“沉闷”多形容气氛、环境，很少用来形容书，且与“一口气看完了”矛盾。"}, "sentence_index": 0, "correct_answer": "有意思"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "为了给父亲治病，他卖掉了房子，这件事很有意思。", "explanation": "这里应该用〈有意义〉。有意思指有趣，说人生中重大的、有分量的事情时要用〈有意义〉。"}, {"text": "这种药很有意思，吃了两天病就好了。", "explanation": "这里应该用〈有效〉。有意思指有趣，说药物、治疗的效果要用〈有效〉。"}, {"text": "每天锻炼一小时，对身体很有意思。", "explanation": "这里应该用〈有益〉。有意思指有趣，说对身体、对人有好处要用〈有益〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dad82014-6291-4aef-ad40-dae724446334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94948, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有意思", "is_correct": true, "explanation": "正确。“很有意思的人”说人风趣，与“总能让大家笑起来”相符。"}, {"text": "冷淡", "is_correct": false, "explanation": "语义：“冷淡”说人态度冷漠，与“总能让大家笑起来”相反。"}, {"text": "木讷", "is_correct": false, "explanation": "语域：“木讷”偏书面，且说人不善言辞，与“总能让大家笑起来”矛盾。"}, {"text": "呆板", "is_correct": false, "explanation": "语义：“呆板”说人死板、不活泼，与“总能让大家笑起来”矛盾。"}], "explanations": {"有意思": "正确。“很有意思的人”说人风趣，与“总能让大家笑起来”相符。", "冷淡": "语义：“冷淡”说人态度冷漠，与“总能让大家笑起来”相反。", "木讷": "语域：“木讷”偏书面，且说人不善言辞，与“总能让大家笑起来”矛盾。", "呆板": "语义：“呆板”说人死板、不活泼，与“总能让大家笑起来”矛盾。"}, "sentence_index": 6, "correct_answer": "有意思"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场降雨对庄稼很有意思，地里的收成比去年多了一半。", "explanation": "这里应该用〈有利〉。有意思指有趣，说天气、自然条件对庄稼的好处要用〈有利〉。"}, {"text": "这次投资很有意思，公司一年就赚回了两倍的钱。", "explanation": "这里应该用〈有价值〉。有意思指有趣，说投资、工作的回报和值得性要用〈有价值〉。"}, {"text": "这把剪刀很有意思，家里剪纸、剪布都靠它。", "explanation": "这里应该用〈有用〉。有意思指有趣，说工具、物品的作用要用〈有用〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dad82014-6291-4aef-ad40-dae724446334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94948, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在图书馆找到一本很有意思书。", "corrected_sentence": "我在图书馆找到一本很有意思的书。", "error_description": "“很有意思”修饰名词时，后面要加“的”，应说“很有意思的书”，不能说“很有意思书”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dad82014-6291-4aef-ad40-dae724446334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94948, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他觉得学中文是一件很有意思事，每天都想学。", "corrected_sentence": "他觉得学中文是一件很有意思的事，每天都想学。", "error_description": "“很有意思”修饰名词“事”时，中间要加“的”，应说“很有意思的事”，不能说“很有意思事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dad82014-6291-4aef-ad40-dae724446334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
