INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94950, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "拥有许多财产，富裕。", "primary_collocate": null, "pronunciation": "yǒu qián", "ipa": "joʊ̯˨˩˦ tɕʰjɛn˧˥", "syllable_count": 2, "sentences": [{"text": "他家很有钱。", "target_word": "有钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个老板非常有钱。", "target_word": "有钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不是很有钱，但是很快乐。", "target_word": "有钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有钱的人不一定幸福。", "target_word": "有钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他爸爸很有钱，开了三家公司。", "target_word": "有钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他以前不太有钱，现在有钱了。", "target_word": "有钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住大房子的人，一定很有钱吗？", "target_word": "有钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市里有钱的家庭很多。", "target_word": "有钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说他很有钱，可是总坐公共汽车。", "target_word": "有钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看上去很有钱，穿着名牌衣服。", "target_word": "有钱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "有钱人", "label": "复合"}, {"form": "有钱了", "label": "体标（变化）"}], "register": "中性", "sense_fingerprint": "拥有许多财产，生活富裕", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '904ff82c-9949-44d4-8c88-d63d71ef0a8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
